window.__REE={"order":["travel","transport","driving","places","cities","weekends","housework","moving","spicy","films","news","phones","airports","interviews","coffee","breakfast","salt","sleep","junkfood","doom","ragebait","fraud","freelance","gold"],"eps":{"travel":{"ser":"Real Easy English","icon":"🚌","bg":"Пътят до работа","t":"Travel","a":"ree/audio/travel.mp3","sp":["Neil","Georgie"],"L":[[0,"Hello and welcome to Real Easy English.","Здравейте и добре дошли в Real Easy English.",[30,73,100,159,194,237,283],335],[0,"In this podcast we have real conversations in easy English to help you learn.","В този подкаст водим истински разговори на лесен английски, за да ви помогнем да учите.",[389,411,433,513,547,578,625,754,770,824,892,904,936,959],991],[0,"I'm Neil.","Аз съм Нийл.",[1042,1056],1089],[1,"And I'm Georgie.","А аз съм Джорджи.",[1114,1132,1151],1202],[1,"Remember, if you want to read along to this podcast, you can find a script on our website: bblearningenglish.com.","Не забравяйте: ако искате да четете заедно с подкаста, ще намерите текста на нашия сайт: bbclearningenglish.com.",[1273,1352,1367,1384,1408,1423,1459,1501,1517,1536,1644,1666,1683,1715,1718,1787,1803,1818,1915],2137],[0,"Hi, Georgie. How are you doing?","Здравей, Джорджи. Как си?",[2804,2822,2873,2904,2908,2929],2969],[1,"I'm fine thanks, Neil.","Добре съм, благодаря, Нийл.",[3016,3036,3076,3107],3140],[1,"How are you?","Ти как си?",[3141,3163,3166],3201],[0,"I'm very well, thank you.","Много добре, благодаря.",[3228,3246,3270,3294,3326],3346],[1,"What's today's conversation about, Neil?","За какво е днешният разговор, Нийл?",[3400,3434,3474,3542,3575],3611],[0,"Today we're going to talk about travel.","Днес ще говорим за пътуване.",[3646,3702,3730,3767,3778,3816,3848],3908],[0,"We talked about holidays in another episode.","Говорихме за ваканции в друг епизод.",[3952,3970,4020,4048,4127,4145,4180],4249],[0,"But today we'll talk about everyday travel and compare our journeys to work.","Но днес ще говорим за ежедневното пътуване и ще сравним пътя си до работа.",[4274,4306,4370,4398,4437,4488,4558,4634,4650,4714,4738,4795,4812],4855],[1,"So, Neil. What is your journey to work like?","Е, Нийл. Какъв е твоят път до работа?",[4945,4988,5045,5102,5123,5161,5199,5214,5249],5302],[0,"Well, because we live in London and it's a big city, it's quite long.","Ами, понеже живеем в Лондон, а той е голям град, пътят е доста дълъг.",[5361,5416,5533,5556,5575,5589,5680,5698,5716,5720,5748,5919,5934,5979],6023],[0,"But I get a bus to a tube stop.","Но вземам автобус до спирка на метрото.",[6102,6136,6159,6183,6190,6309,6370,6398,6461],6486],[0,"The tube is the underground train.","„The tube“ е метрото – подземният влак.",[6486,6494,6525,6542,6567,6633],6675],[0,"And then I get the tube to near the BBC and then I walk.","После вземам метрото до близо до Би Би Си и после вървя пеша.",[6722,6739,6761,6778,6811,6819,6931,7022,7089,7114,7167,7181,7197,7206],7247],[1,"Nice. I walk to work.","Хубаво. Аз ходя пеша до работа.",[7323,7408,7428,7459,7472],7527],[1,"I don't like using the tube, the underground train, because there's so many people on it.","Не обичам да ползвам метрото, защото в него има толкова много хора.",[7536,7566,7619,7658,7720,7731,7777,7819,7880,7977,8016,8036,8102,8128,8183,8195],8225],[1,"I prefer to get some fresh air in the morning.","Предпочитам сутрин да подишам малко чист въздух.",[8277,8298,8358,8402,8428,8442,8480,8513,8530,8535],8583],[0,"Ah, you walk to work.","А, ходиш пеша до работа.",[8597,8660,8685,8730,8747],8783],[0,"That's interesting in London.","Това е интересно за Лондон.",[8784,8807,8886,8905],8957],[0,"Tell me about your walk to work.","Разкажи ми за пътя си пеша до работа.",[9016,9047,9070,9117,9186,9214,9227],9269],[1,"Well, my walk starts with walking along some streets towards a park and then I walk across a park and then I walk through some more streets because there is a little bit of time between the park and the office and then I arrive at the office.","Ами, тръгвам по няколко улици към един парк, после пресичам парка, после минавам през още улици, защото има още малко път между парка и офиса, и после пристигам в офиса.",[9312,9386,9406,9452,9514,9586,9678,9720,9739,9814,9894,9900,10023,10038,10053,10073,10119,10178,10184,10267,10288,10367,10445,10495,10523,10542,10572,10647,10762,10783,10797,10802,10834,10852,10862,10948,11030,11044,11097,11146,11167,11239,11258,11289,11304,11333,11342,11353],11395],[0,"Very nice. So you don't like public transport?","Много хубаво. Значи не обичаш градския транспорт?",[11472,11488,11617,11629,11644,11673,11706,11745],11805],[1,"I use it sometimes when there's an emergency like if it's raining or if I don't have time.","Ползвам го понякога, когато има спешен случай – например ако вали или ако нямам време.",[11806,11901,12033,12067,12159,12223,12248,12257,12367,12438,12454,12473,12561,12602,12624,12634,12659,12684],12738],[1,"But if I have time I like to walk to work.","Но ако имам време, обичам да ходя пеша до работа.",[12786,12812,12829,12841,12879,12947,12988,13024,13035,13065,13075],13116],[0,"And how long does your journey take?","А колко време ти отнема пътят?",[13150,13162,13182,13256,13275,13296,13341],13387],[1,"My journey takes me one hour if I walk and thirty minutes if I take the tube.","Пътят ми отнема един час, ако вървя пеша, и трийсет минути, ако взема метрото.",[13443,13475,13512,13560,13616,13653,13719,13741,13749,13819,13897,13950,14000,14022,14032,14072,14093],14147],[0,"That's pretty good for London.","Това е доста добре за Лондон.",[14191,14212,14242,14288,14303],14345],[1,"What about you?","А ти?",[14364,14380,14406],14434],[0,"My journey takes at least an hour, sometimes more.","Моят път отнема поне час, понякога и повече.",[14467,14491,14528,14628,14644,14696,14708,14870,14934],14996],[1,"And Neil, you have to get a bus and a train.","А ти, Нийл, трябва да вземеш автобус и влак.",[15050,15067,15103,15134,15153,15166,15199,15205,15248,15291,15297],15356],[1,"What's your journey like?","Какъв е твоят път?",[15378,15412,15431,15466],15505],[0,"Well, it can be good, but sometimes there's traffic jams on the roads and so the bus can take a long time.","Ами, може да е добре, но понякога има задръствания по пътищата и автобусът може да се бави много.",[15534,15595,15617,15659,15720,15775,15796,15925,16047,16103,16154,16176,16186,16306,16325,16344,16357,16450,16489,16519,16525,16581],16641],[0,"But once I get on to the tube, it's usually OK as I travel across London.","Но щом се кача на метрото, обикновено е наред, докато пресичам Лондон.",[16669,16759,16797,16807,16850,16876,16891,16900,16969,17004,17172,17241,17266,17278,17394,17458],17516],[1,"Ooh, Neil, can you explain what we mean by traffic jam?","Ох, Нийл, можеш ли да обясниш какво значи „traffic jam“?",[17622,17644,17691,17719,17747,17826,17847,17862,17904,17947,18004],18047],[0,"Yeah, so a traffic jam is when there are too many cars and buses on the road and so the traffic can't move very quickly or can't move at all.","Да, „traffic jam“ (задръстване) е когато на пътя има твърде много коли и автобуси и движението не може да върви бързо или изобщо не може да мръдне.",[18073,18100,18138,18153,18214,18298,18319,18348,18369,18385,18425,18478,18607,18628,18719,18738,18747,18809,18831,18867,18912,18991,19020,19078,19119,19172,19192,19219,19251,19285],19317],[1,"Oh yeah traffic jams are so rubbish.","О, да, задръстванията са толкова гадни.",[19373,19389,19420,19462,19508,19526,19564],19623],[1,"Are there times of the day when there are more traffic jams?","Има ли часове от деня, когато има повече задръствания?",[19653,19659,19676,19727,19736,19747,19792,19813,19832,19840,19884,19920],19962],[0,"Yes, so during rush hour.","Да, в пиковия час.",[19986,20041,20092,20138,20180],20224],[0,"Rush hour is when most people are going to work so the roads are busier.","Пиковият час е, когато повечето хора отиват на работа, затова пътищата са по-натоварени.",[20280,20320,20349,20375,20420,20454,20494,20498,20526,20538,20615,20632,20642,20688,20698],20753],[0,"And also, if it's the school run.","И също, ако е времето за водене на децата на училище.",[20825,20860,20954,20972,20994,21005,21058],21097],[0,"School run time, so lots of people on the roads, taking their kids to school, then the bus journey takes a long time.","Тогава по пътищата има много хора, които карат децата си на училище, и пътуването с автобуса отнема много време.",[21121,21155,21189,21238,21279,21306,21313,21345,21362,21378,21497,21540,21550,21600,21609,21688,21797,21803,21839,21884,21931,21940,21964],21991],[1,"OK. So, that's in the morning and in the afternoons?","Добре. Значи това е сутрин и следобед?",[22028,22068,22084,22123,22141,22147,22212,22227,22236,22248],22321],[0,"Yeah. That's right.","Да. Точно така.",[22322,22342,22370],22395],[0,"Well, Georgie, your journey to work sounds nicer than mine, probably more relaxing.","Е, Джорджи, твоят път до работа звучи по-приятен от моя, вероятно и по-спокоен.",[23098,23125,23177,23288,23325,23343,23377,23434,23481,23498,23557,23620,23646],23719],[1,"Yes. Not when it's raining, though.","Да. Но не и когато вали.",[23794,23851,23874,23888,23903,23945],23967],[0,"Let's recap the words we learned during the conversation.","Нека преговорим думите, които научихме в разговора.",[24062,24096,24156,24164,24207,24225,24267,24308,24323],24406],[1,"We had towards - travelling in the direction of.","Имахме „towards“ – движа се в посока към нещо.",[24464,24477,24530,24530,24645,24702,24722,24729,24797],24841],[0,"Across - travelling from one side to the other.","„Across“ – минавам от едната страна до другата.",[24903,24903,24992,25050,25077,25119,25189,25207,25222],25261],[1,"Rush hour - a time when a lot of people are moving around the city, usually for work or school.","„Rush hour“ – време, когато много хора се движат из града, обикновено за работа или училище.",[25379,25409,25409,25479,25487,25537,25561,25568,25601,25611,25660,25675,25724,25762,25769,25842,25895,25918,25966,25982],26036],[0,"And an expression for something I hate: traffic jam, which we use to talk about a big delay when you're driving.","И израз за нещо, което мразя: „traffic jam“ – използваме го, когато говорим за голямо забавяне, докато шофираме.",[26075,26114,26139,26220,26232,26279,26312,26393,26462,26550,26570,26584,26623,26631,26664,26700,26707,26748,26823,26836,26857],26916],[1,"Thanks for listening to Real Easy English.","Благодарим, че слушахте Real Easy English.",[27277,27329,27339,27396,27416,27460,27515],27566],[1,"Visit our website for more activities and courses to help you with your English: bbclearningenglish.com.","Посетете нашия сайт за още упражнения и курсове, които ще ви помогнат с английския: bbclearningenglish.com.",[27587,27624,27644,27726,27736,27765,27845,27860,27959,27971,28004,28019,28043,28064,28180],28403],[0,"Next time, we'll talk about the news.","Следващия път ще говорим за новините.",[28434,28469,28524,28542,28573,28613,28625],28689],[1,"See you, then. Bye.","Ще се чуем тогава. Чао.",[28723,28737,28749,28803],28847],[0,"Goodbye!","Довиждане!",[28851],28903]],"v":[["journey","път, пътуване (до някъде)",13],["towards","към, в посока към",24],["across","през, от едната страна до другата",24],["rush hour","пиков час",41],["traffic jam","задръстване",37],["public transport","градски транспорт",25],["fresh air","чист въздух",20],["the tube","лондонското метро",16]],"g":[["underground",16,4,1],["fresh air",20,5,2],["towards",24,9,1],["across",24,16,1],["public transport",25,6,2],["emergency",26,7,1],["at least",32,3,2],["traffic jams",35,8,2],["rush hour",41,3,2],["school run",43,5,2],["relaxing",47,12,1],["raining",26,11,1]],"q":[["How does Neil get to work?","Как Нийл стига до работа?","by bus, then by tube, then on foot","by car","on foot all the way",15],["Why doesn't Georgie like the tube?","Защо Джорджи не обича метрото?","there are too many people on it","it is too expensive","it is too slow",19],["When does Georgie use public transport?","Кога Джорджи ползва градски транспорт?","when it's raining or she has no time","every Monday","only in the evening",26],["How long is Georgie's journey on foot?","Колко време е пътят на Джорджи пеша?","one hour","thirty minutes","two hours",29],["What makes Neil's bus journey slow?","Какво бави пътуването на Нийл с автобуса?","traffic jams","the weather","the bus driver",35],["When are there more traffic jams?","Кога има повече задръствания?","during rush hour and the school run","late at night","at the weekend",41]]},"transport":{"ser":"Real Easy English","icon":"🚇","bg":"Градският транспорт","t":"Public transport","a":"ree/audio/transport.mp3","sp":["Neil","Georgie"],"L":[[0,"Hello and welcome to Real Easy English, the podcast where we have real conversations in easy English to help you learn.","Здравейте и добре дошли в Real Easy English – подкастът, в който водим истински разговори на лесен английски, за да ви помогнем да учите.",[19,61,83,127,152,202,248,302,324,397,416,432,463,502,627,642,695,747,763,791,803],833],[0,"I'm Neil, and with me is Georgie.","Аз съм Нийл, а с мен е Джорджи.",[865,883,926,951,975,1010,1036],1083],[1,"Hello. Did you know that you can now watch a video of this podcast?","Здравейте. Знаете ли, че вече можете да гледате видео на този подкаст?",[1120,1143,1232,1248,1276,1290,1307,1331,1361,1401,1411,1482,1497,1519],1597],[1,"And you can read along with a transcript on our website.","И можете да четете заедно с текста на нашия сайт.",[1600,1638,1646,1666,1698,1730,1748,1751,1819,1836,1851],1911],[1,"Visit bblearningenglish.com.","Посетете bbclearningenglish.com.",[1952,1983],2201],[0,"Hi, Georgie. How are you?","Здравей, Джорджи. Как си?",[2791,2807,2848,2871,2880],2905],[1,"I'm very well, thank you, Neil.","Много добре, благодаря, Нийл.",[2929,2952,2975,2997,3025,3037],3070],[1,"How are you?","Ти как си?",[3071,3089,3091],3123],[1,"How was your journey into work?","Как мина пътят ти до работа?",[3125,3139,3152,3162,3202,3238],3270],[0,"My journey into work was very good today, actually.","Пътят ми до работа днес всъщност беше много добър.",[3298,3317,3369,3391,3422,3438,3459,3481,3519],3578],[0,"And we're actually talking about transport today.","А днес всъщност говорим за транспорта.",[3637,3688,3710,3742,3803,3870,3916],3956],[0,"How was your journey to work?","Как мина твоят път до работа?",[3988,4009,4030,4055,4092,4106],4141],[1,"My journey was quite easy this morning, actually.","Пътят ми тази сутрин всъщност беше доста лесен.",[4188,4227,4280,4303,4327,4363,4380,4412],4477],[1,"It isn't always.","Не винаги е така.",[4484,4491,4524],4595],[1,"And, Neil, we actually have a very similar commute, don't we?","И, Нийл, ние всъщност пътуваме до работа по много подобен начин, нали?",[4597,4645,4676,4688,4716,4733,4738,4773,4816,4859,4884],4911],[1,"I get the Tube to work, which in the UK is the underground train.","Взимам метрото до работа – във Великобритания това е подземният влак.",[4962,4983,5061,5186,5252,5277,5311,5352,5370,5383,5438,5453,5474,5545],5616],[1,"So I walk to the station around 15 to 20 minutes, and then I get the underground train, one train, and then I change and then get another one, and then I walk to work.","Вървя пеша до станцията около 15–20 минути, после вземам метрото, един влак, после се прекачвам на друг и после вървя пеша до работа.",[5698,5715,5722,5758,5766,5774,5851,5881,5947,5959,5981,6037,6055,6076,6088,6119,6137,6188,6312,6336,6373,6388,6399,6406,6489,6505,6516,6528,6556,6666,6683,6695,6700,6722,6733],6762],[1,"What about you?","А ти?",[6816,6828,6848],6866],[0,"I do that, but before, before your bit, I have to get a bus as well.","И аз правя това, но преди… преди твоята част трябва да взема и автобус.",[6900,6917,6936,6994,7009,7145,7233,7266,7316,7334,7359,7369,7389,7395,7448,7469],7503],[1,"Are you that far away from the station?","Толкова далеч ли си от станцията?",[7572,7575,7586,7603,7627,7650,7669,7675],7722],[0,"A couple of miles.","На няколко мили.",[7855,7945,7988,8009],8073],[1,"OK.","Добре.",[8097],8138],[0,"Three kilometres.","Три километра.",[8191,8212],8277],[1,"A bit too far to walk, then.","Значи малко далечко за пеша.",[8292,8303,8330,8350,8372,8389,8420],8431],[0,"A bit too far to walk.","Малко далечко за пеша.",[8431,8434,8450,8466,8488,8503],8544],[0,"I have walked when the public transport has been unreliable.","Ходил съм пеша, когато градският транспорт е бил ненадежден.",[8553,8566,8597,8697,8741,8763,8796,8843,8855,8870],8950],[0,"But normally I, I get the bus to the Tube stop, and then I get on the Tube into work.","Но обикновено вземам автобуса до спирката на метрото и после се качвам на метрото до работа.",[9002,9086,9149,9213,9237,9255,9261,9374,9409,9420,9473,9549,9570,9600,9614,9633,9641,9648,9797,9822],9855],[1,"Lovely. And do you like the Tube?","Чудесно. А харесваш ли метрото?",[9882,9949,9978,9995,10010,10038,10047],10080],[1,"What do you think about it?","Какво мислиш за него?",[10081,10094,10102,10108,10134,10161],10176],[0,"I think the Tube is very convenient, actually, because the trains go very frequently.","Мисля, че метрото е много удобно всъщност, защото влаковете минават много често.",[10294,10312,10340,10350,10400,10478,10517,10592,10699,10814,10849,10886,10903,10941],11012],[0,"So if you miss one, you can wait just a couple of minutes and get the next one.","Така че ако изпуснеш един, можеш да почакаш само няколко минути и да вземеш следващия.",[11038,11064,11099,11118,11144,11185,11199,11260,11290,11312,11315,11344,11352,11388,11398,11428,11441,11471],11493],[0,"And it's probably the quickest way to get into central London because there's so much traffic.","И вероятно е най-бързият начин да стигнеш до центъра на Лондон, защото има толкова много трафик.",[11618,11730,11749,11811,11822,11878,11911,11941,12022,12060,12113,12183,12320,12333,12349,12369],12409],[0,"Driving is a really bad idea.","Да караш кола е наистина лоша идея.",[12410,12463,12471,12478,12536,12570],12614],[1,"Yeah, I agree with you.","Да, съгласна съм с теб.",[12768,12803,12864,12890,12906],12937],[1,"It is very reliable.","Много е надеждно.",[12957,12975,13018,13046],13118],[1,"It's usually very easy.","Обикновено е много лесно.",[13119,13147,13191,13219],13287],[1,"The thing I don't like about it, especially in the morning at rush hour, is the number of people on the Tube.","Нещото, което не харесвам, особено сутрин в пиковия час, е броят на хората в метрото.",[13288,13317,13339,13349,13380,13403,13434,13481,13556,13569,13575,13644,13659,13697,13815,13874,13897,13931,13941,14022,14044,14052],14099],[1,"The, the underground trains in London are very old.","Влаковете на метрото в Лондон са много стари.",[14100,14116,14130,14228,14294,14300,14408,14427,14506],14555],[1,"They're very small.","Много са малки.",[14611,14625,14653],14734],[1,"And they are very crowded in the mornings.","И сутрин са много претъпкани.",[14750,14822,14858,14863,15009,15066,15081,15087],15159],[1,"So crowded means there's lots of people.","„Crowded“ значи, че има много хора.",[15159,15178,15228,15265,15284,15309,15317],15372],[1,"We can also say packed.","Можем да кажем и „packed“ (натъпкан).",[15437,15477,15493,15515,15547],15611],[1,"Yeah. And I really don't like being in a tight space with lots of people in the mornings, so early in the morning.","Да. И наистина не обичам да съм в тясно пространство с много хора сутрин, толкова рано сутринта.",[15647,15670,15780,15809,15841,15865,15953,16043,16056,16062,16094,16149,16162,16192,16199,16250,16266,16272,16344,16374,16400,16409,16416],16458],[0,"Yeah, I agree, but I'm lucky because I get on the Tube at the first stop, so I always get a seat, but then by the time you get on, it is usually really packed.","Да, съгласен съм, но аз имам късмет, защото се качвам на метрото на първата спирка, така че винаги имам място, но докато ти се качиш, обикновено е много претъпкано.",[16518,16584,16600,16643,16659,16678,16741,16778,16793,16822,16840,16847,16915,16928,16935,16969,17009,17031,17040,17076,17100,17103,17213,17231,17257,17284,17318,17350,17369,17400,17428,17444,17466,17550,17594],17653],[0,"And the closer you get into central London, the more packed it is.","И колкото повече наближаваш центъра на Лондон, толкова по-претъпкано е.",[17674,17709,17740,17787,17806,17859,17890,17932,17981,18003,18043,18087,18097],18134],[0,"You're squashed up against strangers.","Притиснат си до непознати.",[18185,18199,18236,18253,18287],18361],[0,"It's not always fun.","Не винаги е забавно.",[18408,18439,18454,18495],18528],[1,"I hate it.","Мразя го.",[18553,18562,18598],18614],[1,"What about buses?","А автобусите?",[18641,18651,18674],18716],[1,"Do you like buses?","Харесваш ли автобусите?",[18717,18725,18731,18748],18794],[0,"Buses are OK.","Автобусите са окей.",[18993,19032,19035],19088],[0,"They, in London again, they are quite frequent.","В Лондон, пак казвам, минават доста често.",[19157,19164,19170,19269,19336,19414,19434,19512],19597],[0,"And that's convenient.","И това е удобно.",[19654,19670,19692],19773],[1,"Not always. I mean, they are, they're frequent, but they're more unreliable than trains, aren't they?","Не винаги. Искам да кажа, минават често, но са по-ненадеждни от влаковете, нали?",[19812,19844,19910,19918,19935,19956,19988,20022,20139,20154,20167,20203,20289,20314,20381,20409],20438],[0,"There always seems to be roadworks near where I live, and when there are roadworks, there are traffic lights and then there are delays on the buses.","Близо до мен сякаш винаги има ремонт на пътя, а когато има ремонти, има светофари и после автобусите закъсняват.",[20439,20486,20531,20566,20574,20586,20667,20701,20723,20735,20776,20806,20927,20947,20956,21019,21031,21038,21078,21126,21140,21159,21175,21185,21267,21280,21288],21328],[1,"So in the city, public transport can be great.","Значи в града градският транспорт може да е страхотен.",[21329,21382,21472,21528,21689,21728,21815,21831,21840],21901],[1,"But what about when we go outside of the city?","Но какво става, когато излезем извън града?",[21902,21927,21950,22026,22058,22071,22083,22137,22145,22153],22204],[1,"What do you use to go to other parts of the UK?","С какво пътуваш до други части на Обединеното кралство?",[22291,22315,22329,22341,22400,22438,22577,22588,22610,22641,22648,22658],22702],[0,"If it's quite far, so if I'm going really far north, maybe to Scotland or to, I don't know, Manchester or a northern city, it's probably better to get the train because it's faster and I really like trains.","Ако е доста далеч – ако отивам много на север, може би в Шотландия или, не знам, в Манчестър или друг северен град, вероятно е по-добре да взема влака, защото е по-бърз, а и много обичам влаковете.",[22812,22829,22896,22932,22978,23000,23016,23027,23051,23094,23123,23204,23266,23277,23363,23378,23460,23466,23480,23510,23575,23585,23602,23646,23798,23809,23851,23894,23911,23942,23953,24057,24106,24120,24176,24209,24219,24253,24277],24319],[0,"You can relax.","Можеш да се отпуснеш.",[24320,24332,24347],24419],[0,"It's a relaxing experience.","Това е спокойно преживяване.",[24419,24438,24442,24519],24604],[0,"Some of my best travel experiences have been on long distance trains.","Някои от най-хубавите ми пътувания са били с влакове на дълги разстояния.",[24644,24672,24682,24700,24762,24816,24974,24991,25024,25053,25093,25135],25185],[1,"Yeah?","Така ли?",[25285],25319],[0,"Yeah.","Да.",[25343],25356],[1,"Can you... Where have you been that's been so fantastic on a train?","Можеш ли… Къде си ходил, че да е било толкова фантастично с влак?",[25412,25428,25481,25512,25522,25528,25555,25572,25596,25625,25687,25698,25704],25744],[0,"Well, I once went from Prague to Moscow on a train.","Ами, веднъж пътувах от Прага до Москва с влак.",[25751,25902,25919,25955,25976,26016,26063,26076,26149,26161,26169],26206],[1,"Wow.","Уау.",[26206],26261],[0,"Yeah.","Да.",[26330],26351],[1,"What was that like?","И как беше?",[26365,26377,26390,26407],26444],[0,"Really exciting.","Наистина вълнуващо.",[26506,26563],26630],[1,"Why?","Защо?",[26670],26722],[0,"It took about three days, and I was with some friends, and we could eat and drink and look out the window.","Отне около три дни, бях с приятели, можехме да ядем, да пием и да гледаме през прозореца.",[26789,26811,26869,26902,26927,27025,27135,27143,27164,27176,27194,27298,27308,27318,27350,27376,27385,27429,27444,27460,27471,27478],27530],[0,"The landscape changed frequently.","Пейзажът се сменяше често.",[27565,27572,27640,27693],27758],[0,"It was just exciting.","Беше просто вълнуващо.",[27846,27857,27875,27897],27951],[0,"Let's recap the vocabulary we heard in this podcast, starting with some useful adjectives to describe public transport.","Нека преговорим думите, които чухме в подкаста, като започнем с някои полезни прилагателни за описване на градския транспорт.",[28472,28519,28586,28596,28680,28697,28736,28752,28773,28843,28906,28925,28949,29029,29142,29160,29206,29238],29309],[0,"For example, we had crowded, which means very busy.","Например имахме „crowded“, което значи много пълен с хора.",[29336,29351,29404,29420,29475,29550,29579,29607,29638],29681],[0,"We also hear packed.","Чуваме и „packed“.",[29715,29729,29767,29800],29888],[1,"We had reliable, which describes something you can trust, and unreliable which describes something you can't trust.","Имахме „reliable“ – за нещо, на което можеш да разчиташ, и „unreliable“ – за нещо, на което не можеш да разчиташ.",[29904,29919,29959,30049,30090,30149,30199,30213,30231,30306,30348,30425,30450,30500,30544,30560,30594],30647],[0,"We heard frequent, which describes something that happens often.","Чухме „frequent“ – за нещо, което се случва често.",[30700,30722,30775,30856,30888,30969,31024,31038,31100],31147],[1,"And we also heard delayed, which means something, like public transport, comes later than expected.","И чухме „delayed“ – когато нещо, например градският транспорт, идва по-късно от очакваното.",[31242,31272,31285,31319,31368,31436,31462,31506,31562,31582,31616,31687,31722,31773,31794],31862],[0,"That's it for this episode of Real Easy English.","Това е за този епизод на Real Easy English.",[31862,31945,31957,31974,31997,32047,32066,32106,32138],32188],[0,"Don't forget to go to our website where you can get a free worksheet to download to test what you've learnt.","Не забравяйте да отидете на нашия сайт, където можете да свалите безплатен работен лист и да проверите какво научихте.",[32188,32217,32256,32268,32283,32304,32312,32370,32385,32395,32413,32449,32461,32512,32569,32580,32631,32654,32687,32707,32727],32773],[0,"It's at bbclearningenglish.com.","Адресът е bbclearningenglish.com.",[32825,32845,32854],33016],[1,"Next time, we're talking about different times of year.","Следващия път ще говорим за различните сезони.",[33056,33079,33116,33131,33179,33213,33246,33289,33295],33338],[1,"Spring, summer, autumn and winter.","Пролет, лято, есен и зима.",[33350,33410,33475,33519,33555],33583],[1,"See you then.","Ще се чуем тогава.",[33619,33627,33638],33663],[0,"Goodbye.","Довиждане.",[33664],33725],[1,"Bye.","Чао.",[33750],33794]],"v":[["crowded","претъпкан, пълен с хора",39],["packed","натъпкан",41],["reliable","надежден",34],["unreliable","ненадежден",25],["frequent","чест",51],["delayed","закъснял",79],["convenient","удобен",29],["commute","път до работа",14]],"g":[["commute",14,8,1],["unreliable",25,9,1],["convenient",29,6,1],["frequently",29,13,1],["reliable",34,3,1],["crowded",39,4,1],["packed",41,4,1],["strangers",45,4,1],["roadworks",54,5,1],["delays",54,23,1],["long distance",61,9,2],["landscape",72,1,1]],"q":[["How does Georgie get to work?","Как Джорджи стига до работа?","she walks, then takes two underground trains","she drives","she takes a bus",16],["How far is Neil's home from the station?","Колко далеч е домът на Нийл от станцията?","about three kilometres","about ten kilometres","five minutes on foot",22],["Why does Neil think the Tube is convenient?","Защо Нийл смята, че метрото е удобно?","the trains go very frequently","it is cheap","it is new",29],["What doesn't Georgie like about the Tube?","Какво не харесва Джорджи в метрото?","it is very crowded in the morning","it is too slow","it is too expensive",39],["Why does Neil always get a seat?","Защо Нийл винаги има място за сядане?","he gets on at the first stop","he travels late","he pays more",43],["Where did Neil once travel by train?","Къде е пътувал веднъж Нийл с влак?","from Prague to Moscow","from London to Paris","from Madrid to Rome",65]]},"driving":{"ser":"Real Easy English","icon":"🚗","bg":"Шофирането","t":"Driving","a":"ree/audio/driving.mp3","sp":["Neil","Beth"],"L":[[0,"Welcome to Real Easy English, our easy podcast where we have real conversations in easy English.","Добре дошли в Real Easy English, нашия лесен подкаст, в който водим истински разговори на лесен английски.",[19,62,88,125,167,248,293,326,410,426,443,490,520,633,651,698],742],[0,"I'm Neil.","Аз съм Нийл.",[761,778],809],[1,"And I'm Beth.","А аз съм Бет.",[827,867,890],914],[1,"You can watch a video version of this podcast over on our website and you'll find a free worksheet there as well.","Можете да гледате видео версия на подкаста на нашия сайт, а там ще намерите и безплатен работен лист.",[978,996,1017,1050,1069,1119,1175,1195,1214,1279,1315,1337,1357,1446,1461,1475,1514,1520,1559,1611,1634,1662],1696],[1,"Go to bbclearningenglish.com.","Отидете на bbclearningenglish.com.",[1729,1746,1773],1982],[0,"Hi Beth, how are you?","Здравей, Бет, как си?",[2708,2727,2758,2773,2782],2809],[1,"I'm good, thank you, although I was late to work this morning.","Добре съм, благодаря, макар че тази сутрин закъснях за работа.",[2841,2877,2898,2925,2944,2983,2998,3027,3059,3070,3116,3137],3180],[0,"Oh no!","О, не!",[3182,3196],3255],[1,"The traffic was bad.","Трафикът беше ужасен.",[3288,3301,3366,3405],3447],[0,"Ah, we're talking about driving today.","А, днес говорим за шофирането.",[3474,3612,3624,3662,3693,3760],3805],[1,"We are. And sometimes I drive to work.","Да. Понякога карам до работа.",[3840,3861,3915,3936,3993,4042,4075,4091],4102],[1,"And I did today but I should have got the train because... yeah, like I say, the traffic was bad.","Днес също карах, но трябваше да взема влака, защото… да, както казах, трафикът беше ужасен.",[4103,4153,4161,4181,4244,4258,4268,4289,4300,4318,4323,4370,4473,4518,4539,4546,4589,4603,4662,4690],4739],[0,"So, clearly you can drive.","Значи явно можеш да караш.",[4800,4870,4971,4987,5009],5066],[0,"Do you like driving?","Обичаш ли да шофираш?",[5140,5155,5178,5207],5259],[1,"It depends. If I am commuting - so coming to work - by car, I don't enjoy it, usually because of the traffic.","Зависи. Ако пътувам до работа – тоест идвам на работа – с кола, обикновено не ми е приятно заради трафика.",[5422,5434,5519,5552,5579,5661,5661,5741,5768,5814,5828,5828,5973,6005,6048,6062,6103,6134,6292,6337,6378,6390,6398],6488],[1,"But if I have a long journey, like if I go to see a friend and I'm in the car for three hours, I actually really enjoy it because I listen to music, podcasts, maybe an audiobook, and I can relax and just drive along the motorway listening to something I like.","Но ако имам дълго пътуване, например ако отивам при приятел и съм в колата три часа, всъщност много ми харесва, защото слушам музика, подкасти, може би аудиокнига, и мога да се отпусна и просто да карам по магистралата, слушайки нещо, което харесвам.",[6489,6506,6523,6531,6583,6592,6638,6707,6742,6756,6767,6789,6805,6824,6828,6879,6894,6910,6920,6928,6960,7023,7052,7155,7168,7207,7237,7282,7305,7344,7418,7442,7458,7558,7650,7674,7684,7807,7829,7840,7932,7976,7989,8048,8075,8098,8104,8195,8232,8241,8275,8285],8331],[1,"What about you?","А ти?",[8398,8413,8432],8455],[1,"You drive, don't you?","Ти караш, нали?",[8456,8474,8506,8530],8548],[0,"I drive, yeah.","Карам, да.",[8579,8591,8635],8659],[0,"Not that often because I live in London and I can use public transport.","Не много често, защото живея в Лондон и мога да ползвам градския транспорт.",[8670,8691,8719,8804,8840,8847,8872,8886,8924,8952,8964,8983,9009,9050],9121],[1,"That's one of the benefits of living in London, definitely.","Това определено е едно от предимствата на живота в Лондон.",[9152,9177,9191,9200,9207,9272,9289,9326,9335,9380],9447],[1,"Do you enjoy driving?","Харесва ли ти да шофираш?",[9499,9510,9516,9547],9603],[0,"It's OK. It's not a big love of mine.","Горе-долу. Не е голямата ми любов.",[9641,9662,9766,9785,9889,9894,9919,9966,9985],10024],[0,"But, like you said, sometimes it's quite nice if you're somewhere, maybe in the countryside, on your own, you can listen to loud music and sing.","Но както каза, понякога е доста приятно, ако си някъде, може би на село, сам – можеш да пуснеш силно музика и да пееш.",[10086,10190,10216,10230,10294,10362,10371,10402,10510,10524,10535,10618,10646,10655,10661,10828,10843,10861,10918,10926,10940,10968,11041,11070,11114,11124],11153],[1,"Yeah! Yeah, singing in the car is good fun.","Да! Да, пеенето в колата е голяма забава.",[11154,11229,11247,11294,11305,11312,11425,11439,11456],11473],[1,"Are you good at driving?","Добър шофьор ли си?",[11623,11634,11666,11695,11708],11767],[1,"Or do you think people would say you're good at driving?","Или мислиш, че хората биха казали, че караш добре?",[11767,11784,11800,11808,11834,11873,11890,11938,11956,11978,11988],12045],[0,"I don't know.","Не знам.",[12089,12195,12212],12238],[0,"I think I'm OK.","Мисля, че съм горе-долу добре.",[12239,12247,12270,12286],12352],[0,"I've never had an accident - touch wood!","Никога не съм имал катастрофа – да чукна на дърво!",[12444,12459,12478,12505,12517,12517,12588,12628],12662],[1,"Oh, that's good!","О, това е хубаво!",[12670,12716,12743],12773],[1,"That's good. I haven't had an accident but I did get caught speeding once and I...","Хубаво е. Аз не съм имала катастрофа, но веднъж ме хванаха за превишена скорост и аз…",[12774,12806,12887,12906,12935,12962,12977,13037,13160,13185,13212,13238,13281,13379,13430,13451],13480],[1,"That means I was going too fast.","Това значи, че карах твърде бързо.",[13531,13544,13564,13570,13587,13621,13642],13712],[1,"And I had to go on a Speed Awareness Course and I haven't sped since.","И трябваше да мина курс за безопасна скорост и оттогава не съм превишавала скоростта.",[13724,13743,13750,13774,13784,13811,13828,13831,13878,13938,14085,14100,14119,14161,14201],14269],[0,"Speeding! Beth, that's dangerous!","Превишена скорост! Бет, това е опасно!",[14383,14459,14550,14566],14641],[1,"I was going a few miles an hour over the speed limit.","Карах с няколко мили в час над ограничението.",[14642,14657,14675,14708,14712,14738,14783,14791,14842,14928,14938,14972],15026],[0,"Hmm.","Хм.",[15050],15085],[1,"So, is there anything that you don't like about driving, Neil?","А има ли нещо, което не харесваш в шофирането, Нийл?",[15113,15136,15153,15166,15211,15232,15248,15292,15344,15372,15417],15453],[0,"Yeah, I don't really like parking because, in a busy city especially, it can be difficult to find somewhere to park.","Да, не обичам много паркирането, защото, особено в оживен град, може да е трудно да намериш място за паркиране.",[15488,15522,15539,15564,15603,15641,15848,16023,16039,16043,16077,16129,16222,16236,16254,16265,16327,16337,16393,16443,16474],16530],[0,"And also, when you do find somewhere to park, the space can be really small and then you have to try to get your car into this little space.","А и когато намериш място, то може да е съвсем малко и после трябва да се опиташ да вкараш колата в това мъничко място.",[16584,16620,16702,16725,16743,16783,16819,16863,16875,16927,16937,16977,16997,17012,17044,17157,17167,17181,17192,17220,17258,17282,17331,17369,17384,17431,17450,17474,17499],17556],[1,"Yeah.","Да.",[17590],17625],[0,"Often with other people waiting for you to do it.","Често докато други хора чакат да го направиш.",[17627,17690,17712,17731,17772,17844,17856,17875,17884,17911],17928],[1,"Yeah, I don't like doing that, when you're on a road and there's cars behind you.","Да, не обичам това – когато си на пътя и зад теб има коли.",[17956,17988,18005,18031,18056,18086,18108,18124,18136,18150,18156,18259,18269,18288,18317,18356],18397],[1,"Outside of my house, we have to reverse into a parking space.","Пред къщата ми трябва да паркираме на заден ход.",[18411,18544,18559,18600,18644,18658,18681,18714,18783,18822,18831,18875],18937],[1,"So, reversing - going backwards - for parking, I'm OK with now.","Така че с паркирането на заден ход – движение назад – вече съм добре.",[18938,19008,19008,19072,19100,19100,19285,19302,19400,19484,19512,19531],19562],[1,"I didn't used to like it but now it's fine because I have to do it whenever I drive.","Преди не ми харесваше, но сега е наред, защото трябва да го правя всеки път, когато карам.",[19572,19584,19618,19646,19656,19688,19706,19788,19819,19841,19874,19909,19953,19966,19981,20000,20036,20077,20088],20134],[0,"Beth, did you find it difficult or easy to learn how to drive?","Бет, трудно ли ти беше или лесно да се научиш да караш?",[20175,20212,20240,20255,20297,20344,20425,20450,20510,20524,20579,20602,20613],20658],[1,"Hmm, good question.","Хм, добър въпрос.",[20701,20733,20776],20846],[1,"I found it not easy, not difficult.","Не ми беше нито лесно, нито трудно.",[20893,20908,20955,21129,21166,21206,21224],21288],[1,"I remember thinking, \"Everyone I know can drive so I know that I'm also going to be able to drive.\" And that helped me.","Помня, че си мислех: „Всички, които познавам, могат да карат, значи знам, че и аз ще мога.“ И това ми помогна.",[21340,21353,21401,21550,21609,21622,21651,21675,21752,21785,21803,21827,21845,21876,21908,21939,21948,21960,21988,22002,22106,22120,22134,22169],22198],[1,"But the driving on a road was fine and even changing gears, that kind of thing, was OK.","Карането по пътя беше наред, дори смяната на скоростите и такива неща беше окей.",[22202,22245,22264,22315,22327,22331,22372,22400,22523,22550,22591,22641,22770,22792,22819,22828,22854,22873],22919],[1,"But I found parking, when I was learning how to park, and we have to... or we had to reverse around a corner - those kinds of manoeuvres, they call them, I found difficult.","Но паркирането – когато се учех да паркирам и трябваше да завиваме на заден ход зад ъгъл – такива маневри, както ги наричат, ми бяха трудни.",[22920,22989,23000,23034,23100,23114,23122,23144,23194,23209,23222,23269,23297,23308,23322,23379,23388,23400,23425,23450,23507,23539,23544,23544,23656,23681,23708,23744,23844,23863,23891,23952,23966,24112],24180],[1,"But I did pass my test first time.","Но взех изпита си от първия път.",[24190,24227,24241,24259,24291,24305,24366,24400],24427],[0,"Ah.","А.",[24444],24490],[1,"What about you?","А ти?",[24552,24565,24582],24619],[1,"Did you find it easy to learn to drive?","Лесно ли ти беше да се научиш да караш?",[24619,24638,24716,24741,24750,24780,24794,24815,24828],24880],[0,"I think it was quite easy.","Мисля, че беше доста лесно.",[24912,24943,24969,24980,25000,25034],25102],[0,"I passed first time, like you did, but I remember the man who took the test was very critical of me at the end and even angry.","И аз взех от първия път, като теб, но помня, че човекът, който ме изпитваше, беше много критичен към мен накрая и дори ядосан.",[25107,25119,25156,25193,25259,25283,25297,25378,25397,25406,25493,25502,25547,25630,25653,25662,25794,25812,25866,25950,25963,26023,26042,26056,26119,26203,26233],26304],[0,"And I was scared; I thought I must have failed the test.","И се уплаших; помислих си, че сигурно съм скъсал на изпита.",[26323,26338,26349,26366,26432,26454,26558,26568,26594,26605,26662,26674],26743],[0,"And then he said, \"Congratulations.","А после каза: „Поздравления.",[26744,26756,26767,26781,26840],26924],[0,"You passed.\" I think he just wanted to let me know that driving is dangerous and you shouldn't just relax now because you've passed, and that you will continue to learn after your test.","Минахте.“ Мисля, че просто искаше да ми покаже, че шофирането е опасно и не бива да се отпускаш сега, защото си взел изпита, и че ще продължиш да се учиш и след изпита.",[26925,26935,27029,27039,27066,27080,27100,27156,27168,27194,27206,27314,27377,27479,27519,27631,27673,27681,27736,27760,27808,27833,27861,27875,27933,27959,27992,28008,28025,28081,28094,28158,28186,28202],28241],[1,"Definitely.","Определено.",[28273],28338],[0,"Let's recap the vocabulary we've learned in this podcast, starting with to commute, which means to travel to work, either in a car, a train, a bus, some form of transport.","Нека преговорим думите, които научихме в подкаста, като започнем с „to commute“, което значи да пътуваш до работа – с кола, влак, автобус, някакъв вид транспорт.",[28992,29019,29084,29096,29178,29200,29244,29265,29283,29355,29410,29442,29466,29555,29579,29648,29662,29723,29744,29830,29860,29869,29873,29952,29956,30006,30017,30123,30144,30173,30181],30249],[1,"We also had speeding.","Имахме и „speeding“.",[30383,30409,30444,30494],30594],[1,"If you speed, you're going faster than you are allowed to - faster than the speed limit.","Ако „speed“-ваш, караш по-бързо, отколкото е позволено – по-бързо от ограничението на скоростта.",[30631,30650,30662,30730,30750,30791,30865,30889,30903,30923,30965,30965,31025,31075,31101,31110,31152],31209],[0,"We heard to park, which means to move your car into a space where you can leave it for a while.","Чухме „to park“, което значи да вкараш колата си на място, където да я оставиш за известно време.",[31221,31241,31290,31303,31356,31388,31431,31485,31534,31566,31631,31662,31667,31746,31764,31778,31795,31828,31846,31865,31869],31917],[0,"And the noun of that is parking.","А съществителното е „parking“.",[31963,31977,31983,32028,32041,32069,32095],32160],[1,"When you reverse a car, you drive it backwards.","Когато „reverse“ колата, я караш назад.",[32244,32264,32281,32334,32339,32389,32404,32435,32447],32519],[1,"And when you are parking, you often need to reverse.","А когато паркираш, често трябва да даваш на заден.",[32527,32562,32595,32613,32625,32701,32716,32762,32787,32800],32826],[0,"That's it for this episode of Real Easy English.","Това е за този епизод на Real Easy English.",[32827,32976,32995,33009,33035,33089,33107,33147,33184],33238],[0,"Why not test what you've learned with the free worksheet on our website, bbclearningenglish.com?","Защо не проверите какво научихте с безплатния работен лист на нашия сайт, bbclearningenglish.com?",[33238,33278,33300,33345,33362,33387,33451,33468,33475,33523,33571,33581,33590,33650],33829],[1,"And we'll be back next week with another conversation in easy English.","И ще се върнем следващата седмица с още един разговор на лесен английски.",[33857,33885,33903,33915,33941,33973,34011,34036,34074,34165,34183,34240],34295],[1,"See you soon.","До скоро.",[34309,34330,34338],34380],[0,"Goodbye.","Довиждане.",[34381],34466]],"v":[["commute","пътувам до работа",62],["speeding","превишаване на скоростта",31],["speed limit","ограничение на скоростта",35],["park","паркирам",38],["reverse","давам на заден ход",43],["motorway","магистрала",15],["accident","катастрофа",29],["pass a test","взимам изпит",57]],"g":[["traffic",8,1,1],["commuting",14,5,1],["motorway",15,46,1],["public transport",19,12,2],["accident",29,4,1],["speeding",31,12,1],["speed limit",35,10,2],["parking",38,5,1],["reverse",43,7,1],["backwards",44,4,1],["manoeuvres",51,27,1],["critical",57,18,1]],"q":[["Why was Beth late to work?","Защо Бет закъсня за работа?","the traffic was bad","she missed the train","her car broke down",8],["When does Beth enjoy driving?","Кога на Бет ѝ харесва да шофира?","on long journeys with music or podcasts","when she commutes to work","in the city centre",15],["Why doesn't Neil drive very often?","Защо Нийл не шофира много често?","he lives in London and uses public transport","he doesn't have a licence","he is afraid of cars",19],["What happened to Beth once?","Какво се случи веднъж с Бет?","she was caught speeding","she had an accident","she failed her driving test",31],["What doesn't Neil like about driving?","Какво не харесва Нийл в шофирането?","parking","singing in the car","the countryside",38],["How was the man who gave Neil his driving test?","Какъв беше човекът, който изпитваше Нийл?","very critical and even angry","very friendly","very quiet",57]]},"places":{"ser":"Real Easy English","icon":"🏞️","bg":"Град или село?","t":"Visiting places","a":"ree/audio/places.mp3","sp":["Georgie","Beth"],"L":[[0,"Hello and welcome to Real Easy English.","Здравейте и добре дошли в Real Easy English.",[36,80,103,151,169,213,268],331],[0,"In this podcast, we have real conversations in easy English to help you learn.","В този подкаст водим истински разговори на лесен английски, за да ви помогнем да учите.",[352,364,380,442,453,486,533,625,641,692,740,754,781,794],826],[0,"I'm Georgie.","Аз съм Джорджи.",[855,876],921],[1,"And I'm Beth.","А аз съм Бет.",[922,978,1007],1033],[1,"You can find a video of this podcast and a worksheet to help you practice what you've learnt on our website, bblearningenglish.com.","На нашия сайт ще намерите видео на подкаста и работен лист, с който да упражните наученото: bbclearningenglish.com.",[1090,1107,1122,1163,1178,1242,1255,1275,1343,1380,1387,1464,1481,1513,1529,1579,1598,1619,1687,1709,1729,1811],2012],[0,"How are you today, Beth?","Как си днес, Бет?",[2691,2707,2719,2735,2766],2795],[1,"I'm very well, thank you.","Много добре, благодаря.",[2841,2852,2875,2891,2916],2930],[1,"How are you?","Ти как си?",[2932,2941,2951],2982],[0,"Yes, I'm pretty good, thank you.","Да, доста добре съм, благодаря.",[2993,3018,3039,3062,3083,3111],3129],[1,"Good. So, what are we talking about today?","Добре. И така, за какво говорим днес?",[3130,3188,3214,3228,3236,3259,3298,3326],3361],[0,"Well, Beth, today we are talking about places.","Ами, Бет, днес говорим за места.",[3384,3419,3458,3495,3518,3530,3575,3603],3677],[0,"We'll talk about the city and the countryside and which we prefer.","Ще говорим за града и за природата извън града и какво предпочитаме.",[3719,3780,3819,3843,3850,3908,3945,3953,4040,4062,4096,4112],4148],[1,"Very nice. OK, let's start then.","Много хубаво. Добре, тогава да започваме.",[4242,4271,4343,4412,4434,4461],4484],[1,"So, Georgie, if you were going to visit somewhere, for example, would you prefer to visit the city or the countryside?","Е, Джорджи, ако щеше да посетиш някое място, например, какво би предпочела – град или провинцията?",[4537,4627,4786,4801,4817,4827,4867,4882,4970,5077,5103,5184,5212,5229,5284,5314,5356,5366,5412,5443,5453],5520],[0,"Are we talking about the UK or going abroad?","За Обединеното кралство ли говорим, или за пътуване в чужбина?",[5573,5589,5601,5641,5786,5803,5855,5886,5908],5948],[1,"Let's start with the UK.","Да започнем с Обединеното кралство.",[6126,6150,6176,6189,6198],6254],[0,"OK. If I visit somewhere in the UK, I would usually want to go to the countryside.","Добре. Ако посещавам някое място в Обединеното кралство, обикновено бих искала да отида в провинцията.",[6290,6380,6403,6428,6456,6492,6509,6520,6619,6670,6688,6803,6831,6845,6894,6914,6923],7023],[0,"That's because I live in a city.","Това е, защото живея в град.",[7086,7114,7228,7241,7255,7267,7270],7320],[0,"I live in London, but I'm from the countryside, so sometimes I crave going out into a more rural area where I can see more green space, there's more wildlife.","Живея в Лондон, но съм от провинцията, така че понякога силно ми се иска да отида в по-селски район, където виждам повече зеленина и има повече диви животни.",[7327,7339,7370,7388,7491,7503,7517,7542,7548,7620,7670,7770,7784,7925,7955,7981,8014,8017,8044,8090,8159,8172,8178,8195,8217,8238,8270,8500,8520,8534],8630],[0,"It's almost like you need to escape the busy hustle and bustle of the city.","Почти все едно имаш нужда да избягаш от забързаната суета на града.",[8736,8755,8791,8869,8877,8892,8903,8955,9011,9078,9109,9122,9186,9197,9208],9259],[1,"Yeah. D'you know, I, I completely agree with you.","Да. Знаеш ли, аз… напълно съм съгласна с теб.",[9297,9350,9372,9398,9478,9488,9538,9586,9606],9628],[1,"Cities in the UK are great.","Градовете в Обединеното кралство са страхотни.",[9666,9711,9719,9728,9850,9861],9905],[1,"There are some great cities, but I have visited quite a lot of them.","Има някои страхотни градове, но съм посетила доста от тях.",[9906,9922,9927,9953,9975,10022,10094,10111,10166,10230,10268,10273,10303,10314],10344],[1,"And after a while the cities are all similar.","И след известно време всички градове си приличат.",[10367,10505,10540,10544,10662,10671,10723,10742,10777],10820],[1,"Whereas the countryside, you can do different activities.","Докато в провинцията можеш да правиш различни неща.",[10821,10950,10960,11097,11109,11130,11149,11180],11293],[1,"It's really nice to see new places.","Наистина е хубаво да видиш нови места.",[11320,11337,11372,11400,11412,11466,11493],11560],[1,"I, a few years ago, I went to Kent and I had never been to Kent before because I'm from the north of England and Kent is in the south, and it was amazing.","Аз… преди няколко години отидох в Кент, а никога преди не бях ходила там, защото съм от северна Англия, а Кент е на юг, и беше невероятно.",[11583,11601,11716,11745,11775,11802,11816,11840,11851,11912,11930,11941,11959,11990,12011,12021,12061,12102,12158,12177,12203,12210,12238,12246,12362,12456,12491,12504,12516,12522,12581,12611,12623,12641],12722],[1,"They had different kinds of buildings and like architecture on the farms.","Имаха различни сгради и архитектура във фермите.",[12723,12734,12765,12799,12830,12880,12950,12962,12998,13078,13091,13097],13174],[1,"We don't have those same kind of roofs in the farms in the north.","На север във фермите нямаме такива покриви.",[13175,13188,13202,13225,13331,13366,13394,13403,13470,13497,13504,13573,13589,13634],13714],[0,"Yeah, I also went to Kent last year.","Да, и аз ходих в Кент миналата година.",[13748,13778,13801,13839,13859,13866,13903,13925],13963],[0,"I did, but I went to the seaside because Kent also has a bit of coastline.","Ходих, но отидох на морето, защото Кент има и малко крайбрежие.",[13964,13984,14016,14031,14048,14069,14075,14082,14203,14222,14281,14310,14354,14359,14372,14381],14456],[0,"Yeah. And yeah, I really enjoyed visiting Kent.","Да. И да, много ми хареса да посетя Кент.",[14475,14491,14578,14620,14640,14685,14772,14815],14859],[1,"And the villages are so like cute and picturesque, we could say.","А селата са толкова сладки и живописни, бихме могли да кажем.",[14859,14912,14932,14985,14988,15040,15107,15166,15256,15367,15384,15401],15453],[0,"What about when you go abroad?","А когато пътуваш в чужбина?",[15472,15493,15519,15531,15545,15625],15697],[0,"Do you, do you also visit the countryside in other countries?","И в други държави ли посещаваш провинцията?",[15697,15716,15822,15834,15847,15878,15903,15909,15978,15991,16006],16070],[1,"I have done, but to be honest, I would normally go to a city if I go abroad, maybe the capital city or maybe a smaller city.","Случвало ми се е, но честно казано, обикновено бих отишла в град, ако пътувам в чужбина – може би столицата или по-малък град.",[16132,16166,16204,16253,16280,16291,16303,16390,16413,16438,16483,16498,16514,16517,16589,16605,16615,16639,16690,16742,16751,16799,16844,16851,16882,16885,16928],16968],[1,"But one of the reasons for that, I think, is the transport.","Но мисля, че една от причините за това е транспортът.",[16969,17058,17086,17096,17118,17172,17184,17233,17246,17277,17295,17310],17404],[1,"It's so much easier to get a train or a bus when you're in a city.","Много по-лесно е да вземеш влак или автобус, когато си в град.",[17405,17443,17462,17486,17534,17641,17666,17669,17725,17755,17759,17854,17882,17925,17939,17944],18016],[1,"And you'd have to hire a car, I think, to visit a village or something like that.","А мисля, че ще трябва да наемеш кола, за да посетиш село или нещо такова.",[18059,18188,18206,18228,18238,18281,18284,18381,18391,18412,18423,18481,18487,18532,18539,18581,18600],18625],[0,"It's very true.","Много вярно.",[18644,18656,18681],18712],[0,"Usually if you go abroad, you fly to an airport and the airports are usually closer to the city.","Обикновено, ако пътуваш в чужбина, летиш до летище, а летищата обикновено са по-близо до града.",[18713,18767,18779,18788,18804,18909,18919,18987,18998,19006,19062,19072,19081,19147,19150,19194,19231,19245,19254],19309],[0,"And if you only have a few days in a place, it's easier to just stay in the city.","И ако имаш само няколко дни на едно място, по-лесно е просто да останеш в града.",[19369,19448,19460,19475,19491,19526,19531,19559,19622,19634,19641,19709,19725,19762,19775,19794,19818,19826,19832],19882],[0,"It's also, I guess, easier to do lots of, like, activities in the city when you visit and try out lots of the local restaurants, everything is closer together so you can do more things.","Предполагам, че е и по-лесно да правиш много неща в града, когато го посещаваш, и да опиташ много местни ресторанти – всичко е по-близо едно до друго, така че можеш да направиш повече.",[19984,20000,20065,20073,20169,20218,20394,20423,20453,20488,20500,20659,20666,20694,20753,20766,20776,20831,20905,20943,20963,20990,21048,21057,21091,21218,21256,21267,21305,21379,21388,21398,21413,21435,21450],21505],[1,"Well, I'm just thinking if you're in the city you can, like, search on your phone for really good restaurants really easily.","Ами, тъкмо си мислех, че ако си в града, можеш много лесно да потърсиш на телефона си наистина добри ресторанти.",[21524,21545,21560,21577,21674,21691,21704,21721,21728,21797,21817,21847,21921,21969,21978,21991,22073,22097,22119,22138,22187,22214],22268],[1,"But if I'm in Italy, for example, and I don't speak Italian, it would be really difficult, I think, for me to find a good restaurant because I wouldn't know where to go.","Но ако съм в Италия например и не говоря италиански, мисля, че ще ми е много трудно да намеря добър ресторант, защото няма да знам къде да отида.",[22285,22328,22353,22445,22459,22512,22528,22584,22603,22617,22673,22710,22819,22831,22854,22887,22934,23009,23022,23048,23062,23084,23097,23195,23209,23303,23351,23375,23382,23447,23481,23497,23512],23550],[1,"Sometimes it's the locals in the countryside that are able to tell you this.","Понякога местните хора на село са тези, които могат да ти кажат това.",[23550,23603,23653,23672,23814,23829,23837,23918,23943,23957,23983,23996,24025,24050],24078],[1,"It might not even be on the internet.","Може дори да го няма в интернет.",[24079,24092,24117,24137,24162,24241,24254,24265],24326],[0,"Yep. That's very true.","Да. Много вярно.",[24398,24425,24450,24475],24515],[0,"Let's recap the language we used in this conversation, starting with countryside land outside of towns and cities where there are not many buildings.","Нека преговорим езика, който използвахме в разговора, като започнем с „countryside“ – земята извън градовете, където няма много сгради.",[24549,24564,25013,25113,25148,25262,25306,25318,25333,25411,25480,25511,25647,25690,25732,25740,25785,25805,25861,25886,25900,25905,25941,25971],26053],[0,"We can also describe this with the adjective rural.","Можем да опишем това и с прилагателното „rural“ (селски).",[26056,26063,26079,26115,26167,26190,26204,26217,26319],26363],[1,"And hustle and bustle, the busyness and noise that you find in the city.","И „hustle and bustle“ – забързаността и шумът, които има в града.",[26444,26478,26528,26544,26627,26638,26712,26750,26804,26813,26830,26881,26900,26906],26963],[0,"We had picturesque, which means pretty or beautiful.","Имахме „picturesque“, което значи красив, живописен.",[27028,27038,27075,27160,27186,27219,27268,27285],27357],[0,"We often use this to describe a place.","Често го използваме, за да опишем място.",[27377,27398,27429,27452,27473,27484,27533,27538],27606],[1,"And visit, to go somewhere for a short time.","И „visit“ – отивам някъде за кратко време.",[27693,27717,27783,27811,27838,27884,27906,27919,27968],28006],[0,"That's it for this episode of Real Easy English.","Това е за този епизод на Real Easy English.",[28006,28110,28128,28136,28155,28212,28228,28276,28316],28372],[0,"Go to our website to find a worksheet to test what you've learned. bbclearningenglish.com","Отидете на нашия сайт, за да намерите работен лист и да проверите какво научихте: bbclearningenglish.com",[28373,28399,28412,28426,28475,28484,28511,28525,28588,28604,28634,28644,28658,28706],28900],[1,"And next week we'll be talking about gifts.","А следващата седмица ще говорим за подаръци.",[28950,28972,28999,29022,29045,29062,29108,29157],29225],[1,"So see you then.","Ще се чуем тогава.",[29225,29257,29278,29288],29308],[0,"Goodbye.","Довиждане.",[29339],29394]],"v":[["countryside","провинция, природа извън града",11],["rural","селски",18],["hustle and bustle","забързаност и шум",19],["picturesque","живописен",32],["visit","посещавам",13],["abroad","в чужбина",14],["wildlife","диви животни",18],["locals","местните хора",45]],"g":[["countryside",11,7,1],["abroad",14,8,1],["rural",18,18,1],["wildlife",18,29,1],["hustle and bustle",19,9,3],["similar",23,8,1],["architecture",27,8,1],["seaside",30,7,1],["picturesque",32,8,1],["hire a car",38,4,3],["local",42,23,1],["locals",45,3,1]],"q":[["Where does Georgie usually want to go in the UK?","Къде обикновено иска да отиде Джорджи в Обединеното кралство?","to the countryside","to another city","to the airport",16],["Where is Georgie from?","Откъде е Джорджи?","the countryside","Kent","Italy",18],["What did Beth like about Kent?","Какво хареса Бет в Кент?","the buildings and roofs on the farms","the big shops","the airport",27],["Where did Georgie go in Kent?","Къде отиде Джорджи в Кент?","to the seaside","to a farm","to a museum",30],["Where does Beth usually go when she travels abroad?","Къде обикновено ходи Бет, когато пътува в чужбина?","to a city","to a village","to the mountains",35],["Who can tell you about good restaurants in the countryside?","Кой може да ти каже за добри ресторанти на село?","the locals","the internet","the airport staff",45]]},"cities":{"ser":"Real Easy English","icon":"🏙️","bg":"Животът в големия град","t":"Cities","a":"ree/audio/cities.mp3","sp":["Neil","Georgie"],"L":[[0,"Hello, I'm Neil.","Здравейте, аз съм Нийл.",[35,77,100],136],[1,"And I'm Georgie.","А аз съм Джорджи.",[156,186,207],263],[1,"Welcome to Real Easy English.","Добре дошли в Real Easy English.",[274,313,339,382,432],491],[0,"You can find a worksheet and transcript for this episode on our website, bbclearningenglish.com","На нашия сайт ще намерите работен лист и текст на епизода: bbclearningenglish.com",[529,540,556,598,611,683,704,773,784,810,866,885,898,959],1168],[1,"Hello Neil. How are you doing?","Здравей, Нийл. Как си?",[1828,1855,1889,1909,1913,1929],1972],[0,"I'm very well, thank you, Georgie.","Много добре, благодаря, Джорджи.",[2027,2043,2062,2089,2118,2127],2169],[0,"How are you?","Ти как си?",[2170,2200,2211],2239],[1,"Yes, I'm very well, thank you.","Да, и аз съм много добре, благодаря.",[2260,2296,2338,2367,2392,2428],2459],[1,"Neil, today we're talking about cities.","Нийл, днес говорим за градовете.",[2495,2564,2629,2647,2704,2742],2829],[1,"We both live and work in London, which is a very big city.","И двамата живеем и работим в Лондон, който е много голям град.",[2878,2906,2943,3008,3029,3083,3104,3161,3180,3195,3199,3253,3278],3327],[0,"It is. It's a huge city - very busy and bustling.","Така е. Огромен град – много натоварен и оживен.",[3358,3370,3423,3439,3444,3509,3509,3634,3655,3766,3802],3869],[0,"Bustling means there's lots of activity, lots of things going on, busy.","„Bustling“ значи, че има много движение, много неща се случват – оживено.",[3870,4032,4077,4095,4184,4198,4277,4312,4319,4432,4465,4547],4600],[1,"Speaking of, what do you like about living in a big, bustling city?","Като стана дума – какво харесваш в живота в голям, оживен град?",[4643,4695,4752,4784,4805,4814,4875,4909,4967,4984,4989,5037,5104],5162],[0,"Well, there are lots of good things about living in a big city.","Ами, има много хубави неща в живота в голям град.",[5227,5381,5397,5400,5431,5442,5462,5528,5572,5631,5677,5698,5719],5767],[0,"It's convenient. It's very convenient.","Удобно е. Много е удобно.",[5834,5867,5992,6003,6022],6095],[0,"So, there is lots of public transport, which is sometimes good.","Има много градски транспорт, което понякога е добре.",[6125,6156,6181,6201,6234,6247,6295,6416,6488,6600,6659],6689],[0,"And you can get things that you need quite easily.","И можеш да намериш нещата, които ти трябват, доста лесно.",[6936,7178,7190,7212,7237,7276,7289,7306,7429,7466],7521],[1,"That's very true.","Много вярно.",[7522,7566,7592],7628],[0,"Yeah.","Да.",[7648],7676],[1,"Yeah. There's also a lot of things to do.","Да. Има и много неща за правене.",[7726,7748,7766,7795,7799,7823,7833,7865,7876],7922],[1,"We are lucky in London to have lots of theatres where you can see plays.","В Лондон имаме късмет, че има много театри, където можеш да гледаш пиеси.",[7960,7966,7982,7995,8086,8131,8228,8264,8289,8300,8457,8474,8488,8504,8524],8607],[1,"There's a really good music scene, so you can watch and listen to a lot of live music.","Има наистина добра музикална сцена, така че можеш да гледаш и слушаш много музика на живо.",[8623,8725,8735,8769,8809,8864,8914,8957,8979,8997,9088,9104,9137,9157,9162,9183,9197,9237],9293],[1,"If you have no plans on a day, you can always find plans, spontaneous plans, so we are really lucky in that sense.","Ако един ден нямаш планове, винаги можеш да си намериш, спонтанни планове, така че в това отношение наистина имаме късмет.",[9394,9410,9425,9449,9469,9554,9568,9574,9636,9648,9665,9716,9746,9829,9966,10017,10054,10073,10091,10115,10178,10188,10206],10252],[0,"Yeah, and if you like art, there's all kinds of exhibitions and galleries and museums.","Да, а ако харесваш изкуство, има всякакви изложби, галерии и музеи.",[10269,10329,10343,10354,10372,10432,10553,10578,10598,10645,10665,10762,10776,10891,10966],11041],[1,"Lots of good things.","Много хубави неща.",[11151,11191,11202,11222],11284],[1,"But there are obviously some bad things about living in a city, aren't there?","Но очевидно има и някои лоши неща в живота в град, нали?",[11284,11399,11430,11433,11557,11579,11604,11634,11659,11688,11696,11700,11744,11773],11804],[0,"Yes.","Да.",[11853],11904],[1,"Do you want to tell us some?","Искаш ли да ни кажеш някои?",[11923,11932,11940,11955,11961,11974,11988],12015],[0,"Yeah. Well, it's very noisy and dirty...","Да. Ами, много е шумно и мръсно…",[12062,12112,12177,12202,12274,12362,12446],12500],[1,"Yeah.","Да.",[12535],12560],[0,"...and busy and expensive.","…и натоварено, и скъпо.",[12561,12588,12746,12768],12860],[1,"Yeah.","Да.",[12890],12925],[0,"It's always more expensive in a big city, especially the capital city.","В голям град винаги е по-скъпо, особено в столицата.",[12926,12943,13011,13041,13111,13120,13125,13151,13234,13294,13301,13357],13406],[0,"So, you can do all of the things that we just talked about...","Така че можеш да правиш всички неща, за които току-що говорихме…",[13476,13728,13738,13756,13776,13804,13816,13827,13872,13883,13905,13936,13966],14011],[1,"Yeah.","Да.",[14045],14069],[0,"...but you have to pay for them.","…но трябва да плащаш за тях.",[14070,14096,14103,14122,14133,14168,14202],14265],[1,"Yeah!","Да!",[14276],14281],[0,"And things like eating out, especially going for a drink, is a really expensive thing to do in the capital city.","А неща като храненето навън, особено излизането на по питие, са наистина скъпи в столицата.",[14282,14296,14343,14448,14497,14594,14653,14686,14703,14709,14830,14846,14849,14891,14963,14988,14999,15053,15067,15079,15121],15165],[1,"I feel like every time I leave the house I just spend loads of money and that is quite frustrating, but you have to pay for good... for good times, I guess.","Имам чувството, че всеки път, когато изляза от къщи, харча куп пари и това е доста неприятно, но предполагам, че трябва да плащаш за… за хубавите моменти.",[15185,15200,15232,15267,15307,15352,15363,15385,15393,15445,15458,15492,15540,15568,15576,15682,15735,15769,15815,15839,15905,15996,16009,16027,16037,16073,16092,16152,16161,16179,16234,16245],16289],[0,"Yeah. Have you ever lived in another city apart from London?","Да. Живяла ли си в друг град освен Лондон?",[16298,16398,16418,16433,16456,16527,16540,16578,16628,16665,16687],16735],[1,"Yeah, I have.","Да, живяла съм.",[16792,16820,16840],16878],[1,"I used to live in Barcelona, which is quite different to London because, well, it has a beach and the sea on one side and on the other side it has mountains, so it's contained by nature and you can get to the nature quite quickly, which is really nice.","Преди живеех в Барселона, която е доста различна от Лондон, защото… ами, от едната страна има плаж и море, а от другата – планини, така че е заобиколена от природа и можеш да стигнеш до природата доста бързо, което е много хубаво.",[16879,16892,16932,16943,17006,17056,17162,17190,17208,17253,17306,17318,17367,17492,17505,17512,17562,17623,17689,17705,17712,17745,17756,17782,17865,17883,17896,17907,17923,17962,18002,18031,18106,18137,18177,18255,18274,18314,18352,18364,18445,18471,18501,18512,18551,18580,18788,18812,18825,18850],18904],[1,"What about you?","А ти?",[18917,18930,18952],18971],[1,"Have you lived anywhere different?","Живял ли си някъде другаде?",[18972,18986,19003,19026,19088],19151],[0,"Yeah, I've lived in a few big cities - a few capital cities, actually.","Да, живял съм в няколко големи града – всъщност в няколко столици.",[19156,19179,19212,19243,19255,19258,19316,19341,19341,19470,19501,19528,19577,19622],19671],[0,"I've also lived in Spain, but in Madrid.","Живял съм и в Испания, но в Мадрид.",[19672,19705,19741,19767,19801,19833,19875,19909],19997],[0,"I lived and worked in Prague and that is a really pretty... it's a beautiful city.","Живях и работих в Прага, а тя е наистина хубав… красив град.",[19998,20001,20020,20314,20333,20348,20381,20436,20521,20536,20542,20689,20813,20827,20830,20870],20920],[1,"Yeah.","Да.",[20933],20972],[0,"The architecture looks fantastic.","Архитектурата изглежда фантастично.",[20973,20986,21130,21170],21251],[1,"Nice buildings. Talking about nice buildings, I lived in Edinburgh because I did my master's degree there and that has beautiful buildings.","Хубави сгради. Като стана дума за хубави сгради – живях в Единбург, защото там учих магистратура, а там има красиви сгради.",[21300,21328,21384,21433,21461,21488,21547,21581,21605,21616,21700,21724,21741,21766,21894,21990,22028,22106,22127,22153,22219,22300],22355],[1,"I loved that city.","Много обичах този град.",[22356,22378,22452,22483],22538],[1,"It has a castle on a big rock in the middle and it's just amazing to look at.","Има замък на голяма скала по средата и е просто невероятно да го гледаш.",[22547,22559,22583,22587,22675,22694,22700,22753,22797,22812,22818,22909,22921,22937,22995,23039,23052,23073],23099],[1,"So, we've talked about cities we've been to.","И така, говорихме за градове, в които сме били.",[23140,23171,23184,23216,23239,23303,23325,23361],23406],[1,"What about the future?","А бъдещето?",[23453,23468,23492,23498],23562],[1,"Are there any cities you really want to visit or maybe even live in?","Има ли градове, които наистина искаш да посетиш или може би дори да живееш в тях?",[23590,23614,23628,23644,23698,23717,23750,23772,23781,23845,23856,23912,23945,23975],24014],[0,"Oh, that's an interesting question!","О, това е интересен въпрос!",[24064,24103,24133,24141,24206],24268],[0,"I've never been to Georgia or Armenia or that part of the world, so I'm going to say I'd like to go to Tbilisi in Georgia.","Никога не съм бил в Грузия или Армения, или в онази част на света, така че ще кажа, че бих искал да отида в Тбилиси в Грузия.",[24450,24481,24530,24638,24800,24859,24895,24975,24994,25012,25050,25056,25062,25171,25199,25224,25249,25256,25308,25329,25354,25366,25389,25425,25499,25512],25562],[1,"That's a good answer.","Добър отговор.",[25564,25647,25650,25667],25720],[1,"I'd love to go there as well.","И аз бих искала да отида там.",[25726,25744,25762,25773,25791,25809,25820],25856],[1,"For me, I'm desperate to go to Latin America.","За мен – отчаяно искам да отида в Латинска Америка.",[25909,25920,25980,26006,26070,26082,26113,26208,26237],26307],[1,"I really want to go to Rio de Janeiro, and at the time when the carnival is there, because that sounds really fun and I like to party!","Наистина искам да отида в Рио де Жанейро по време на карнавала, защото звучи много забавно, а аз обичам да купонясвам!",[26321,26329,26368,26391,26401,26499,26549,26574,26587,26675,26767,26777,26784,26841,26903,26939,26989,27007,27032,27133,27153,27186,27210,27280,27291,27300,27319,27326],27376],[1,"Let's recap the vocabulary we heard during the conversation, starting with bustling, which means busy with lots of people and activity.","Нека преговорим думите, които чухме в разговора, като започнем с „bustling“, което значи оживен, пълен с хора и движение.",[28039,28066,28102,28111,28188,28207,28250,28288,28295,28399,28456,28484,28562,28594,28628,28730,28743,28776,28786,28837,28858],28930],[0,"We also heard convenient.","Чухме и „convenient“.",[29014,29028,29078,29118],29202],[0,"If something is convenient, it means it's very easy to do it.","Ако нещо е „convenient“, значи е много лесно да се направи (удобно е).",[29242,29256,29313,29334,29413,29433,29465,29481,29538,29600,29625,29656],29681],[0,"For example, there's lots of public transport in London, so it's convenient for travel.","Например в Лондон има много градски транспорт, така че е удобно за пътуване.",[29713,29734,29827,29846,29881,29900,29950,30020,30040,30111,30138,30152,30238,30252],30301],[1,"And we talked about possible plans for the future, using would like to.","И говорихме за възможни планове за бъдещето с „would like to“.",[30349,30370,30382,30409,30436,30482,30524,30532,30542,30619,30672,30703,30734],30767],[0,"For example, I'd like to visit Tbilisi in Georgia.","Например: бих искал да посетя Тбилиси в Грузия.",[30818,30840,30921,30937,30965,30977,31022,31095,31115],31166],[1,"That's it for this episode of Real Easy English, but we'll be back next week with another conversation in easy English.","Това е за този епизод на Real Easy English, но ще се върнем следващата седмица с още един разговор на лесен английски.",[31209,31248,31273,31285,31306,31364,31385,31427,31470,31544,31577,31591,31605,31633,31663,31696,31717,31760,31859,31876,31922],31981],[0,"And you should check out our series The London to Edinburgh Challenge.","И разгледайте нашата поредица „Предизвикателството Лондон – Единбург“.",[32025,32070,32092,32122,32153,32179,32198,32255,32267,32316,32329,32382],32437],[0,"We've been talking about Edinburgh today.","Днес говорихме за Единбург.",[32463,32478,32495,32536,32577,32614],32659],[0,"It's a beautiful place and you can see it in this series.","Красиво място е и можете да го видите в тази поредица.",[32694,32707,32712,32750,32791,32812,32825,32841,32881,32921,32944,32969],33019],[0,"It's on our website, bbclearningenglish.com.","Тя е на нашия сайт, bbclearningenglish.com.",[33020,33040,33051,33065,33157],33346],[1,"Goodbye for now.","Засега довиждане.",[33406,33438,33452],33491],[0,"Goodbye!","Довиждане!",[33544],33595]],"v":[["bustling","оживен",10],["convenient","удобен",14],["would like to","бих искал да",56],["capital city","столица",32],["live music","музика на живо",21],["spontaneous","спонтанен",22],["eating out","хранене навън",37],["architecture","архитектура",48]],"g":[["bustling",10,10,1],["convenient",14,1,1],["theatres",20,9,1],["live music",21,16,2],["spontaneous",22,13,1],["exhibitions",23,10,1],["noisy",28,4,1],["expensive",30,3,1],["capital city",32,10,2],["eating out",37,3,2],["architecture",48,1,1],["castle",51,3,1]],"q":[["What does 'bustling' mean?","Какво значи „bustling“?","busy, with lots of activity","quiet and calm","old and dirty",11],["What can you see in London's theatres?","Какво можеш да гледаш в театрите на Лондон?","plays","football","films only",20],["What are the bad things about the city, says Neil?","Кои са лошите неща в града според Нийл?","noisy, dirty, busy and expensive","cold and boring","small and far away",30],["What is special about Barcelona, says Georgie?","Какво е специалното в Барселона според Джорджи?","it has the sea on one side and mountains on the other","it is very cold","it has no beach",41],["Why did Georgie live in Edinburgh?","Защо Джорджи е живяла в Единбург?","she did her master's degree there","she worked in a castle","her family lives there",49],["Which city would Neil like to visit?","Кой град би искал да посети Нийл?","Tbilisi","Rio de Janeiro","Madrid",56]]},"weekends":{"ser":"Real Easy English","icon":"🛋️","bg":"Уикендите","t":"Weekends","a":"ree/audio/weekends.mp3","sp":["Georgie","Phil"],"L":[[0,"Hello and welcome to Real Easy English.","Здравейте и добре дошли в Real Easy English.",[27,70,88,134,171,209,260],326],[0,"In this podcast, we have real conversations in easy English to help you learn.","В този подкаст водим истински разговори на лесен английски, за да ви помогнем да учите.",[341,352,370,445,462,501,534,632,661,699,769,780,809,819],847],[0,"I'm Georgie.","Аз съм Джорджи.",[866,885],930],[1,"And I'm Phil.","А аз съм Фил.",[979,1008,1038],1084],[1,"Remember, you can watch a video of this podcast on our website with subtitles to help you understand it.","Не забравяйте, че можете да гледате видео на подкаста на нашия сайт със субтитри, които ще ви помогнат да разберете.",[1129,1191,1206,1222,1249,1254,1318,1331,1347,1398,1416,1430,1484,1505,1589,1600,1640,1664,1717],1730],[1,"And that's bbclearningenglish.com.","Адресът е bbclearningenglish.com.",[1771,1780,1807],2034],[0,"Hello Phil. How are you doing?","Здравей, Фил. Как си?",[2732,2766,2837,2846,2854,2866],2902],[1,"I'm good, I'm good.","Добре съм, добре съм.",[2921,2934,2980,2991],3023],[1,"And I'm looking forward to the weekend.","И чакам с нетърпение уикенда.",[3054,3070,3086,3112,3143,3155,3162],3215],[0,"Me too. It's been a busy week and actually today we're talking about weekends.","И аз. Седмицата беше натоварена, а и днес всъщност говорим за уикендите.",[3255,3288,3331,3350,3368,3374,3400,3488,3496,3553,3595,3614,3672,3707],3788],[0,"We'll talk about what we usually do at the weekends.","Ще говорим какво обикновено правим през уикенда.",[3788,3812,3838,3870,3891,3913,3975,4041,4056,4063],4114],[0,"So, Phil, do you like weekends?","Е, Фил, обичаш ли уикендите?",[4116,4205,4299,4318,4330,4363],4428],[1,"I love weekends.","Обожавам уикендите.",[4472,4482,4523],4591],[1,"It's just great.","Просто са страхотни.",[4635,4661,4681],4716],[1,"You don't need to get up as early as you do during the week.","Не е нужно да ставаш толкова рано, колкото през седмицата.",[4716,4730,4764,4791,4802,4832,4872,4900,4974,4991,5000,5024,5060,5067],5105],[1,"And it's just a bit more relaxed.","И всичко е малко по-спокойно.",[5166,5212,5230,5248,5252,5266,5286],5359],[1,"That's nice.","Това е хубаво.",[5360,5375],5414],[0,"I know. Who doesn't like weekends?","Знам. Кой не обича уикендите?",[5441,5447,5519,5535,5564,5588],5661],[0,"Everyone needs some time off and time not doing work.","Всеки има нужда от почивка и от време, в което не работи.",[5698,5736,5765,5787,5854,5908,5923,5950,5970,5995],6034],[0,"What do you usually do at the weekends?","Какво обикновено правиш през уикенда?",[6098,6143,6151,6195,6240,6266,6275,6283],6341],[1,"Usually, as I say, I usually get up not very early, certainly not as early as during the week.","Обикновено, както казах, ставам не много рано – със сигурност не толкова рано, колкото през седмицата.",[6365,6498,6512,6516,6547,6556,6602,6631,6738,6797,6872,6922,6964,7000,7017,7072,7089,7125,7139],7192],[1,"My children go to play music at the weekends, so we have to make sure that they have breakfast and maybe we take them there or we pick them up, but apart from that, it's time... it's time when you don't have to do something specific.","Децата ми ходят да свирят музика през уикенда, така че трябва да се погрижим да закусят и може би да ги закараме или да ги вземем, но освен това е време… време, в което не трябва да правиш нещо конкретно.",[7322,7341,7378,7394,7411,7434,7484,7497,7505,7553,7584,7597,7611,7622,7642,7664,7686,7727,7747,7822,7856,7886,7906,7934,7955,7972,7991,8020,8042,8061,8148,8162,8198,8219,8302,8328,8477,8494,8518,8529,8539,8559,8596,8613,8682,8757],8839],[1,"So, maybe there's things to catch up on, maybe clean the house, but it's less pressure.","Може да има неща, които да наваксаш, може би да почистиш къщата, но има по-малко напрежение.",[8840,8937,8970,8992,9017,9028,9064,9083,9110,9163,9196,9203,9269,9377,9400,9419],9465],[0,"Yeah, you can kind of choose what you feel like doing.","Да, можеш някак да избереш какво ти се прави.",[9494,9507,9523,9537,9557,9566,9616,9633,9643,9690,9718],9766],[0,"For me, it depends whether I've had a busy week.","За мен зависи дали съм имала натоварена седмица.",[9858,9875,9898,9909,10022,10055,10097,10145,10155,10190],10231],[0,"If I've had a busy week of work, and sometimes I have social plans every evening, then at the weekends I prefer to just chill and catch up on my home things, like cleaning.","Ако съм имала натоварена работна седмица, а понякога имам срещи с приятели всяка вечер, тогава през уикенда предпочитам просто да почивам и да наваксам домашните неща, като чистенето.",[10233,10258,10273,10431,10438,10469,10493,10503,10578,10616,10658,10665,10715,10765,10812,10848,10912,10966,10980,10988,11073,11083,11143,11190,11219,11272,11306,11350,11373,11469,11486,11523,11558,11575],11641],[0,"But if I've had quite a quiet week, I like to be quite active.","Но ако седмицата ми е била доста спокойна, обичам да съм доста активна.",[11736,11747,11761,11777,11805,11828,11834,11883,11966,12008,12044,12055,12072,12094],12145],[0,"So, I like to make plans with friends, do some exercise.","Обичам да правя планове с приятели, да спортувам.",[12147,12222,12233,12255,12311,12334,12364,12375,12452,12466,12488],12594],[0,"Yeah, so it kind of depends, but that's why weekends are good, because you can kind of choose what you do.","Да, значи някак зависи, но затова уикендите са хубави – защото можеш някак да избираш какво да правиш.",[12794,12848,12863,12873,12894,12903,12964,12980,13003,13089,13128,13131,13169,13203,13209,13222,13249,13289,13383,13405,13412],13440],[1,"Yeah. I always think it's nice to make the most of the weekend when you can, particularly... especially, you get up on a Saturday or a Sunday and it's really sunny and it's nice - you kind of want to do something don't you?","Да. Винаги си мисля, че е хубаво да използваш уикенда максимално, когато можеш, особено… особено ако станеш в събота или неделя и е много слънчево и хубаво – някак ти се иска да направиш нещо, нали?",[13511,13539,13549,13572,13594,13609,13634,13644,13669,13681,13743,13756,13765,13846,13872,13887,13912,14041,14078,14099,14127,14149,14165,14169,14236,14249,14252,14290,14302,14311,14334,14413,14457,14476,14476,14607,14620,14641,14648,14663,14669,14690,14727,14744],14755],[1,"Go out for a walk or visit somewhere new.","Да излезеш на разходка или да посетиш някое ново място.",[14756,14773,14788,14806,14809,14873,14928,14973,15001],15036],[0,"Yeah, that's true.","Да, вярно е.",[15052,15090,15120],15152],[0,"But if it's raining, my favourite thing at the weekend is to, yeah, not set my alarm, wake up still kind of early, go down, make a coffee, bring it to bed, have a coffee in bed, and either read or watch an episode of something, a YouTube video.","Но ако вали, любимото ми нещо през уикенда е да не си навивам алармата, да се събудя пак някак рано, да сляза, да си направя кафе, да го донеса в леглото, да си пия кафето в леглото и или да чета, или да гледам епизод от нещо, видео в YouTube.",[15153,15214,15231,15247,15356,15367,15419,15491,15672,15683,15728,15752,15805,15824,15852,15871,15888,16005,16035,16049,16078,16105,16113,16187,16203,16276,16300,16305,16379,16403,16416,16427,16501,16516,16520,16555,16568,16629,16640,16674,16774,16860,16935,16995,17050,17058,17107,17113,17159],17215],[0,"That's my favourite thing, because you don't have to suddenly get up and go.","Това е любимото ми нещо, защото не трябва изведнъж да ставаш и да тръгваш.",[17216,17258,17273,17318,17374,17395,17402,17419,17438,17450,17491,17510,17532,17544],17572],[1,"OK. So, we're talking about weekends, Georgie.","Добре. Значи говорим за уикендите, Джорджи.",[17680,17703,17722,17747,17785,17809,17856],17897],[1,"Do you have any plans for this weekend?","Имаш ли планове за този уикенд?",[17965,17978,18000,18022,18040,18084,18097,18146],18209],[0,"Yes, I do.","Да, имам.",[18297,18346,18377],18450],[0,"So, a lot of my friends are turning 30 years old this year, and on Saturday I have a 30th birthday party, so that's in the evening.","Много от приятелите ми навършват 30 години тази година и в събота имам рожден ден за 30-ия, който е вечерта.",[18456,18480,18584,18602,18609,18625,18665,18669,18731,18809,18835,18856,18880,18928,18963,18976,19041,19057,19092,19101,19171,19225,19377,19462,19486,19496,19512],19572],[0,"I think it will probably be a late night, so on Sunday I think I'm going to take it easy.","Мисля, че вероятно ще стане късно, така че в неделя мисля да си почивам.",[19573,19587,19681,19693,19706,19767,19818,19827,19860,19947,19992,20008,20144,20147,20178,20189,20202,20228,20258,20267],20318],[0,"So, just relax, not make any plans and just see... see where the wind blows me!","Просто да се отпусна, да не правя планове и просто да видя… да видя накъде ще ме отвее вятърът!",[20330,20352,20380,20465,20480,20508,20524,20637,20647,20665,20753,20784,20803,20815,20848,20888],20909],[1,"That's nice.","Хубаво.",[21072,21097],21136],[0,"What about you, Phil?","А ти, Фил?",[21137,21150,21173,21194],21231],[1,"Well, we had quite a busy weekend last weekend, so this weekend, there's a lot of things that we need to get done.","Ами, миналия уикенд беше доста натоварен, така че този уикенд има много неща, които трябва да свършим.",[21244,21315,21328,21351,21382,21390,21423,21492,21540,21652,21703,21738,21842,21860,21866,21885,21901,21966,21982,21999,22024,22038,22067],22144],[1,"We can't just take it easy.","Не можем просто да си почиваме.",[22148,22158,22198,22215,22239,22251],22291],[0,"Urgh.","Уф.",[22366],22382],[1,"We need to clean the house and just organise some of those... those life admin things - those little tasks that we haven't done.","Трябва да почистим къщата и да организираме някои от тези… тези дребни битови задачи – малките неща, които не сме свършили.",[22383,22404,22425,22485,22512,22524,22585,22601,22629,22688,22732,22744,22797,22819,22850,22919,22919,22968,22984,23015,23072,23104,23119,23150],23169],[1,"We need to get them done...","Трябва да ги свършим…",[23169,23191,23206,23218,23253,23271],23303],[0,"Yeah.","Да.",[23315],23362],[1,"...this weekend.","…този уикенд.",[23363,23393],23441],[0,"Will you do anything fun?","Ще направите ли нещо забавно?",[23462,23472,23481,23512,23588],23631],[1,"We'll see. If we get time, yeah.","Ще видим. Ако имаме време, да.",[23781,23831,23865,23876,23885,23903,23950],23976],[0,"If you get the... if you get the things done.","Ако… ако свършите нещата.",[24000,24012,24021,24043,24063,24082,24090,24108,24116,24152],24182],[1,"Yes. If we get everything done, we can...","Да. Ако свършим всичко, можем…",[24213,24242,24257,24266,24280,24316,24403,24412],24438],[1,"Well, we can chill or we can do something nice.","Ами, можем да почиваме или да направим нещо хубаво.",[24498,24519,24530,24547,24590,24597,24609,24622,24633,24663],24700],[0,"Ah nice. OK.","О, хубаво. Добре.",[24718,24734,25557],25593],[0,"Let's recap the language we heard during the conversation.","Нека преговорим езика, който чухме в разговора.",[25594,25632,25677,25685,25733,25752,25795,25828,25835],25921],[0,"We heard make the most of something.","Чухме „make the most of something“.",[25959,25970,26015,26051,26063,26105,26113],26168],[0,"If you make the most of your weekend, you use the time well - you don't waste it.","Ако „make the most of your weekend“, използваш времето добре – не го губиш.",[26222,26232,26244,26275,26287,26321,26331,26343,26426,26440,26476,26485,26536,26536,26593,26600,26631,26666],26688],[1,"We also heard get something done, which means to complete a task.","Чухме и „get something done“, което значи да свършиш задача.",[26796,26816,26848,26902,26949,27012,27097,27115,27144,27156,27231,27239],27295],[1,"It might be something like cleaning your house.","Например да почистиш къщата.",[27296,27316,27338,27345,27381,27429,27472,27487],27532],[1,"If you do that, you got something done over the weekend.","Ако го направиш, си свършил нещо през уикенда.",[27537,27550,27559,27579,27626,27644,27681,27729,27763,27791,27800],27850],[0,"We also heard take it easy or chill, which means you relax and don't do much.","Чухме и „take it easy“ или „chill“, което значи, че почиваш и не правиш много.",[27933,27947,27981,28016,28062,28069,28127,28145,28214,28232,28263,28275,28338,28365,28393,28416],28463],[1,"We talked about this weekend and when we say this weekend, we mean the one that's coming - the one that's at the end of this week.","Говорихме за „this weekend“ – когато казваме „this weekend“, имаме предвид идващия уикенд, този в края на тази седмица.",[28547,28556,28581,28622,28680,28731,28746,28790,28802,28837,28878,28983,28995,29027,29037,29082,29109,29109,29152,29175,29211,29243,29250,29266,29289,29307,29347],29393],[0,"And that's it for this episode of Real Easy English, but we'll be back next week with another conversation in easy English.","Това е за този епизод на Real Easy English, но ще се върнем следващата седмица с още един разговор на лесен английски.",[29417,29432,29462,29483,29494,29522,29581,29598,29641,29681,29738,29760,29789,29801,29826,29863,29897,29913,29956,30055,30077,30118],30169],[1,"Try the worksheet on our website to practise what you've learnt.","Опитайте работния лист на нашия сайт, за да упражните наученото.",[30227,30252,30262,30330,30350,30375,30426,30445,30519,30547,30567],30606],[1,"And that's at bbclearningenglish.com.","Адресът е bbclearningenglish.com.",[30631,30639,30667,30693],30922],[0,"Goodbye for now!","Засега довиждане!",[30962,30997,31011],31039],[1,"Bye!","Чао!",[31066],31101]],"v":[["make the most of","използвам максимално",29],["get something done","свършвам нещо",58],["take it easy","почивам си, не се натоварвам",38],["chill","почивам, отпускам се",25],["this weekend","този (идващ) уикенд",35],["catch up on","наваксвам",22],["life admin","дребни битови задачи",45],["looking forward to","очаквам с нетърпение",8]],"g":[["looking forward to",8,2,3],["time off",18,3,2],["catch up on",22,5,3],["pressure",22,15,1],["chill",25,24,1],["active",26,13,1],["make the most of",29,7,4],["alarm",32,16,1],["take it easy",38,17,3],["get done",42,21,2],["life admin",45,13,2],["tasks",45,19,1]],"q":[["Why does Phil love weekends?","Защо Фил обожава уикендите?","he doesn't need to get up early","he can work more","he goes to school",14],["What do Phil's children do at the weekends?","Какво правят децата на Фил през уикенда?","they play music","they play football","they go swimming",21],["What does Georgie do after a busy week?","Какво прави Джорджи след натоварена седмица?","she chills and cleans her home","she goes on a trip","she works more",25],["What is Georgie's favourite thing on a rainy weekend?","Кое е любимото нещо на Джорджи в дъждовен уикенд?","coffee in bed with a book or a video","a long walk","shopping",32],["What is Georgie doing on Saturday?","Какво прави Джорджи в събота?","going to a 30th birthday party","cleaning the house","visiting her parents",37],["What must Phil do this weekend?","Какво трябва да направи Фил този уикенд?","clean the house and do life admin","go to a party","take it easy",45]]},"housework":{"ser":"Real Easy English","icon":"🧹","bg":"Домакинската работа","t":"Housework","a":"ree/audio/housework.mp3","sp":["Georgie","Phil"],"L":[[0,"Hi, Phil. How are you doing?","Здравей, Фил. Как си?",[35,54,63,69,76,88],132],[1,"I'm good, I'm good.","Добре съм, добре съм.",[156,189,249,262],298],[1,"A little bit tired, but yeah.","Малко уморен, но да.",[299,309,342,351,366,383],403],[1,"I'm good.","Добре съм.",[404,424],446],[0,"Oh no. Why?","О, не. Защо?",[447,521,536],541],[1,"Lots of housework this weekend.","Много домакинска работа този уикенд.",[542,598,607,635,644],679],[1,"We had to get the house ready so, yeah, a lot to do.","Трябваше да приготвим къщата, така че, да, много работа.",[680,689,701,714,732,748,786,801,832,838,841,855,872],902],[0,"You said ready?","Каза „да приготвите“?",[907,2991,3013],3073],[0,"Ready for what?","За какво?",[3096,3121,3134],3168],[1,"Oh, we've got some people coming to visit, so we had to... we had to get ready for that.","А, ще ни идват гости, така че трябваше… трябваше да се приготвим за това.",[3193,3205,3220,3234,3248,3270,3294,3303,3348,3381,3391,3408,3445,3456,3473,3480,3495,3514,3530],3552],[0,"Well, Phil, we are talking about housework today in Real Easy English.","Е, Фил, днес в Real Easy English говорим за домакинската работа.",[3585,3617,3666,3702,3720,3778,3809,3860,3913,3930,3956,3994],4048],[0,"So, housework is all of those jobs you do in the house.","Домакинската работа са всички онези задачи, които вършиш вкъщи.",[4049,4089,4145,4152,4161,4169,4183,4195,4205,4212,4219,4229],4243],[0,"So, cleaning, washing, cooking - things like that.","Чистене, пране, готвене – такива неща.",[4243,4251,4272,4292,4292,4311,4328,4340],4352],[1,"Yep. All really important things.","Да. Все много важни неща.",[4352,4362,4371,4388,4413],4429],[1,"Just before we start, I just wanted to remind everyone that they can go to our website to get a worksheet to get even more practice, and that is bblearningenglish.com.","Точно преди да започнем, исках да напомня на всички, че могат да отидат на нашия сайт за работен лист за още повече упражнения – адресът е bbclearningenglish.com.",[4429,4441,4458,4466,4480,4485,4497,4514,4521,4538,4560,4572,4584,4594,4601,4608,4618,4637,4644,4654,4659,4683,4690,4700,4712,4724,4746,4755,4767,4775],4850],[0,"So, Phil, you said at the weekend you did a lot of housework.","Е, Фил, каза, че през уикенда си свършил много домакинска работа.",[4850,4857,4869,4878,4912,4932,4939,4995,5012,5040,5045,5063,5079],5178],[0,"What did you do?","Какво направи?",[5179,5232,5247,5258],5282],[1,"Well, I mean we share out the housework, but I was...","Ами, ние си поделяме домакинската работа, но аз…",[5347,5389,5395,5413,5440,5467,5481,5488,5549,5631,5645],5689],[1,"I had to make sure I was cleaning the kitchen.","Трябваше да се погрижа да изчистя кухнята.",[5739,5742,5753,5761,5779,5795,5802,5821,5871,5879],5932],[1,"I also did...","Също така…",[6019,6102,6143],6196],[1,"We say do the hoovering or do the vacuuming, around all the carpets to make sure that's nice and clean, under all the furniture.","Казваме „do the hoovering“ или „do the vacuuming“ (минавам с прахосмукачката) – по всички килими, за да са хубави и чисти, и под всички мебели.",[6250,6256,6272,6298,6306,6357,6366,6384,6398,6506,6588,6609,6620,6684,6694,6711,6722,6742,6762,6775,6817,6836,6845,6853],6925],[1,"So, Georgie, do you do a lot of housework?","Е, Джорджи, ти вършиш ли много домакинска работа?",[6989,7042,7095,7108,7141,7161,7166,7180,7188],7253],[0,"Well, I live in a shared flat, so I have two housemates, who are not super clean, so I have a bit of a routine with them.","Ами, живея в споделен апартамент с двама съквартиранти, които не са супер чисти, така че имаме нещо като график.",[7289,7330,7353,7397,7422,7425,7484,7533,7567,7584,7608,7647,7762,7800,7906,7937,7992,8092,8110,8141,8195,8200,8220,8235,8243,8304,8322],8363],[0,"Every weekend, one person will clean the communal areas.","Всеки уикенд един човек чисти общите части.",[8387,8420,8505,8527,8599,8681,8737,8774,8835],8907],[0,"So, those are the areas that are shared - so the kitchen and the living room.","Това са частите, които са общи – кухнята и хола.",[8908,8938,8970,8973,8984,9105,9135,9140,9140,9221,9232,9238,9298,9310,9316,9349],9391],[0,"One person will clean those properly.","Един човек ги почиства както трябва.",[9433,9464,9500,9511,9555,9578],9641],[0,"So, wipe the surfaces, wipe away the crumbs.","Избърсва повърхностите, избърсва трохите.",[9642,9738,9776,9785,9890,9925,9951,9958],10009],[0,"So, the crumbs are little bits of food.","Трохите са малки парченца храна.",[10010,10028,10035,10080,10093,10116,10141,10149],10206],[0,"Then hoover or sweep the floor.","После минава с прахосмукачката или мете пода.",[10247,10298,10372,10390,10437,10446],10494],[0,"So, that removes the crumbs from the floor so that the floor is ready to be mopped.","Това маха трохите от пода, за да е готов подът за миене с моп.",[10505,10517,10528,10576,10583,10629,10644,10651,10741,10760,10788,10805,10837,10850,10908,10919,10933],10990],[0,"So, when you mop, that's when you make the floor wet and properly clean.","Когато „mop“, мокриш пода и го почистваш както трябва.",[10998,11016,11031,11041,11081,11110,11128,11200,11220,11228,11255,11311,11337,11382],11420],[1,"That's a really impressive system.","Това е наистина впечатляваща система.",[11421,11445,11450,11500,11550],11601],[1,"I like the way you've got it so organised.","Харесва ми колко добре сте я организирали.",[11715,11724,11737,11743,11754,11763,11773,11780,11809],11858],[1,"We always find we run out of time to get a lot of housework done, or we're doing stuff at the weekend or we're working during the week, and so some of those jobs, they get put off and put off and put off, which isn't good.","При нас винаги се оказва, че нямаме време да свършим много домакинска работа – или правим нещо през уикенда, или работим през седмицата, и някои от задачите се отлагат, и отлагат, и отлагат, което не е добре.",[11881,11893,11912,11935,11946,11980,11994,12005,12098,12109,12133,12142,12158,12164,12202,12228,12236,12248,12275,12297,12303,12309,12370,12373,12389,12439,12464,12472,12562,12570,12587,12612,12619,12639,12706,12719,12741,12772,12812,12828,12853,12878,12896,12921,12989,13007,13031],13064],[1,"But yeah, it happens sometimes.","Но да, случва се понякога.",[13088,13199,13214,13242,13282],13333],[0,"Well, there's also just so many other things we would rather be doing.","Е, просто има и толкова много други неща, които бихме предпочели да правим.",[13359,13370,13390,13420,13457,13487,13517,13538,13582,13596,13611,13655,13670],13723],[0,"So, yeah, it's easy to put off - to delay.","Така че, да, лесно е да отложиш – да забавиш.",[13732,13811,13850,13869,13907,13952,13977,13977,13997,14011],14067],[1,"Georgie, we're talking about household chores.","Джорджи, говорим за домакинските задължения.",[14117,14183,14191,14225,14263,14318],14362],[1,"Is there one that you really hate doing?","Има ли едно, което наистина мразиш да правиш?",[14420,14445,14464,14503,14523,14550,14633,14717],14755],[0,"Yes, Phil, there is one job that comes to mind immediately, which is cleaning the bathroom - specifically cleaning the toilet.","Да, Фил, има една задача, която веднага ми идва наум – почистването на банята, по-точно почистването на тоалетната.",[14805,14837,14888,14916,14928,14953,14984,15006,15035,15044,15088,15190,15225,15260,15300,15306,15306,15401,15506,15546,15553],15594],[1,"Oh yes.","О, да.",[15628,15644],15684],[0,"Not very nice!","Не е много приятно!",[15699,15716,15735],15768],[1,"Yeah. No, not at all.","Да. Не, изобщо.",[15784,15800,15825,15846,15863],15878],[0,"Do you have one that you hate the most?","А ти имаш ли задача, която мразиш най-много?",[15968,15981,15996,16015,16032,16044,16056,16081,16090],16137],[1,"I think what I really dislike is trying to clean things - the bits on the cooker where everything gets stuck on, and you have to really rub it and scrub it really hard.","Мисля, че това, което наистина не обичам, е да почиствам неща – частите на печката, където всичко залепва и трябва наистина да търкаш и да стържеш много силно.",[16211,16219,16300,16328,16331,16413,16478,16494,16533,16546,16603,16603,16697,16706,16738,16752,16759,16822,16861,16916,16956,17000,17024,17037,17044,17053,17066,17119,17166,17191,17205,17271,17284,17352],17406],[1,"I hate those jobs.","Мразя тези задачи.",[17513,17531,17546,17568],17603],[0,"So, do you...","А ти…",[17622,17641,17681],17743],[0,"You said that you share... you share the chores.","Каза, че си поделяте… поделяте задълженията.",[17744,17759,17777,17788,17797,17855,17865,17900,17962],18019],[0,"Do you get your kids to do chores?","Караш ли децата си да вършат домакинска работа?",[18057,18078,18117,18144,18162,18201,18214,18232],18285],[1,"Now, that's a really good question.","Това е наистина добър въпрос.",[18303,18316,18334,18338,18360,18376],18423],[1,"We ask the kids to do chores and sometimes they do something.","Молим децата да вършат задачи и понякога правят нещо.",[18462,18481,18532,18541,18579,18591,18611,18746,18792,18942,18968,19091],19138],[0,"OK.","Добре.",[19189],19220],[1,"But not a lot.","Но не много.",[19221,19246,19279,19282],19304],[1,"I'd really like them to be able to keep their rooms tidy.","Наистина бих искал да могат да поддържат стаите си подредени.",[19348,19369,19420,19461,19480,19490,19499,19513,19522,19567,19585,19622],19670],[1,"That's never going to happen, it feels.","Имам чувството, че това никога няма да стане.",[19747,19779,19816,19830,19836,19897,19909],19975],[1,"I'd really like it if they could, you know, help out cleaning the living room and putting things away.","Наистина бих искал да могат, знаеш, да помагат с чистенето на хола и с прибирането на нещата.",[20027,20084,20119,20157,20173,20191,20203,20247,20256,20272,20307,20334,20372,20379,20413,20431,20441,20472,20497],20533],[1,"But, yeah, we haven't taught them very well.","Но, да, не сме ги научили много добре.",[20534,20627,20647,20661,20685,20709,20720,20742],20778],[0,"Oh, maybe one day!","О, може би някой ден!",[20796,20883,20908,20931],20956],[1,"Maybe.","Може би.",[20990],21042],[0,"It's when you become an adult, I think, that you really appreciate a clean space, so hopefully that will come.","Мисля, че когато станеш възрастен, наистина започваш да цениш чистото пространство, така че дано и това дойде.",[21058,21071,21086,21094,21124,21134,21181,21191,21222,21243,21262,21293,21375,21381,21416,21477,21497,21556,21581,21592],21621],[1,"I was terrible as a teenager.","Аз бях ужасен като тийнейджър.",[21656,21667,21684,21746,21759,21765],21821],[1,"I didn't do much as a teenager at all, so this is just coming back to me now.","Като тийнейджър изобщо не правех много, така че сега просто ми се връща.",[21900,21986,22030,22045,22078,22089,22097,22144,22161,22178,22277,22297,22306,22323,22350,22377,22389,22403],22428],[0,"Yeah. Well, me too!","Да. Е, и аз!",[22455,22503,22516,22533],22560],[0,"So, we've talked about chores that we hate doing, but are there any jobs that you enjoy doing?","И така, говорихме за задачите, които мразим, но има ли задачи, които ти харесва да вършиш?",[22601,22612,22623,22647,22666,22706,22724,22773,22799,22938,22982,22995,23009,23027,23064,23080,23133,23178],23212],[1,"Well, you know what?","Ами, знаеш ли какво?",[23359,23376,23388,23401],23451],[1,"Laundry or washing - that's washing your clothes.","Прането – това е пране на дрехите.",[23503,23577,23591,23591,23655,23672,23705,23716],23781],[1,"That can sometimes be really satisfying when you get a lot of it done.","Понякога може да е наистина удовлетворяващо, когато изпереш много.",[23836,23859,23873,23918,23931,23972,24051,24062,24070,24084,24091,24125,24138,24149],24196],[1,"And actually, I've just got a new washing machine and it's much bigger than the one I had before, so I can do so much in one load.","А всъщност току-що си взех нова пералня и тя е много по-голяма от старата, така че мога да изпера толкова много наведнъж.",[24244,24295,24368,24378,24399,24414,24417,24439,24472,24562,24593,24619,24649,24692,24713,24719,24739,24750,24769,24817,24834,24842,24863,24882,24936,25011,25029,25050],25094],[0,"Phil, that is so exciting.","Фил, това е толкова вълнуващо.",[25129,25165,25182,25200,25263],25340],[1,"Even better - because it's summer at the moment, I can get it dry so quick.","Още по-хубаво – понеже сега е лято, мога да го изсуша толкова бързо.",[25341,25371,25371,25406,25447,25467,25509,25517,25525,25614,25624,25637,25649,25658,25699,25747],25808],[1,"It's amazing!","Невероятно е!",[25810,25835],25875],[0,"I love that!","Обожавам това!",[25875,25888,25898],25922],[0,"Putting a... putting a load of washing in the washing machine and then having it dry by the end of the day.","Да сложиш… да сложиш пране в пералнята и после да е сухо до края на деня.",[25948,25975,26063,26095,26107,26144,26204,26307,26331,26397,26426,26473,26495,26542,26574,26581,26619,26635,26647,26666,26672,26683],26724],[0,"That is so good.","Това е толкова хубаво.",[26732,26745,26756,26781],26813],[1,"It's the best thing.","Най-хубавото нещо е.",[26860,26887,26897,26924],26949],[0,"Teenage Georgie would be so disappointed that I'm excited by laundry, but here we go...!","Тийнейджърката Джорджи щеше да е толкова разочарована, че се вълнувам от пране, но какво да се прави…!",[27031,27079,27122,27137,27152,27192,27263,27278,27302,27355,27370,27432,27456,27473,27481],27505],[0,"OK. Phil, let's recap the vocabulary we used in this conversation, starting with housework.","Добре. Фил, нека преговорим думите, които използвахме в разговора, като започнем с „housework“.",[28080,28102,28150,28178,28223,28232,28304,28323,28375,28393,28407,28497,28553,28571],28646],[0,"So, this is the general term for jobs that we have to do in the house.","Това е общата дума за задачите, които трябва да вършим вкъщи.",[28647,28679,28708,28730,28742,28786,28835,28894,28925,28938,28949,28968,28981,29030,29051,29057],29106],[0,"And then we had chores, which are the specific jobs that you have to do - for example, laundry.","После имахме „chores“ – конкретните задачи, които трябва да вършиш, например прането.",[29156,29184,29208,29215,29244,29305,29326,29351,29362,29430,29469,29482,29493,29508,29519,29519,29559,29578,29656],29714],[1,"Yes. So, laundry is washing your clothes.","Да. „Laundry“ е прането на дрехите.",[29748,29782,29828,29930,29949,30003,30023],30083],[1,"We say do the laundry, or just do the washing.","Казваме „do the laundry“ или просто „do the washing“.",[30084,30096,30118,30155,30164,30211,30242,30287,30316,30325],30406],[0,"Yes. And we had some other chores - for example, hoovering and sweeping the floor, which is what you do when there are crumbs on the floor.","Да. И имахме и други задачи – например минаването с прахосмукачката и метенето на пода, което правиш, когато на пода има трохи.",[30459,30500,30514,30522,30544,30568,30589,30589,30642,30656,30711,30788,30838,30919,30929,30974,31002,31016,31031,31044,31083,31102,31125,31131,31171,31181,31188],31225],[0,"After you've swept the crumbs, you can mop the floor, which is when you make the floor wet and clean it like that.","След като изметеш трохите, можеш да измиеш пода с моп – тоест го мокриш и го почистваш така.",[31278,31356,31378,31489,31530,31583,31606,31630,31667,31679,31727,31752,31764,31781,31796,31820,31830,31893,31960,31974,31999,32008,32028],32050],[1,"Yes. We also talked about jobs that you hate, and sometimes when you really hate a job, you end up putting it off - that means to delay it.","Да. Говорихме и за задачите, които мразиш, а понякога, когато наистина мразиш някоя задача, накрая я отлагаш – това значи да я забавиш.",[32082,32105,32127,32165,32192,32230,32279,32301,32333,32439,32483,32565,32584,32598,32626,32663,32670,32764,32781,32799,32835,32898,32939,32939,33002,33026,33054,33069,33131],33164],[1,"If you put something off, you delay something, sometimes because you just don't want to do it.","Ако „put something off“, отлагаш нещо, понякога защото просто не искаш да го правиш.",[33166,33184,33198,33218,33253,33275,33288,33332,33413,33465,33490,33497,33544,33569,33585,33595,33618],33630],[0,"So, that is the end of this episode of Real Easy English, but we'll be back next week, won't we?","Е, това е краят на този епизод на Real Easy English, но ще се върнем следващата седмица, нали?",[33668,33689,33747,33761,33774,33802,33817,33838,33886,33905,33935,33976,34030,34060,34075,34088,34118,34142,34162,34183],34207],[1,"Yes, we'll be back with another episode.","Да, ще се върнем с още един епизод.",[34253,34293,34307,34314,34327,34347,34404],34446],[1,"Also, don't forget about that worksheet that's on our website, bbclearningenglish.com.","И не забравяйте работния лист на нашия сайт, bbclearningenglish.com.",[34493,34520,34559,34609,34631,34658,34726,34747,34762,34774,34835],35037],[0,"Goodbye for now.","Засега довиждане.",[35056,35090,35103],35135],[1,"Bye!","Чао!",[35195],35238]],"v":[["housework","домакинска работа",5],["chores","домакински задължения",37],["laundry","пране",65],["hoovering","минаване с прахосмукачка",20],["sweep","мета",28],["mop","мия пода с моп",30],["put off","отлагам",33],["crumbs","трохи",26]],"g":[["housework",5,2,1],["share out",17,4,2],["hoovering",20,4,1],["housemates",22,11,1],["communal",23,7,1],["crumbs",26,7,1],["sweep",28,3,1],["mopped",29,16,1],["organised",32,8,1],["put off",33,36,2],["chores",37,5,1],["laundry",65,0,1]],"q":[["Why is Phil tired?","Защо Фил е уморен?","he did lots of housework at the weekend","he worked at night","he went to a party",5],["Why did Phil have to get the house ready?","Защо Фил трябваше да приготви къщата?","some people were coming to visit","he was selling the house","it was his birthday",9],["Who does Georgie live with?","С кого живее Джорджи?","two housemates","her parents","her sister",22],["Which chore does Georgie hate most?","Коя домакинска задача Джорджи мрази най-много?","cleaning the toilet","doing the laundry","cooking",39],["What would Phil like his kids to do?","Какво би искал Фил да правят децата му?","keep their rooms tidy","cook dinner","wash the car",53],["Why is Phil happy about doing the laundry now?","Защо Фил сега се радва на прането?","he has a new, bigger washing machine","his kids do it","it's winter",67]]},"moving":{"ser":"Real Easy English","icon":"📦","bg":"Местене в нов дом","t":"Moving house","a":"ree/audio/moving.mp3","sp":["Georgie","Neil"],"L":[[0,"Hello and welcome to Real Easy English.","Здравейте и добре дошли в Real Easy English.",[0,37,53,98,121,161,208],263],[0,"We're back with another conversation in easy English to help you learn.","Връщаме се с още един разговор на лесен английски, за да ви помогнем да учите.",[264,292,325,342,381,470,487,543,592,608,636,649],676],[0,"I'm Georgie.","Аз съм Джорджи.",[688,703],744],[1,"And I'm Neil.","А аз съм Нийл.",[745,762,780],815],[1,"Don't forget that there's a video version of this podcast on our website, bbclearningenglish.com.","Не забравяйте, че на нашия сайт има видео версия на подкаста: bbclearningenglish.com.",[849,871,912,931,962,991,1036,1090,1111,1131,1191,1204,1217,1278],1472],[1,"You can read along with the subtitles and download a free worksheet.","Можете да четете заедно със субтитрите и да свалите безплатен работен лист.",[1496,1506,1520,1542,1575,1587,1593,1671,1702,1777,1790,1866],1922],[0,"Hello Neil. How are you doing?","Здравей, Нийл. Как си?",[2489,2516,2552,2568,2575,2584],2623],[1,"Hi Georgie. Yeah, I'm fine.","Здравей, Джорджи. Да, добре съм.",[2666,2678,2722,2736,2752],2784],[1,"How are you?","Ти как си?",[2784,2800,2809],2836],[0,"Yes, I'm very well too, thank you.","Да, и аз съм много добре, благодаря.",[2847,2886,2908,2933,2955,2985,3021],3045],[0,"Today, Neil, in this conversation, we're talking about moving house.","Днес, Нийл, в този разговор говорим за местене в нов дом.",[3091,3154,3191,3209,3223,3298,3316,3362,3420,3489],3562],[0,"So, when was the last time you moved house?","Е, кога за последен път се премести?",[3563,3659,3675,3691,3699,3723,3744,3770,3798],3845],[1,"Oh, I moved house probably 12 years ago.","О, преместих се преди около 12 години.",[3866,3974,3985,4017,4053,4102,4142,4172],4205],[0,"Oh wow! And why did you move to where you live now?","О, уау! А защо се премести там, където живееш сега?",[4224,4239,4305,4347,4388,4405,4419,4495,4509,4527,4544,4560],4594],[1,"Because my family was getting bigger.","Защото семейството ми ставаше по-голямо.",[4620,4650,4673,4734,4745,4786],4816],[1,"More children need more space, so we moved to somewhere bigger and further out of London.","Повече деца имат нужда от повече място, така че се преместихме на по-голямо място, по-далеч от Лондон.",[4924,4942,5006,5038,5059,5113,5135,5184,5214,5268,5305,5377,5398,5472,5500,5511],5555],[1,"How about you?","А ти?",[5647,5664,5695],5724],[0,"I rent my flat.","Аз живея под наем.",[5749,5753,5831,5948],5970],[0,"And the place I was living before - the owners of the place wanted to sell the house, so I needed to move because I couldn't live there anymore.","А мястото, където живеех преди – собствениците искаха да продадат къщата, така че трябваше да се преместя, защото вече не можех да живея там.",[5970,6021,6041,6063,6116,6150,6180,6180,6220,6258,6308,6408,6456,6516,6562,6591,6759,6788,6945,7009,7038,7064,7077,7125,7181,7186,7214,7239,7258],7300],[0,"And also, my friend had this flat and he was offering me very cheap rent, so that's why I live there.","А и един мой приятел имаше този апартамент и ми предлагаше много евтин наем, затова живея там.",[7345,7409,7489,7508,7592,7616,7631,7678,7695,7728,7752,7797,7811,7872,7903,7956,8027,8053,8072,8077,8097],8134],[0,"But I'm very happy there because it's between two really nice parks.","Но съм много щастлива там, защото е между два много хубави парка.",[8175,8219,8228,8247,8275,8294,8338,8403,8462,8517,8544,8569],8636],[0,"It has good transport links and, yeah, it was a good decision.","Има добри транспортни връзки и, да, беше добро решение.",[8666,8677,8695,8720,8798,8852,8928,8973,8978,8994,8998,9103],9158],[1,"And how was the move itself?","А как мина самото местене?",[9195,9208,9234,9264,9275,9345],9415],[0,"The move was actually very easy because I don't have many possessions.","Местенето всъщност беше много лесно, защото нямам много вещи.",[9416,9448,9531,9553,9647,9702,9766,9850,9880,9988,10027,10114],10167],[0,"I'm a bit of a minimalist.","Малко съм минималистка.",[10167,10187,10192,10216,10227,10242],10325],[0,"The reason is because I moved country, so I just didn't really have many things to bring back to the UK, so I didn't need a big van or anything.","Причината е, че се преместих от друга държава, така че просто нямах много неща за връщане в Обединеното кралство и не ми трябваше голям бус или нещо такова.",[10364,10372,10413,10432,10480,10531,10562,10609,10629,10692,10744,10767,10784,10809,10832,10859,10869,10954,10979,10993,11008,11080,11086,11094,11108,11176,11216,11233,11242,11245],11315],[0,"I just ordered a taxi and put all of my bags in the taxi and it was very easy.","Просто поръчах такси, сложих всичките си чанти в таксито и беше много лесно.",[11316,11383,11395,11438,11465,11495,11521,11678,11697,11710,11730,11844,11855,11866,11966,11977,11983,11999,12030],12066],[0,"And what about you?","А при теб?",[12066,12102,12110,12130],12155],[1,"It was the opposite of that.","Беше точно обратното.",[12270,12277,12289,12300,12349,12360],12392],[0,"Oh no!","О, не!",[12405,12430],12455],[1,"We had a removal van and some removal men, who came and packed everything up in boxes to make sure that things were easy to carry into the van, and also that they didn't get damaged.","Имахме камион за пренасяне и хамали, които дойдоха и опаковаха всичко в кашони, за да е лесно за пренасяне до камиона и също да не се повреди.",[12594,12605,12622,12627,12700,12769,12835,12879,12925,12991,13003,13031,13053,13103,13166,13232,13250,13476,13491,13513,13535,13550,13684,13703,13759,13798,13841,13863,13873,13937,13976,14019,14035,14054,14083,14116],14186],[1,"And then they drove all of our stuff to my new house.","После закараха всичките ни неща до новата ми къща.",[14214,14278,14324,14387,14440,14465,14478,14509,14580,14687,14706,14737],14790],[0,"Yeah. Did you have... did you have any fragile bits?","Да. Имахте ли… имахте ли чупливи неща?",[14818,14871,14887,14897,15036,15051,15061,15083,15123,15218],15248],[0,"So, fragile means that it's easy to break, not very strong.","„Fragile“ значи, че нещо се чупи лесно, не е много здраво.",[15249,15263,15307,15355,15395,15417,15448,15458,15535,15549,15570],15630],[0,"Plates and things - did you have...?","Чинии и такива неща – имахте ли…?",[15678,15758,15774,15774,15806,15818,15832],15870],[1,"Yes. Those things had to be wrapped and protected, otherwise they would break.","Да. Тези неща трябваше да се увият и защитят, иначе щяха да се счупят.",[15889,15940,16008,16074,16093,16104,16189,16297,16315,16435,16482,16495,16512],16551],[0,"Yes. And did you have to move furniture as well?","Да. А трябваше ли да местите и мебели?",[16566,16645,16666,16678,16692,16712,16725,16756,16810,16825],16856],[1,"Yeah, we had to move sofas and cupboards and wardrobes and heavy things like that, yeah.","Да, трябваше да местим дивани, шкафове, гардероби и такива тежки неща, да.",[16912,16957,16970,16991,17038,17109,17195,17297,17344,17366,17456,17526,17572,17609,17634,17864],17888],[0,"It does sound different to my experience, doesn't it?","Звучи различно от моя опит, нали?",[17909,17922,17941,17969,18006,18016,18038,18094,18162],18185],[0,"I didn't have any furniture to take.","Аз нямах никакви мебели за пренасяне.",[18187,18200,18222,18241,18257,18306,18318],18362],[0,"Do you find moving house exciting?","Местенето вълнуващо ли ти е?",[18362,18372,18428,18519,18650,18754],18832],[0,"Scary?","Страшно?",[18856],18937],[0,"How do you feel about moving house?","Какво изпитваш при местене?",[18953,18969,18979,18985,19010,19035,19060],19104],[1,"I think it's both.","Мисля, че и двете.",[19144,19153,19181,19197],19254],[1,"It's exciting and scary.","Вълнуващо е и страшно.",[19256,19276,19334,19366],19423],[1,"It's exciting because this is going to be your new life, or where your new life will happen.","Вълнуващо е, защото това ще е новият ти живот, или там ще се случва новият ти живот.",[19463,19489,19557,19659,19681,19691,19706,19713,19744,19769,19850,19901,19925,19969,20000,20028,20069,20088],20144],[1,"But it's also scary because you don't know what that's going to be like.","Но е и страшно, защото не знаеш какво ще е.",[20231,20379,20409,20449,20524,20557,20568,20605,20712,20736,20762,20788,20799,20812],20858],[1,"You don't know what your neighbours are going to be like.","Не знаеш какви ще са съседите ти.",[20925,20937,20966,21052,21068,21084,21154,21170,21196,21208,21221],21264],[0,"That's very true.","Много вярно.",[21290,21309,21331],21369],[1,"You don't know what your new friends are going to be like.","Не знаеш какви ще са новите ти приятели.",[21385,21398,21434,21529,21546,21566,21592,21650,21654,21680,21688,21702],21733],[0,"Yes.","Да.",[21734],21794],[1,"So, there's lots of things that you don't know.","Така че има много неща, които не знаеш.",[21796,21817,21837,21874,21885,21990,22005,22013,22038],22052],[1,"And that's scary, but also exciting.","А това е страшно, но и вълнуващо.",[22053,22086,22108,22157,22191,22224],22286],[0,"Yeah, a lot of uncertainty for sure.","Да, определено много несигурност.",[22307,22336,22352,22378,22390,22469,22486],22524],[0,"Yeah, I think it can depend.","Да, мисля, че може да зависи.",[22606,22625,22635,22655,22669,22685],22761],[0,"It depends if you're moving somewhere better or worse.","Зависи дали се местиш на по-добро или по-лошо място.",[22801,22808,22843,22856,22870,22907,22958,23040,23052],23102],[0,"But yeah, I was quite excited when I moved because I knew that my new flat had a nice outdoor terrace.","Но да, аз бях доста развълнувана, когато се местех, защото знаех, че новият ми апартамент има хубава открита тераса.",[23103,23253,23293,23309,23342,23391,23456,23496,23512,23561,23626,23642,23683,23724,23748,23781,23821,23854,23870,23910,23975],24040],[0,"As I said, we were close to parks and stuff, so I was excited.","Както казах, бяхме близо до паркове и такива неща, така че бях развълнувана.",[24040,24065,24081,24122,24146,24187,24235,24260,24309,24341,24390,24414,24430,24463],24528],[1,"So, Georgie, if you are planning a move, what do you need to do to prepare?","Е, Джорджи, ако планираш местене, какво трябва да направиш, за да се подготвиш?",[24528,24552,24617,24642,24674,24707,24780,24796,24837,24877,24901,24925,24948,24959,25030,25044],25102],[0,"Well, you need to do things like setting up WiFi in the new house.","Ами, трябва да направиш неща като да пуснеш интернет (WiFi) в новия дом.",[25157,25199,25209,25222,25296,25336,25381,25447,25492,25612,25666,25684,25690,25712],25762],[0,"Other bills, like electricity and heating, gas - you need to put your name on the accounts.","Други сметки, като ток и отопление, газ – трябва да прехвърлиш сметките на свое име.",[25763,25865,25950,26038,26122,26208,26270,26270,26434,26444,26458,26465,26483,26506,26565,26575,26583],26658],[0,"You need to plan what you're going to take.","Трябва да планираш какво ще вземеш.",[26819,26829,26851,26899,26951,26969,26978,27000,27012],27072],[0,"So, when you move, it's a really good time to look at all of your possessions and think, what do I need?","Когато се местиш, е много подходящо време да погледнеш всичките си вещи и да си помислиш: какво ми трябва?",[27079,27181,27275,27285,27312,27327,27332,27358,27375,27412,27464,27488,27494,27518,27531,27544,27604,27620,27662,27695,27712,27722],27768],[0,"Maybe I can get rid of stuff, so throw stuff away.","Може би мога да се отърва от някои неща, тоест да изхвърля неща.",[27778,27806,27813,27882,27900,27919,27925,27983,28072,28095,28124],28166],[0,"Have you got any other ideas?","Имаш ли други идеи?",[28217,28351,28362,28375,28389,28407],28453],[0,"What else can you do to prepare for a move?","Какво друго можеш да направиш, за да се подготвиш за местене?",[28454,28469,28487,28501,28511,28532,28545,28612,28625,28628],28676],[1,"You can hire a removal company or van if you're doing it yourself, if you're... if you need to transport your stuff to your new house and you can't just use a taxi. Yeah.","Можеш да наемеш фирма за пренасяне или бус, ако го правиш сам – ако трябва да превозиш нещата си до новия дом и не можеш просто да ползваш такси. Да.",[28753,28765,28788,28854,28888,29007,29071,29133,29209,29225,29238,29273,29287,29366,29382,29492,29503,29516,29547,29556,29632,29651,29719,29731,29744,29781,29878,29901,29908,29934,29960,29976,29981,30112],30135],[0,"Sounds like a lot of work.","Звучи като много работа.",[30137,30262,30300,30303,30319,30326],30367],[0,"I don't want to move anytime soon.","Не искам да се местя скоро.",[30391,30400,30413,30431,30444,30469,30509],30547],[1,"No.","Не.",[30567],30594],[0,"You?","А ти?",[30617],30652],[1,"Me neither. No.","Нито пък аз. Не.",[30653,30690,30744],30783],[0,"OK. Let's recap the language we heard during the conversation.","Добре. Нека преговорим езика, който чухме в разговора.",[31331,31362,31400,31442,31449,31493,31506,31544,31581,31588],31666],[0,"We heard possessions, which are the things that you own or have.","Чухме „possessions“ – нещата, които притежаваш или имаш.",[31684,31694,31735,31816,31838,31862,31873,31914,31930,31950,31993,32017],32055],[0,"For example, my phone and my clothes are my possessions.","Например телефонът и дрехите ми са мои вещи.",[32094,32104,32154,32173,32223,32261,32273,32334,32356,32375],32444],[1,"We talked about removal vans.","Говорихме за „removal vans“.",[32494,32516,32563,32624,32686],32738],[1,"A removal van is a large vehicle that people put your possessions into to go from one home to another, and the company is called a removals company or removals firm.","„Removal van“ е голямо превозно средство, в което хората слагат вещите ти, за да ги пренесат от един дом в друг, а фирмата се нарича фирма за пренасяне.",[32739,32756,32811,32851,32874,32891,32936,33041,33055,33095,33142,33174,33274,33361,33374,33395,33419,33439,33512,33536,33639,33681,33693,33769,33783,33831,33875,33937,33985,34000,34060],34104],[0,"We heard packing, and packing is where you put your own things into boxes, so that a removal firm can take them to your new home.","Чухме „packing“, а „packing“ е когато слагаш нещата си в кашони, за да може фирмата за пренасяне да ги закара до новия ти дом.",[34188,34200,34237,34304,34328,34375,34388,34406,34424,34442,34466,34498,34546,34574,34670,34684,34700,34706,34758,34796,34819,34846,34873,34890,34909,34934],34973],[1,"And we heard fragile.","И чухме „fragile“.",[35062,35108,35131,35175],35261],[1,"Fragile is an adjective which describes something that can break easily.","„Fragile“ е прилагателно, което описва нещо, което се чупи лесно.",[35300,35372,35392,35402,35470,35508,35575,35624,35644,35675,35775],35828],[1,"For example, glass - glass is fragile.","Например стъклото – стъклото е чупливо.",[35829,35854,35952,35952,36036,36077,36094],36147],[0,"That's it for this episode of Real Easy English.","Това е за този епизод на Real Easy English.",[36148,36192,36211,36223,36241,36295,36304,36347,36395],36447],[0,"Don't forget to test what you've learned using the free worksheet on our website.","Не забравяйте да проверите какво научихте с безплатния работен лист на нашия сайт.",[36449,36475,36515,36528,36563,36575,36596,36642,36679,36688,36734,36794,36805,36818],36896],[0,"Go to bbclearningenglish.com.","Отидете на bbclearningenglish.com.",[36897,36911,36924],37116],[1,"We'll be back next week with another conversation in easy English.","Ще се върнем следващата седмица с още един разговор на лесен английски.",[37167,37181,37194,37230,37259,37287,37300,37328,37413,37441,37482],37531],[1,"Bye for now.","Засега чао.",[37531,37563,37576],37597],[0,"Goodbye.","Довиждане.",[37598],37673]],"v":[["possessions","вещи, притежания",23],["removal van","камион за пренасяне",30],["packing","опаковане",77],["fragile","чуплив",32],["rent","наем; живея под наем",17],["furniture","мебели",36],["neighbours","съседи",47],["get rid of","отървавам се от",63]],"g":[["rent",17,1,1],["owners",18,9,1],["transport links",21,3,2],["possessions",23,11,1],["minimalist",24,5,1],["removal van",30,3,2],["damaged",30,35,1],["fragile",32,8,1],["furniture",36,7,1],["neighbours",47,5,1],["uncertainty",53,4,1],["bills",60,1,1]],"q":[["When did Neil last move house?","Кога Нийл се е местил за последно?","about 12 years ago","last year","2 years ago",12],["Why did Neil move?","Защо се премести Нийл?","his family was getting bigger","he got a new job","the rent was too high",14],["Why did Georgie have to move from her old place?","Защо Джорджи трябваше да напусне старото си жилище?","the owners wanted to sell the house","it was too small","it was too far from work",18],["Why was Georgie's move easy?","Защо местенето на Джорджи беше лесно?","she doesn't have many possessions","her friends helped her","she had a big van",23],["How does Neil feel about moving house?","Какво изпитва Нийл към местенето?","it's exciting and scary","it's boring","it's easy",44],["What do you need to do before a move, says Georgie?","Какво трябва да направиш преди местене според Джорджи?","set up WiFi and the bills","buy new furniture","meet the neighbours",59]]},"spicy":{"ser":"Real Easy English","icon":"🌶️","bg":"Люта храна","t":"Spicy food","a":"ree/audio/spicy.mp3","sp":["Neil","Georgie"],"L":[[0,"Hello, I'm Neil.","Здравейте, аз съм Нийл.",[31,73,95],132],[1,"And I'm Georgie.","А аз съм Джорджи.",[152,182,203],259],[1,"Welcome to Real Easy English.","Добре дошли в Real Easy English.",[270,309,333,378,428],487],[0,"You can find a worksheet and transcript for this episode on our website, bbclearningenglish.com.","На нашия сайт ще намерите работен лист и текст на епизода: bbclearningenglish.com.",[508,519,535,577,590,662,683,752,764,789,845,864,878,938],1148],[0,"Hi Georgie. How are you?","Здравей, Джорджи. Как си?",[1788,1803,1845,1864,1874],1908],[1,"I'm very well, thank you, Neil.","Много добре, благодаря, Нийл.",[1921,1944,1971,1994,2027,2039],2087],[1,"Something that made me very happy yesterday was that my housemate made me a delicious meal.","Нещо, което много ме зарадва вчера, беше, че съквартирантката ми ми сготви вкусна храна.",[2088,2140,2155,2186,2221,2263,2294,2369,2432,2451,2471,2538,2579,2616,2629,2712],2764],[1,"It was very spicy.","Беше много люто.",[2777,2784,2800,2837],2903],[0,"Well, we're talking about spicy food today.","Е, днес говорим за лютата храна.",[2976,3007,3029,3075,3107,3159,3195],3237],[1,"Yes. Spicy food is food that makes your mouth hot, and sometimes it can be painful.","Да. Лютата храна е храна, от която устата ти пари, а понякога може и да боли.",[3354,3400,3458,3509,3532,3558,3571,3601,3612,3653,3700,3720,3780,3794,3809,3821],3884],[1,"Neil, I like spicy food.","Нийл, аз обичам люто.",[4009,4044,4059,4077,4112],4171],[1,"What about you?","А ти?",[4184,4198,4220],4244],[0,"Yeah, I really like spicy food.","Да, много обичам люто.",[4280,4302,4322,4359,4391,4434],4471],[0,"I think, well, it has a lot of flavour.","Мисля, че има много вкус.",[4539,4547,4605,4657,4729,4792,4802,4836,4847],4912],[0,"And it can make you actually feel good when you eat spicy food.","И всъщност може да те накара да се чувстваш добре, когато ядеш люто.",[4938,5090,5195,5216,5245,5265,5306,5354,5402,5420,5433,5459,5501],5534],[0,"It can, kind of, lift your mood.","Може някак да ти повдигне настроението.",[5536,5562,5698,5759,5774,5809,5822],5872],[1,"Yeah, I agree actually.","Да, всъщност съм съгласна.",[5873,5891,5912,5945],5988],[1,"Spicy food really makes you feel alive.","Лютата храна наистина те кара да се чувстваш жив.",[5990,6033,6097,6116,6144,6152,6175],6238],[1,"The food that my housemate made for me yesterday was jerk chicken, which she put on the barbecue and it really had a kick.","Храната, която съквартирантката ми сготви вчера, беше ямайско пиле „джърк“, което тя изпече на барбекюто, и наистина беше с „ритник“.",[6252,6336,6384,6400,6444,6498,6541,6569,6583,6636,6670,6719,6781,6803,6844,6877,6894,6900,7022,7088,7102,7200,7219,7222],7272],[1,"So, if something has a kick, it means that it's a little bit spicy.","Ако нещо „has a kick“, значи, че е малко люто.",[7284,7366,7375,7403,7428,7431,7469,7481,7516,7530,7606,7611,7628,7641],7711],[1,"So, we had some mayonnaise with it to, kind of, cool it down.","Затова ядохме майонеза с него, за да го поохладим някак.",[7747,7766,7775,7797,7822,7888,7902,7928,7966,7992,8012,8052,8064],8114],[0,"Yeah, good idea.","Да, добра идея.",[8168,8219,8238],8289],[0,"Sometimes when you eat really spicy food or hot food.","Понякога, когато ядеш много люта или „гореща“ храна.",[8290,8417,8431,8444,8467,8544,8596,8673,8686,8724],8766],[0,"We say hot food and it doesn't mean the temperature always - it means spicy.","Казваме „hot food“ и това невинаги значи температурата – значи люто.",[8785,8814,8834,8874,8938,8957,8965,9076,9112,9121,9190,9190,9289,9301,9325],9391],[0,"When you have spicy food or hot food, it can make it feel like your mouth is on fire.","Когато ядеш люто, може да имаш чувството, че устата ти гори.",[9479,9505,9516,9537,9598,9653,9664,9690,9741,9748,9772,9817,9828,9855,9881,9898,9955,9972,10000],10038],[1,"Very true. Have you always liked spicy food or was it something you had to learn to love?","Много вярно. Винаги ли си обичал люто, или трябваше да се научиш да го обичаш?",[10064,10075,10130,10153,10350,10389,10417,10461,10500,10531,10553,10562,10650,10662,10683,10736,10802,10822],10858],[0,"I think so.","Мисля, че да.",[10919,10925,10952],10994],[0,"I think I've always liked spicy food.","Мисля, че винаги съм обичал люто.",[11036,11044,11073,11091,11141,11172,11233],11281],[0,"Yeah, I've always eaten lots of Indian curries, or Mexican food, or Caribbean food, like your jerk chicken.","Да, винаги съм ял много индийско къри, мексиканска храна или карибска храна, като твоето пиле „джърк“.",[11339,11384,11397,11434,11475,11500,11562,11608,11678,11782,11834,11898,12067,12123,12159,12183,12201,12238],12291],[1,"Yeah, I remember going on holiday with my family in Spain, and they have a dish there made of peppers, and some of them are very mild so they aren't very spicy, but some of them really have a kick, and you don't know which one is going to be really spicy, so it was quite... it was almost like an exciting game.","Да, помня, че бях на почивка със семейството си в Испания и там имат ястие от чушки, като някои от тях са много меки, тоест не са много люти, но някои наистина са с „ритник“, и не знаеш коя ще е много люта, така че беше доста… беше почти като вълнуваща игра.",[12314,12406,12419,12471,12508,12518,12565,12585,12601,12667,12683,12773,12787,12794,12814,12819,12858,12973,13007,13016,13097,13144,13177,13191,13267,13319,13348,13444,13456,13475,13511,13536,13697,13712,13746,13762,13787,13834,13853,13856,13897,13915,13931,13969,14050,14085,14184,14200,14235,14275,14291,14322,14378,14399,14419,14434,14472,14509,14534,14571,14591,14609,14669],14722],[1,"So, I've always enjoyed spice.","Така че винаги съм обичала лютото.",[14775,14828,14850,14881,14916],14972],[0,"OK. So, Georgie, you can eat spicier food now than when you were younger.","Добре. Значи, Джорджи, сега можеш да ядеш по-люта храна, отколкото когато беше по-малка.",[15028,15065,15096,15131,15156,15177,15242,15319,15353,15425,15437,15459,15475,15483],15530],[1,"Yes. Now, Neil, what's the spiciest meal you've ever eaten?","Да. А сега, Нийл, кое е най-лютото ястие, което си ял някога?",[15562,15675,15690,15736,15775,15787,15949,15997,16022,16055],16115],[0,"Well, I was travelling in South East Asia, and there was something on a menu, in a restaurant or bar I was in, called the spicy sausage salad... and they weren't lying!","Ами, пътувах из Югоизточна Азия и в менюто на един ресторант или бар, където бях, имаше нещо, наречено „люта салата с наденица“… и не лъжеха!",[16208,16322,16356,16427,16547,16615,16655,16693,16833,16891,16912,16927,16974,16987,16991,17114,17132,17238,17284,17297,17354,17366,17391,17480,17572,17579,17639,17691,17825,17986,18000,18031],18083],[0,"It was so spicy, it felt almost like somebody had attacked my tongue.","Беше толкова люто, че имах чувството, че някой е нападнал езика ми.",[18169,18304,18326,18375,18528,18542,18575,18617,18688,18752,18844,18936,18957],18998],[1,"Oh no! Was your mouth on fire?","О, не! Гореше ли ти устата?",[19032,19050,19272,19282,19294,19328,19344],19395],[0,"My mouth... My whole head was on fire!","Устата ми… Цялата ми глава гореше!",[19397,19414,19444,19466,19506,19547,19572,19588],19638],[0,"And it took a long time and lots of water before... before I felt normal again.","И мина много време и много вода, преди… преди да се почувствам нормално отново.",[19670,19707,19734,19819,19922,19956,20006,20022,20054,20073,20176,20294,20333,20341,20372,20412],20450],[1,"Does water help?","Помага ли водата?",[20462,20484,20528],20584],[0,"I don't know.","Не знам.",[20631,20638,20659],20691],[0,"I needed to try something.","Трябваше да опитам нещо.",[20717,20804,20838,20850,20884],20951],[1,"I think sometimes milk can help, but I don't know if there are... if there's anything else that can help.","Мисля, че понякога млякото помага, но не знам дали има… дали има нещо друго, което помага.",[21039,21055,21077,21171,21211,21234,21329,21341,21352,21445,21452,21463,21481,21496,21509,21537,21569,21585,21631,21643],21673],[1,"But sometimes you really need something to cool down.","Но понякога наистина ти трябва нещо, за да се охладиш.",[21674,21769,21824,21834,21864,21984,22038,22047,22071],22106],[0,"Yeah. How about you, Georgie?","Да. А ти, Джорджи?",[22120,22205,22228,22259,22288],22343],[0,"What's the hottest thing that you've ever eaten?","Кое е най-лютото нещо, което си яла?",[22344,22376,22389,22450,22476,22488,22531,22571],22621],[1,"Well, it wasn't a meal, but I used to work in a restaurant.","Ами, не беше ястие, но преди работех в ресторант.",[22693,22730,22754,22833,22883,22944,22994,23006,23042,23052,23095,23108,23113],23202],[1,"And there was a chef there who had three bottles of hot sauce with different levels of spice, and we were all trying it - everyone that worked there - and the spiciest one was so hot.","И там имаше един готвач с три бутилки лют сос с различна степен на лютивина, и всички го опитвахме – всички, които работеха там – и най-лютият беше страшно лют.",[23212,23329,23341,23353,23357,23411,23454,23485,23529,23583,23647,23669,23699,23746,23773,23817,23869,23884,24014,24056,24073,24085,24105,24147,24147,24169,24221,24248,24294,24294,24408,24495,24504,24590,24659,24675,24760],24823],[1,"It was so spicy, it... my mouth was completely on fire.","Беше толкова лют, че… устата ми направо гореше.",[24829,24845,24857,24901,25003,25047,25072,25118,25140,25209,25223],25260],[1,"It was horrible.","Беше ужасно.",[25261,25285,25347],25406],[1,"I actually didn't enjoy that.","Всъщност изобщо не ми хареса.",[25407,25416,25497,25523,25559],25582],[1,"Everyone was sweating, crying.","Всички се потяха и плачеха.",[25609,25657,25672,25787],25882],[1,"I don't think anyone enjoyed the experience.","Не мисля, че на някого му хареса това преживяване.",[25933,25959,26004,26022,26064,26110,26120],26204],[0,"Time now to recap the vocabulary we've heard in this episode, starting with spicy.","Време е да преговорим думите от епизода, като започнем със „spicy“.",[26909,26938,26958,26973,27032,27040,27121,27140,27174,27189,27209,27259,27309,27330],27413],[0,"If something is spicy, it makes your mouth feel hot and that can be uncomfortable or even painful.","Ако нещо е „spicy“, от него устата ти пари, а това може да е неприятно или дори болезнено.",[27459,27467,27507,27520,27632,27641,27668,27683,27726,27783,27861,27872,27893,27917,27971,28048,28070,28105],28162],[1,"We can also describe food as hot.","Можем да опишем храната и като „hot“.",[28200,28211,28227,28262,28315,28353,28377],28440],[1,"Now, hot is not always about the temperature - it can also mean spicy.","„Hot“ не винаги е за температурата – може да значи и люто.",[28448,28461,28508,28528,28553,28614,28648,28655,28655,28761,28772,28789,28855,28891],28964],[0,"If food is spicy, we can say it has a kick.","Ако храната е люта, можем да кажем, че „has a kick“.",[29003,29019,29066,29083,29185,29203,29221,29264,29280,29337,29369],29416],[0,"Now, Georgie said she had some Jamaican jerk chicken and that had a kick - it was spicy.","Джорджи каза, че е яла ямайско пиле „джърк“ и то „had a kick“ – беше люто.",[29491,29509,29552,29582,29604,29632,29678,29744,29785,29838,29878,29900,29927,29931,29931,29992,30005,30019],30083],[1,"If you eat something that's really spicy, you could say, \"My mouth is on fire!\" And it means it made your mouth feel very hot.","Ако ядеш нещо наистина люто, можеш да кажеш: „Устата ми гори!“ Това значи, че устата ти е станала много гореща.",[30125,30138,30150,30175,30222,30241,30294,30363,30381,30406,30456,30476,30526,30551,30592,30629,30682,30697,30730,30750,30780,30794,30819,30862,30900],30959],[1,"If your mouth is on fire, you might want to cool it down with maybe a glass of water or a glass of milk.","Ако устата ти гори, може да искаш да я охладиш с чаша вода или чаша мляко.",[31015,31027,31037,31063,31076,31089,31162,31175,31209,31227,31246,31283,31296,31358,31384,31421,31427,31456,31469,31538,31544,31550,31580,31588],31626],[0,"That's it for this episode of Real Easy English, but don't forget to go to our website where you can find a free worksheet and you can test yourself on what you've learned.","Това е за този епизод на Real Easy English, но не забравяйте да отидете на нашия сайт, където ще намерите безплатен работен лист и можете да се изпитате върху наученото.",[31672,31719,31733,31749,31772,31822,31839,31869,31903,31950,31981,32003,32039,32050,32067,32089,32106,32189,32200,32217,32233,32287,32300,32359,32450,32460,32466,32479,32513,32557,32572,32595,32608],32650],[0,"That's at bbclearningenglish.com.","Адресът е bbclearningenglish.com.",[32670,32696,32712],32890],[1,"And we'll be back next week with another conversation in easy English.","И ще се върнем следващата седмица с още един разговор на лесен английски.",[32952,32990,33014,33025,33051,33083,33109,33128,33163,33257,33282,33333],33388],[1,"Goodbye for now.","Засега довиждане.",[33388,33427,33441],33465],[0,"Goodbye!","Довиждане!",[33466],33525]],"v":[["spicy","лют",7],["hot (food)","лют (за храна)",22],["have a kick","люто е, „пари“",29],["my mouth is on fire","устата ми гори",58],["cool down","охлаждам (се)",42],["mild","мек, не лют",29],["flavour","вкус",13],["housemate","съквартирант",6]],"g":[["housemate",6,10,1],["delicious",6,14,1],["flavour",13,8,1],["lift your mood",15,4,3],["barbecue",18,17,1],["kick",18,23,1],["cool it down",20,10,3],["on fire",24,17,2],["mild",29,26,1],["attacked",34,10,1],["hot sauce",46,11,2],["sweating",50,2,1]],"q":[["Who made Georgie a spicy meal yesterday?","Кой сготви люта храна на Джорджи вчера?","her housemate","her mother","a chef",6],["How does spicy food make Neil feel?","Как се чувства Нийл от лютата храна?","it can lift his mood","it makes him sleepy","it makes him angry",15],["Why did they eat mayonnaise with the chicken?","Защо ядоха майонеза с пилето?","to cool it down","to make it spicier","because it was cold",20],["What did Georgie eat on holiday in Spain?","Какво яде Джорджи на почивка в Испания?","a dish made of peppers","jerk chicken","a sausage salad",29],["Where did Neil eat the spicy sausage salad?","Къде яде Нийл лютата салата с наденица?","in South East Asia","in Mexico","in India",33],["What happened when Georgie tried the hot sauce?","Какво стана, когато Джорджи опита лютия сос?","everyone was sweating and crying","everyone loved it","nobody wanted to try it",50]]},"films":{"ser":"Real Easy English","icon":"🎬","bg":"Филми и сериали","t":"Films","a":"ree/audio/films.mp3","sp":["Georgie","Neil"],"L":[[0,"Welcome to Real Easy English, the podcast where we have real conversations in easy English to help you learn.","Добре дошли в Real Easy English – подкастът, в който водим истински разговори на лесен английски, за да ви помогнем да учите.",[0,67,83,132,189,254,283,352,365,375,402,439,539,558,606,656,678,707,725],759],[0,"I'm Georgie.","Аз съм Джорджи.",[791,807],856],[1,"And I'm Neil.","А аз съм Нийл.",[857,900,922],965],[1,"To read along with this podcast, visit our website: bbclearningenglish.com.","За да четете заедно с подкаста, посетете нашия сайт: bbclearningenglish.com.",[1017,1034,1065,1106,1135,1156,1247,1298,1331,1429],1657],[0,"How are you today, Neil?","Как си днес, Нийл?",[2286,2302,2316,2327,2357],2386],[1,"I'm very well, Georgie.","Много добре, Джорджи.",[2433,2448,2477,2502],2557],[1,"How are you?","Ти как си?",[2584,2605,2609],2640],[0,"I'm pretty good, thank you, as well.","И аз съм доста добре, благодаря.",[2666,2688,2712,2740,2769,2791,2815],2858],[1,"So, Georgie, what are we talking about in today's episode?","Е, Джорджи, за какво говорим в днешния епизод?",[2916,2948,3001,3059,3073,3090,3141,3187,3212,3286],3353],[0,"Today's episode is all about films and television.","Днешният епизод е изцяло за филми и телевизия.",[3383,3434,3495,3514,3539,3573,3634,3662],3731],[0,"We'll talk about our favourite movies and shows.","Ще говорим за любимите си филми и предавания.",[3759,3780,3812,3844,3861,3916,3973,3998],4062],[1,"Great, let's get started.","Чудесно, да започваме.",[4064,4121,4173,4201],4262],[0,"OK, Neil. So, what kinds of films do you like?","Добре, Нийл. Какви филми харесваш?",[4417,4447,4473,4514,4541,4588,4596,4639,4648,4656],4699],[1,"I like foreign films, films that are not in English, because I like stories from other countries.","Харесвам чуждестранни филми – филми, които не са на английски, защото обичам истории от други страни.",[4741,4783,4900,4954,5052,5091,5107,5110,5161,5180,5292,5362,5376,5443,5495,5522,5541],5626],[1,"What about you?","А ти?",[5686,5709,5739],5784],[0,"I like two kinds of films.","Харесвам два вида филми.",[5864,5878,5906,5938,5964,5972],6045],[0,"One type of film I really like is films that you can learn from, and the other type of film is films that you can escape from reality.","Единият вид, който много обичам, са филми, от които можеш да научиш нещо, а другият – филми, с които можеш да избягаш от реалността.",[6083,6123,6144,6154,6186,6198,6226,6284,6365,6405,6417,6426,6444,6486,6568,6591,6605,6626,6656,6666,6712,6811,6880,6945,6962,6981,7029,7051],7108],[0,"So usually quite silly films or fantasy films.","Обикновено доста глупави филми или фентъзи.",[7109,7127,7228,7253,7287,7337,7367,7419],7465],[1,"OK. Do you have a favourite film?","Добре. Имаш ли любим филм?",[7489,7532,7547,7562,7596,7611,7678],7716],[0,"Yes, I do.","Да, имам.",[7768,7816,7828],7859],[0,"I really love the Harry Potter series.","Много обичам поредицата „Хари Потър“.",[7860,7871,7924,7959,7970,7995,8026],8094],[1,"So, Georgie, can you tell us about your favourite film, the Harry Potter film you mentioned?","Е, Джорджи, можеш ли да ни разкажеш за любимия си филм – „Хари Потър“, който спомена?",[8146,8178,8222,8256,8273,8304,8344,8441,8506,8552,8590,8601,8634,8668,8725,8740],8789],[0,"Yes. So you want to know about the plot, which is what happens in the film.","Да. Значи искаш да знаеш сюжета – това, което се случва във филма.",[8809,8859,8869,8914,8933,8943,8987,9010,9016,9067,9094,9108,9129,9187,9200,9206],9248],[0,"So Harry Potter is all about a boy who discovers that he is a wizard.","„Хари Потър“ е за едно момче, което открива, че е магьосник.",[9294,9326,9362,9430,9456,9475,9509,9517,9575,9623,9700,9712,9745,9775,9781],9856],[0,"That is someone who does magic.","Тоест някой, който прави магии.",[9856,9884,9900,9989,10047,10066],10131],[0,"And he goes to a school for magic called Hogwarts and he meets his best friends Ron and Hermione who are other characters in the film.","И той отива в училище за магия, наречено Хогуортс, и среща най-добрите си приятели Рон и Хърмаяни, които са други герои във филма.",[10172,10209,10234,10273,10283,10288,10358,10372,10420,10442,10517,10567,10588,10623,10658,10697,10762,10800,10814,10870,10889,10917,10934,10997,11012,11019],11055],[0,"And he spends a lot of his time trying to escape a dark wizard called Voldemort and it's very dangerous.","И прекарва много от времето си в опити да избяга от един зъл магьосник на име Волдемор, а това е много опасно.",[11115,11186,11259,11301,11306,11331,11342,11361,11401,11425,11434,11520,11528,11598,11656,11692,11823,11875,11890,11917],11986],[0,"It's a great film!","Страхотен филм е!",[12025,12041,12044,12070],12098],[1,"Wow, it sounds like there's lots of interesting characters in these films.","Уау, звучи така, сякаш в тези филми има много интересни герои.",[12128,12161,12177,12217,12245,12277,12311,12381,12453,12568,12584,12608],12641],[0,"Yes. Very evil characters and also really nice characters.","Да. Много зли герои, но и много мили герои.",[12672,12748,12780,12812,12884,12903,12971,13024,13066],13134],[1,"So, Georgie, you talked a lot about your favourite film Harry Potter.","Е, Джорджи, ти говори много за любимия си филм „Хари Потър“.",[13247,13288,13341,13375,13446,13452,13503,13569,13587,13633,13673,13705],13755],[1,"And the grammar you used to describe the film was present simple.","А граматиката, която използва, за да опишеш филма, беше сегашно просто време (present simple).",[13812,13947,13962,14049,14106,14175,14303,14359,14369,14449,14465,14517],14577],[1,"So, for example, you said the film is about a boy who discovers that he is a wizard and he goes to a school, a special school for wizards, and he makes friends with Ron and Hermione.","Например каза, че филмът е за момче, което открива, че е магьосник, и отива в училище, специално училище за магьосници, и се сприятелява с Рон и Хърмаяни.",[14600,14671,14692,14759,14780,14814,14822,14880,14940,15001,15004,15086,15132,15229,15242,15277,15329,15336,15418,15463,15555,15599,15641,15658,15720,15724,15779,15854,15875,15998,16076,16089,16147,16221,16254,16297,16338],16407],[1,"All present simple.","Всичко е в present simple.",[16457,16488,16526],16570],[0,"Yes, that's right.","Да, точно така.",[16626,16660,16684],16711],[0,"We use the present simple to describe the plot of a story like a book or a film.","Използваме present simple, за да опишем сюжета на история – например на книга или филм.",[16712,16724,16775,16784,16822,16867,16906,16974,16986,17062,17090,17102,17191,17209,17234,17275,17296,17300],17347],[0,"We also use the present simple to tell stories sometimes, things that happened to us in the past, which is interesting.","Понякога използваме present simple и когато разказваме истории – неща, които са ни се случили в миналото, което е интересно.",[17412,17428,17447,17471,17480,17517,17562,17589,17631,17681,17781,17809,17822,17856,17867,17887,17899,17906,17994,18008,18018],18071],[0,"What about you?","А ти?",[18188,18207,18231],18249],[0,"What's your favourite film?","Кой е твоят любим филм?",[18250,18274,18285,18321],18354],[1,"Well. I think my favourite film is from when I was a kid, and it's Raiders Of The Lost Ark.","Ами, мисля, че любимият ми филм е от детството ми – „Похитителите на изчезналия кивот“.",[18456,18578,18631,18670,18685,18754,18797,18821,18845,18863,18876,18897,18900,19014,19059,19126,19177,19188,19195,19231],19280],[0,"Wow. I haven't seen that.","Уау. Не съм го гледала.",[19300,19385,19409,19438,19473],19563],[1,"It's very old, but it's got Indiana Jones, and he was my hero when I was a kid.","Много е стар, но в него е Индиана Джоунс, а той беше моят герой, когато бях дете.",[19627,19642,19672,19707,19723,19742,19788,19839,19889,19906,19953,19980,19997,20059,20092,20104,20122,20125],20172],[0,"Really?","Наистина ли?",[20183],20275],[1,"Yeah.","Да.",[20275],20294],[0,"Why was he your hero?","Защо ти беше герой?",[20294,20335,20353,20361,20375],20414],[1,"Because it was... he's all about action and adventure and catching bad guys.","Защото… той е само екшън и приключения и залавяне на лоши хора.",[20454,20500,20512,20580,20636,20662,20698,20756,20773,20885,20901,20948,20985],21033],[0,"Oh interesting! See I'm not a big fan of action and adventure.","О, интересно! Виж, аз не съм голям фен на екшъна и приключенията.",[21059,21073,21163,21184,21211,21229,21234,21255,21303,21323,21366,21375],21450],[1,"So, Georgie, do you watch lots of movies?","Е, Джорджи, гледаш ли много филми?",[21475,21556,21616,21638,21654,21681,21744,21767],21829],[0,"I actually don't, because I have quite a short attention span.","Всъщност не, защото вниманието ми трае доста кратко.",[21870,21906,21956,22062,22100,22103,22119,22148,22151,22210,22267],22313],[0,"I actually prefer to watch TV or series.","Всъщност предпочитам да гледам телевизия или сериали.",[22314,22335,22376,22412,22485,22575,22642,22687],22758],[0,"What about you?","А ти?",[22773,22785,22808],22831],[1,"Yeah, again, I think there's so much choice these days, sometimes actually I watch nothing because I don't know what to choose.","Да, пак казвам, мисля, че днес има толкова голям избор, че понякога всъщност не гледам нищо, защото не знам какво да избера.",[22916,22957,23058,23066,23108,23125,23175,23207,23258,23287,23328,23488,23522,23555,23589,23640,23676,23690,23715,23731,23747,23759],23803],[1,"But sometimes, I really get into a TV series and, yeah, watch it all very quickly and talk about it a lot.","Но понякога наистина се увличам по някой сериал и, да, го изглеждам целия много бързо и говоря много за него.",[23825,23865,23978,23991,24106,24132,24177,24213,24271,24334,24496,24525,24566,24577,24603,24621,24691,24708,24732,24754,24770,24775],24809],[0,"That's called binge watching.","Това се нарича „binge watching“ – запойно гледане.",[24901,24920,24938,24982],25091],[0,"How do you watch these series?","Как гледаш тези сериали?",[25162,25194,25206,25219,25246,25262],25315],[1,"On TV. But, you know, I stream them, like everybody these days.","По телевизора. Но, знаеш, стриймвам ги, като всички днес.",[25363,25466,25515,25544,25560,25588,25597,25640,25695,25726,25788,25812],25849],[0,"So, you just used the word stream.","Ти току-що използва думата „stream“.",[25940,25955,25994,26019,26039,26048,26068],26138],[0,"You stream TV shows and movies and that means watching films or TV using the internet.","Стриймваш предавания и филми – това значи да гледаш филми или телевизия през интернет.",[26138,26160,26249,26285,26331,26351,26394,26410,26426,26507,26562,26627,26640,26712,26743,26749],26836],[0,"You can watch things whenever you want when you stream things.","Когато стриймваш, можеш да гледаш каквото искаш, когато поискаш.",[26894,26911,26920,26946,26969,26995,27012,27052,27073,27081,27123],27166],[1,"OK. Let's look again at the vocabulary we learned during the conversation.","Добре. Нека пак погледнем думите, които научихме в разговора.",[27788,27837,27867,27891,27931,27955,27969,28058,28075,28129,28162,28169],28248],[0,"We learned plot, which means the story of a film, TV programme or book, so what happens.","Научихме „plot“ – сюжетът на филм, предаване или книга, тоест какво се случва.",[28286,28306,28357,28432,28458,28495,28506,28565,28575,28582,28651,28695,28762,28776,28860,28893,28913],28977],[1,"Character, that's a person in a story.","„Character“ – това е човек (герой) в история.",[29039,29154,29192,29199,29258,29280,29282],29333],[0,"And stream, watch a film or programme online.","И „stream“ – гледам филм или предаване онлайн.",[29375,29414,29520,29556,29565,29612,29625,29682],29751],[1,"And we learned how to use present simple to talk about what happens in a film.","И научихме как да използваме present simple, за да говорим какво се случва във филм.",[29783,29838,29865,29900,29926,29939,29970,30017,30111,30125,30155,30183,30208,30306,30324,30326],30367],[0,"For example, Harry Potter goes to a magic school called Hogwarts and meets two best friends.","Например Хари Потър отива в училище за магия, наречено Хогуортс, и среща двама най-добри приятели.",[30456,30476,30552,30588,30638,30688,30730,30750,30798,30830,30856,30927,30952,31001,31045,31076],31124],[1,"Thanks for listening to Real Easy English.","Благодарим, че слушахте Real Easy English.",[31188,31413,31423,31465,31500,31549,31588],31638],[1,"You can find more easy conversation on our website: bbclearningenglish.com.","Ще намерите още лесни разговори на нашия сайт: bbclearningenglish.com.",[31669,31687,31705,31743,31786,31829,31905,31923,31937,32021],32206],[0,"Next time, we'll be talking about pets.","Следващия път ще говорим за домашни любимци.",[32246,32274,32306,32336,32350,32399,32438],32504],[1,"Bye for now.","Засега чао.",[32506,32531,32541],32574],[0,"Bye.","Чао.",[32575],32632]],"v":[["plot","сюжет",22],["character","герой (в история)",61],["stream","гледам онлайн (стриймвам)",55],["foreign films","чуждестранни филми",13],["wizard","магьосник",23],["attention span","продължителност на вниманието",48],["binge watching","запойно гледане на сериал",53],["escape","избягвам",16]],"g":[["foreign",13,2,1],["reality",16,27,1],["fantasy",17,6,1],["plot",22,8,1],["wizard",23,14,1],["characters",25,22,1],["evil",29,2,1],["present simple",31,10,2],["hero",41,12,1],["adventure",45,8,1],["attention span",48,9,2],["stream",55,6,1]],"q":[["What kind of films does Neil like?","Какви филми харесва Нийл?","foreign films","horror films","cartoons",13],["What is Georgie's favourite film series?","Коя е любимата филмова поредица на Джорджи?","Harry Potter","Indiana Jones","Star Wars",20],["Which tense do we use to describe the plot of a film?","Кое време използваме, за да опишем сюжета на филм?","present simple","past simple","future",35],["Who was Neil's hero when he was a kid?","Кой беше героят на Нийл като дете?","Indiana Jones","Harry Potter","Voldemort",41],["Why doesn't Georgie watch many movies?","Защо Джорджи не гледа много филми?","she has a short attention span","she has no TV","she doesn't like stories",48],["What does 'stream' mean?","Какво значи „stream“?","watch films or TV using the internet","go to the cinema","buy a DVD",57]]},"news":{"ser":"Real Easy English","icon":"📰","bg":"Следиш ли новините?","t":"Following the news","a":"ree/audio/news.mp3","sp":["Beth","Neil"],"L":[[0,"Hello. You're listening to Real Easy English from BBC Learning English.","Здравейте. Слушате Real Easy English от BBC Learning English.",[16,130,173,225,259,310,375,446,486,571,627],699],[0,"I'm Beth.","Аз съм Бет.",[714,743],766],[1,"And I'm Neil.","А аз съм Нийл.",[786,819,843],884],[1,"This is the podcast where we have real conversations in easy English for you to listen along and learn.","Това е подкастът, в който водим истински разговори на лесен английски, за да слушате и учите.",[951,973,992,1001,1080,1115,1131,1161,1204,1320,1344,1414,1475,1488,1515,1527,1568,1647,1669],1711],[0,"As always, you can find a text version of this episode to read along on our website: bblearningenglish.com","Както винаги, на нашия сайт ще намерите текста на епизода, за да четете заедно: bbclearningenglish.com",[1853,1880,1952,1973,1993,2043,2048,2110,2174,2197,2227,2291,2320,2354,2399,2421,2436,2527],2761],[1,"So, Beth, how are you this week?","Е, Бет, как си тази седмица?",[3550,3611,3645,3673,3680,3720,3749],3792],[0,"I'm very good, thank you.","Много добре, благодаря.",[3811,3845,3873,3902,3945],3966],[0,"How are you, Neil?","Ти как си, Нийл?",[3966,3981,3986,4006],4039],[1,"I'm very well, thank you.","Много добре, благодаря.",[4041,4066,4102,4128,4163],4184],[1,"What are we talking about today?","За какво ще говорим днес?",[4234,4264,4270,4291,4348,4391],4441],[0,"We are talking about how much we follow the news.","Говорим за това колко следим новините.",[4489,4527,4535,4584,4630,4667,4733,4755,4805,4820],4888],[1,"Ah, the news!","А, новините!",[4888,4931,4950],5030],[1,"OK, so what do we mean by follow the news?","Добре, какво имаме предвид с „следя новините“?",[5031,5072,5136,5180,5191,5208,5263,5311,5381,5414],5470],[0,"So, when we say follow the news, it means that you are interested in the news.","Когато казваме „follow the news“, значи, че се интересуваш от новините.",[5522,5548,5584,5601,5641,5716,5737,5794,5820,5881,5903,5930,5970,6062,6091,6098],6155],[0,"So you might read it on your phone, listen to it on the radio or watch it on TV quite regularly.","Може да ги четеш на телефона, да ги слушаш по радиото или да ги гледаш по телевизията доста редовно.",[6180,6241,6260,6316,6355,6373,6391,6411,6498,6536,6555,6567,6589,6598,6681,6708,6747,6756,6781,6856,6897],6978],[1,"Yes, and you can also follow sports, can't you?","Да, и можеш да следиш и спорт, нали?",[7025,7078,7133,7148,7163,7211,7275,7361,7402],7417],[1,"So if you like a particular, for example, football team, you might check your phone a lot to find out the score, to follow and see how they're doing.","Ако харесваш например определен футболен отбор, може често да гледаш телефона си, за да разбереш резултата и да видиш как се справят.",[7419,7512,7537,7552,7601,7606,7765,7781,7829,7878,7951,7970,8059,8173,8186,8220,8228,8291,8302,8334,8351,8359,8401,8414,8522,8534,8555,8578,8593],8634],[0,"Yeah, exactly. So, Neil, do you follow the news?","Да, точно. Е, Нийл, ти следиш ли новините?",[8684,8719,8902,8950,8997,9028,9038,9087,9097],9156],[1,"Yes, I think it's difficult not to follow the news.","Да, мисля, че е трудно да не следиш новините.",[9183,9249,9265,9315,9342,9392,9442,9456,9503,9569],9595],[1,"First thing in the morning, I look on my phone to see if anything big has happened overnight, and then I check a lot during the day just to see what's happening.","Първото нещо сутрин е да погледна телефона си дали нещо голямо се е случило през нощта, а после проверявам много пъти през деня просто да видя какво става.",[9666,9701,9720,9736,9743,9789,9825,9920,9940,9957,10011,10041,10124,10136,10201,10246,10269,10336,10472,10484,10499,10512,10607,10613,10648,10677,10684,10744,10763,10770,10839,10858],10910],[1,"So I do follow the news.","Така че да, следя новините.",[10911,10931,10941,10968,10997,11003],11049],[1,"How about you?","А ти?",[11051,11091,11123],11152],[0,"Yes, I'm the same.","Да, и аз съм така.",[11220,11275,11297,11305],11355],[0,"So I get notifications on my phone throughout the day, but sometimes I find that that's a little bit too much.","Получавам известия на телефона през целия ден, но понякога ми идват малко в повече.",[11356,11442,11465,11502,11617,11637,11658,11698,11750,11760,11871,11940,12011,12035,12092,12129,12214,12221,12253,12278,12311],12368],[0,"Sometimes you need a break when you're working and you don't want to see the news all the time, and my phone does notify me a lot about the news.","Понякога ти трябва почивка, докато работиш, и не искаш да виждаш новините постоянно, а телефонът ми ме известява за новините много често.",[12369,12424,12436,12465,12471,12562,12649,12668,12727,12738,12751,12773,12803,12881,12914,12923,12981,13010,13020,13070,13100,13118,13219,13260,13324,13377,13383,13429,13460,13474],13529],[1,"Yeah, I think you can have too much news and it can be not very good for you to read lots of usually quite bad news.","Да, мисля, че може да имаш твърде много новини и да не ти е много полезно да четеш куп обикновено доста лоши новини.",[13575,13640,13650,13744,13752,13776,13796,13835,13909,13996,14021,14036,14070,14212,14233,14260,14284,14307,14330,14421,14479,14510,14577,14619,14654,14699],14746],[0,"Yes, definitely. So, why do you like to follow the news, even though it can be too sad?","Да, определено. А защо обичаш да следиш новините, въпреки че може да са твърде тъжни?",[14791,14869,15006,15040,15074,15112,15134,15201,15222,15266,15277,15371,15426,15515,15530,15555,15596,15626],15661],[1,"That's a very good question.","Много добър въпрос.",[15662,15723,15790,15839,15861],15930],[1,"I think it's a bit of a habit.","Мисля, че е донякъде навик.",[15974,15979,16013,16066,16074,16165,16177,16181],16249],[1,"It's a bit addictive and I think we sometimes feel like we need to know what's happening, even if we have actually no control over what is happening.","Малко пристрастява и мисля, че понякога имаме чувството, че трябва да знаем какво става, дори ако всъщност нямаме никакъв контрол над това, което се случва.",[16280,16308,16339,16368,16488,16514,16526,16623,16656,16765,16842,16881,16889,16959,16971,17062,17084,17199,17233,17245,17258,17286,17330,17362,17471,17491,17529,17559],17602],[0,"Yeah, I completely agree because even though I get notifications and I read the news, I sometimes feel like I still don't know enough about what's going on because there's so much information out there, and so many different ways to get the news that it's not enough to just read one article.","Да, напълно съгласна съм, защото макар да получавам известия и да чета новините, понякога имам чувството, че пак не знам достатъчно какво става, понеже има толкова много информация и толкова много начини да получиш новините, че не е достатъчно да прочетеш само една статия.",[17666,17705,17725,17791,17828,17920,17948,17961,17973,18014,18134,18152,18229,18262,18276,18378,18391,18453,18479,18516,18531,18578,18628,18688,18753,18793,18825,18856,18903,19010,19038,19091,19134,19223,19250,19272,19303,19323,19360,19398,19453,19472,19506,19516,19635,19750,19776,19810,19860,19884,19969,20006,20031],20099],[0,"There's so much information that you want to understand.","Има толкова много информация, която искаш да разбереш.",[20100,20128,20169,20192,20259,20286,20353,20392,20406],20488],[1,"So, Beth, we work at the BBC.","Е, Бет, ние работим в Би Би Си.",[20528,20561,20603,20669,20701,20720,20728],20807],[0,"We do.","Да.",[20829,20841],20884],[1,"It's a news organisation.","Това е новинарска организация.",[20894,20913,20920,20964],21063],[1,"Have your news habits changed since you started working at the BBC?","Промениха ли се навиците ти с новините, откакто започна работа в Би Би Си?",[21126,21170,21228,21266,21313,21408,21456,21478,21598,21635,21644,21656],21716],[0,"Yes, I think they definitely have.","Да, мисля, че определено се промениха.",[21782,21869,21920,21964,21981,22032],22086],[0,"I think I probably pay more attention to the news now than I did in the past and...","Мисля, че вероятно обръщам повече внимание на новините сега, отколкото в миналото, и...",[22137,22148,22179,22194,22269,22321,22375,22438,22454,22466,22525,22632,22655,22668,22724,22744,22752,22829],22879],[0,"For example, I already knew some information about certain topics, but now I want to learn even more.","Например вече знаех нещо по определени теми, но сега искам да науча още повече.",[22934,22954,23037,23058,23119,23174,23215,23359,23391,23429,23497,23531,23586,23612,23645,23660,23740,23778],23825],[0,"So I try to pay more attention to things that maybe I wasn't as interested in in the past.","Затова се опитвам да обръщам повече внимание на неща, които може би не ме интересуваха толкова преди.",[23826,23851,23864,23891,23907,23931,23971,24024,24046,24091,24115,24150,24159,24215,24245,24311,24368,24382,24389],24453],[0,"What about you?","А ти?",[24536,24572,24594],24622],[0,"Does working at the BBC mean you pay more attention to the news?","Работата в Би Би Си кара ли те да обръщаш повече внимание на новините?",[24623,24672,24719,24728,24739,24810,24852,24869,24905,24938,24995,25012,25021],25094],[1,"Well, I used to be a journalist at the BBC.","Ами, аз бях журналист в Би Би Си.",[25123,25243,25260,25322,25331,25369,25373,25493,25520,25527],25602],[1,"So probably I used to pay more attention or follow the news more than I do now because now I make these programmes about English.","Така че вероятно преди обръщах повече внимание и следях новините повече, отколкото сега, защото сега правя тези предавания за английския.",[25603,25637,25688,25784,25818,25909,25931,25973,26027,26031,26074,26087,26121,26172,26192,26201,26226,26293,26321,26377,26385,26448,26474,26547,26610],26662],[0,"Maybe it's good that you don't follow the news as much as you did, because it's not always good.","Може би е хубаво, че не следиш новините толкова, колкото преди, защото не винаги са хубави.",[26699,26733,26751,26792,26818,26832,26858,26895,26905,26964,26988,27017,27031,27042,27128,27225,27245,27262,27300],27345],[1,"It's not. It's often bad news.","Не са. Често са лоши новини.",[27381,27400,27441,27457,27489,27521],27556],[1,"OK, let's recap the vocabulary we learned during the conversation.","Добре, нека преговорим думите, които научихме в разговора.",[28171,28233,28272,28326,28338,28414,28431,28473,28504,28512],28596],[0,"We had follow the news, which means to be interested in the news.","Имахме „follow the news“, което значи да се интересуваш от новините.",[28650,28667,28717,28763,28775,28850,28879,28925,28956,28989,29060,29082,29091],29146],[1,"We used too, and too means more than is needed of something, so I watch too much news.","Използвахме „too“, а „too“ значи повече, отколкото трябва – например „гледам твърде много новини“.",[29169,29187,29248,29329,29348,29383,29419,29465,29492,29511,29579,29591,29669,29728,29739,29778,29828,29869],29932],[0,"We also had enough, which means as much as is needed of something.","Имахме и „enough“, което значи толкова, колкото трябва.",[30039,30065,30095,30150,30241,30265,30326,30356,30406,30451,30481,30539,30548],30610],[0,"So if you think you watch enough news, you don't need more and you don't need less.","Ако мислиш, че гледаш достатъчно новини, не ти трябват нито повече, нито по-малко.",[30657,30733,30751,30766,30811,30831,30894,30977,31029,31063,31091,31112,31157,31177,31188,31207,31235],31278],[1,"And we've had already, which means before now.","И имахме „already“, което значи преди сега, вече.",[31317,31345,31377,31425,31498,31532,31594,31659],31691],[0,"Yes, I said that before I worked at the BBC, I already followed quite a bit of news.","Да, казах, че преди да работя в Би Би Си, вече следях доста новини.",[31739,31788,31810,31845,31895,31923,31957,31996,32010,32017,32102,32140,32260,32347,32375,32379,32403,32416],32455],[0,"And I can't believe it is already the end of this episode and it's the end of the series!","И не мога да повярвам, че вече е краят на епизода и на поредицата!",[32573,32613,32626,32656,32702,32725,32745,32832,32850,32882,32894,32926,33038,33120,33135,33151,33194,33212,33220],33307],[1,"Yes, that's sad news!","Да, това са тъжни новини!",[33308,33343,33382,33424],33471],[1,"So we will be back with more easy English podcasts for you.","Ще се върнем с още подкасти на лесен английски за вас.",[33502,33534,33556,33577,33594,33658,33677,33732,33781,33812,33881,33905],33928],[1,"But for now, you can find lots more activities and courses to help with your English on our website: bbclearningenglish.com","Но засега ще намерите много още упражнения и курсове за английския на нашия сайт: bbclearningenglish.com",[33970,33995,34007,34077,34093,34112,34156,34193,34225,34315,34343,34406,34427,34465,34481,34496,34578,34588,34603,34694],34903],[0,"Thank you for listening.","Благодарим, че слушахте.",[34924,34986,35000,35013],35069],[0,"See you soon.","До скоро.",[35096,35119,35128],35180],[1,"Bye.","Чао.",[35199],35237]],"v":[["follow the news","следя новините",10],["too (much)","твърде (много)",23],["enough","достатъчно",30],["already","вече",38],["notifications","известия",23],["habit","навик",28],["addictive","пристрастяващ",29],["pay attention","обръщам внимание",37]],"g":[["interested",13,12,1],["regularly",14,20,1],["score",16,21,1],["overnight",19,17,1],["notifications",23,3,1],["break",24,4,1],["habit",28,7,1],["addictive",29,3,1],["control",29,23,1],["enough",30,23,1],["attention",37,6,1],["journalist",42,6,1]],"q":[["What does 'follow the news' mean?","Какво значи „follow the news“?","to be interested in the news","to write the news","to hate the news",13],["What does Neil do first thing in the morning?","Какво прави Нийл първо нещо сутрин?","he looks at the news on his phone","he reads a newspaper","he listens to the radio",19],["What is Beth's problem with her phone?","Какъв проблем има Бет с телефона си?","it sends her too many news notifications","it is too old","it has no internet",24],["Why does Neil think he follows the news?","Защо според Нийл следи новините?","it's a habit and a bit addictive","it's his job now","his wife asks him",28],["How has working at the BBC changed Beth?","Как работата в Би Би Си е променила Бет?","she pays more attention to the news","she never reads the news now","she watches more films",37],["What was Neil's job at the BBC before?","Каква беше работата на Нийл в Би Би Си преди?","a journalist","a cameraman","a teacher",42]]},"phones":{"ser":"Real Easy English","icon":"📱","bg":"Навици с телефона","t":"Phone habits","a":"ree/audio/phones.mp3","sp":["Neil","Becca"],"L":[[0,"Hello and welcome to Real Easy English.","Здравейте и добре дошли в Real Easy English.",[25,69,90,137,169,217,257],315],[0,"In this podcast, we have real conversations in easy English to help you learn.","В този подкаст водим истински разговори на лесен английски, за да ви помогнем да учите.",[335,348,369,435,452,494,531,620,644,695,763,778,805,816],848],[0,"I'm Neil.","Аз съм Нийл.",[877,891],923],[1,"And I'm Becca.","А аз съм Бека.",[946,967,988],1039],[1,"You can find a video version of this podcast along with a transcript to help you learn on our website, bbclearningenglish.com.","На нашия сайт ще намерите видео версия на подкаста и текст, който ще ви помогне да учите: bbclearningenglish.com.",[1070,1087,1107,1156,1166,1199,1253,1273,1291,1367,1395,1411,1417,1504,1521,1546,1559,1612,1623,1636,1695],1879],[0,"Hi Becca, how are you?","Здравей, Бека, как си?",[2484,2500,2532,2554,2559],2588],[1,"I'm well, thanks, Neil.","Добре съм, благодаря, Нийл.",[2594,2612,2638,2673],2705],[1,"How about you?","А ти?",[2705,2723,2748],2786],[0,"I'm pretty good.","Доста добре.",[2801,2816,2839],2864],[0,"Today, we're talking about phones.","Днес говорим за телефоните.",[2866,3001,3020,3079,3139],3228],[0,"Now, Becca, how much time do you spend on your phone every day?","Е, Бека, колко време прекарваш на телефона си всеки ден?",[3245,3314,3415,3497,3522,3569,3591,3620,3726,3741,3762,3817,3853],3883],[1,"Ooh, I don't know the number.","Ох, не знам числото.",[3905,4042,4095,4141,4203,4277],4349],[1,"I haven't checked my screen time in a while.","Отдавна не съм проверявала екранното си време.",[4372,4384,4441,4486,4523,4570,4616,4630,4633],4695],[1,"So, your screen time is the time in which you spend looking on your phone screen.","„Screen time“ е времето, което прекарваш в гледане на екрана на телефона.",[4727,4766,4795,4845,4891,4944,4959,5009,5027,5059,5073,5139,5180,5227,5241,5280],5325],[1,"I probably would guess that I spend quite a few hours looking at my phone.","Предполагам, че прекарвам доста часове в гледане на телефона си.",[5407,5440,5523,5551,5595,5609,5623,5670,5726,5729,5753,5836,5868,5881,5893],5933],[1,"How about you?","А ти?",[5958,5973,5991],6016],[0,"Yeah, I spend probably a lot of time on my phone every day, and I'm not really happy about that because I think it's a waste of time.","Да, вероятно прекарвам много време на телефона всеки ден и не съм особено доволен от това, защото мисля, че е загуба на време.",[6072,6159,6172,6301,6403,6414,6438,6448,6514,6525,6539,6581,6609,6689,6708,6722,6747,6773,6820,6947,7046,7114,7127,7161,7176,7180,7225,7233],7283],[0,"But I do it, like millions of other people.","Но го правя, като милиони други хора.",[7323,7444,7453,7481,7528,7553,7590,7599,7614],7655],[1,"Mmm, yeah. I mean, phones can be very useful.","Ммм, да. Искам да кажа, телефоните могат да са много полезни.",[7665,7748,7788,7791,7831,7875,7902,7915,7952],8007],[1,"You can get information very quickly.","Можеш да получиш информация много бързо.",[8074,8085,8102,8114,8167,8192],8241],[0,"Yes, this is true.","Да, това е вярно.",[8330,8369,8390,8400],8442],[0,"So, they are also really handy of course for finding out information quickly, and you can do loads of things that used to be quite hard to do.","Освен това, разбира се, са много удобни за бързо намиране на информация и можеш да правиш куп неща, които преди бяха доста трудни.",[8443,8470,8565,8587,8667,8754,8826,8843,8911,8937,8984,8999,9075,9197,9247,9259,9282,9360,9400,9408,9471,9498,9525,9532,9581,9616,9650,9660],9693],[1,"Yeah. One of those things that we can probably do better with phones is to connect with people and to have contact with people.","Да. Едно от нещата, които вероятно правим по-добре с телефоните, е да се свързваме с хората и да имаме контакт с тях.",[9711,9745,9767,9778,9806,9843,9857,9868,9884,9938,9967,10000,10013,10058,10084,10125,10165,10175,10223,10239,10263,10285,10331,10341],10386],[1,"Do you get lots of notifications from your friends and family on your phone?","Получаваш ли много известия от приятели и роднини на телефона си?",[10438,10450,10514,10543,10573,10618,10728,10747,10759,10792,10803,10839,10849,10865],10905],[0,"Because I don't like spending too much time on my phone, I turned off my notifications.","Понеже не обичам да прекарвам твърде много време на телефона, изключих известията си.",[10906,10996,11019,11057,11100,11152,11178,11212,11272,11293,11313,11375,11437,11476,11503,11527],11652],[0,"Now, notifications are the little messages that you get from apps when people or the app wants to tell you something.","Известията са малките съобщения, които получаваш от приложенията, когато хора или приложението искат да ти кажат нещо.",[11689,11756,11893,11914,11950,12057,12119,12137,12156,12198,12230,12320,12350,12442,12528,12548,12586,12617,12628,12653,12678],12788],[1,"OK. So, that's a good tip really, if you want to reduce your screen time, is to turn off your notifications.","Добре. Значи това е добър съвет, ако искаш да намалиш екранното си време – да изключиш известията.",[12822,12866,12878,12903,12906,12927,12960,13003,13015,13030,13055,13109,13159,13175,13216,13255,13278,13306,13337,13349,13362],13453],[0,"Yeah. I also try not to doomscroll.","Да. Опитвам се и да не „doomscroll“-вам.",[13522,13618,13631,13800,13850,13897,13922],14051],[0,"What's doomscrolling?","Какво е „doomscrolling“?",[14053,14150],14272],[1,"That's probably how I spend a lot of time on my phone.","Вероятно така прекарвам много време на телефона си.",[14336,14378,14501,14538,14551,14587,14592,14632,14643,14678,14690,14712],14780],[1,"So, when you doomscroll, you look at negative news stories or things that make you feel maybe a bit upset, a bit sad.","Когато „doomscroll“-ваш, гледаш негативни новини или неща, от които може би се разстройваш, натъжаваш.",[14781,14858,14883,14896,14959,15025,15054,15074,15205,15233,15291,15307,15355,15371,15397,15414,15470,15522,15527,15573,15637,15641,15660],15716],[1,"And you just keep scrolling and scrolling and scrolling and it really doesn't make you feel good.","И просто продължаваш да скролваш, и да скролваш, и да скролваш и наистина не се чувстваш добре от това.",[15762,15832,15853,15884,15907,15975,16000,16069,16090,16147,16166,16172,16210,16240,16273,16282,16306],16351],[0,"And so if you do, like you Becca, a lot of doomscrolling, that could be a sign of an addiction.","И ако правиш, като теб, Бека, много „doomscrolling“, това може да е признак на зависимост.",[16372,16384,16410,16445,16487,16603,16623,16638,16697,16709,16757,16785,16931,16966,17003,17047,17056,17122,17181,17197],17266],[0,"Now, an addiction is something that you can't stop doing.","Зависимостта е нещо, което не можеш да спреш да правиш.",[17333,17378,17399,17466,17506,17569,17587,17612,17668,17713],17771],[0,"So, for example, an obvious example is smoking.","Очевиден пример е пушенето.",[17825,17862,17888,17959,17993,18041,18115,18181],18252],[0,"People who smoke - they have an addiction.","Хората, които пушат, имат зависимост.",[18309,18344,18371,18371,18412,18425,18453,18465],18544],[0,"It's something they have to do.","Това е нещо, което трябва да правят.",[18547,18568,18602,18615,18659,18669],18709],[0,"And we hear a lot about phone addiction.","И чуваме много за зависимостта от телефона.",[18759,18783,18797,18838,18856,18937,18978,19042],19138],[1,"And it's really hard to stop an addiction.","И е наистина трудно да спреш зависимост.",[19138,19156,19174,19211,19269,19338,19400,19414],19480],[1,"Even though I know doomscrolling is very bad for me and it doesn't make me feel good, I can't stop doing it.","Въпреки че знам, че „doomscrolling“ е много лошо за мен и не се чувствам добре от него, не мога да спра.",[19530,19572,19638,19660,19684,19785,19802,19850,19889,19916,19960,19983,19994,20038,20069,20081,20105,20188,20205,20245,20269,20300],20322],[0,"I don't think you're alone, Becca, but do you think most people look at their phone too much?","Не мисля, че си сама, Бека, но мислиш ли, че повечето хора гледат телефона си твърде много?",[20358,20369,20394,20427,20450,20494,20544,20613,20625,20641,20719,20775,20862,20884,20894,20909,20954,20975],21025],[1,"I do, and I think that it doesn't matter how old you are.","Да, и мисля, че няма значение на колко си години.",[21038,21053,21112,21134,21147,21190,21207,21219,21247,21284,21362,21401,21422],21451],[1,"I see phone addictions with people my age, people younger and people older.","Виждам зависимост от телефона при хора на моята възраст, при по-млади и при по-възрастни.",[21453,21478,21560,21589,21653,21666,21731,21772,21798,21831,21860,21897,21934],21962],[1,"I think that a lot of people are addicted to their phones.","Мисля, че много хора са пристрастени към телефоните си.",[21963,22006,22031,22050,22053,22084,22091,22153,22172,22219,22230,22245],22307],[0,"Yeah. If you just look around anywhere.","Да. Просто се огледай навсякъде.",[22334,22404,22419,22428,22448,22469,22597],22675],[0,"Most people have their head down at that angle, looking at their phone, missing what's going on in the real world.","Повечето хора са с наведени глави под онзи ъгъл, гледат телефона си и изпускат какво става в истинския свят.",[22700,22728,22826,22841,22856,22880,22922,22945,22969,23084,23111,23122,23136,23206,23283,23309,23344,23362,23373,23381,23416],23459],[1,"OK. Let's recap the vocabulary we learnt in this episode.","Добре. Нека преговорим думите, които научихме в епизода.",[24138,24186,24219,24282,24294,24372,24389,24422,24438,24456],24538],[1,"First screen time, and that's the time that you spend looking at an electronic screen.","Първо „screen time“ – времето, което прекарваш в гледане на електронен екран.",[24539,24608,24651,24694,24719,24746,24756,24793,24808,24820,24873,24908,24942,24954,25006],25063],[1,"We usually use it to talk about looking at our phones.","Обикновено го използваме, когато говорим за гледане на телефоните си.",[25099,25120,25165,25196,25213,25223,25252,25286,25316,25331,25342],25413],[0,"We heard doomscrolling.","Чухме „doomscrolling“.",[25482,25501,25561],25666],[0,"Doomscrolling is when you look at one story after another, after another, after another, and they're usually bad news stories.","„Doomscrolling“ е когато гледаш една история след друга, и след друга, и след друга, а те обикновено са лоши новини.",[25688,25779,25814,25841,25868,25941,25958,26017,26113,26149,26231,26266,26342,26375,26436,26452,26464,26538,26600,26621],26679],[1,"Notifications are the messages that apps will send you to make you check your phone.","„Notifications“ са съобщенията, които приложенията ти изпращат, за да те накарат да провериш телефона си.",[26712,26831,26850,26857,26933,26963,26997,27010,27048,27078,27095,27125,27137,27164,27176],27233],[0,"If something is an addiction, it means that you can't stop doing it.","Ако нещо е „addiction“ (зависимост), значи не можеш да спреш да го правиш.",[27256,27273,27338,27358,27369,27451,27464,27501,27522,27534,27575,27633,27666],27691],[1,"That's it for this week's episode of Real Easy English.","Това е за епизода тази седмица на Real Easy English.",[27739,27776,27797,27812,27844,27872,27956,27985,28026,28085],28169],[1,"You can head to our website for a free worksheet to test what you've learnt.","Можете да отидете на нашия сайт за безплатен работен лист, за да проверите какво научихте.",[28170,28195,28210,28235,28254,28268,28341,28363,28369,28400,28473,28484,28521,28538,28559],28633],[1,"That's at bbclearningenglish.com.","Адресът е bbclearningenglish.com.",[28634,28665,28687],28925],[0,"And we'll be back next week with another conversation in easy English.","И ще се върнем следващата седмица с още един разговор на лесен английски.",[28926,28983,28995,29006,29040,29071,29102,29115,29144,29244,29260,29294],29334],[0,"Goodbye for now.","Засега довиждане.",[29335,29375,29387],29412],[1,"Bye!","Чао!",[29413],29481]],"v":[["screen time","екранно време",12],["doomscrolling","безкрайно скролване на лоши новини",28],["notifications","известия",23],["addiction","зависимост",32],["a waste of time","загуба на време",16],["handy","удобен, полезен",21],["turn off","изключвам",26],["reduce","намалявам",26]],"g":[["screen time",12,4,2],["waste of time",16,25,3],["useful",18,8,1],["handy",21,5,1],["notifications",23,5,1],["turned off",24,12,2],["reduce",26,11,1],["doomscroll",27,6,1],["negative",30,7,1],["upset",30,19,1],["addiction",32,19,1],["smoking",34,7,1]],"q":[["Does Becca know her screen time?","Знае ли Бека екранното си време?","no, she hasn't checked it in a while","yes, it's two hours","yes, it's ten minutes",12],["Why is Neil not happy about his phone time?","Защо Нийл не е доволен от времето на телефона?","he thinks it's a waste of time","his phone is old","it costs too much",16],["What did Neil do to spend less time on his phone?","Какво направи Нийл, за да прекарва по-малко време на телефона?","he turned off his notifications","he sold his phone","he deleted all apps",24],["What do you look at when you doomscroll?","Какво гледаш, когато „doomscroll“-ваш?","negative news stories","funny videos","photos of friends",30],["What is an example of an addiction, says Neil?","Какъв пример за зависимост дава Нийл?","smoking","reading","walking",34],["Who has phone addictions, according to Becca?","Кой има зависимост от телефона според Бека?","people of all ages","only young people","only old people",42]]},"airports":{"ser":"Real Easy English","icon":"🛂","bg":"На летището","t":"Airports","a":"ree/audio/airports.mp3","sp":["Neil","Becca"],"L":[[0,"Hi Becca.","Здравей, Бека.",[37,49],97],[1,"Hi Neil. How are you?","Здравей, Нийл. Как си?",[98,127,177,197,224],268],[1,"Have you got any trips coming up soon?","Предстоят ли ти скоро някакви пътувания?",[280,299,315,334,377,415,445,460],507],[0,"I have. I'm going to Montenegro, which is exciting.","Да. Отивам в Черна гора, което е вълнуващо.",[553,572,617,646,689,726,808,840,865],949],[0,"I've never been there before, but it means that I have to go to an airport and I have to fly.","Никога не съм бил там, но това значи, че трябва да отида на летище и да летя.",[974,982,999,1028,1046,1181,1216,1234,1274,1287,1308,1338,1348,1375,1401,1409,1484,1516,1521,1538,1546],1605],[0,"I don't like flying.","Не обичам да летя.",[1629,1636,1657,1682],1723],[1,"But we're talking about airports today in this episode of Real Easy English.","Но днес в този епизод на Real Easy English говорим за летищата.",[1723,1771,1784,1821,1841,1887,1929,1945,1962,2007,2018,2034,2064],2121],[0,"We are. But people need to know that to get a transcript and a worksheet for this episode, they need to go to our website, bblearningenglish.com.","Да. Но хората трябва да знаят, че за да получат текста и работния лист за епизода, трябва да отидат на нашия сайт, bbclearningenglish.com.",[2134,2155,2186,2252,2280,2298,2307,2338,2376,2388,2421,2434,2505,2541,2545,2614,2624,2645,2738,2749,2768,2777,2800,2817,2825,2877],3079],[1,"Absolutely. So, you'll be going to an airport for your holiday, but what happens at an airport, Neil?","Абсолютно. Значи ще ходиш на летище за почивката си, но какво става на летището, Нийл?",[3080,3855,3871,3894,3909,3952,3966,3974,4022,4036,4049,4235,4252,4272,4320,4327,4335,4380],4408],[0,"One of the most important things is check in.","Едно от най-важните неща е чекирането (check in).",[4444,4466,4480,4490,4530,4587,4631,4670,4713],4745],[0,"Now, to check in is to officially tell the airline that you're going to fly.","Да се чекираш значи официално да кажеш на авиокомпанията, че ще летиш.",[4802,4820,4831,4869,4895,4926,4980,5041,5088,5105,5198,5216,5238,5278,5291],5339],[0,"Normally, now, we do this online, but you can still check in at the airport, I think.","Обикновено сега го правим онлайн, но мисля, че все още можеш да се чекираш и на летището.",[5384,5477,5525,5555,5577,5627,5681,5716,5730,5766,5812,5844,5905,5914,5930,5984,5992],6030],[1,"Yes, you can.","Да, можеш.",[6055,6091,6102],6134],[1,"Yeah. So, there will be check-in gates.","Да. Там ще има гишета за чекиране.",[6134,6161,6180,6200,6220,6252,6298],6352],[1,"It is very important.","Много е важно.",[6402,6413,6430,6459],6558],[0,"It is, because they give you a boarding pass then, don't they?","Така е, защото тогава ти дават бордна карта, нали?",[6559,6567,6604,6656,6670,6691,6715,6733,6782,6826,6851,6884],6904],[1,"They do.","Да.",[6921,6932],6937],[0,"The boarding pass is the document that lets you get on the plane and also tells you what seat that you have on the plane as well.","Бордната карта е документът, с който се качваш на самолета, и също ти казва кое е мястото ти в самолета.",[6938,6962,7039,7082,7115,7211,7333,7390,7437,7454,7491,7506,7513,7593,7617,7665,7702,7714,7735,7800,7813,7830,7901,7916,7927,7963,7977],8003],[1,"So, you've checked in and you've got your boarding pass.","Значи си се чекирал и имаш бордна карта.",[8040,8092,8122,8164,8230,8243,8259,8285,8300,8347],8407],[1,"What happens next?","Какво следва?",[8426,8449,8490],8542],[0,"Well, then you need to go through security, and that's when they check you to make sure you haven't got anything that you shouldn't have on a plane.","Ами, после трябва да минеш през проверката за сигурност – там те проверяват, за да са сигурни, че нямаш нещо, което не бива да имаш в самолета.",[8597,8633,8696,8720,8740,8750,8774,8806,8947,8959,8988,9010,9044,9086,9115,9129,9156,9188,9203,9234,9280,9392,9405,9414,9447,9494,9522,9527],9578],[1,"I hate airport security.","Мразя проверката за сигурност на летището.",[9658,9709,9798,9859],9945],[1,"Even though I know that I'm not carrying anything that I'm not supposed to have, it still makes me feel a bit stressed.","Макар да знам, че не нося нищо непозволено, пак ме кара да се чувствам малко стресирана.",[10047,10100,10189,10212,10259,10284,10319,10361,10423,10488,10528,10544,10564,10609,10617,10714,10725,10752,10784,10798,10822,10827,10845],10931],[0,"Yeah, I know what you mean.","Да, знам какво имаш предвид.",[10958,10984,11008,11028,11038,11053],11086],[0,"You feel guilty even if you haven't done anything.","Чувстваш се виновен, дори да не си направил нищо.",[11088,11131,11169,11228,11261,11278,11291,11321,11352],11393],[1,"Exactly! Yeah, airport security is one of the reasons I don't really enjoy airports.","Точно! Да, проверката за сигурност е една от причините да не обичам особено летищата.",[11394,11574,11623,11664,11790,11818,11838,11849,11861,11902,11925,11959,12029,12089],12148],[0,"Really?","Наистина ли?",[12156],12197],[0,"You don't like airports?","Не обичаш летищата?",[12198,12226,12279,12301],12354],[1,"I don't like airports.","Не обичам летищата.",[12355,12359,12387,12406],12452],[1,"I enjoy flying but... yeah, airports can be a bit stressful for me.","Обичам да летя, но… да, летищата могат да са малко стресиращи за мен.",[12453,12466,12501,12628,12662,12729,12776,12812,12834,12838,12878,12938,12956],12997],[0,"Well, I'm the exact opposite of you because I quite like airports, but I really don't like flying.","Е, аз съм точно обратното на теб, защото доста харесвам летищата, но наистина не обичам да летя.",[13016,13050,13075,13088,13148,13201,13216,13279,13405,13430,13461,13494,13566,13622,13635,13704,13731,13758],13811],[1,"What do you like about airports?","Какво харесваш в летищата?",[13830,13863,13873,13891,13919,13947],14011],[0,"I think because when you finally get to the airport, it's somebody else's problem for you to travel.","Мисля, че защото когато най-после стигнеш до летището, пътуването ти вече е чужд проблем.",[14052,14058,14083,14161,14209,14232,14292,14322,14359,14375,14522,14569,14610,14671,14775,14793,14815,14825],14878],[0,"So, it's my responsibility to get to the airport but once I'm there, I can relax.","Моя отговорност е да стигна до летището, но щом съм там, мога да се отпусна.",[14919,14941,14993,15028,15125,15143,15179,15209,15222,15350,15365,15404,15425,15568,15575,15588],15641],[1,"OK. And have you ever been in a situation where you relaxed a bit too much and almost missed a flight?","Добре. А бил ли си в ситуация, в която си се отпуснал малко повече и почти си изпуснал полет?",[15659,15719,15768,15806,15838,15875,15925,15950,15954,16056,16079,16101,16159,16162,16207,16238,16422,16553,16609,16641,16645],16719],[0,"Yes, I have missed a flight once and it was very stressful.","Да, веднъж изпуснах полет и беше много стресиращо.",[16774,16838,16866,16900,16927,16930,16977,17081,17097,17106,17121,17174],17235],[0,"I was travelling in Ireland and I had a flight in Dublin, and I was in a different city - in Cork.","Пътувах из Ирландия и имах полет от Дъблин, а бях в друг град – в Корк.",[17347,17360,17384,17425,17443,17566,17624,17631,17650,17655,17743,17778,17850,17866,17875,17900,17922,17932,17969,17969,18041,18059],18116],[0,"And I missed the train from Cork to Dublin and so I couldn't get to the airport on time.","И изпуснах влака от Корк за Дъблин, така че не можах да стигна до летището навреме.",[18181,18200,18203,18277,18286,18368,18396,18434,18446,18541,18552,18578,18586,18622,18740,18753,18768,18850,18886],18920],[1,"So, you did miss that flight?","Значи наистина изпусна онзи полет?",[18962,18975,18997,19022,19053,19071],19106],[0,"I missed it.","Изпуснах го.",[19106,19109,19140],19171],[1,"Oh no!","О, не!",[19172,19197],19328],[0,"So, Becca, have you ever missed a flight?","А ти, Бека, изпускала ли си полет?",[19369,19415,19449,19472,19511,19565,19593,19596],19644],[1,"Thankfully, no, I haven't missed a flight.","За щастие не, не съм изпускала полет.",[19706,19775,19800,19896,20019,20042,20044],20093],[1,"I was very close to missing a flight...","Бях много близо да изпусна полет…",[20094,20109,20136,20187,20258,20278,20311,20316],20354],[1,"I was just relaxing.","Просто си почивах.",[20402,20471,20520,20550],20659],[1,"I had travelled from Vietnam and I was really tired, so I wasn't really listening carefully.","Бях пристигнала от Виетнам и бях много уморена, така че не слушах внимателно.",[20668,20689,20709,20763,20847,20930,20940,20951,20975,21011,21090,21109,21192,21226,21258,21313],21387],[1,"Well, they didn't call my name, so I was really stressed trying to find the gate, but luckily I caught it.","Е, не извикаха името ми, но бях много стресирана, докато търсех изхода, но за щастие успях да хвана полета.",[21528,21620,21633,21657,21678,21693,21739,21777,21860,21888,21936,22064,22096,22105,22128,22135,22222,22245,22303,22317,22355],22385],[1,"I think I was the last person to board the plane, and that's always a little bit embarrassing as well.","Мисля, че бях последният човек, който се качи в самолета, а това винаги е и малко неудобно.",[22386,22398,22418,22423,22441,22449,22499,22566,22586,22610,22617,22659,22677,22700,22764,22773,22824,22845,22929,22943],22979],[0,"You know what, Becca?","Знаеш ли какво, Бека?",[23012,23020,23040,23065],23121],[0,"I think if you get your name read out on the loudspeaker in an airport, that's really embarrassing because everyone in the airport is thinking, \"Who's that person?","Мисля, че ако прочетат името ти по високоговорителя на летището, това е наистина неудобно, защото всички на летището си мислят: „Кой е този човек?",[23130,23150,23218,23234,23249,23272,23295,23371,23418,23497,23514,23520,23597,23615,23626,23708,23730,23793,23919,24029,24084,24095,24112,24162,24175,24259,24291,24325],24424],[0,"That person who's going to miss their flight!\"","Онзи, който ще изпусне полета си!“",[24445,24481,24525,24550,24579,24589,24615,24637],24691],[1,"And you don't want to be that person.","А ти не искаш да си този човек.",[24692,24711,24752,24772,24797,24806,24869,24891],24951],[0,"OK. Becca, it's time to recap the vocabulary that we used in this episode, starting with check in.","Добре. Бека, време е да преговорим думите, които използвахме в епизода, като започнем с „check in“.",[25597,25628,25653,25681,25704,25715,25776,25787,25879,25895,25914,25969,25996,26019,26089,26135,26156,26198],26225],[0,"Check in is the verb, which means you officially tell the plane company that you plan to get on the plane, and you give them your bags as well.","„Check in“ е глаголът, който значи, че официално казваш на авиокомпанията, че ще се качиш на самолета, и им даваш и багажа си.",[26269,26294,26308,26324,26336,26378,26400,26480,26505,26559,26599,26606,26642,26693,26730,26742,26791,26800,26838,26858,26864,26977,26991,27000,27020,27060,27075,27121,27135],27163],[0,"And at the airport you do this at the check-in desk.","На летището правиш това на гишето за чекиране.",[27212,27275,27290,27300,27345,27360,27385,27413,27462,27473,27553],27607],[1,"Yes. And at the check-in desk, that's where you get your boarding pass, and that's the ticket that you need to get on the plane.","Да. А на гишето за чекиране получаваш бордната си карта – билетът, който ти трябва, за да се качиш на самолета.",[27656,27702,27744,27764,27775,27822,27870,27895,27906,27921,27940,27956,28006,28053,28072,28098,28108,28144,28162,28189,28252,28264,28283,28296,28302],28345],[0,"And then we heard the expression go through security.","После чухме израза „go through security“.",[28398,28433,28462,28473,28510,28531,28597,28626,28670],28765],[0,"If you go through security, you go through that area where they check and make sure you have nothing with you that should not be on a plane.","Ако „go through security“, минаваш през зоната, където проверяват и се уверяват, че нямаш нищо, което не бива да е в самолета.",[28796,28807,28821,28860,28888,28950,28965,28988,29019,29048,29103,29144,29158,29202,29234,29257,29288,29310,29333,29383,29406,29425,29441,29483,29521,29546,29562,29565],29598],[1,"Yes. Going through security - my least favourite thing about airports.","Да. Проверката за сигурност – най-неприятното за мен нещо на летищата.",[29677,29723,29766,29796,29796,29863,29906,29946,29985,30022,30054],30125],[1,"After security, you wait at the boarding gate and this is the area that you wait at before you get on the plane.","След проверката чакаш на изхода за качване – мястото, където чакаш, преди да се качиш на самолета.",[30167,30197,30288,30319,30356,30375,30389,30428,30460,30476,30495,30512,30539,30611,30631,30644,30675,30693,30731,30747,30772,30787,30794],30841],[0,"If you catch a flight, it means you successfully get on the plane and fly somewhere, but if you miss a flight, like I did in Ireland, it means that you were too late to get on the plane.","Ако „catch a flight“, значи успешно се качваш на самолета и летиш някъде, а ако „miss a flight“, както аз в Ирландия, значи си закъснял да се качиш на самолета.",[30900,30919,30954,31001,31013,31061,31076,31113,31123,31206,31235,31257,31264,31301,31317,31349,31393,31416,31438,31456,31516,31527,31592,31620,31639,31677,31700,31807,31820,31875,31889,31902,31910,31952,32006,32021,32055,32069,32077],32114],[1,"Well, Neil, that's it for this week's episode of Real Easy English, but we'll be back next week with another episode.","Е, Нийл, това е за епизода тази седмица на Real Easy English, но ще се върнем следващата седмица с още един епизод.",[32179,32217,32248,32278,32290,32303,32328,32350,32388,32397,32413,32446,32509,32577,32595,32615,32651,32695,32733,32758,32804],32900],[0,"Don't forget that you can download a free worksheet on our website, bbclearningenglish.com.","Не забравяйте, че можете да свалите безплатен работен лист от нашия сайт, bbclearningenglish.com.",[32901,32920,32956,32970,32984,33001,33053,33057,33088,33156,33175,33191,33254],33420],[0,"Goodbye for now.","Засега довиждане.",[33487,33515,33525],33545],[1,"Bye!","Чао!",[33546],33589]],"v":[["check in","чекирам се",9],["boarding pass","бордна карта",15],["go through security","минавам през проверката за сигурност",20],["boarding gate","изход за качване",59],["catch a flight","хващам полет",60],["miss a flight","изпускам полет",60],["stressful","стресиращ",29],["embarrassing","неудобен, срамен",47]],"g":[["trips",2,4,1],["check in",9,7,2],["airline",10,9,1],["boarding pass",15,7,2],["security",20,7,1],["stressed",22,22,1],["guilty",24,2,1],["responsibility",33,3,1],["missed",34,18,1],["on time",37,17,2],["embarrassing",47,17,1],["loudspeaker",49,11,1]],"q":[["Where is Neil going on holiday?","Къде отива Нийл на почивка?","to Montenegro","to Ireland","to Vietnam",3],["What does the boarding pass tell you?","Какво ти казва бордната карта?","which seat you have","the weather","the price of the ticket",17],["How does airport security make Becca feel?","Как се чувства Бека на проверката за сигурност?","a bit stressed","very happy","bored",22],["What does Neil not like?","Какво не харесва Нийл?","flying","airports","trains",30],["Why did Neil miss his flight in Ireland?","Защо Нийл изпусна полета си в Ирландия?","he missed the train from Cork to Dublin","he forgot his passport","he was asleep at the airport",37],["Did Becca miss her flight after Vietnam?","Изпусна ли Бека полета си след Виетнам?","no, but she was the last person to board","yes, she missed it","she didn't fly",47]]},"interviews":{"ser":"Real Easy English","icon":"💼","bg":"Интервю за работа","t":"Job interviews","a":"ree/audio/interviews.mp3","sp":["Becca","Neil"],"L":[[0,"Hi Neil. How are you?","Здравей, Нийл. Как си?",[28,52,84,100,110],157],[1,"I'm very well, Becca.","Много добре, Бека.",[169,180,201,222],258],[1,"How are you?","Ти как си?",[259,278,283],310],[0,"Yeah, I'm very well as well, thank you.","Да, и аз съм много добре, благодаря.",[324,376,405,435,457,473,498,538],567],[0,"Today on Real Easy English, we're talking about job interviews.","Днес в Real Easy English говорим за интервютата за работа.",[577,662,681,699,727,770,787,839,900,926],994],[1,"Job interviews... they're quite hard, aren't they?","Интервютата за работа… доста са трудни, нали?",[1043,1070,1186,1201,1234,1272,1292],1310],[0,"They are. They're a little bit stressful.","Така е. Малко са стресиращи.",[1311,1348,1370,1394,1398,1454,1471],1547],[1,"Very stressful.","Много стресиращи.",[1561,1585],1650],[0,"But first, before we get started, we need to remind our listeners and our watchers that there is a transcript and a worksheet and activities over on our website, bbclearningenglish.com.","Но първо, преди да започнем, трябва да напомним на слушателите и зрителите ни, че на нашия сайт има текст, работен лист и упражнения: bbclearningenglish.com.",[1650,1680,1732,1759,1770,1786,1891,1900,1916,1927,1975,1993,2059,2091,2112,2180,2259,2293,2327,2334,2412,2423,2427,2480,2489,2614,2634,2641,2656,2716],2888],[1,"So, Becca, job interviews - how do they make you feel?","Е, Бека, интервютата за работа – как те карат да се чувстваш?",[3462,3488,3534,3584,3584,3672,3711,3723,3740,3772,3809],3861],[0,"Ooh, they make me feel a little bit nervous, Neil.","Ох, карат ме да се чувствам малко нервна, Нийл.",[3877,3962,3980,4009,4029,4080,4092,4141,4165,4230],4266],[1,"Nervous?","Нервна?",[4317],4384],[1,"Is that because it's an important thing and you really want it to go well, so it's that feeling of being worried that it won't go well?","Защото е важно и наистина искаш да мине добре, тоест това е чувството, че се притесняваш, че няма да мине добре?",[4386,4405,4423,4533,4559,4567,4630,4675,4684,4700,4728,4767,4788,4801,4827,4887,4909,4922,4939,4984,4996,5063,5123,5135,5145,5182,5207],5239],[0,"Exactly. And I think it is natural to be nervous and natural to worry a little bit, because if you're not worried, it means that you don't care.","Точно. И мисля, че е естествено да си нервен и естествено да се тревожиш малко, защото ако не се тревожиш, значи не ти пука.",[5256,5340,5356,5365,5391,5400,5430,5492,5511,5526,5591,5675,5717,5732,5774,5777,5805,5829,5892,5907,5916,5933,5972,5982,6012,6022,6035,6082],6114],[1,"That's true, yeah.","Вярно е, да.",[6157,6178,6216],6243],[1,"And it's actually... it's a really strange situation, a job interview, because you meet these people, who you don't know, and you have to be friendly and smiley and show that you're a nice person, but also that you are serious and you can do the job.","А всъщност… това е наистина странна ситуация, интервюто за работа, защото срещаш хора, които не познаваш, и трябва да си дружелюбен и усмихнат и да покажеш, че си приятен човек, но и че си сериозен и можеш да вършиш работата.",[6244,6262,6282,6389,6402,6406,6440,6498,6573,6589,6619,6679,6790,6804,6831,6856,6935,6951,6962,6989,7042,7087,7098,7119,7130,7147,7226,7239,7361,7378,7414,7426,7452,7457,7484,7584,7601,7643,7658,7675,7683,7760,7778,7790,7807,7823,7832],7876],[0,"And it is difficult to find that balance between being very friendly and also seeming very confident in yourself.","И е трудно да намериш баланса между това да си много дружелюбен и да изглеждаш много уверен в себе си.",[7909,7929,7941,7964,8020,8036,8079,8097,8144,8198,8231,8331,8406,8475,8512,8550,8600,8696,8715],8781],[0,"What are some common questions that you might be asked in an interview?","Кои са някои често срещани въпроси, които може да ти зададат на интервю?",[8783,8809,8817,8864,8924,8999,9017,9062,9089,9112,9174,9187,9197],9255],[1,"So, a really common interview question is, \"Why do you want this job?\" and it's a good question because if you don't want the job, it means that you're lying immediately and that's not a good sign.","Много често срещан въпрос на интервю е: „Защо искате тази работа?“ – и е добър въпрос, защото ако не искаш работата, значи веднага лъжеш, а това не е добър знак.",[9287,9349,9353,9398,9469,9518,9591,9657,9700,9717,9732,9761,9788,9879,9889,9904,9908,9926,10011,10106,10130,10142,10166,10191,10200,10362,10377,10401,10412,10431,10506,10612,10649,10688,10711,10714,10738],10777],[1,"So, I think that's a really good question, but it can be difficult to answer so you should probably be prepared and think about it before the interview.","Така че мисля, че това е наистина добър въпрос, но може да е трудно да се отговори, затова вероятно трябва да си подготвен и да помислиш преди интервюто.",[10797,10890,10899,10926,10950,10954,10984,11014,11074,11091,11104,11156,11212,11278,11303,11348,11371,11391,11409,11480,11506,11580,11592,11631,11673,11773,11825,11838],11884],[0,"I think with that question as well, it's really important to be confident in your answer, because there will be lots of people who are answering that same question as well.","Мисля, че и при този въпрос е много важно да си уверен в отговора си, защото ще има много хора, които отговарят на същия въпрос.",[11898,11905,11961,11994,12017,12064,12080,12109,12131,12159,12227,12262,12364,12450,12467,12492,12569,12606,12617,12628,12644,12680,12689,12730,12748,12777,12816,12834,12871,12938,12963],12984],[1,"Yeah, absolutely. And also, it's a little bit false when you are talking in an interview because you are answering the questions, but you're also trying to display lots of things, so you're trying to tell someone about your skills and your experience, for example.","Да, абсолютно. А и е малко неестествено, когато говориш на интервю, защото отговаряш на въпросите, но и се опитваш да покажеш много неща – опитваш се да кажеш на някого за уменията и опита си например.",[13006,13040,13121,13138,13275,13300,13305,13338,13392,13478,13500,13524,13540,13594,13610,13620,13689,13790,13813,13857,13908,13915,13983,13998,14012,14048,14087,14142,14217,14250,14261,14334,14353,14369,14403,14412,14464,14506,14534,14552,14642,14682,14709,14791,14803],14859],[0,"Yeah.","Да.",[14872],14900],[1,"Your skills are the things that you can do that will make you good for the job.","Уменията ти са нещата, които можеш да правиш и които ще те направят подходящ за работата.",[14919,14931,14980,14989,14999,15050,15061,15081,15109,15200,15218,15236,15264,15275,15296,15309,15322],15359],[1,"And the experience, of course, is if you have done this kind of thing before.","А опитът, разбира се, е дали си правил такова нещо преди.",[15399,15437,15447,15531,15548,15589,15669,15689,15702,15722,15756,15781,15814,15823,15859],15944],[0,"Yeah. And usually, you'll give the interviewer your CV, your cover letter, which is a piece of paper that has your skills and experiences, but they'll still ask you about these things, and they'll want a little bit of a more detailed explanation so that they can get to know you a bit more.","Да. И обикновено даваш на интервюиращия своята автобиография, мотивационното си писмо – лист хартия с уменията и опита ти, но те пак ще те питат за тези неща и ще искат малко по-подробно обяснение, за да те опознаят малко повече.",[16003,16009,16108,16162,16199,16248,16324,16458,16494,16562,16580,16609,16656,16683,16722,16728,16755,16762,16793,16809,16843,16864,16901,16910,17049,17063,17082,17125,17164,17228,17259,17281,17320,17354,17370,17404,17409,17444,17481,17503,17508,17597,17662,17767,17788,17804,17819,17850,17866,17881,17895,17922,17929,17948],17979],[1,"Yeah. And what they really want is examples.","Да. А това, което наистина искат, са примери.",[18009,18034,18061,18091,18109,18145,18209,18230],18312],[1,"So, I think it's very easy to say, \"Oh, you should do this or you should do this in this situation.\" But if you can say, \"I did this in a previous job.","Мисля, че е много лесно да кажеш: „О, трябва да се направи това или това в тази ситуация.“ Но ако можеш да кажеш: „Направих това на предишна работа.",[18362,18402,18415,18461,18478,18521,18630,18643,18759,18819,18843,18884,18910,18989,19010,19031,19059,19082,19129,19147,19170,19296,19317,19334,19348,19358,19401,19450,19486,19591,19604,19610,19669],19706],[1,"I did this and then it was a successful result,\" then that is what people want to hear.","Направих това и резултатът беше успешен“ – тогава това е, което хората искат да чуят.",[19716,19745,19770,19865,19890,20018,20029,20058,20070,20156,20268,20314,20363,20378,20396,20426,20446,20458],20487],[0,"Absolutely, yeah. And on top of that, another way to prepare for a job interview is to research the company or wherever it is that you're interviewing because if you can give them examples that fit, maybe with the job that you're interviewing for, then they'll really like that.","Абсолютно, да. А освен това друг начин да се подготвиш за интервю е да проучиш фирмата или мястото, където кандидатстваш, защото ако можеш да им дадеш примери, които пасват – може би с работата, за която кандидатстваш, – това наистина ще им хареса.",[20512,20593,20626,20667,20685,20716,20731,20776,20807,20828,20846,21001,21021,21024,21042,21113,21156,21244,21364,21403,21482,21507,21554,21570,21588,21600,21625,21798,21840,21848,21859,21878,21894,21909,21979,22038,22092,22131,22150,22163,22200,22222,22248,22303,22334,22416,22438,22535,22564],22585],[1,"Yeah, that's really good advice on how to prepare for a job interview.","Да, това е наистина добър съвет как да се подготвиш за интервю за работа.",[22613,22639,22666,22687,22704,22756,22778,22795,22838,22900,22919,22948,22973],23066],[1,"Now, job interviews don't always go well.","Е, интервютата не винаги минават добре.",[23069,23134,23159,23209,23235,23287,23388],23438],[1,"Can you think of a time you've had a really bad question?","Сещаш ли се за случай, когато са ти задали наистина лош въпрос?",[23503,23521,23538,23590,23610,23615,23737,23749,23762,23766,23794,23828],23882],[1,"What's the worst question you've had?","Кой е най-лошият въпрос, който са ти задавали?",[23884,23910,23919,23956,24012,24028],24062],[0,"Ooh... often the interviewer will ask what your weakness is.","Ох… често интервюиращият пита каква е слабостта ти.",[24084,24216,24330,24422,24512,24565,24635,24666,24686,24769],24826],[0,"So, you have your strengths - those are the things that you're really good at - so, like, your skills.","Имаш силни страни – нещата, в които си наистина добър – тоест уменията си.",[24828,24864,24883,24900,24917,24917,24991,25028,25038,25050,25077,25087,25099,25120,25140,25140,25176,25222,25244,25254],25311],[0,"And then your weaknesses are the things that you might not be so good at, so you don't really want to tell the interviewer what you're not good at!","А после слабостите ти са нещата, в които може би не си толкова добър, така че всъщност не искаш да казваш на интервюиращия в какво не си добър!",[25378,25390,25401,25413,25512,25557,25577,25612,25638,25646,25683,25698,25725,25741,25764,25835,25844,25862,25891,25931,25954,25963,26122,26140,26208,26250,26266,26283,26301],26323],[0,"But it is important, I think, to be honest.","Но мисля, че е важно да си честен.",[26326,26353,26367,26416,26484,26494,26526,26538,26554],26636],[1,"Yeah.","Да.",[26679],26700],[0,"Maybe it's difficult to balance me saying what my weaknesses are, but also, you know, kind of making that good for the job.","Може би е трудно да намеря баланса между това да кажа какви са слабостите ми, но и, знаеш, някак да го обърна в полза на работата.",[26701,26864,26885,26927,26939,27072,27134,27179,27220,27235,27291,27306,27320,27418,27431,27441,27585,27596,27636,27747,27775,27793,27804],27843],[1,"Yeah, it's really... it's really tricky to answer because you don't want to be completely honest and say, \"Oh well, my weakness is I really hate working and I can't get up on time.\"","Да, наистина е… наистина е трудно да се отговори, защото не искаш да си напълно честен и да кажеш: „Ами, слабостта ми е, че наистина мразя да работя и не мога да ставам навреме.“",[27863,27905,27924,28015,28038,28075,28107,28125,28160,28264,28281,28300,28319,28325,28344,28400,28454,28477,28506,28531,28618,28633,28683,28707,28714,28743,28781,28823,28994,28996,29038,29058,29081,29098],29144],[0,"Yeah...!","Да…!",[29271],29319],[1,"But you also don't want to pretend that you're perfect because nobody believes that somebody is perfect.","Но и не искаш да се правиш на съвършен, защото никой не вярва, че някой е съвършен.",[29368,29469,29492,29590,29610,29629,29637,29690,29701,29713,29770,29793,29839,29903,29919,29953,29963],30013],[0,"Absolutely, yeah. Alright Neil, it's time to recap some of the vocabulary that we used in this conversation.","Абсолютно, да. Добре, Нийл, време е да преговорим някои от думите, които използвахме в разговора.",[30014,30127,30839,30870,30912,30940,30967,30981,31032,31054,31065,31076,31152,31166,31178,31220,31231,31244],31332],[0,"And the first is an adjective that we all probably might feel in a job interview and that is nervous.","Първата е прилагателно, което вероятно всички може да изпитаме на интервю за работа – „nervous“.",[31333,31388,31394,31444,31456,31462,31522,31550,31571,31614,31662,31687,31744,31759,31764,31783,31835,31852,31867,31887],31969],[0,"So, nervous is when you feel worried about something.","„Nervous“ е когато се тревожиш за нещо.",[32009,32025,32084,32104,32127,32147,32181,32254,32282],32335],[1,"Yeah, we also heard, or we used, the word confident.","Да, чухме, или използвахме, и думата „confident“.",[32394,32471,32482,32527,32591,32594,32612,32656,32663,32691],32775],[1,"If you are confident, it means that you are fairly sure that you're going to do well at something.","Ако си „confident“, значи си доста сигурен, че ще се справиш добре с нещо.",[32850,32873,32891,32900,32970,32988,33043,33057,33135,33155,33200,33266,33280,33297,33331,33342,33374,33435,33449],33497],[0,"And you can be confident in your skills, for example.","И можеш да си уверен например в уменията си.",[33533,33568,33581,33600,33616,33691,33706,33736,33806,33833],33889],[0,"So, your skills are the things that you can do.","Уменията ти са нещата, които можеш да правиш.",[33891,33919,33948,34051,34068,34076,34109,34124,34143,34181],34211],[0,"And when you're in a job interview, you need to tell the person interviewing you which skills you're good at.","А когато си на интервю за работа, трябва да кажеш на човека, който те интервюира, в кои умения си добър.",[34212,34232,34251,34268,34275,34284,34306,34405,34415,34456,34478,34524,34534,34574,34653,34724,34754,34804,34822,34841],34885],[1,"Yes, and it's best if you use examples - examples of real things that you've done that you can tell people, so it doesn't sound like you just took these examples from the internet.","Да, и е най-добре да използваш примери – примери за истински неща, които си правил и можеш да разкажеш, за да не звучи все едно просто си взел тези примери от интернет.",[34906,34988,35062,35082,35155,35179,35203,35269,35269,35440,35519,35573,35603,35644,35656,35681,35725,35747,35764,35785,35814,35858,35878,35892,35938,35974,35995,36007,36069,36101,36122,36188,36223,36236],36289],[0,"Well, that's it for this episode of Real Easy English, but we have a worksheet on our website.","Е, това е за този епизод на Real Easy English, но на нашия сайт има работен лист.",[36404,36416,36445,36461,36470,36488,36529,36538,36554,36581,36636,36676,36701,36711,36736,36827,36858,36878],36948],[0,"That's at bbclearningenglish.com.","Адресът е bbclearningenglish.com.",[36950,36982,37004],37222],[1,"Join us again next week for another easy conversation.","Присъединете се отново следващата седмица за още един лесен разговор.",[37250,37270,37282,37306,37336,37359,37377,37414,37454],37529],[1,"Bye for now.","Засега чао.",[37530,37566,37577],37600],[0,"Bye!","Чао!",[37600],37648]],"v":[["nervous","нервен, притеснен",10],["confident","уверен",16],["skills","умения",21],["experience","опит",21],["weakness","слабост",34],["strengths","силни страни",35],["CV","автобиография",25],["prepared","подготвен",19]],"g":[["stressful",6,6,1],["nervous",10,8,1],["natural",13,6,1],["balance",16,7,1],["confident",16,16,1],["prepared",19,20,1],["skills",21,39,1],["experience",21,42,1],["examples",26,7,1],["research",29,17,1],["weakness",34,8,1],["honest",37,8,1]],"q":[["How do job interviews make Becca feel?","Как се чувства Бека на интервю за работа?","a little bit nervous","very happy","angry",10],["Why is it natural to be worried, says Becca?","Защо е естествено да се тревожиш според Бека?","if you're not worried, you don't care","because interviews are easy","because you will fail",13],["What is a common interview question?","Кой е често срещан въпрос на интервю?","Why do you want this job?","How old are you?","Where do you live?",18],["What do interviewers really want, says Neil?","Какво наистина искат интервюиращите според Нийл?","examples","a smile","a short answer",26],["How else can you prepare for an interview?","Как още можеш да се подготвиш за интервю?","research the company","buy new clothes","sleep all day",29],["What is a difficult question for Becca?","Кой е труден въпрос за Бека?","What is your weakness?","Why do you want this job?","What is your name?",34]]},"coffee":{"ser":"6 Minute English","icon":"☕","bg":"Ароматът на кафето","t":"Coffee","a":"ree/audio/coffee.mp3","sp":["Neil","Catherine","Tim Hayward"],"L":[[0,"Hello. Welcome to 6 Minute English, I'm Neil.","Здравейте. Добре дошли в 6 Minute English, аз съм Нийл.",[78,102,157,185,212,233,328,336],349],[1,"And I'm Catherine.","А аз съм Катрин.",[350,366,384],418],[0,"Catherine, I'm going to start this programme with a quick test, just for you.","Катрин, ще започна това предаване с кратък тест само за теб.",[441,468,479,510,520,743,806,892,914,937,949,979,1063,1112],1206],[1,"Ooo, I love tests!","Ооо, обичам тестове!",[1356,1388,1400,1435],1476],[0,"Complete this phrase: Wake up and smell the...","Довърши фразата: „Събуди се и помириши…“",[1477,1526,1547,1560,1585,1602,1653,1672],1704],[1,"Coffee Neil! It's coffee.","Кафето, Нийл! Кафето.",[1734,1772,1796,2757],2798],[1,"I have to say, I love coffee, it's great.","Трябва да кажа, обичам кафе, страхотно е.",[2800,2811,2825,2836,2870,2888,2939,2988,3002],3102],[0,"OK, so do you drink much?","Добре, и много ли пиеш?",[3104,3139,3166,3181,3193,3228],3270],[1,"Well, just a couple of cups, you know.","Ами, само няколко чаши, нали знаеш.",[3271,3345,3373,3378,3406,3417,3455,3466],3505],[0,"Every day?","Всеки ден?",[3538,3584],3614],[1,"No, every hour!","Не, всеки час!",[3616,3627,3773],3809],[1,"I love coffee, don't you like coffee, Neil?","Обичам кафе, ти не обичаш ли кафе, Нийл?",[3809,3875,3920,3953,3974,3988,4003,4036],4073],[0,"I do but maybe not as much as you!","Обичам, но може би не колкото теб!",[4127,4139,4192,4234,4259,4288,4303,4312,4330],4334],[0,"What's the best thing about it?","Кое е най-хубавото нещо в него?",[4335,4441,4447,4475,4488,4530],4539],[1,"It's the smell.","Ароматът.",[4541,4555,4562],4608],[1,"It's got to be the smell.","Определено ароматът.",[4609,4625,4645,4655,4672,4681],4709],[1,"You know, when you open the packet, it's great isn't it?","Знаеш, когато отвориш пакета, страхотно е, нали?",[4711,4728,4745,4761,4772,4806,4814,4855,4870,4931,4961],4995],[0,"Yes, but it never quite tastes as good as it smells, does it?","Да, но вкусът никога не е съвсем толкова хубав, колкото ароматът, нали?",[5052,5083,5092,5102,5133,5200,5262,5284,5300,5311,5317,5361,5381],5391],[1,"Well no, not really.","Ами не, не съвсем.",[5416,5456,5497,5522],5541],[1,"It's always a little disappointing.","Винаги е малко разочароващо.",[5542,5555,5575,5578,5602],5672],[1,"I live in hope, another cup, I think it will be better.","Живея с надежда – още една чаша и мисля, че ще е по-добре.",[5680,5695,5712,5723,5762,5798,5834,5838,5865,5876,5884,5903],5937],[1,"I might change brands actually and try a different one.","Всъщност може да сменя марката и да опитам друга.",[5938,5949,5977,6009,6063,6106,6117,6141,6148,6184],6223],[0,"OK, you've had quite a lot of coffee today, haven't you?","Добре, днес си изпила доста кафе, нали?",[6231,6320,6334,6347,6363,6366,6377,6384,6419,6445,6477],6492],[1,"Just the usual six cups.","Само обичайните шест чаши.",[6528,6547,6566,6614,6650],6697],[0,"Well, our topic today is the smell of coffee and coffee is also the subject of today's question.","Е, темата ни днес е ароматът на кафето, а кафето е и темата на днешния въпрос.",[6762,6816,6846,6893,6905,6915,6924,6989,7000,7049,7059,7112,7126,7147,7157,7208,7216,7249],7307],[0,"The world's biggest producer of coffee is...","Най-големият производител на кафе в света е…",[7343,7358,7414,7469,7524,7533,7586],7617],[1,"Brazil! Brazil!","Бразилия! Бразилия!",[7618,7722],7772],[0,"Yes, yes, but that's not the question.","Да, да, но това не е въпросът.",[7773,7823,7878,7892,7919,7936,7942],7991],[0,"The question is, Brazil is the biggest coffee producer, which is the second largest coffee producing country?","Въпросът е: Бразилия е най-големият производител на кафе, а коя е втората по големина страна производител на кафе?",[8042,8049,8090,8127,8196,8217,8224,8272,8302,8412,8437,8450,8460,8540,8595,8627,8676],8728],[0,"Is it: a: Colombia b: Vietnam c: Ethiopia","Дали е: а) Колумбия, б) Виетнам, в) Етиопия?",[8729,8744,8759,8793,8875,8934,8997,9039],9099],[1,"Right, so it's not Brazil but I bet it's another South American country, so I'm going to go for Columbia.","Добре, значи не е Бразилия, но обзалагам се, че е друга южноамериканска страна, така че ще избера Колумбия.",[9237,9259,9269,9281,9302,9340,9354,9365,9389,9406,9431,9461,9509,9573,9584,9597,9609,9616,9634,9675],9741],[1,"Columbia, is that right?","Колумбия – вярно ли е?",[9742,9805,9811,9828],9875],[0,"OK, we'll have the answer later in the programme by which time, maybe the caffeine will have left your body Catherine.","Добре, ще кажем отговора по-късно в предаването, когато може би кофеинът вече ще е излязъл от тялото ти, Катрин.",[9875,9913,9928,9944,9955,9989,10047,10072,10077,10130,10141,10162,10181,10278,10284,10333,10344,10360,10391,10405,10464],10508],[0,"Tim Hayward is a coffee shop owner.","Тим Хейуърд е собственик на кафене.",[10555,10584,10622,10655,10677,10711,10741],10772],[0,"He appeared in the BBC Radio 4 programme The Kitchen Cabinet.","Той участва в предаването на BBC Radio 4 „The Kitchen Cabinet“.",[10773,10797,10856,10869,10875,10923,10956,10983,11055,11064,11105],11169],[0,"How important does he say the smell of coffee is?","Колко важен казва, че е ароматът на кафето?",[11202,11238,11289,11308,11316,11344,11352,11384,11394,11433],11458],[2,"It's absolutely vital, it's the key thing.","Абсолютно жизненоважен е, това е ключовото нещо.",[11539,11573,11658,11714,11773,11781,11805],11836],[2,"And when you walk in to the coffee shop in the morning and that smell hits you, you're getting physiological responses.","И когато влезеш в кафенето сутрин и те удари този аромат, получаваш физиологични реакции.",[11838,11861,11881,11938,11981,11991,11998,12008,12031,12048,12055,12061,12089,12098,12114,12144,12170,12183,12197,12227,12283],12353],[0,"So how important is it?","Е, колко важен е?",[12423,12442,12461,12512,12527],12553],[1,"I'm feeling a bit calmer now.","Вече се чувствам малко по-спокойна.",[12723,12738,12766,12769,12791,12838],12882],[1,"Tim Hayward says the smell of coffee is vital.","Тим Хейуърд казва, че ароматът на кафето е „vital“ – жизненоважен.",[12943,12971,13012,13053,13069,13100,13109,13159,13228],13309],[1,"That means it's very important, it's perhaps the most important thing.","Това значи, че е много важен, може би най-важното нещо.",[13349,13375,13406,13425,13493,13597,13613,13656,13669,13728,13784],13818],[1,"And he backs this up by saying that it's the key thing.","И той подкрепя това, като казва, че е „the key thing“ – ключовото нещо.",[13849,13863,13875,13925,13949,13959,13977,14022,14053,14085,14110,14135],14173],[1,"Something that's key is something that is essential, it's really important.","Нещо „key“ е нещо съществено, наистина важно.",[14173,14236,14280,14305,14324,14387,14419,14438,14501,14532,14577],14640],[0,"And he says that when you experience the smell, when the smell hits you, you get a physiological response.","И казва, че когато усетиш аромата, когато те удари, получаваш физиологична реакция.",[14640,14665,14684,14715,14747,14778,14804,14873,14898,14936,14968,14993,15031,15062,15087,15113,15138,15150,15239],15295],[0,"This phrase means your body has a reaction to the smell of coffee.","Тази фраза значи, че тялото ти реагира на аромата на кафето.",[15295,15327,15371,15409,15441,15472,15497,15510,15567,15586,15611,15649,15668],15712],[0,"Perhaps your mouth begins to water in anticipation.","Може би устата ти започва да се пълни със слюнка в очакване.",[15712,15762,15794,15831,15869,15878,15916,15925],16003],[0,"Catherine, when you get a coffee, do you normally have it there or take it away?","Катрин, когато си вземаш кафе, обикновено го пиеш там или го взимаш за вкъщи?",[16040,16075,16104,16119,16138,16141,16184,16201,16210,16253,16281,16291,16326,16357,16381,16388],16419],[1,"Well, I usually take it away, although if I'm feeling really in need of a coffee hit, I might have one there and then get another one and take with me.","Ами, обикновено го взимам за из път, макар че ако наистина имам нужда от доза кафе, може да изпия едно там и после да си взема още едно с мен.",[16488,16509,16522,16557,16585,16597,16688,16732,16762,16781,16835,16922,16935,16959,16969,16975,17010,17038,17045,17068,17103,17122,17150,17178,17194,17210,17241,17260,17269,17294,17316],17343],[0,"Can you describe the container you are given when you have a coffee to go?","Можеш ли да опишеш съда, който ти дават, когато вземеш кафе за из път?",[17359,17384,17395,17459,17466,17532,17550,17553,17597,17631,17644,17659,17662,17703,17713],17751],[1,"Yes, it's in a tall paper cup with a lid.","Да, висока хартиена чаша с капаче.",[17791,17816,17844,17856,17866,17938,17978,18022,18044,18062],18093],[1,"And the lid has a hole in it so that I can drink that lovely coffee.","А капачето има дупка, за да мога да пия онова прекрасно кафе.",[18132,18149,18157,18199,18231,18238,18266,18284,18304,18339,18353,18364,18393,18447,18479,18537],18591],[0,"Don't you think that's a problem?","Не мислиш ли, че това е проблем?",[18625,18651,18659,18694,18725,18730],18780],[0,"I mean, we know how important the smell is, so what is the effect of the lid on that experience?","Искам да кажа, знаем колко е важен ароматът, тогава какъв е ефектът на капачето върху това преживяване?",[18799,18807,18843,18859,18878,18895,18941,18948,18984,19019,19090,19110,19122,19138,19185,19192,19201,19245,19262,19277],19347],[1,"The effect of the lid?","Ефектът на капачето?",[19348,19375,19406,19420,19441],19489],[0,"Yes. Well here's Tim Hayward again talking about coffee being served with lids.","Да. Ето пак Тим Хейуърд, който говори за кафето, сервирано с капачета.",[19547,19579,19602,19625,19650,19680,19743,19775,19797,19850,19881,19916,19953],19994],[2,"What baffles me is that how many of the large coffee chains actually sell a product in a cup that removes the smell.","Това, което ме озадачава, е колко много от големите вериги кафенета всъщност продават продукт в чаша, която премахва аромата.",[20023,20037,20084,20108,20119,20128,20142,20167,20175,20184,20242,20277,20364,20394,20418,20424,20546,20559,20564,20614,20636,20705,20711],20762],[2,"So you walk into the coffee shop, you get the smell, but when you actually take the drink out you are drinking it from something that is designed to deliver the hot liquid directly past your tongue but stop any smell coming up to your nose.","Влизаш в кафенето, усещаш аромата, но когато изнесеш напитката, я пиеш от нещо, направено да вкарва горещата течност директно покрай езика ти, но да спира всякакъв аромат да стигне до носа ти.",[20830,20840,20849,20866,20878,20886,20908,20925,20944,20977,20984,21018,21055,21073,21081,21100,21121,21127,21159,21184,21192,21197,21222,21230,21242,21275,21284,21291,21321,21328,21356,21362,21386,21453,21486,21519,21528,21581,21593,21640,21659,21689,21712,21724,21733,21744],21785],[2,"That's just weird.","Това е просто странно.",[21813,21853,21911],21956],[0,"So what is he describing there?","И какво описва той там?",[22022,22100,22135,22150,22178,22241],22264],[1,"I see now, yes, He's talking about the big coffee chains.","Сега разбирам, да. Той говори за големите вериги кафенета.",[22296,22308,22362,22370,22398,22430,22482,22523,22534,22578,22619],22691],[1,"A chain is a company that has lots of its stores in towns and cities sometimes around the world.","„Chain“ е компания, която има много свои магазини в градове, понякога по целия свят.",[22728,22736,22787,22822,22829,22881,22903,22937,22984,22994,23021,23066,23092,23142,23156,23210,23266,23295,23303],23356],[1,"I think we can all think of a few well-known coffee chains.","Мисля, че всички се сещаме за няколко известни вериги кафенета.",[23403,23413,23434,23445,23459,23497,23525,23534,23541,23576,23628,23662],23713],[1,"He says that by putting a lid on take away cups, you're actually blocking the smell - that smell that is really important to the coffee experience.","Той казва, че като се слага капаче на чашите за из път, всъщност се блокира ароматът – онзи аромат, който е наистина важен за преживяването с кафето.",[23756,23772,23810,23898,23931,23969,23975,24007,24026,24054,24079,24134,24157,24201,24273,24284,24284,24335,24368,24413,24431,24441,24503,24635,24650,24659,24690],24779],[0,"Yes, and he says that he finds that weird, which is a way of saying he finds it unusual, thinks it's strange, odd.","Да, и казва, че това му се струва „weird“, което е начин да кажеш, че го намира необичайно, странно, чудато.",[24807,24849,24872,24884,24922,24931,24937,24972,24991,25088,25109,25119,25124,25145,25153,25181,25194,25229,25241,25319,25359,25381,25435],25481],[0,"So much so that he says it baffles him.","Дотолкова, че казва, че това го „baffles“ – озадачава го.",[25535,25550,25569,25597,25617,25627,25656,25674,25742],25765],[0,"If you are baffled by something, you find it confusing, you can't really understand it.","Ако нещо те „baffles“, намираш го объркващо, не можеш наистина да го разбереш.",[25811,25827,25844,25855,25910,25925,25969,25977,26006,26014,26089,26105,26144,26183,26245],26263],[0,"Here's Tim Hayward again.","Ето пак Тим Хейуърд.",[26296,26315,26333,26365],26390],[2,"What baffles me is that how many of the large coffee chains actually sell a product in a cup that removes the smell.","Това, което ме озадачава, е колко много от големите вериги кафенета всъщност продават продукт в чаша, която премахва аромата.",[26450,26470,26512,26536,26545,26555,26569,26594,26603,26612,26670,26705,26790,26821,26844,26850,26972,26986,26996,27040,27062,27131,27138],27188],[2,"So you walk into the coffee shop, you get the smell, but when you actually take the drink out you are drinking it from something that is designed to deliver the hot liquid directly past your tongue but stop any smell coming up to your nose.","Влизаш в кафенето, усещаш аромата, но когато изнесеш напитката, я пиеш от нещо, направено да вкарва горещата течност директно покрай езика ти, но да спира всякакъв аромат да стигне до носа ти.",[27256,27267,27275,27293,27305,27312,27336,27352,27371,27403,27411,27445,27481,27500,27507,27526,27547,27553,27587,27612,27619,27624,27649,27657,27669,27702,27712,27718,27748,27756,27783,27790,27812,27880,27912,27945,27955,28007,28019,28068,28087,28117,28140,28152,28161,28172],28214],[2,"That's just weird.","Това е просто странно.",[28241,28283,28339],28383],[0,"That was coffee shop owner Tim Hayward.","Това беше собственикът на кафене Тим Хейуърд.",[28455,28478,28499,28533,28565,28592,28623],28672],[0,"Right before we have another cup of this week's vocabulary, let's get the answer to the question.","Добре, преди да изпием още една чаша от думите за седмицата, да чуем отговора на въпроса.",[28699,28754,28796,28810,28828,28854,28881,28893,28917,28944,29055,29122,29150,29161,29185,29194,29202],29249],[0,"After Brazil, which country produces most coffee?","След Бразилия коя страна произвежда най-много кафе?",[29271,29303,29360,29400,29438,29490,29510],29553],[0,"Is it: a: Colombia b: Vietnam c: Ethiopia Catherine, you said?","Дали е: а) Колумбия, б) Виетнам, в) Етиопия? Катрин, ти каза?",[29576,29603,29620,29662,29754,29818,29903,29956,30052,30088,30102],30146],[1,"I said it was a: Colombia.","Казах а) Колумбия.",[30167,30202,30238,30248,30271,30303],30382],[0,"A, sorry, no extra coffee for you today!","А, съжалявам, днес няма допълнително кафе за теб!",[30406,30467,30549,30598,30632,30667,30676,30710],30759],[0,"The answer is Vietnam.","Отговорът е Виетнам.",[30760,30830,30862,30883],30952],[0,"And now on to the vocabulary we looked at.","А сега към думите, които разгледахме.",[30982,30995,31016,31032,31040,31048,31117,31128,31154],31170],[0,"Take it away Catherine.","Давай, Катрин.",[31171,31206,31212,31236],31278],[1,"So the first word was vital, which is an adjective that means very important.","Първата дума беше „vital“ – прилагателно, което значи много важен.",[31353,31370,31379,31430,31456,31479,31558,31581,31595,31607,31672,31692,31729,31776],31853],[1,"And another word with a very similar meaning was key, meaning essential.","А друга дума с много сходно значение беше „key“ – съществен.",[31892,31922,31956,31981,31998,32002,32030,32078,32115,32141,32232,32276],32349],[0,"Next we had the phrase physiological responses.","После имахме фразата „physiological responses“.",[32366,32417,32440,32462,32469,32530,32620],32704],[0,"Physiological refers to what our bodies do and a response is a reaction.","„Physiological“ се отнася до това, което правят телата ни, а „response“ е реакция.",[32740,32827,32871,32879,32903,32918,32965,33002,33042,33048,33139,33150,33155],33216],[0,"So a physiological response is a reaction your body has to something, like the smell of coffee.","Значи физиологичната реакция е реакция на тялото ти към нещо, например към аромата на кафето.",[33262,33285,33288,33365,33434,33450,33454,33512,33530,33570,33598,33606,33684,33705,33712,33737,33745],33787],[1,"Something that baffles you, confuses you, you don't understand it.","Нещо, което те „baffles“, те обърква, не го разбираш.",[33819,33855,33900,33956,34016,34094,34119,34155,34189,34256],34286],[0,"You might find something that baffles you to be weird.","Нещо, което те озадачава, може да ти се стори „weird“.",[34292,34306,34334,34358,34392,34408,34465,34478,34488,34506],34579],[0,"This adjective means unusual or strange.","Това прилагателно значи необичаен или странен.",[34619,34644,34695,34738,34819,34831],34899],[1,"And finally, a chain is a group of shops from the same company with the same name.","И накрая, „chain“ е група магазини от една и съща компания с едно и също име.",[34946,34973,35050,35055,35119,35148,35154,35187,35199,35244,35262,35270,35314,35370,35400,35408,35450],35496],[0,"Well that is the end of our programe.","Е, това е краят на предаването ни.",[35556,35586,35611,35629,35644,35662,35673,35688],35754],[0,"For more from us, check out Instagram, Facebook, Twitter, YouTube and our App and of course the website bbclearningenglish.com.","За още от нас ни намерете в Instagram, Facebook, Twitter, YouTube и в нашето приложение и, разбира се, на сайта bbclearningenglish.com.",[35755,35770,35790,35808,35830,35856,35877,35940,36007,36049,36111,36137,36162,36206,36219,36225,36250,36256,36306],36475],[0,"See you soon, bye.","До скоро, чао.",[36503,36523,36531,36562],36606],[1,"Bye! Fancy a coffee?","Чао! Искаш ли едно кафе?",[36635,36728,36757,36763],36812],[0,"I think you've had too much!","Мисля, че си пила твърде много!",[36850,36862,36887,36899,36945,36964],36994]],"v":[["vital","жизненоважен",36],["key","ключов, съществен",36],["physiological response","физиологична реакция",44],["baffled","озадачен",66],["weird","странен",58],["chain","верига (магазини)",61],["lid","капаче",50],["take away","за из път, за вкъщи",63]],"g":[["smell",4,6,1],["disappointing",19,4,1],["brands",21,3,1],["producer",25,3,1],["caffeine",32,14,1],["vital",36,2,1],["key",36,5,1],["physiological",37,19,1],["lid",50,9,1],["baffles",56,1,1],["chains",56,11,1],["weird",58,2,1]],"q":[["How much coffee does Catherine drink?","Колко кафе пие Катрин?","about six cups a day","one cup a week","no coffee",23],["What is the best thing about coffee for Catherine?","Кое е най-хубавото нещо в кафето за Катрин?","the smell","the price","the colour",14],["Who is Tim Hayward?","Кой е Тим Хейуърд?","a coffee shop owner","a doctor","a farmer in Brazil",33],["How does Catherine usually have her coffee?","Как обикновено пие кафето си Катрин?","she takes it away","she drinks it at home","she drinks it at the coffee shop",48],["What baffles Tim Hayward?","Какво озадачава Тим Хейуърд?","coffee chains sell coffee in cups with lids that block the smell","coffee is too expensive","people drink too much coffee",56],["Which country is the second largest coffee producer?","Коя страна е вторият по големина производител на кафе?","Vietnam","Colombia","Ethiopia",77]]},"breakfast":{"ser":"6 Minute English","icon":"🥣","bg":"Закуската","t":"Is breakfast the most important meal of the day?","a":"ree/audio/breakfast.mp3","sp":["Georgie","Phil","Professor Alexandra Johnstone","Ruth Alexander","Courtney Peterson"],"L":[[0,"Hello, this is 6 Minute English from BBC Learning English.","Здравейте, това е 6 Minute English от BBC Learning English.",[0,78,88,94,133,185,240,283,343,401],455],[0,"I'm Georgie.","Аз съм Джорджи.",[456,462],487],[1,"And I'm Phil.","А аз съм Фил.",[488,539,836],853],[1,"Did you have any breakfast today, Georgie, or did you skip it?","Закуси ли днес, Джорджи, или я пропусна?",[854,888,896,915,934,981,1004,1046,1051,1062,1080,1092],1119],[0,"I did have some breakfast.","Да, закусих.",[1124,1140,1204,1256,1408],1472],[0,"On the way to the office, I got myself a pastry and a coffee.","На път за офиса си взех тестена закуска и кафе.",[1473,1488,1501,1511,1556,1570,1594,1597,1685,1744,1768,1814,1858,1917],1949],[0,"What about you?","А ти?",[1950,1978,2076],2094],[1,"I had a big bowl of porridge, but it was at six o'clock this morning so I'm hungry again now.","Изядох голяма купа овесена каша, но беше в шест сутринта, така че сега пак съм гладен.",[2176,2201,2261,2305,2388,2402,2497,2539,2668,2683,2701,2709,2744,2775,2793,2829,2852,2873,2941,2983],3030],[1,"And you might soon be hungry as well because we're going to talk about breakfast.","А може скоро и вие да огладнеете, защото ще говорим за закуската.",[3076,3108,3138,3162,3189,3202,3247,3269,3323,3365,3408,3436,3450,3477,3501],3577],[1,"How important is it?","Колко е важна?",[3616,3650,3731,3755],3780],[1,"Let's start by hearing from Professor Alexandra Johnstone, a nutrition scientist who spoke to Ruth Alexander, host of BBC World Service programme The Food Chain.","Да започнем с професор Александра Джонстоун, учен в областта на храненето, която говори с Рут Александър, водеща на предаването на BBC World Service „The Food Chain“.",[3838,3859,3897,3916,3951,3972,4016,4092,4159,4170,4230,4289,4304,4333,4346,4384,4479,4512,4520,4573,4620,4671,4753,4765,4798],4832],[2,"I am supporting the meme 'breakfast like a king and dine like a pauper'.","Подкрепям мема „закусвай като цар и вечеряй като просяк“.",[4928,4952,4970,5043,5051,5141,5192,5216,5220,5275,5306,5346,5371,5377],5442],[3,"For you then, breakfast is the most important meal of the day.","Значи за вас закуската е най-важното хранене за деня.",[5460,5468,5491,5536,5595,5636,5646,5674,5712,5733,5742,5748],5789],[2,"I agree. So, it's really important, particularly for people who are trying to maintain a healthy weight and people who are trying to lose weight.","Съгласна съм. Наистина е много важна, особено за хората, които се опитват да поддържат здравословно тегло, и за хората, които се опитват да отслабнат.",[5841,5860,5911,5927,5938,5962,6020,6075,6153,6192,6222,6243,6283,6317,6365,6371,6416,6463,6505,6550,6606,6627,6659,6671,6706],6753],[1,"Alexandra says that you should 'breakfast like a king and dine like a pauper'.","Александра казва, че трябва да „закусваш като цар и да вечеряш като просяк“.",[6806,6858,6892,6905,6922,6945,7023,7047,7050,7129,7162,7204,7225,7230],7275],[1,"Pauper is an old-fashioned word for a very poor person.","„Pauper“ е старомодна дума за много беден човек.",[7347,7410,7428,7444,7520,7548,7564,7567,7597,7634],7689],[1,"The expression means have a big breakfast and a small dinner.","Изразът значи: закусвай обилно и вечеряй малко.",[7724,7733,7805,7866,7886,7894,7917,7998,8019,8022,8061],8091],[0,"We're going to find out some of the reasons that Alexandra and other experts recommend doing this.","Ще разберем някои от причините, поради които Александра и други експерти препоръчват това.",[8130,8140,8162,8171,8204,8224,8245,8255,8266,8312,8325,8401,8430,8450,8512,8572,8605],8640],[1,"And as usual, we'll learn some useful new words and phrases.","И както обикновено, ще научим някои полезни нови думи и изрази.",[8664,8688,8707,8745,8777,8805,8823,8871,8899,8937,8947],9002],[1,"And remember - you'll find all the vocabulary and a quiz on our website, bbclearningenglish.com.","И не забравяйте – всички думи и тест ще намерите на нашия сайт, bbclearningenglish.com.",[9054,9066,9066,9127,9144,9198,9227,9234,9336,9363,9370,9452,9475,9492,9559],9797],[0,"OK. But first I have a question for you, Phil.","Добре. Но първо имам въпрос към теб, Фил.",[9825,9900,9930,9971,9985,10007,10012,10059,10080,10094],10127],[0,"According to a recent survey, which of the following is the most popular breakfast in the UK?","Според скорошна анкета коя от следните е най-популярната закуска във Великобритания?",[10174,10216,10225,10233,10280,10333,10374,10385,10394,10442,10460,10470,10521,10572,10642,10660,10672],10743],[0,"Is it: a) eggs, b) toast, or c) cereal?","Дали е: а) яйца, б) препечен хляб, или в) зърнена закуска?",[10777,10791,10804,10881,10974,11027,11118,11136,11202],11277],[1,"Well, I think people like to keep it simple so I'm going to say toast.","Ами, мисля, че хората обичат простите неща, така че ще кажа препечен хляб.",[11314,11338,11350,11377,11402,11419,11428,11455,11466,11525,11559,11591,11623,11635,11734],11783],[0,"OK. Well, we'll find out the answer later in the programme.","Добре. Ще разберем отговора по-късно в предаването.",[11821,11847,11885,11900,11934,11949,11959,12015,12069,12081,12088],12135],[0,"Let's hear some reasons for why we should breakfast like a king or queen.","Да чуем някои причини защо трябва да закусваме като цар или царица.",[12174,12197,12211,12234,12278,12290,12321,12331,12352,12412,12431,12435,12474,12492],12546],[0,"Courtney Peterson, who researches eating behaviours, explains how the time of day affects how our bodies process food, on BBC World Service programme The Food Chain:","Кортни Питърсън, която изследва хранителното поведение, обяснява как времето от деня влияе на начина, по който тялото ни преработва храната, в предаването на BBC World Service „The Food Chain“:",[12585,12617,12673,12689,12750,12787,12872,12920,12942,12950,12984,12994,13030,13072,13092,13105,13149,13211,13296,13309,13350,13377,13419,13472,13485,13515],13549],[4,"And so, if you can eat a large breakfast in the morning, and/or I would even say a large lunch in the morning, your body's going to be better at metabolising that food.","И така, ако можете да изядете обилна закуска сутрин и/или бих казала дори обилен обяд сутрин, тялото ви ще метаболизира тази храна по-добре.",[13637,13647,13672,13684,13700,13741,13818,13822,13856,13905,13915,13924,14031,14088,14096,14108,14130,14150,14155,14208,14255,14265,14272,14353,14363,14397,14413,14425,14431,14449,14455,14528,14544],14572],[4,"And what that means is your body's going to actually... your blood sugar levels won't spike as high, you might burn slightly more fat, you might burn slightly more calories from eating earlier in the day.","А това означава, че тялото ви всъщност… кръвната ви захар няма да скочи толкова високо, може да изгорите малко повече мазнини, може да изгорите малко повече калории, като се храните по-рано през деня.",[14574,14628,14647,14663,14694,14710,14720,14772,14795,14801,14844,14881,14900,14920,14957,14979,15012,15022,15103,15151,15178,15195,15228,15247,15290,15306,15323,15341,15373,15390,15445,15457,15488,15525,15538,15548],15581],[4,"Whereas if you had... if you eat most of your food later in the day, your metabolism is actually slower later in the day.","Докато ако… ако изядете повечето от храната си по-късно през деня, метаболизмът ви всъщност е по-бавен по-късно през деня.",[15645,15688,15695,15709,15776,15785,15795,15807,15828,15834,15853,15881,15906,15916,15925,15957,15969,16024,16034,16066,16128,16147,16157,16168],16188],[4,"So, for instance, if you ate the same, I don't know, bowl of ice cream in the morning, the afternoon and the evening, your blood sugar levels will spike significantly higher in the afternoon and the evening.","Например ако изядете една и съща, не знам, купа сладолед сутрин, следобед и вечер, кръвната ви захар ще скочи значително по-високо следобед и вечер.",[16188,16206,16222,16256,16266,16281,16300,16309,16410,16422,16434,16472,16500,16506,16534,16560,16571,16578,16638,16654,16712,16728,16738,16790,16806,16837,16859,16899,16910,16946,17053,17099,17109,17119,17165,17175,17185],17222],[1,"We heard the noun metabolism.","Чухме съществителното „metabolism“.",[17297,17316,17338,17349,17390],17476],[1,"This is a word that refers to the chemical processes in your body, and we most often use it to talk about those that convert food into energy.","Това е дума за химичните процеси в тялото ти, като най-често я използваме, когато говорим за онези, които превръщат храната в енергия.",[17494,17522,17534,17540,17580,17591,17634,17644,17656,17709,17778,17800,17818,17912,17922,17930,17959,17999,18024,18038,18047,18075,18101,18135,18150,18196,18257,18287],18335],[1,"And we also heard had the verb form - metabolise.","И чухме и глаголната форма – „metabolise“.",[18337,18394,18409,18432,18447,18462,18472,18528,18528,18591],18700],[0,"Courtney talked about blood sugar levels spiking.","Кортни говореше за това как кръвната захар „скача“ (spiking).",[18743,18781,18809,18837,18868,18900,18947],19025],[0,"A spike is a sharp, pointed shape.","„Spike“ е остра, заострена форма.",[19069,19074,19130,19138,19141,19194,19238],19290],[0,"If you see it on a line graph, it means that something has increased very rapidly.","Ако я видиш на линейна графика, значи, че нещо се е увеличило много бързо.",[19307,19321,19328,19347,19356,19366,19372,19406,19444,19466,19497,19509,19547,19560,19612,19640],19696],[0,"We often use the noun spike to mean a sudden increase in a value that is being measured.","Често използваме съществителното „spike“ със значение на внезапно увеличение на стойност, която се измерва.",[19747,19757,19793,19815,19822,19865,19910,19931,19955,19962,20000,20050,20066,20071,20122,20138,20150,20177],20224],[0,"The verb spike means to suddenly increase.","Глаголът „spike“ значи внезапно да се увеличи.",[20265,20278,20319,20384,20409,20419,20479],20541],[1,"We've heard that eating earlier in the day can be healthier for us.","Чухме, че храненето по-рано през деня може да е по-здравословно за нас.",[20591,20614,20645,20666,20723,20762,20782,20791,20816,20831,20847,20906,20938],20962],[1,"Now, people often don't eat breakfast, sometimes because they don't have time and sometimes because they are trying to save money.","Хората често не закусват – понякога защото нямат време, а понякога защото се опитват да спестят пари.",[21010,21032,21097,21160,21210,21225,21281,21342,21370,21385,21403,21422,21483,21492,21547,21578,21586,21591,21624,21634,21666],21707],[1,"Let's hear again from Professor Alexandra Johnstone, talking to BBC World Service's The Food Chain.","Да чуем пак професор Александра Джонстоун пред „The Food Chain“ на BBC World Service.",[21737,21760,21778,21809,21831,21879,21941,22028,22072,22084,22147,22184,22247,22278,22309],22352],[2,"Now, breakfast skipping is interesting because my own work would tend to suggest - and that sort of observational, large-scale, epidemiological studies would also support this - that people who have a regular breakfast are actually leaner.","Пропускането на закуската е интересно, защото собствената ми работа показва – а и някои наблюдателни, мащабни епидемиологични изследвания също подкрепят това, – че хората, които закусват редовно, всъщност са по-слаби.",[22434,22500,22547,22597,22612,22672,22818,22850,22881,22925,22940,22969,22975,22975,23037,23047,23072,23096,23113,23207,23282,23406,23438,23482,23540,23607,23607,23798,23838,23888,23964,24041,24056,24109,24256,24309,24359],24425],[2,"And my own work would tend to suggest that having your largest meal of the day in the morning period gives you a much better appetite control, which then means it's much easier to control food intake later in the day.","И собствената ми работа показва, че ако най-голямото ви хранене за деня е сутрин, това ви дава много по-добър контрол на апетита, а това означава, че е много по-лесно да контролирате приема на храна по-късно през деня.",[24491,24547,24569,24609,24647,24662,24691,24697,24778,24850,24914,24931,24998,25044,25059,25181,25187,25206,25212,25276,25423,25453,25479,25493,25531,25599,25657,25781,25811,25843,25896,25917,25951,26062,26069,26125,26154,26231,26286,26309,26317],26356],[0,"Alexandra starts by mentioning 'breakfast skipping'.","Александра започва, като споменава „пропускането на закуската“.",[26429,26488,26529,26541,26611,26671],26736],[0,"If you skip something, then you don't do it.","Ако „skip“ нещо, не го правиш.",[26765,26772,26782,26813,26891,26904,26913,26940,26957],26982],[0,"Bad students might skip lessons - they don't go to them.","Лошите ученици може да пропускат часове – не ходят на тях.",[27021,27048,27100,27123,27155,27155,27219,27241,27256,27277,27288],27307],[0,"If you skip a meal, it means that you don't eat it.","Ако пропуснеш хранене, значи не ядеш.",[27352,27364,27372,27396,27401,27451,27463,27495,27504,27519,27553,27577],27605],[1,"We also heard that people who have a regular breakfast are leaner.","Чухме и че хората, които закусват редовно, са по-слаби (leaner).",[27655,27670,27697,27733,27747,27788,27806,27825,27829,27902,28001,28021],28090],[1,"If someone is lean, then they're not fat.","Ако някой е „lean“, значи не е дебел.",[28145,28152,28185,28205,28262,28311,28325,28372],28420],[0,"And one of the reasons given why people might be leaner is that they have better appetite control.","А една от причините хората да са по-слаби е, че имат по-добър контрол на апетита.",[28460,28485,28501,28509,28522,28570,28613,28628,28661,28684,28695,28750,28767,28781,28790,28812,28847,28909],28958],[0,"Appetite control is where your brain decides how much you should eat.","„Appetite control“ е когато мозъкът ти решава колко трябва да ядеш.",[29015,29055,29102,29120,29132,29147,29186,29234,29258,29293,29300,29321],29363],[1,"Thanks, Georgie. Now, I think it's time that we heard the answer to your question.","Благодаря, Джорджи. Мисля, че е време да чуем отговора на твоя въпрос.",[29410,29436,29520,29571,29588,29621,29646,29690,29702,29716,29739,29756,29782,29794,29814],29873],[0,"Yes, it is.","Да, време е.",[29889,29933,29943],30019],[0,"OK. I asked, \"According to a recent survey, what is the most popular breakfast in the UK?\"","Добре. Попитах: „Според скорошна анкета коя е най-популярната закуска във Великобритания?“",[30020,30054,30082,30159,30203,30214,30224,30265,30317,30371,30390,30402,30435,30494,30556,30581,30592],30662],[1,"And I said, \"Toast.\"","А аз казах: „Препечен хляб.“",[30683,30698,30712,30783],30836],[0,"...which was the most popular in London, but the most popular in the country as a whole was cereal, and that's according to a survey by a cereal manufacturer.","…която беше най-популярна в Лондон, но най-популярна в страната като цяло беше зърнената закуска – и то според анкета на производител на зърнени закуски.",[30881,30923,30964,30974,31010,31061,31089,31163,31212,31225,31250,31289,31310,31319,31370,31382,31387,31439,31466,31594,31607,31625,31657,31669,31673,31723,31744,31754,31801],31876],[0,"So, I'm afraid you got it wrong.","Така че, съжалявам, но отговори грешно.",[31923,31950,31962,31994,32002,32016,32025],32050],[0,"OK. Let's recap the vocabulary we've learned, starting with pauper, which is an old-fashioned word for a very poor person.","Добре. Нека преговорим думите, които научихме, като започнем с „pauper“ – старомодна дума за много беден човек.",[32091,32120,32149,32183,32192,32257,32282,32314,32371,32394,32462,32478,32488,32497,32568,32597,32620,32624,32658,32690],32746],[1,"When we're talking about data, it spikes when it increases suddenly.","Когато говорим за данни, те „spike“, когато внезапно се увеличат.",[32803,32816,32828,32871,32900,32981,32994,33081,33100,33107,33169],33231],[0,"Metabolism refers to the chemical processes inside your body, especially those which process food.","„Metabolism“ се отнася до химичните процеси в тялото ти, особено тези, които преработват храната.",[33265,33335,33383,33394,33402,33444,33512,33557,33568,33626,33675,33707,33726,33772],33821],[1,"If you skip something, you miss it; you don't do it.","Ако „skip“ нещо, пропускаш го; не го правиш.",[33863,33881,33895,33956,34066,34076,34104,34132,34149,34181,34203],34225],[0,"If someone is lean, then they are not fat.","Ако някой е „lean“, значи не е дебел.",[34249,34263,34295,34309,34354,34369,34387,34393,34422],34491],[1,"And finally, appetite control is how your brain decides how much you should eat.","И накрая, „appetite control“ е как мозъкът ти решава колко трябва да ядеш.",[34499,34524,34609,34667,34725,34744,34762,34785,34838,34892,34913,34948,34961,34981],35012],[1,"Once again, our six minutes are up, but why not head over to our website, bbclearningenglish.com, to try the quiz and worksheet for this episode?","Отново шестте ни минути изтекоха, но защо не отидете на нашия сайт, bbclearningenglish.com, за да направите теста и работния лист за този епизод?",[35097,35119,35181,35200,35232,35267,35281,35300,35316,35355,35381,35403,35425,35444,35460,35556,35782,35795,35824,35836,35890,35928,36004,36015,36032],36087],[1,"See you again soon.","До скоро.",[36148,36170,36180,36202],36245],[0,"Goodbye!","Довиждане!",[36260],36324],[1,"Bye!","Чао!",[36348],36405]],"v":[["pauper","просяк, много беден човек",11],["spike","рязко покачване; рязко се покачва",28],["metabolism","метаболизъм",29],["skip","пропускам",3],["lean","слаб, не дебел",49],["appetite control","контрол на апетита",43],["porridge","овесена каша",7],["survey","анкета, проучване",21]],"g":[["skip",3,10,1],["porridge",7,6,1],["pauper",11,13,1],["maintain",13,13,1],["survey",21,4,1],["metabolising",27,30,1],["spike",28,15,1],["calories",28,29,1],["metabolism",29,16,1],["leaner",42,36,1],["appetite control",43,25,2],["cereal",22,8,1]],"q":[["What did Georgie have for breakfast?","Какво закуси Джорджи?","a pastry and a coffee","porridge","eggs and toast",5],["What does 'breakfast like a king and dine like a pauper' mean?","Какво значи „закусвай като цар и вечеряй като просяк“?","have a big breakfast and a small dinner","never eat breakfast","eat only at night",16],["What happens if you eat most of your food late in the day?","Какво става, ако ядеш повечето храна късно през деня?","your metabolism is slower","you burn more fat","you sleep better",29],["Why do people often skip breakfast?","Защо хората често пропускат закуската?","no time or to save money","they don't like eggs","doctors tell them to",40],["What do people who have a regular breakfast have, says Alexandra?","Какво имат хората, които закусват редовно, според Александра?","better appetite control","more stress","a slower metabolism",43],["What is the most popular breakfast in the UK?","Коя е най-популярната закуска във Великобритания?","cereal","toast","eggs",56]]},"salt":{"ser":"6 Minute English","icon":"🧂","bg":"По-малко сол, по-добро здраве","t":"Less salt, better health","a":"ree/audio/salt.mp3","sp":["Neil","Georgie","Marian Sumbiva","Prof Clare Collins"],"L":[[0,"Hello. This is 6 Minute English from BBC Learning English.","Здравейте. Това е 6 Minute English от BBC Learning English.",[0,78,88,94,133,184,239,283,340,401],458],[0,"I'm Neil.","Аз съм Нийл.",[467,797],809],[1,"And I'm Georgie.","А аз съм Джорджи.",[810,903,910],934],[1,"Do you know the five tastes which give food its flavour, Neil?","Знаеш ли петте вкуса, които дават на храната аромат и вкус, Нийл?",[935,951,970,996,1148,1238,1324,1333,1361,1417,1451,1479],1488],[1,"There's sweet...","Има сладко…",[1489,1546],1575],[0,"Yes... and er, sour, bitter...","Да… и, ъъ, кисело, горчиво…",[1576,1637,1655,1658,1686],1732],[1,"And salty! Everyone knows that salt makes food taste better by enhancing the flavours of the ingredients.","И солено! Всеки знае, че солта прави храната по-вкусна, като засилва вкуса на съставките.",[1733,1779,1811,1879,1894,1934,2062,2198,2231,2294,2326,2334,2389,2437,2770,2785,2795],2865],[1,"There's even a phrase you'll see in many recipes - 'add a pinch of salt'.","Има дори фраза, която ще видите в много рецепти – „добавете щипка сол“.",[2866,2908,2931,2935,2978,2991,3027,3041,3075,3075,3164,3183,3189,3220,3230],3272],[0,"But exactly how much salt makes a 'pinch' of salt?","Но колко точно сол е една „щипка“ сол?",[3291,3321,3384,3409,3461,3513,3562,3570,3623,3635],3677],[0,"The World Health Organisation, or WHO, recommends a daily salt intake of less than 5g, about the same as a teaspoon.","Световната здравна организация, или СЗО, препоръчва дневен прием на сол под 5 грама – колкото една чаена лъжичка.",[3734,3742,3774,3809,3903,3959,3981,4091,4144,4192,4233,4288,4299,4338,4352,4477,4507,4514,4558,4575,4580],4646],[0,"In fact, the human body needs salt - at least 1g a day to survive.","Всъщност човешкото тяло има нужда от сол – поне 1 грам на ден, за да оцелее.",[4693,4704,4739,4754,4791,4819,4856,4856,4918,4928,4955,5017,5020,5054,5067],5122],[0,"But most of us eat far too much, increasing the risk of high blood pressure and heart disease.","Но повечето от нас ядат твърде много, което увеличава риска от високо кръвно налягане и сърдечни болести.",[5159,5174,5216,5224,5242,5279,5322,5350,5417,5470,5477,5512,5521,5554,5577,5616,5666,5696],5750],[0,"In this programme, we'll be asking: how much salt is too much?","В това предаване ще се питаме: колко сол е твърде много?",[5813,5828,5847,5898,5931,5945,6016,6038,6066,6109,6134,6171],6213],[0,"And, as usual, we'll be learning some useful new vocabulary as well.","И както обикновено ще научим и някои полезни нови думи.",[6269,6292,6309,6377,6389,6402,6430,6448,6495,6519,6595,6612],6635],[1,"Great! But first I have a question for you, Neil.","Чудесно! Но първо имам въпрос към теб, Нийл.",[6656,6728,6744,6798,6827,6847,6850,6889,6908,6922],6958],[1,"The reason it's difficult to know how much salt you consume is that it's hidden in food, especially processed food.","Трудно е да знаеш колко сол консумираш, защото тя е скрита в храната, особено в преработената храна.",[7019,7030,7069,7091,7136,7150,7181,7197,7222,7255,7267,7344,7358,7370,7384,7438,7461,7531,7603,7659],7692],[1,"So, which of the following everyday foods do you think contains most salt?","И така, коя от следните ежедневни храни според теб съдържа най-много сол?",[7739,7753,7778,7788,7797,7855,7906,7958,7969,8003,8042,8114,8156],8206],[1,"Is it: a) meat?","Дали е: а) месото?",[8245,8262,8280,8339],8394],[1,"b) bread? or, c) pasta?","б) хлябът? или в) пастата?",[8436,8488,8558,8573,8622],8669],[0,"Well, I'm going to guess that meat is the saltiest of those foods.","Ами, ще предположа, че месото е най-соленото от тези храни.",[8698,8769,8780,8797,8805,8862,8902,8978,9003,9009,9070,9083,9112],9150],[1,"OK Neil, I'll reveal the answer later in the programme.","Добре, Нийл, ще разкрия отговора по-късно в предаването.",[9164,9212,9261,9278,9319,9331,9373,9422,9431,9439],9497],[1,"Marian Sumbiva lives in Astana, the capital of Kazakhstan, a country where people eat, on average, 17g of salt a day.","Мариан Сумбива живее в Астана, столицата на Казахстан – страна, където хората ядат средно по 17 грама сол на ден.",[9561,9610,9688,9714,9725,9802,9814,9866,9875,9998,10005,10047,10064,10106,10144,10158,10200,10331,10342,10386,10389],10436],[1,"That's more than three times the amount recommended by the WHO.","Това е над три пъти повече от количеството, препоръчано от СЗО.",[10475,10505,10527,10545,10589,10656,10669,10709,10773,10791,10917],10923],[1,"Here, Marian explains some of the reasons behind this to BBC World Service programme, 'The Food Chain':","Ето как Мариан обяснява някои от причините за това пред предаването на BBC World Service „The Food Chain“:",[10944,11006,11056,11114,11142,11150,11161,11206,11256,11288,11302,11359,11384,11423,11480,11489,11514],11552],[2,"We consume lots of salt, which is due to historical heritage, because when we were nomads, for centuries and centuries we travelled and wandered across the steppes, and here, we had to carry lots of meat which could be preserved only adding salt.","Консумираме много сол, което се дължи на историческото ни наследство, защото когато бяхме номади, векове наред пътувахме и бродехме из степите и тук трябваше да носим много месо, което можеше да се запази само като се добави сол.",[11611,11639,11700,11745,11759,11848,11886,11912,11955,11967,12031,12136,12214,12259,12270,12289,12394,12412,12472,12488,12581,12597,12659,12706,12789,12866,12880,12982,13012,13056,13147,13175,13185,13228,13260,13275,13382,13413,13431,13444,13515,13578,13652],13706],[2,"And even the milk products, the dairy products, are also very much salty for the same reasons.","А дори млечните продукти също са много солени по същите причини.",[13743,13766,13809,13822,13915,13961,13969,14014,14094,14109,14146,14174,14194,14306,14317,14325,14353],14414],[0,"Besides improving its flavour, salt can be used to preserve food, to stop it from going bad.","Освен че подобрява вкуса, солта може да се използва за консервиране на храната – за да не се развали.",[14484,14533,14587,14603,14653,14700,14722,14733,14769,14778,14844,14912,14922,14953,14967,14986,15019],15058],[0,"Traditionally, people in Kazakhstan were nomads, they travelled from place to place with their animals, rather than living in one place all the time.","Традиционно хората в Казахстан са били номади – пътували са от място на място с животните си, вместо да живеят постоянно на едно място.",[15115,15186,15225,15236,15306,15321,15431,15446,15505,15530,15560,15570,15610,15624,15635,15710,15741,15766,15806,15822,15850,15891,15913,15920],15962],[0,"Treating food with salt gave them enough to eat during the long winter months.","Обработването на храната със сол им е давало достатъчно храна през дългите зимни месеци.",[16035,16084,16114,16129,16188,16213,16235,16280,16298,16333,16362,16370,16399,16438],16494],[0,"They even did it with dairy products, foods which are made from milk, such as cheese and butter.","Правили са го дори с млечните продукти – храни, направени от мляко, като сирене и масло.",[16495,16537,16574,16591,16602,16634,16677,16764,16818,16841,16847,16872,16895,16949,16976,16988,17039,17067],17107],[1,"So, salt has a long, and useful, history.","Значи солта има дълга и полезна история.",[17130,17188,17238,17257,17273,17302,17338,17388],17441],[1,"But there's a big difference between traditional Kazakh nomads and the health problems associated with modern processed food.","Но има голяма разлика между традиционните казахски номади и здравословните проблеми, свързани със съвременната преработена храна.",[17482,17495,17511,17519,17544,17591,17632,17694,17736,17810,17830,17836,17871,17934,18019,18033,18079,18135],18183],[1,"When we eat too much salt, the body dilutes it by retaining water.","Когато ядем твърде много сол, тялото я разрежда, като задържа вода.",[18236,18248,18269,18288,18303,18322,18382,18392,18422,18482,18501,18519,18576],18616],[1,"And as a result, the heart works harder to pump liquid around the body.","И в резултат на това сърцето работи по-усилено, за да изпомпва течността из тялото.",[18616,18676,18707,18710,18772,18781,18817,18848,18902,18915,18950,19001,19028,19035],19075],[1,"This causes high blood pressure which, over time, can lead to heart disease.","Това причинява високо кръвно налягане, което с времето може да доведе до сърдечни болести.",[19125,19148,19194,19228,19263,19303,19364,19381,19432,19462,19489,19500,19529],19582],[0,"Globally, governments are fighting this health risk in different ways.","По света правителствата се борят с този риск за здравето по различни начини.",[19647,19719,19775,19800,19853,19870,19901,19941,19953,19985],20031],[0,"The Australian government reduced its recommended salt intake to 6g a day, while the British government has passed laws forcing food companies to reduce the amount of salt they use, and now recommends just 5g of salt per day.","Австралийското правителство намали препоръчителния прием на сол до 6 грама на ден, а британското правителство прие закони, които задължават хранителните компании да намалят количеството сол, което използват, и сега препоръчва само 5 грама сол на ден.",[20070,20084,20135,20176,20222,20238,20298,20331,20375,20384,20472,20476,20538,20569,20576,20614,20656,20682,20719,20745,20805,20837,20891,20901,20950,20963,20998,21007,21041,21058,21129,21147,21173,21228,21245,21336,21347,21382,21400],21428],[1,"Clare Collins is professor of nutrition at the University of Newcastle in Australia.","Клеър Колинс е професор по хранене в Университета на Нюкасъл в Австралия.",[21473,21496,21539,21552,21602,21611,21674,21694,21705,21772,21781,21857,21878],21951],[1,"Here, she explains more about these salt recommendations to BBC World Service programme, 'The Food Chain':","Ето как тя обяснява повече за тези препоръки за солта пред предаването на BBC World Service „The Food Chain“:",[22001,22044,22060,22117,22159,22197,22223,22251,22353,22366,22425,22453,22489,22541,22558,22585],22619],[3,"I think you just gotta take a step back, and look at the bigger picture, like arguing whether it should be 5g or 6g...","Мисля, че просто трябва да направим крачка назад и да погледнем цялостната картина, вместо да спорим дали трябва да е 5 или 6 грама…",[22650,22666,22695,22703,22722,22739,22766,22769,22803,22883,22901,22917,22933,22941,23012,23101,23119,23157,23175,23181,23197,23208,23284,23291],23362],[3,"The issue is that around the world, salt intakes are very high, contributing to high blood pressure, contributing to premature strokes, premature mortality, and we need to address it in a way that's culturally appropriate for each country.","Проблемът е, че по света приемът на сол е много висок, което допринася за високото кръвно налягане, за преждевременни инсулти, за преждевременна смъртност, и трябва да се справим с това по начин, който е културно подходящ за всяка страна.",[23416,23446,23481,23522,23537,23568,23574,23654,23688,23740,23752,23784,23853,23910,23931,23943,23972,24016,24125,24182,24226,24297,24351,24484,24509,24525,24569,24587,24631,24701,24719,24722,24759,24869,24963,25090,25116,25144],25217],[1,"Instead of arguing over grams of salt, Professor Collins thinks we should take a step back and look at the bigger picture.","Вместо да спорим за грамове сол, професор Колинс смята, че трябва да направим крачка назад и да погледнем цялостната картина.",[25229,25264,25276,25329,25353,25392,25400,25463,25508,25558,25583,25595,25617,25659,25664,25697,25749,25782,25815,25824,25836,25862],25901],[1,"She uses two idioms: take a step back, which means to temporarily withdraw from a situation in order to think about it more calmly, and look at the bigger picture - to consider the overall meaning of something, not just the details.","Тя използва два идиома: „take a step back“, което значи временно да се оттеглиш от ситуация, за да помислиш за нея по-спокойно, и „look at the bigger picture“ – да погледнеш цялостния смисъл на нещо, а не само детайлите.",[25952,25972,26011,26038,26127,26152,26156,26184,26226,26262,26294,26305,26394,26458,26481,26484,26571,26586,26614,26628,26662,26690,26701,26726,26850,26892,26925,26941,26951,26974,26974,27059,27070,27114,27138,27188,27225,27232,27302,27347,27372,27379],27443],[0,"Yes, the problem remains that overconsumption of salt is causing premature health problems, problems which are happening sooner than they should.","Да, проблемът си остава, че прекомерната консумация на сол причинява преждевременни здравословни проблеми – проблеми, които се случват по-рано, отколкото би трябвало.",[27444,27489,27498,27541,27609,27638,27753,27764,27807,27825,27878,27965,27997,28073,28155,28174,28180,28229,28282,28303,28314],28354],[0,"By limiting salt and processed food, most people can enjoy long, healthy lives.","Като ограничат солта и преработената храна, повечето хора могат да се радват на дълъг и здравословен живот.",[28407,28424,28479,28525,28536,28587,28644,28678,28718,28738,28772,28820,28860],28905],[0,"And if you don't like your food unsalted, try adding herbs and spices instead.","А ако не харесвате храната си без сол, опитайте вместо това да добавите билки и подправки.",[28947,28960,28969,28981,29007,29038,29055,29091,29175,29206,29231,29288,29304,29362],29412],[1,"Well, speaking of salty foods, I think it's time to reveal the answer to my question, Neil.","Е, като стана дума за солени храни, мисля, че е време да разкрия отговора на моя въпрос, Нийл.",[29436,29493,29555,29566,29603,29649,29675,29698,29712,29743,29756,29800,29816,29856,29866,29881,29930],29962],[1,"If you remember, I asked you which everyday food contains most salt.","Ако помниш, попитах те коя ежедневна храна съдържа най-много сол.",[30010,30020,30031,30094,30112,30149,30167,30201,30254,30319,30385,30419],30468],[0,"And I guessed it was meat...","А аз предположих, че е месото…",[30480,30499,30524,30576,30592,30619],30656],[1,"Which was... the correct answer!","Което беше… верният отговор!",[30656,30683,30761,30774,30817],30875],[1,"Meat contains the highest amount of salt - around 19% - followed by bread with 14%, and pasta with 7%.","Месото съдържа най-голямо количество сол – около 19% – следвано от хляба с 14% и пастата със 7%.",[30930,30964,31013,31022,31079,31112,31120,31120,31192,31242,31242,31386,31424,31438,31487,31505,31635,31653,31718,31730],31811],[1,"OK, let's recap the vocabulary we've learned in this programme starting with the verb 'to preserve food', meaning to do something to stop it rotting so it can be eaten later.","Добре, нека преговорим думите, които научихме в предаването, като започнем с глагола „to preserve food“ – да направиш нещо, за да не се развали храната и да може да се яде по-късно.",[31870,31900,31931,31970,31978,32053,32088,32123,32135,32153,32219,32269,32287,32297,32339,32362,32423,32514,32547,32557,32581,32619,32631,32664,32679,32738,32760,32767,32786,32799,32844],32890],[0,"Nomads are people who travel from one place to another, often with animal livestock, rather than living in one place all the time.","Номадите са хора, които пътуват от едно място на друго, често с добитъка си, вместо да живеят постоянно на едно място.",[32950,33025,33048,33088,33103,33144,33169,33194,33225,33240,33280,33312,33339,33393,33475,33511,33531,33559,33569,33594,33635,33655,33662],33693],[1,"Dairy products are foods such as cheese and butter, which are made from milk.","Млечните продукти са храни като сирене и масло, които се правят от мляко.",[33725,33755,33804,33818,33865,33892,33905,33947,33971,34006,34046,34049,34081,34110],34156],[0,"If you take a step back, you temporarily remove yourself from a situation in order to reevaluate it.","Ако „take a step back“, временно се оттегляш от ситуация, за да я преосмислиш.",[34192,34208,34223,34253,34256,34287,34334,34353,34428,34478,34523,34541,34544,34615,34649,34686,34727,34822],34843],[1,"The idiom 'to look at the bigger picture' means to consider the overall meaning of something rather than the specific details.","Идиомът „to look at the bigger picture“ значи да погледнеш цялостния смисъл на нещо, а не конкретните детайли.",[34856,34881,34929,34949,34981,34999,35006,35033,35104,35130,35141,35199,35221,35274,35317,35325,35391,35423,35442,35449,35510],35573],[0,"And finally, the adjective premature describes something which happens too soon or before the proper time.","И накрая, прилагателното „premature“ описва нещо, което се случва твърде рано или преди подходящото време.",[35577,35604,35663,35679,35733,35798,35852,35893,35912,35957,35987,36064,36077,36133,36142,36176],36222],[0,"Once again, our six minutes are up.","Отново шестте ни минути изтекоха.",[36300,36319,36345,36356,36387,36420,36433],36450],[0,"Goodbye for now!","Засега довиждане!",[36450,36481,36493],36512],[1,"Bye!","Чао!",[36531],36576]],"v":[["preserve (food)","консервирам, запазвам (храна)",26],["nomads","номади",24],["dairy products","млечни продукти",25],["take a step back","правя крачка назад",39],["look at the bigger picture","гледам цялостната картина",39],["premature","преждевременен",40],["intake","прием",9],["processed food","преработена храна",15]],"g":[["flavour",3,10,1],["a pinch of salt",7,11,4],["intake",9,10,1],["blood pressure",11,13,2],["processed food",15,18,2],["nomads",24,15,1],["preserved",24,39,1],["dairy products",25,6,2],["take a step back",39,5,4],["bigger picture",39,13,2],["premature",40,19,1],["herbs and spices",45,10,3]],"q":[["How much salt a day does the WHO recommend?","Колко сол на ден препоръчва СЗО?","less than 5g","at least 17g","about 10g",9],["Why is it difficult to know how much salt you eat?","Защо е трудно да знаеш колко сол ядеш?","it's hidden in food, especially processed food","salt has no taste","shops don't sell it",15],["How much salt do people in Kazakhstan eat on average?","Колко сол ядат средно хората в Казахстан?","17g a day","5g a day","1g a day",21],["Why did nomads in Kazakhstan use a lot of salt?","Защо номадите в Казахстан са използвали много сол?","to preserve meat and dairy products","because it was cheap","to make the food sweet",24],["What happens when we eat too much salt?","Какво става, когато ядем твърде много сол?","the heart works harder and blood pressure goes up","we sleep better","we lose weight",33],["Which food contains the most salt?","Коя храна съдържа най-много сол?","meat","bread","pasta",50]]},"sleep":{"ser":"6 Minute English","icon":"😴","bg":"Защо ни трябва добър сън","t":"Why you need a good night's sleep","a":"ree/audio/sleep.mp3","sp":["Georgie","Phil","Ginny Smith"],"L":[[0,"Hello, this is 6 Minute English from BBC Learning English.","Здравейте, това е 6 Minute English от BBC Learning English.",[0,75,84,91,129,178,237,280,344,398],419],[0,"I'm Georgie, and we're ready to start, Phil... Phil?!","Аз съм Джорджи и сме готови да започнем, Фил… Фил?!",[464,797,818,883,896,925,942,983,1017],1040],[1,"Oh, sorry, Georgie, I was er, just, catching forty winks... you know, getting some shut-eye, dozing, taking a nap...","О, извинявай, Джорджи, аз, ъъ, просто дремех… знаеш, затворих очи за малко, задрямах, подремнах…",[1041,1044,1157,1223,1273,1330,1333,1787,1862,1913,1932,1999,2090,2134,2158,2204,2509,2571,2577],2614],[1,"I was sleeping!","Спях!",[2677,2682,2696],2745],[0,"Sleeping at work!","Спиш на работа!",[2773,2834,2846],2866],[0,"Phil, how could you?","Фил, как можа?",[2909,2975,3005,3041],3073],[1,"I know, I know.","Знам, знам.",[3075,3084,3134,3139],3159],[1,"Sorry, I... I didn't sleep well last night.","Съжалявам, аз… не спах добре снощи.",[3161,3196,3273,3280,3302,3331,3351,3375],3395],[0,"I'll forgive you this time, but make sure you go to bed early tonight because getting a good night's sleep is incredibly important.","Ще ти простя този път, но довечера непременно си легни рано, защото добрият нощен сън е изключително важен.",[3445,3464,3502,3514,3534,3572,3595,3623,3641,3655,3670,3684,3719,3753,3792,3863,3890,3897,3921,3956,3988,4003,4067],4146],[0,"For example, did you know that people who get enough sleep live about five years longer than people who don't?","Например знаеше ли, че хората, които спят достатъчно, живеят около пет години по-дълго от тези, които не спят достатъчно?",[4191,4208,4261,4286,4299,4319,4344,4385,4397,4420,4448,4511,4541,4579,4631,4669,4722,4744,4775,4787],4841],[1,"Wow, so a good night's sleep can lengthen your life.","Уау, значи добрият сън може да удължи живота ти.",[4868,4921,4952,4962,4991,5023,5052,5074,5119,5141],5186],[1,"In this programme, we'll be finding out more about the benefits of sleep, and, as usual, learning some useful new vocabulary as well.","В това предаване ще научим повече за ползите от съня и както обикновено ще научим и някои полезни нови думи.",[5209,5222,5240,5287,5308,5320,5359,5375,5409,5434,5440,5501,5511,5570,5587,5603,5666,5703,5723,5780,5812,5875,5892],5929],[0,"But first, now that you've woken up, I have a question for you.","Но първо, сега като се събуди, имам въпрос към теб.",[5955,5977,6062,6100,6111,6128,6162,6219,6242,6262,6267,6314,6325],6351],[0,"Do you know how much of the average person's life is spent asleep?","Знаеш ли каква част от живота на средностатистическия човек минава в сън?",[6406,6417,6434,6465,6493,6523,6531,6547,6590,6643,6685,6700,6752],6813],[0,"Is it: a) a half?","Дали е: а) половината?",[6850,6865,6883,6939,6943],7004],[0,"b) a quarter? or, c) a third?","б) една четвърт? или в) една трета?",[7036,7087,7093,7189,7206,7263,7268],7333],[1,"Hmm, I think we spend about a third of our lives sleeping.","Хм, мисля, че прекарваме около една трета от живота си в сън.",[7359,7428,7445,7497,7509,7541,7570,7576,7666,7682,7699,7730],7772],[0,"OK, well I'll reveal the correct answer at the end of the programme.","Добре, ще разкрия верния отговор в края на предаването.",[7796,7851,7893,7908,7947,7956,8000,8038,8061,8078,8099,8107,8118],8174],[0,"The question of why humans sleep is not easy to answer.","На въпроса защо хората спят не е лесно да се отговори.",[8226,8234,8278,8300,8327,8372,8411,8435,8471,8505,8515],8574],[0,"In terms of evolution, why would it make sense to go unconscious every night, leaving yourself vulnerable to danger?","От гледна точка на еволюцията защо би имало смисъл да губиш съзнание всяка нощ и да оставаш уязвим за опасности?",[8624,8634,8665,8673,8758,8781,8794,8807,8829,8868,8879,8905,8979,9028,9096,9127,9166,9214,9226],9286],[0,"It can only mean that the benefits gained from sleep are huge.","Това може да означава само, че ползите от съня са огромни.",[9335,9348,9363,9397,9431,9447,9454,9512,9543,9562,9603,9638],9714],[0,"Here, science journalist, Ginny Smith, explains some of these benefits to BBC Radio 4 programme, Inside Science:","Ето как научната журналистка Джини Смит обяснява някои от тези ползи пред предаването на BBC Radio 4 „Inside Science“:",[9771,9809,9854,9924,9948,10023,10085,10103,10110,10129,10188,10201,10256,10294,10323,10391,10432],10494],[2,"So we've probably all experienced this, that if you've had a bad night sleep and then you try and do some work you just can't concentrate - your brain isn't in the right state to take in new information.","Вероятно всички сме го преживявали – ако не си спал добре и после се опиташ да работиш, просто не можеш да се съсредоточиш – мозъкът ти не е в правилното състояние, за да възприема нова информация.",[10534,10556,10569,10594,10608,10670,10694,10706,10714,10727,10739,10744,10767,10798,10844,10858,10872,10883,10903,10912,10922,10942,10975,10984,11006,11044,11044,11105,11114,11139,11178,11189,11197,11223,11256,11267,11308,11319,11342],11408],[2,"But we also need to sleep after we've learnt new things because that's when our brain consolidates the information - takes it from short-term storage to long-term storage, fits it in with other things we already know, that old adage of if you've got a problem sleep on it, your brain does actually work on things during the night, and you can often wake up and have solved the problem in your sleep.","Но ни трябва сън и след като сме научили нови неща, защото тогава мозъкът ни затвърждава информацията – прехвърля я от краткосрочната памет в дългосрочната, свързва я с други неща, които вече знаем; онази стара поговорка „ако имаш проблем, пренощувай с него“ – мозъкът ти наистина работи върху нещата през нощта и често можеш да се събудиш с решен в съня си проблем.",[11408,11450,11469,11497,11522,11530,11581,11619,11636,11686,11703,11751,11778,11812,11851,11882,11912,11987,11998,11998,12065,12093,12100,12112,12159,12209,12219,12266,12345,12384,12397,12415,12425,12448,12504,12519,12551,12600,12656,12679,12719,12736,12746,12759,12769,12773,12808,12838,12852,12865,12877,12903,12922,12950,13003,13019,13063,13088,13094,13125,13136,13145,13169,13198,13227,13246,13256,13266,13313,13321,13355,13364,13375],13410],[1,"When we sleep, our brains refresh, leaving us feeling rested in the morning.","Когато спим, мозъкът ни се освежава и сутрин се чувстваме отпочинали.",[13454,13472,13487,13556,13569,13617,13709,13741,13755,13803,13869,13885,13892],13938],[1,"But after a bad night's sleep it's more difficult to concentrate.","Но след лошо спана нощ е по-трудно да се съсредоточим.",[13980,13994,14019,14023,14069,14101,14161,14187,14217,14267,14276],14364],[1,"We can't take in, or understand, new information.","Не можем да възприемем, или да разберем, нова информация.",[14365,14374,14410,14449,14501,14528,14612,14639],14699],[0,"We also have the saying, if you've got a problem, sleep on it.","Имаме и поговорката „ако имаш проблем, пренощувай с него“.",[14749,14764,14788,14805,14812,14877,14894,14911,14927,14931,14996,15031,15043],15069],[0,"To sleep on it means to delay making a decision until you've had time to think about it.","„To sleep on it“ значи да отложиш решението, докато имаш време да помислиш.",[15109,15122,15156,15169,15191,15227,15239,15278,15319,15322,15391,15415,15431,15449,15480,15492,15519,15547],15561],[0,"But that also turns out to be true scientifically speaking - during sleep, your brain really can work out problems and find solutions.","Но се оказва, че това е вярно и от научна гледна точка – по време на сън мозъкът ти наистина може да решава проблеми и да намира решения.",[15606,15618,15638,15678,15709,15728,15738,15752,15783,15862,15862,15964,15997,16037,16050,16090,16128,16169,16197,16214,16266,16281,16311],16390],[1,"But what about the other side of the story?","Но какво става от другата страна?",[16414,16422,16456,16488,16524,16552,16587,16596,16603],16646],[1,"What happens when you get too little sleep, or none at all?","Какво се случва, когато спиш твърде малко или изобщо не спиш?",[16696,16718,16769,16786,16796,16827,16869,16912,16938,16953,16984,17006],17041],[1,"Here's Ginny Smith again, talking to BBC Radio 4 programme, Inside Science:","Ето пак Джини Смит пред предаването на BBC Radio 4 „Inside Science“:",[17084,17115,17144,17177,17250,17286,17298,17352,17395,17425,17501,17548],17611],[2,"Sleep deprivation is a form of stress, and we know that when you are stressed your sort of fight-or-flight response is activated and that causes all these changes in your body that focus on immediate survival over long-term health.","Лишаването от сън е форма на стрес, а знаем, че когато сме стресирани, се активира нещо като реакцията „бий се или бягай“, а тя причинява всички тези промени в тялото, които се фокусират върху непосредственото оцеляване, а не върху дългосрочното здраве.",[17661,17685,17738,17754,17757,17782,17789,17857,17875,17888,17914,17929,17974,18005,18041,18117,18131,18151,18157,18221,18270,18281,18353,18363,18377,18412,18423,18443,18491,18499,18509,18550,18572,18630,18662,18723,18793,18869,18921],18972],[2,"But if we are chronically stressed - money worries, or a stressful job, or something that's going on forever, or life, or chronic sleep deprivation that's causing that level of stress, then you might constantly have a damped down immune system which can then lead to all these knock-on problems.","Но ако сме хронично стресирани – тревоги за пари, стресираща работа или нещо, което продължава безкрайно, или животът, или хроничното недоспиване, което причинява това ниво на стрес, – тогава може постоянно да имаш потисната имунна система, което после може да доведе до всички тези косвени проблеми.",[18973,18984,19009,19027,19036,19103,19103,19233,19268,19334,19384,19391,19445,19484,19492,19527,19544,19559,19583,19630,19653,19756,19787,19838,19868,19934,19952,19988,20002,20023,20029,20081,20103,20115,20138,20205,20222,20225,20249,20269,20297,20355,20383,20405,20472,20500,20512,20527,20547,20584],20642],[0,"Having none or too little of something important is known as deprivation.","Липсата или твърде малкото количество от нещо важно се нарича „deprivation“ (лишаване).",[20712,20742,20775,20794,20819,20854,20862,20903,20987,21003,21043,21069],21174],[0,"Sleep deprivation is stressful for the body - so stressful that it activates a fight-or-flight response, changes in the human body in response to a life-threatening situation which make us either stay and fight the threat or run away from it.","Лишаването от сън е стресиращо за тялото – толкова стресиращо, че активира реакцията „бий се или бягай“ – промени в човешкото тяло в отговор на животозастрашаваща ситуация, които ни карат или да останем и да се борим със заплахата, или да избягаме от нея.",[21222,21250,21318,21336,21389,21404,21414,21414,21502,21534,21600,21616,21628,21694,21703,21804,21922,21975,21988,21997,22034,22070,22083,22138,22151,22158,22245,22380,22395,22425,22441,22469,22526,22541,22579,22588,22658,22672,22691,22719,22742],22769],[1,"As well as a fight-or-flight response, the stress of not getting enough sleep over a longer period also creates problems including heart disease and a weakened immune system.","Освен реакцията „бий се или бягай“, стресът от недостатъчния сън за по-дълъг период създава и проблеми, включително сърдечни болести и отслабена имунна система.",[22817,22833,22858,22869,22875,22969,23076,23087,23131,23143,23185,23223,23248,23309,23331,23334,23373,23472,23500,23543,23619,23668,23701,23753,23765,23768,23819,23853],23901],[1,"Lack of sleep has these knock-on effects, it causes other things to happen, but not directly.","Липсата на сън има тези „knock-on effects“ – причинява други неща, но не пряко.",[23959,23979,23987,24016,24038,24066,24131,24206,24222,24263,24288,24322,24331,24384,24412,24443],24504],[0,"Now do you see why it's so important to get a good night's sleep, Phil?","Сега разбираш ли защо е толкова важно да спиш добре, Фил?",[24536,24570,24581,24594,24626,24648,24666,24684,24742,24749,24766,24770,24800,24834,24864],24903],[0,"Plus, it will stop you sleeping at work again!","А и това ще те спре да спиш на работа отново!",[24948,24998,25011,25023,25056,25071,25118,25128,25162],25208],[0,"Right, I think it's time to reveal the answer to my question.","Добре, мисля, че е време да разкрия отговора на моя въпрос.",[25254,25325,25350,25366,25381,25409,25422,25465,25483,25519,25534,25555],25616],[1,"Yes, you asked me how much of the average person's life is spent asleep, and I said it was about a third.","Да, попита ме каква част от живота на средностатистическия човек минава в сън, а аз казах, че е около една трета.",[25656,25712,25736,25762,25780,25812,25850,25862,25878,25938,25994,26024,26032,26066,26168,26180,26191,26252,26262,26279,26316,26319],26382],[0,"Which was... the correct answer!","Което беше… верният отговор!",[26384,26422,26548,26560,26606],26665],[0,"Assuming you sleep eight hours a day, the average person will sleep for 229,961 hours in their lifetime or around one third of their life.","Ако приемем, че спиш по осем часа на ден, средностатистическият човек ще спи 229 961 часа през живота си, или около една трета от живота си.",[26719,26769,26782,26822,26841,26873,26877,26928,26948,26987,27040,27052,27087,27113,27502,27581,27594,27608,27712,27758,27788,27813,27847,27858,27875],27918],[0,"OK, let's recap the vocabulary we've learned starting with the phrases catch forty winks, get some shut-eye, doze and take a nap, all of which mean to sleep.","Добре, нека преговорим думите, които научихме, като започнем с фразите „catch forty winks“, „get some shut-eye“, „doze“ и „take a nap“, които всички значат спя.",[27956,28020,28045,28081,28090,28162,28188,28261,28309,28324,28331,28412,28450,28488,28557,28581,28600,28687,28738,28775,28818,28820,28894,28914,28929,28950,28985,29002],29054],[1,"When someone takes in information, they understand it.","Когато някой „takes in“ информация, той я разбира.",[29088,29101,29144,29200,29243,29306,29340,29399],29412],[0,"If you have a problem and you sleep on it, you delay making a decision until you've had time to think about it.","Ако имаш проблем и „sleep on it“, отлагаш решението, докато имаш време да помислиш.",[29458,29476,29489,29506,29512,29562,29585,29601,29645,29657,29718,29731,29771,29812,29817,29871,29901,29918,29940,29975,29985,30011,30038],30055],[1,"Deprivation is an absence or too little of something important such as food or sleep.","„Deprivation“ е липса или твърде малко от нещо важно, като храна или сън.",[30086,30167,30186,30194,30282,30300,30328,30382,30393,30428,30493,30517,30531,30578,30594],30640],[0,"The fight-or-flight response describes changes in the human body in response to a dangerous situation which make us either stay and fight the threat or run away from it.","Реакцията „fight-or-flight“ описва промените в човешкото тяло в отговор на опасна ситуация, които ни карат или да останем и да се борим със заплахата, или да избягаме от нея.",[30641,30682,30762,30817,30876,30923,30935,30942,30981,31025,31037,31092,31105,31125,31182,31309,31325,31356,31375,31403,31456,31470,31500,31511,31581,31596,31613,31637,31657],31681],[1,"And finally, if something has a knock-on effect, it causes other results indirectly.","И накрая, ако нещо има „knock-on effect“, то причинява други резултати косвено.",[31715,31753,31838,31848,31892,31918,31925,31999,32099,32112,32163,32189,32257],32334],[1,"Once again our six minutes are up, but remember to join us again next time for more trending topics and useful vocabulary, here at 6 Minute English.","Отново шестте ни минути изтекоха, но не забравяйте да се присъедините към нас следващия път за още актуални теми и полезни думи тук, в 6 Minute English.",[32401,32425,32455,32470,32506,32536,32556,32581,32594,32662,32681,32714,32726,32767,32789,32818,32833,32875,32925,33000,33022,33056,33137,33164,33179,33200,33230],33266],[1,"Goodbye for now!","Засега довиждане!",[33316,33344,33356],33400],[0,"Bye!","Чао!",[33404],33455]],"v":[["take a nap","подремвам",45],["take in","възприемам, разбирам",22],["sleep on it","пренощувам с проблема (отлагам решението)",23],["deprivation","лишаване, липса",33],["fight-or-flight response","реакция „бий се или бягай“",33],["knock-on effect","косвен ефект",50],["doze","дремя",45],["concentrate","съсредоточавам се",22]],"g":[["forty winks",2,8,2],["shut-eye",2,14,1],["forgive",8,1,1],["benefits",11,10,1],["vulnerable",19,16,1],["concentrate",22,25,1],["take in",22,35,2],["sleep on it",23,46,3],["deprivation",33,1,1],["fight-or-flight",33,18,1],["immune system",34,39,2],["knock-on",34,48,1]],"q":[["Why was Phil sleeping at work?","Защо Фил спеше на работа?","he didn't sleep well last night","he was ill","he was bored",7],["How much longer do people who get enough sleep live?","Колко по-дълго живеят хората, които спят достатъчно?","about five years","about one year","about twenty years",9],["What happens after a bad night's sleep?","Какво става след лошо спана нощ?","it's difficult to concentrate","you feel more creative","you remember more",25],["What does 'sleep on it' mean?","Какво значи „sleep on it“?","delay a decision until you've had time to think","go to bed early","sleep in the afternoon",28],["What can chronic sleep deprivation lead to?","До какво може да доведе хроничното недоспиване?","heart disease and a weakened immune system","better memory","more energy",37],["How much of our life do we spend asleep?","Каква част от живота си прекарваме в сън?","about a third","about a half","about a quarter",43]]},"junkfood":{"ser":"6 Minute English","icon":"🍔","bg":"Бърза храна и спорт","t":"Junk food and sport","a":"ree/audio/junkfood.mp3","sp":["Neil","Sam","Dr Sandro Demaio"],"L":[[0,"Hello. This is 6 Minute English from BBC Learning English.","Здравейте. Това е 6 Minute English от BBC Learning English.",[0,18,44,61,80,98,136,156,208,245],297],[0,"I'm Neil.","Аз съм Нийл.",[328,336],349],[1,"And I'm Sam.","А аз съм Сам.",[350,366,450],466],[0,"The Olympic Games happen every four years and the most recent games were held in Tokyo this summer.","Олимпийските игри се провеждат на всеки четири години, а последните игри бяха в Токио това лято.",[467,474,767,813,878,899,927,942,966,1000,1373,1435,1500,1542,1560,1651,1757,1769],1813],[0,"Did you watch them, Sam?","Гледа ли ги, Сам?",[1955,1979,2423,2447,2459],2495],[1,"Yes, I saw British swimmer, Adam Peaty, win a gold medal and - my personal favourite - 13-year-old, Sky Brown, competing in an exciting sport which was added to the Olympics this year: skateboarding.","Да, видях как британският плувец Адам Пийти печели златен медал и – моят личен фаворит – 13-годишната Скай Браун, която се състезаваше във вълнуващ спорт, добавен към Олимпиадата тази година: скейтборд.",[2516,2568,2582,2609,2649,2677,2723,2768,2786,2793,2818,2895,2895,2918,2936,2995,2995,3048,3168,3209,3295,3345,3352,3362,3422,3459,3478,3500,3530,3544,3555,3600,3623,3669],3773],[0,"Olympic athletes inspire people around the world to take on new challenges, eat healthily and get fit.","Олимпийските спортисти вдъхновяват хора по целия свят да приемат нови предизвикателства, да се хранят здравословно и да влязат във форма.",[3793,3830,3891,3955,3984,4012,4018,4064,4072,4103,4122,4138,4232,4253,4314,4338,4361],4397],[0,"So it seems strange that some of the companies that sponsor - or pay for, the Olympic Games also sell food and drink which is linked to obesity, heart disease and diabetes.","Затова изглежда странно, че някои от компаниите, които спонсорират – тоест плащат за – Олимпийските игри, продават и храни и напитки, свързани със затлъстяване, сърдечни болести и диабет.",[4444,4462,4473,4505,4555,4567,4589,4598,4605,4668,4678,4678,4754,4765,4798,4836,4848,4887,4951,4989,5023,5059,5073,5112,5130,5144,5175,5198,5292,5322,5376,5397],5469],[1,"Tobacco advertising was banned from international sport in 2005 because of the harmful effects of smoking.","Рекламата на тютюн беше забранена в международния спорт през 2005 г. заради вредните ефекти от пушенето.",[5499,5549,5618,5640,5683,5704,5771,5812,5827,5959,5990,5998,6005,6054,6094,6100],6167],[1,"But other companies selling less-than-healthy products still sponsor big sporting events.","Но други компании, които продават не особено здравословни продукти, все още спонсорират големи спортни събития.",[6198,6222,6244,6305,6360,6444,6497,6533,6588,6606,6655],6712],[0,"These could be sugary drink companies, or others who sell fast food - hot food, like hamburgers, that is quick to cook and serve but which is often unhealthy.","Това може да са компании за сладки напитки или други, които продават бърза храна – топла храна като хамбургери, която се приготвя и сервира бързо, но често е нездравословна.",[6739,6753,6766,6778,6822,6853,6931,6962,7002,7011,7038,7081,7081,7141,7170,7215,7231,7306,7330,7349,7388,7398,7433,7446,7511,7547,7571,7591,7622],7692],[1,"In this programme we'll be asking whether it's right for companies selling unhealthy products to sponsor sporting events.","В това предаване ще се питаме дали е правилно компании, които продават нездравословни продукти, да спонсорират спортни събития.",[7701,7715,7735,7777,7789,7799,7851,7873,7901,7936,7946,8000,8040,8093,8175,8186,8232,8283],8348],[0,"But first it's time for my quiz question, Sam.","Но първо е време за моя въпрос от викторината, Сам.",[8375,8392,8430,8443,8467,8475,8492,8527,8574],8607],[0,"McDonalds had a long history with the Olympic Games until the company ended the partnership ahead of the 2024 games in Paris.","„Макдоналдс“ имаше дълга история с Олимпийските игри, докато компанията не прекрати партньорството преди игрите в Париж през 2024 г.",[8635,8680,8692,8705,8731,8794,8812,8822,8855,8906,8942,8948,9009,9053,9061,9148,9173,9181,9191,9303,9342,9356],9412],[0,"But why did McDonalds choose to quit?","Но защо „Макдоналдс“ реши да се откаже?",[9447,9459,9492,9509,9569,9600,9609],9652],[0,"Was it because: a) they wanted to change the name of French fries to McFries?","Дали беше, защото: а) искаха да сменят името на пържените картофи на „МакФрайс“?",[9681,9703,9716,9778,9817,9831,9867,9875,9917,9927,9961,9977,10009,10048,10059],10141],[0,"b) they didn't want to call their hamburger, 'Le Big Mac'? or, c) they wanted to be the only company selling cheese for cheeseburgers?","б) не искаха да наричат хамбургера си „Le Big Mac“? или в) искаха да бъдат единствената компания, която продава сирене за чийзбургери?",[10172,10212,10226,10255,10276,10282,10311,10325,10406,10427,10450,10514,10533,10600,10613,10650,10660,10679,10700,10738,10792,10832,10887,10896],10975],[1,"Hmm, I think maybe it's a) because they wanted to call French fries, McFries.","Хм, мисля, че може би е а) – защото искаха да наричат пържените картофи „МакФрайс“.",[10991,11109,11112,11143,11181,11232,11278,11309,11320,11357,11367,11396,11433,11482],11579],[0,"OK, Sam, we'll find out the answer later in the programme.","Добре, Сам, ще разберем отговора по-късно в предаването.",[11611,11634,11667,11684,11716,11736,11752,11776,11815,11822,11829],11881],[1,"Someone who is worried about the relationship between fast food and sport is Dr Sandro Demaio.","Човек, когото тревожи връзката между бързата храна и спорта, е д-р Сандро Демайо.",[11896,11928,11950,11984,12010,12038,12046,12112,12149,12189,12209,12228,12289,12299,12327,12364],12418],[1,"He worked for the World Health Organisation specialising in obesity before starting his own public health agency in Australia.","Той е работил за Световната здравна организация като специалист по затлъстяването, преди да основе собствена агенция за обществено здраве в Австралия.",[12445,12457,12485,12495,12504,12524,12555,12636,12719,12732,12802,12837,12884,12902,12916,12957,12984,13075,13090],13162],[0,"Here is Dr Demaio speaking with BBC World Service programme, The Food Chain, about the problem with unhealthy brands and food products:","Ето как д-р Демайо говори в предаването на BBC World Service „The Food Chain“ за проблема с нездравословните марки и хранителни продукти:",[13190,13203,13219,13249,13296,13356,13378,13429,13456,13491,13543,13550,13584,13635,13659,13666,13707,13734,13784,13832,13855,13878],13950],[2,"By having their brand alongside a young person's favourite sporting hero, on the chest of their national team, it does two things.","Когато марката им е до любимия спортен герой на младия човек, на гърдите на националния му отбор, това прави две неща.",[13962,13980,14016,14031,14069,14190,14194,14219,14271,14315,14357,14437,14452,14459,14503,14531,14567,14612,14693,14705,14733,14756],14812],[2,"First of all, it creates brand attachment, so if you're a young child you built the connection in your mind that basically fast food equals success.","Първо, създава привързаност към марката, така че ако си малко дете, в съзнанието ти се изгражда връзката, че общо взето бърза храна е равно на успех.",[14850,14890,14899,14927,14940,14978,15008,15078,15094,15108,15131,15134,15162,15237,15249,15292,15299,15342,15348,15358,15403,15422,15531,15570,15612,15650],15720],[2,"At the same time it also gives a health halo to that brand.","В същото време дава и „здравен ореол“ на тази марка.",[15780,15787,15793,15819,15859,15877,15903,15928,15931,15975,16013,16066,16088],16122],[2,"Then you start to think in your mind, even subconsciously, that it can't be that bad...","Тогава започваш да мислиш, дори подсъзнателно, че не може да е чак толкова лошо…",[16175,16221,16237,16268,16275,16312,16325,16337,16393,16412,16500,16538,16547,16572,16585,16609],16649],[1,"You've probably heard of 'brand loyalty', where people have a favourite brand they always buy, but Dr Demaio is concerned about brand attachment.","Вероятно сте чували за „лоялност към марката“ – когато хората имат любима марка, която винаги купуват, но д-р Демайо е загрижен за привързаността към марката.",[16681,16703,16752,16790,16805,16849,16916,16943,16975,16999,17006,17059,17097,17110,17152,17228,17246,17278,17325,17344,17402,17437,17493],17596],[0,"Brand attachment is the emotional connection between humans and brands.","Привързаността към марката е емоционалната връзка между хората и марките.",[17612,17666,17733,17749,17758,17815,17871,17903,17961,17976],18033],[0,"It goes deeper than loyalty so that people mentally connect a particular company with feelings of winning, being healthy and success.","Тя е по-дълбока от лоялността, така че хората мислено свързват определена компания с чувства за победа, здраве и успех.",[18085,18095,18119,18155,18178,18251,18267,18283,18319,18374,18435,18440,18503,18561,18587,18627,18633,18710,18734,18810,18830],18896],[1,"The problem comes when these feelings attach to companies that aren't healthy at all.","Проблемът е, когато тези чувства се свържат с компании, които изобщо не са здравословни.",[18912,18925,18968,19021,19034,19059,19109,19159,19169,19225,19244,19265,19310,19346],19381],[1,"Dr Demaio says this creates a health halo - the belief that something is good, like an angel's halo, even though there is little evidence to support this.","Д-р Демайо казва, че това създава „здравен ореол“ – вярата, че нещо е добро, като ореола на ангел, макар че има малко доказателства за това.",[19428,19459,19506,19546,19565,19623,19637,19684,19684,19775,19787,19828,19847,19885,19901,19966,19984,19995,20047,20134,20178,20218,20237,20253,20285,20341,20350,20400],20451],[0,"On the other hand, fast food and fizzy drink companies invest large amounts of money in sport, over 4.5 billion dollars since the 2016 Rio Olympics, much of it supporting athletes around the world.","От друга страна, компаниите за бърза храна и газирани напитки инвестират големи суми в спорта – над 4,5 милиарда долара от Олимпиадата в Рио през 2016 г., голяма част от тях в подкрепа на спортисти по целия свят.",[20478,20498,20524,20563,20602,20635,20668,20694,20733,20772,20837,20883,20922,20975,20994,21034,21053,21099,21132,21158,21210,21262,21301,21328,21360,21386,21452,21484,21504,21524,21596,21654,21700,21726],21772],[1,"Yes, with travel, training and equipment the cost of being an Olympic athlete can be huge.","Да, с пътуванията, тренировките и екипировката цената да си олимпийски спортист може да е огромна.",[21791,21849,21875,21928,21983,22005,22098,22108,22144,22153,22181,22188,22228,22275,22294,22306],22412],[1,"And depending on your country and your sport, there may be little financial help.","А в зависимост от държавата и спорта ти може да има малко финансова помощ.",[22414,22439,22484,22495,22505,22560,22584,22598,22700,22715,22740,22753,22786,22841],22881],[0,"Many athletes are desperate for any sponsorship they can get - but does that make it right to promote unhealthy eating in return?","Много спортисти отчаяно търсят всякакво спонсорство, което могат да получат – но прави ли това правилно в замяна да се рекламира нездравословно хранене?",[22901,22923,22970,22978,23035,23049,23072,23136,23152,23168,23168,23236,23247,23269,23284,23307,23315,23355,23368,23413,23476,23510,23521],23574],[1,"Not according to Dr Demaio, who thinks people should worry about the nutritional value of fast food, as he explained to BBC World Service's, The Food Chain:","Не и според д-р Демайо, който смята, че хората трябва да се тревожат за хранителната стойност на бързата храна, както обясни пред „The Food Chain“ на BBC World Service:",[23592,23623,23667,23677,23708,23764,23778,23811,23849,23873,23916,23945,23952,24013,24047,24054,24088,24169,24189,24196,24251,24260,24308,24330,24423,24434,24459],24500],[2,"When we think about foods and beverages of public health concern, we tend to start by talking about highly-processed foods, particularly ultra processed foods.","Когато мислим за храни и напитки, които тревожат общественото здраве, обикновено започваме с говорене за силно преработени храни, особено ултрапреработените храни.",[24529,24541,24552,24589,24616,24698,24717,24804,24828,24858,24873,24966,24977,25025,25074,25118,25184,25222,25259,25350,25395,25458,25492,25553],25594],[2,"These are foods that have been really broken down to their basic elements and then built up - they're more products really than foods - they're made in a laboratory not a kitchen.","Това са храни, които са разградени до основните си елементи и после изградени отново – по-скоро са продукти, отколкото храни – правени са в лаборатория, а не в кухня.",[25650,25670,25674,25713,25734,25762,25815,25838,25880,25912,25961,25972,26025,26070,26080,26094,26131,26131,26156,26169,26185,26247,26279,26312,26312,26422,26450,26472,26478,26482,26541,26557,26561],26613],[0,"Dr Demaio mentions unhealthy foods and beverages - another word for drinks.","Д-р Демайо споменава нездравословни храни и „beverages“ – друга дума за напитки.",[26695,26722,26768,26824,26890,26938,26953,26953,27036,27065,27091,27102],27158],[1,"He's concerned about the public health risk of ultra-processed food - foods containing extra ingredients like chemicals, colourings and sweeteners that you wouldn't add when cooking homemade food.","Той е загрижен за риска за общественото здраве от ултрапреработената храна – храни, съдържащи допълнителни съставки като химикали, оцветители и подсладители, които не бихте добавили, когато готвите домашна храна.",[27188,27206,27259,27285,27293,27338,27369,27400,27411,27542,27542,27628,27663,27733,27774,27838,27858,27939,27996,28008,28101,28116,28130,28158,28198,28229,28266,28306],28358],[0,"A potato, for example, is natural - minimally processed.","Картофът например е естествен – минимално преработен.",[28384,28392,28451,28464,28510,28524,28524,28589,28634],28694],[0,"Bake a potato and it becomes 'processed'.","Изпечете картоф и той става „преработен“.",[28722,28764,28769,28817,28836,28842,28897],28966],[0,"Make French fries and it's 'ultra-processed'.","Направете пържени картофи и той е „ултрапреработен“.",[29009,29034,29069,29114,29131,29152],29263],[1,"And speaking of French fries, Neil, what was the answer to your quiz question?","И като стана дума за пържени картофи, Нийл, какъв беше отговорът на въпроса ти от викторината?",[29285,29299,29333,29341,29367,29405,29436,29471,29518,29535,29565,29580,29589,29616],29667],[0,"Yes, I asked Sam the reason behind the decision McDonald's made not to sponsor the 2024 Paris Olympics.","Да, питах Сам за причината за решението на „Макдоналдс“ да не спонсорира Олимпиадата в Париж през 2024 г.",[29692,29719,29736,29756,29779,29788,29823,29860,29866,29913,29982,30016,30036,30060,30109,30137,30233,30281],30345],[1,"I said it was, a) because they wanted to call French fries, McFries.","Аз казах а) – защото искаха да наричат пържените картофи „МакФрайс“.",[30383,30398,30428,30438,30475,30517,30551,30563,30597,30606,30632,30664,30714],30819],[0,"Which was... the wrong answer!","Което беше… грешният отговор!",[30835,30859,30927,30942,30972],31014],[0,"In fact, McDonald's wanted to be only company allowed to advertise cheese so it could boost cheeseburger sales.","Всъщност „Макдоналдс“ искаше да е единствената компания, на която е позволено да рекламира сирене, за да увеличи продажбите на чийзбургери.",[31015,31035,31122,31195,31271,31279,31306,31325,31375,31407,31414,31475,31544,31561,31572,31588,31631,31704],31760],[1,"This didn't go down well with officials in France, a country with over a thousand different types of cheese!","Това не се хареса на официалните лица във Франция – държава с над хиляда различни вида сирена!",[31848,31869,31896,31910,31942,31970,31988,32031,32041,32098,32110,32155,32178,32206,32213,32282,32313,32345,32351],32405],[1,"OK, let's recap the vocabulary from this programme starting with fast food - hot food that is quick to cook but may be unhealthy.","Добре, нека преговорим думите от предаването, като започнем с „fast food“ – топла храна, която се приготвя бързо, но може да е нездравословна.",[32471,32537,32559,32598,32607,32662,32678,32696,32750,32808,32844,32902,32902,32981,33006,33039,33050,33066,33091,33102,33150,33183,33204,33225],33298],[0,"Companies that sponsor sports events, pay for them to happen.","Компаниите, които „sponsor“ спортни събития, плащат, за да се проведат.",[33319,33360,33376,33438,33478,33515,33548,33561,33581,33590],33634],[1,"Brand attachment is a psychological connection between someone and a brand.","„Brand attachment“ е психологическа връзка между човек и марка.",[33661,33690,33752,33775,33781,33859,33921,33965,34023,34078,34088],34145],[0,"A health halo is the perception that something is healthy for you, even if it's not.","„Health halo“ е възприятието, че нещо е здравословно за теб, дори да не е.",[34164,34172,34211,34264,34282,34290,34347,34357,34398,34420,34466,34490,34533,34557,34564,34581],34611],[1,"Ultra-processed foods are foods containing added artificial ingredients like colourings and preservatives.","Ултрапреработените храни са храни, съдържащи добавени изкуствени съставки като оцветители и консерванти.",[34641,34725,34775,34790,34825,34887,34921,34980,35044,35069,35128,35144],35237],[0,"And a beverage is another word for a drink.","А „beverage“ е друга дума за напитка.",[35260,35279,35286,35337,35375,35399,35425,35442,35446],35488],[1,"That's all from us, but if you'd like to find out more about the business, science and culture of food, why not download The Food Chain podcast! - it's updated weekly and available now.","Това е всичко от нас, но ако искате да научите повече за бизнеса, науката и културата на храната, защо не свалите подкаста „The Food Chain“! – обновява се всяка седмица и е достъпен сега.",[35488,35519,35531,35550,35585,35597,35610,35627,35648,35656,35686,35706,35754,35783,35791,35852,35904,35925,35969,35990,36062,36088,36118,36169,36180,36213,36241,36241,36321,36344,36400,36463,36484,36530],36567],[0,"Join us again soon for more topical discussion and vocabulary here at 6 Minute English.","Присъединете се отново скоро за още актуални дискусии и думи тук, в 6 Minute English.",[36592,36611,36623,36644,36677,36688,36706,36752,36805,36814,36887,36916,36931,36962,36989],37028],[0,"Bye for now!","Засега чао!",[37052,37069,37078],37103],[1,"Goodbye!","Довиждане!",[37104],37175]],"v":[["sponsor","спонсорирам",7],["fast food","бърза храна",10],["brand attachment","привързаност към марка",23],["health halo","„здравен ореол“",24],["ultra-processed food","ултрапреработена храна",39],["beverage","напитка",54],["obesity","затлъстяване",7],["athletes","спортисти",6]],"g":[["inspire",6,2,1],["sponsor",7,10,1],["obesity",7,27,1],["banned",8,3,1],["fast food",10,10,2],["partnership",13,14,1],["brand attachment",23,5,2],["health halo",24,8,2],["evidence",30,24,1],["equipment",32,5,1],["beverages",36,6,1],["ultra-processed",39,8,1]],"q":[["Where were the most recent Olympic Games, says Neil?","Къде бяха последните Олимпийски игри според Нийл?","in Tokyo","in Paris","in Rio",3],["When was tobacco advertising banned from international sport?","Кога рекламата на тютюн беше забранена в международния спорт?","in 2005","in 2016","in 2024",8],["What does brand attachment make young children think?","Какво кара децата да мислят привързаността към марката?","that fast food equals success","that sport is boring","that cheese is unhealthy",23],["How much have fast food and fizzy drink companies invested in sport since 2016?","Колко са инвестирали компаниите за бърза храна и газирани напитки в спорта от 2016 г.?","over 4.5 billion dollars","over 1 million dollars","over 100 billion dollars",31],["Where are ultra-processed foods made, according to Dr Demaio?","Къде се правят ултрапреработените храни според д-р Демайо?","in a laboratory, not a kitchen","on a farm","at home",37],["Why did McDonald's stop sponsoring the Olympics?","Защо „Макдоналдс“ спря да спонсорира Олимпиадата?","they wanted to be the only company advertising cheese","they wanted to rename French fries","they didn't like 'Le Big Mac'",47]]},"doom":{"ser":"6 Minute English","icon":"📉","bg":"Безкрайното скролване на лоши новини","t":"Doomscrolling","a":"ree/audio/doom.mp3","sp":["Sam","Neil","Ella al-Shamahi","Clara Amfo"],"L":[[0,"Hello. This is 6 Minute English from BBC Learning English.","Здравейте. Това е 6 Minute English от BBC Learning English.",[0,18,44,61,80,98,136,158,208,245],297],[0,"I'm Sam.","Аз съм Сам.",[328,336],350],[1,"And I'm Neil.","А аз съм Нийл.",[351,366,385],406],[0,"Have you heard the expression doomscrolling, Neil?","Чувал ли си израза „doomscrolling“, Нийл?",[407,436,442,455,501,543,992],1117],[0,"It's when people spend a lot of time reading, or 'scrolling', a mobile phone or computer screen in order to read negative news stories - stories full of doom.","Това е, когато хората прекарват много време да четат, или „скролват“, екрана на телефона или компютъра, за да четат негативни новини – истории, пълни с обреченост.",[1306,1330,1341,1367,1397,1412,1421,1427,1451,1541,1548,1590,1671,1899,1956,2604,2657,2704,2723,2745,2759,2793,2861,2888,2888,2977,3030,3071,3086],3136],[1,"I hate to admit it, but I do sometimes doomscroll.","Мразя да си го призная, но понякога и аз го правя.",[3137,3171,3208,3227,3270,3288,3302,3316,3362,3430],3506],[0,"Well don't feel too bad, Neil, because you're not alone.","Е, не се чувствай толкова зле, Нийл, защото не си сам.",[3551,3566,3589,3609,3636,3659,3684,3720,3730,3761],3812],[0,"Research from the University of California found that people all over the world doomscroll, regardless of culture.","Изследване на Калифорнийския университет установи, че хората по целия свят правят това, независимо от културата си.",[3848,3898,3911,3923,3983,3989,4059,4098,4112,4153,4189,4211,4222,4277,4380,4439,4447],4503],[0,"What's more, there may even be evolutionary reasons why we're attracted to bad news.","Нещо повече – може дори да има еволюционни причини да ни привличат лошите новини.",[4550,4573,4614,4639,4664,4703,4730,4809,4861,4881,4897,4950,4959,4988],5036],[1,"In this programme, we'll be investigating why we feel compelled to look at, and even seek out, bad news.","В това предаване ще изследваме защо се чувстваме принудени да гледаме и дори да търсим лоши новини.",[5062,5075,5091,5147,5173,5186,5277,5302,5322,5348,5423,5431,5459,5511,5527,5569,5620,5667,5709],5765],[1,"And, as usual, we'll be learning some new vocabulary, as well.","И както обикновено ще научим и някои нови думи.",[5812,5838,5858,5902,5924,5941,5973,5992,6012,6091,6109],6134],[0,"But before that I have a question for you, Neil.","Но преди това имам въпрос към теб, Нийл.",[6134,6166,6202,6236,6248,6267,6272,6323,6341,6355],6383],[0,"Doomscrolling is a very modern idea which is only possible with the 24/7, non-stop cycle of news reporting.","„Doomscrolling“ е много модерна идея, която е възможна само с денонощния, непрекъснат цикъл на новините.",[6438,6505,6519,6528,6550,6597,6659,6688,6706,6740,6796,6810,6819,6929,6986,7038,7049,7078],7139],[0,"So, according to international news agency, Reuters, what has been the top global news story of 2023 so far?","Според международната новинарска агенция „Ройтерс“ коя е водещата световна новина за 2023 г. досега?",[7152,7177,7230,7240,7321,7349,7402,7461,7495,7511,7559,7569,7609,7661,7685,7732,7746,7841,7863],7901],[0,"Is it: a) The war in Ukraine?","Дали е: а) войната в Украйна?",[7951,7968,8012,8070,8085,8103,8112],8167],[0,"b) Increasing prices and inflation?, or, c) Prince Harry's autobiography?","б) растящите цени и инфлацията? или в) автобиографията на принц Хари?",[8209,8256,8329,8381,8400,8468,8487,8577,8608,8644],8724],[1,"I think the answer is an issue that's affecting everyone - inflation.","Мисля, че отговорът е проблем, който засяга всички – инфлацията.",[8772,8797,8833,8847,8905,8942,8955,8997,9018,9084,9084,9159],9228],[0,"OK, Neil. I'll reveal the answer at the end of the programme.","Добре, Нийл. Ще разкрия отговора в края на предаването.",[9249,9281,9305,9331,9367,9381,9411,9436,9450,9471,9483,9490],9543],[0,"Now, it might be true that the non-stop news cycle makes doomscrolling possible, but that doesn't explain why we do it.","Може да е вярно, че непрекъснатият цикъл на новините прави „doomscrolling“ възможен, но това не обяснява защо го правим.",[9604,9627,9637,9660,9673,9721,9743,9751,9812,9838,9874,9906,9969,10053,10069,10091,10125,10184,10244,10259,10280],10309],[0,"Anthropologist Ella al-Shamahi thinks the answer may lie in human evolution.","Антроположката Ела ал-Шамахи смята, че отговорът може да се крие в човешката еволюция.",[10339,10431,10450,10567,10595,10609,10645,10666,10691,10712,10753],10828],[0,"Here she outlines the problem for BBC Radio 4 programme, Why Do We Do That?","Ето как тя описва проблема за предаването на BBC Radio 4 „Why Do We Do That?“",[10870,10889,10909,10956,10966,11012,11025,11072,11102,11125,11197,11231,11245,11259,11278],11323],[2,"We go searching out for bad news, looking for things that will make us feel sick inside.","Тръгваме да търсим лоши новини, търсим неща, от които ще ни призлее отвътре.",[11381,11392,11412,11478,11511,11525,11556,11628,11672,11686,11742,11766,11778,11808,11822,11845,11872],11945],[2,"And so many of us do it.","И толкова много от нас го правят.",[11995,12013,12063,12103,12113,12131,12152],12174],[2,"Is it a result of 24/7 doom on tap on our phones?","Дали е резултат от денонощната обреченост „на кран“ в телефоните ни?",[12216,12233,12244,12248,12286,12300,12423,12455,12488,12523,12541,12552],12616],[2,"Or, is it some kind of compulsion that comes from somewhere way, way back?","Или е някакъв вид непреодолимо влечение, което идва от много, много отдавна?",[12688,12783,12798,12807,12845,12875,12881,12957,12984,13022,13038,13126,13176,13201],13242],[0,"Reading bad news stories makes us feel sick - an informal American phrase which means feel sick, often because of something disgusting or disturbing.","Четенето на лоши новини ни кара да „feel ick“ – неформален американски израз, който значи да ти призлее, често заради нещо отвратително или тревожно.",[13337,13369,13393,13413,13453,13487,13511,13565,13565,13618,13633,13699,13750,13795,13816,13854,13884,13958,13995,14031,14039,14084,14159,14181],14255],[0,"It's a feeling caused by the fact that, thanks to the internet, now we have the news on tap - easily available so that you can have as much of it as you want, whenever you want.","Това чувство идва от факта, че благодарение на интернет сега имаме новините „on tap“ – лесно достъпни, така че можеш да имаш колкото искаш от тях, когато поискаш.",[14287,14304,14310,14353,14385,14399,14407,14461,14474,14507,14522,14538,14649,14677,14691,14723,14731,14764,14784,14784,14864,14913,14973,14991,15008,15016,15035,15062,15088,15125,15135,15148,15169,15179,15242,15281,15301],15344],[1,"But Ella thinks that's not the whole story.","Но Ела смята, че това не е цялата история.",[15345,15394,15419,15462,15494,15514,15523,15548],15599],[1,"There's another theory: way back in human history, when we lived in caves, it seemed everything could kill us, from wild animals to eating the wrong mushroom.","Има и друга теория: много отдавна в човешката история, когато живеехме в пещери, изглеждало, че всичко може да ни убие – от дивите животни до изяждането на грешната гъба.",[15639,15667,15694,15756,15778,15810,15827,15862,15916,15937,15955,15977,15990,16084,16103,16149,16219,16242,16275,16298,16331,16378,16434,16445,16483,16490,16521],16580],[1,"Knowing what the dangers were, and how to avoid them, was vital to our survival, and from an evolutionary perspective, survival is everything.","Да знаеш какви са опасностите и как да ги избегнеш е било жизненоважно за оцеляването ни, а от еволюционна гледна точка оцеляването е всичко.",[16624,16665,16681,16690,16743,16796,16815,16840,16856,16896,16919,16959,17005,17024,17040,17156,17178,17206,17215,17299,17386,17462,17524],17579],[1,"As a result, we humans naturally pay attention to the negative stuff, something Ella calls 'negativity bias'.","В резултат на това ние, хората, по природа обръщаме внимание на негативните неща – нещо, което Ела нарича „негативно пристрастие“.",[17631,17652,17656,17708,17731,17794,17865,17899,17952,17964,17974,18028,18102,18154,18183,18233,18323],18388],[0,"But while cavemen only knew what was happening in their local area, nowadays we know the bad news from all over the world.","Но докато пещерните хора са знаели само какво става в тяхната околност, днес знаем лошите новини от целия свят.",[18442,18465,18491,18543,18584,18622,18641,18656,18700,18719,18734,18782,18866,18931,18941,18959,18969,19000,19038,19059,19088,19110,19122],19182],[0,"Here's Ella again, discussing this with her friend, TV presenter, Clara Amfo, for BBC Radio 4 programme, Why Do We Do That?","Ето пак Ела, която обсъжда това с приятелката си, телевизионната водеща Клара Амфо, за предаването на BBC Radio 4 „Why Do We Do That?“",[19225,19253,19281,19341,19400,19420,19432,19441,19490,19544,19600,19637,19734,19743,19791,19820,19845,19919,19938,19950,19962,19981],20019],[2,"Before it would be like, I don't know, I'm assuming you'd go to the neighbour's cave and they'd only know... the bad news from... that particular mountain.","Преди щеше да е, не знам, предполагам, че отиваш в пещерата на съседа и той знае само… лошите новини от… онази конкретна планина.",[20125,20176,20184,20195,20216,20253,20259,20268,20275,20284,20316,20329,20343,20354,20362,20397,20472,20488,20503,20525,20568,20581,20609,20647,20665,20728,20797],20856],[2,"Whereas now, it's like, 'Let me tell you about the really bad information and situation that's going on in some island somewhere...'.","Докато сега е все едно: „Да ти разкажа за наистина лошата информация и ситуация, която се случва на някой остров някъде…“.",[20856,20941,20968,20988,21050,21076,21091,21112,21131,21154,21163,21191,21215,21303,21353,21409,21425,21447,21465,21472,21494,21528],21565],[2,"It's just the good news doesn't make up for it...","Просто добрите новини не компенсират това…",[21585,21619,21682,21700,21724,21750,21777,21801,21814,21841],21879],[3,"It really doesn't, and I think trauma's romanticised, really.","Наистина не компенсират, и мисля, че травмата наистина се романтизира.",[21888,21910,21933,21979,22029,22038,22071,22108,22209],22270],[3,"'What doesn't kill you makes you stronger', 'this is a test'.","„Каквото не те убива, те прави по-силен“, „това е изпитание“.",[22305,22316,22342,22362,22377,22400,22410,22581,22601,22613,22621],22694],[3,"I think we're conditioned to believe that negative experiences shape us more than joyous ones.","Мисля, че сме приучени да вярваме, че негативните преживявания ни оформят повече от радостните.",[22723,22730,22755,22835,22892,22905,22931,22942,22988,23056,23094,23109,23125,23142,23188],23235],[1,"Reading bad news from around the world can depress us, and Ella thinks that the little good news we do hear doesn't make up for the depressing news.","Четенето на лоши новини от целия свят може да ни потисне, а Ела смята, че малкото добри новини, които чуваме, не компенсират потискащите.",[23317,23354,23386,23425,23443,23471,23477,23516,23543,23592,23642,23658,23685,23729,23758,23775,23810,23833,23869,23891,23922,23983,24017,24048,24066,24088,24099,24154],24191],[1,"To make up for something means to compensate for something bad with something good.","„To make up for something“ значи да компенсираш нещо лошо с нещо добро.",[24239,24259,24293,24315,24327,24373,24407,24419,24502,24512,24548,24609,24632,24681],24719],[0,"Good news is hard to find.","Добрите новини са трудни за намиране.",[24762,24781,24822,24839,24866,24875],24934],[0,"In fact, Clara thinks society has romanticised bad, traumatic news.","Всъщност Клара смята, че обществото е романтизирало лошите, травмиращи новини.",[24934,24950,25026,25059,25091,25150,25182,25288,25331,25409],25457],[0,"If you romanticise something, you talk about it in a way that makes it sound better than it really is.","Ако „romanticise“ нещо, говориш за него така, че да звучи по-добре, отколкото наистина е.",[25500,25510,25526,25606,25681,25694,25725,25761,25775,25788,25794,25824,25840,25871,25881,25940,25974,25989,26000,26040],26087],[0,"Connected to this is the saying, 'What doesn't kill you makes you stronger', meaning that by going through difficult experiences in life, people build up strength and resilience for the future.","С това е свързана поговорката „Каквото не те убива, те прави по-силен“, която значи, че като преминават през трудни преживявания в живота, хората натрупват сила и устойчивост за бъдещето.",[26135,26194,26208,26241,26256,26268,26332,26350,26385,26407,26440,26475,26486,26589,26630,26648,26662,26698,26724,26776,26856,26865,26933,26970,26997,27009,27066,27083,27144,27151,27159],27211],[1,"Maybe it's best to stop doomscrolling altogether, but with so much bad news pouring into our mobile phones every day, it's not easy.","Може би е най-добре да спрем изцяло с „doomscrolling“, но при толкова много лоши новини, които се изсипват в телефоните ни всеки ден, не е лесно.",[27240,27271,27287,27322,27329,27380,27461,27583,27608,27624,27653,27682,27715,27751,27794,27823,27840,27880,27922,27941,27983,28000,28026],28065],[0,"OK, it's time to reveal the answer to my question, Neil.","Добре, време е да разкрия отговора на моя въпрос, Нийл.",[28122,28166,28180,28206,28218,28247,28258,28284,28299,28311,28355],28388],[0,"I asked you what news agency, Reuters, considers the top news story of 2023 so far.","Попитах те коя смята новинарската агенция „Ройтерс“ за водеща новина на 2023 г. досега.",[28445,28460,28502,28522,28553,28584,28647,28712,28771,28782,28827,28850,28892,28902,28997,29020],29063],[1,"And I guessed it was b) inflation.","А аз предположих, че е б) инфлацията.",[29078,29095,29108,29145,29153,29174,29211],29281],[0,"Which was... the correct answer, although there's still plenty of time for 2023 to bring us more doom, hopefully along with a little positivity too.","Което беше… верният отговор, макар че има още много време 2023 г. да ни донесе още обреченост, надявам се заедно с малко позитивност.",[29315,29334,29385,29394,29434,29511,29558,29579,29606,29655,29662,29700,29712,29821,29833,29856,29869,29893,29972,30024,30053,30071,30093,30146,30218],30253],[0,"OK, let's recap the vocabulary we've learned from this programme about doomscrolling - spending lots of time reading bad news stories on your phone.","Добре, нека преговорим думите, които научихме от това предаване за „doomscrolling“ – прекарване на много време в четене на лоши новини на телефона.",[30325,30367,30393,30434,30444,30512,30528,30566,30588,30605,30654,30699,30699,30812,30862,30898,30909,30953,30989,31017,31036,31081,31092,31104],31160],[1,"Feeling ick is American slang for feeling sick, often because of something disgusting or disturbing.","„Feeling ick“ е американски жаргон за това да ти е лошо, често заради нещо отвратително или тревожно.",[31185,31237,31271,31297,31344,31388,31414,31446,31497,31566,31596,31604,31640,31706,31728],31790],[0,"When something is on tap, it's easily available so that you can have of much of it as you want.","Когато нещо е „on tap“, то е лесно достъпно, така че можеш да имаш колкото искаш от него.",[31825,31843,31886,31904,31936,31989,32015,32062,32121,32137,32155,32162,32180,32205,32231,32267,32275,32289,32312,32322],32370],[1,"The phrasal verb to make up for something means to compensate for something bad with something good.","Фразовият глагол „to make up for something“ значи да компенсираш нещо лошо с нещо добро.",[32385,32395,32445,32483,32503,32535,32554,32565,32613,32644,32665,32747,32760,32812,32869,32892,32939],32978],[0,"When we romanticise something, we make it sound better than it is.","Когато „romanticise“ нещо, караме го да звучи по-добре, отколкото е.",[33022,33047,33071,33152,33198,33209,33232,33240,33269,33303,33319,33331],33375],[1,"And finally, the saying 'what doesn't kill you makes you stronger' means that by going through difficult life experiences, people build up strength for the future.","И накрая, поговорката „what doesn't kill you makes you stronger“ значи, че като преминават през трудни житейски преживявания, хората натрупват сила за бъдещето.",[33419,33446,33538,33546,33594,33619,33654,33681,33706,33738,33745,33833,33862,33884,33909,33959,33996,34056,34085,34171,34212,34239,34254,34320,34334,34344],34394],[0,"Once again our six minutes are up, but if doomscrolling's not for you, remember you can find lots of positive news stories to build your vocabulary here at 6 Minute English.","Отново шестте ни минути изтекоха, но ако „doomscrolling“ не е за вас, помнете, че тук, в 6 Minute English, ще намерите много позитивни истории, с които да обогатите речника си.",[34438,34462,34500,34512,34541,34572,34592,34614,34657,34679,34762,34785,34796,34870,34911,34925,34948,34986,35033,35042,35094,35116,35156,35173,35202,35213,35319,35336,35344,35372,35398],35441],[1,"Don't forget that there is more to BBC Learning English than 6 Minute English.","Не забравяйте, че BBC Learning English е нещо повече от 6 Minute English.",[35458,35488,35531,35547,35571,35588,35613,35627,35688,35724,35759,35785,35819,35850],35899],[1,"Why not try to improve your vocabulary through the language in news headlines.","Защо не опитате да подобрите речника си чрез езика на заглавията в новините?",[35900,35959,35980,36012,36027,36071,36086,36169,36194,36202,36256,36272,36318],36383],[1,"Try the News Review video on our website or download the podcast.","Пробвайте видеото News Review на нашия сайт или свалете подкаста.",[36409,36438,36451,36492,36524,36567,36586,36599,36655,36681,36741,36747],36816],[0,"But that's bye for now!","Но засега чао!",[36835,36846,36866,36882,36896],36922],[1,"Bye!","Чао!",[36939],36976]],"v":[["doomscrolling","безкрайно четене на лоши новини",3],["feel ick","призлява ми, гади ми се",6],["on tap","лесно достъпен, „на кран“",23],["make up for","компенсирам",35],["romanticise","романтизирам, разкрасявам",43],["what doesn't kill you makes you stronger","каквото не те убива, те прави по-силен",37],["negativity bias","негативно пристрастие",30],["survival","оцеляване",29]],"g":[["admit",5,3,1],["regardless",7,14,1],["compelled",9,9,1],["non-stop",12,13,1],["inflation",15,4,1],["evolution",19,10,1],["on tap",23,7,2],["survival",29,14,1],["negativity bias",30,15,2],["make up for",35,6,3],["romanticised",36,7,1],["resilience",44,27,1]],"q":[["What is doomscrolling?","Какво е „doomscrolling“?","spending a lot of time reading negative news on a screen","writing bad news","playing games on your phone",4],["Who doomscrolls, according to the research?","Кой прави „doomscrolling“ според изследването?","people all over the world","only young people","only Americans",7],["What was the top global news story of 2023, according to Reuters?","Коя беше водещата световна новина за 2023 г. според „Ройтерс“?","increasing prices and inflation","the war in Ukraine","Prince Harry's autobiography",49],["Why do humans naturally pay attention to negative things?","Защо хората по природа обръщат внимание на негативните неща?","knowing the dangers was vital for survival","because we are sad","because of television",29],["What did cavemen know about?","За какво са знаели пещерните хора?","only what was happening in their local area","news from all over the world","nothing at all",31],["What does 'make up for' mean?","Какво значи „make up for“?","compensate for something bad with something good","invent a story","put on make-up",40]]},"ragebait":{"ser":"6 Minute English","icon":"😡","bg":"Съдържание, което ни ядосва","t":"Rage bait","a":"ree/audio/ragebait.mp3","sp":["Phil","Beth","Andrea Jones","Megan Lawton","Dr William Brady"],"L":[[0,"Hello, this is 6 Minute English from BBC Learning English, I'm Phil.","Здравейте, това е 6 Minute English от BBC Learning English, аз съм Фил.",[0,79,88,94,133,184,235,283,347,401,467,483],519],[1,"And I'm Beth.","А аз съм Бет.",[526,538,881],913],[0,"If you use the internet, and nearly everyone does, you've probably read headlines like this: You won't believe what plastic surgery this celebrity has had done!","Ако използвате интернет, а почти всеки го прави, вероятно сте чели заглавия като това: „Няма да повярвате каква пластична операция си е направила тази знаменитост!“",[914,931,938,965,971,1014,1025,1043,1094,1119,1150,1185,1206,1243,1417,1433,1548,1574,1628,1688,1830,1862,1911,2008,2076,2099],2127],[0,"Known as clickbait, headlines like these are used to grab your attention and make you read more.","Известни като „clickbait“ (примамка за кликове), такива заглавия се използват, за да грабнат вниманието ви и да ви накарат да четете още.",[2128,2157,2208,2267,2339,2370,2457,2805,2836,2845,2896,2918,3020,3031,3055,3073,3109],3125],[1,"But now, a new trend called rage bait is spreading across social media.","Но сега нова тенденция, наречена „rage bait“ (примамка за гняв), се разпространява в социалните мрежи.",[3125,3191,3227,3242,3278,3320,3362,3397,3441,3456,3503,3541,3587],3630],[1,"Rage bait is online content designed to make you angry or outraged.","„Rage bait“ е онлайн съдържание, създадено да ви ядоса или възмути.",[3674,3705,3738,3759,3814,3877,3934,3945,3980,3998,4063,4095],4170],[1,"In this programme, we'll explore the trend of rage-baiting, and, as usual, we'll learn some useful new vocabulary, all of which you can find on our website, bbclearningenglish.com.","В това предаване ще разгледаме тенденцията „rage-baiting“ и както обикновено ще научим някои полезни нови думи, които можете да намерите на нашия сайт, bbclearningenglish.com.",[4203,4216,4231,4277,4298,4355,4366,4425,4441,4527,4561,4592,4634,4662,4688,4711,4762,4791,4895,4909,4921,4952,4969,4985,5016,5027,5042,5116],5312],[0,"Great, but first it's time for my question, Beth, which is about the two terms we've been using: 'clickbait' and 'rage bait'.","Чудесно, но първо е време за моя въпрос, Бет, който е за двата термина, които използваме: „clickbait“ и „rage bait“.",[5334,5412,5446,5499,5525,5549,5560,5577,5630,5714,5731,5741,5786,5796,5838,5880,5894,5909,5981,6059,6111,6160],6200],[0,"Both contain the word, 'bait', but what is its actual meaning?","И двата съдържат думата „bait“, но какво всъщност означава тя?",[6259,6293,6352,6359,6423,6517,6534,6584,6603,6619,6672],6717],[0,"Is bait: a) a strong feeling of anger?","„Bait“ дали е: а) силно чувство на гняв?",[6742,6770,6858,6928,6938,7005,7055,7069],7128],[0,"b) food put on a hook to catch fish or animals?","б) храна, сложена на кука, за да се хване риба или животно?",[7195,7256,7302,7322,7336,7339,7375,7386,7419,7453,7466],7522],[0,"c) a piece of computer software?","в) компютърна програма?",[7566,7612,7620,7647,7653,7697],7742],[1,"I am fairly confident that it is b) - food put on a hook.","Доста съм уверена, че е б) – храна, сложена на кука.",[7775,7852,7872,7922,7973,7990,8006,8025,8025,8077,8106,8135,8145,8151],8192],[0,"OK. Well, we'll find out the correct answer later in the programme.","Добре. Ще разберем верния отговор по-късно в предаването.",[8250,8268,8285,8303,8346,8362,8371,8411,8498,8534,8555,8562],8617],[0,"Here's how rage bait works: a creator posts a provocative piece of content online, a message maybe, or a video.","Ето как работи „rage bait“: създател публикува провокативно съдържание онлайн – може би съобщение или видео.",[8705,8764,8786,8840,8869,8970,8977,9028,9081,9086,9151,9178,9188,9238,9309,9318,9362,9404,9426,9429],9476],[0,"People see it, feel outraged, and comment angrily.","Хората го виждат, възмущават се и коментират ядосано.",[9524,9555,9590,9657,9695,9816,9832,9889],9949],[0,"Others see it, like it and share it around.","Други го виждат, харесват го и го споделят.",[10025,10057,10085,10121,10150,10167,10179,10217,10229],10281],[0,"Either way, the content creates interest, increases internet traffic and makes money for the creator.","Така или иначе съдържанието предизвиква интерес, увеличава трафика в интернет и носи пари на създателя.",[10340,10378,10420,10446,10505,10573,10651,10712,10764,10819,10832,10860,10898,10910,10920],10974],[0,"Here's marketing strategist, Andrea Jones, explaining more to Megan Lawton, presenter of BBC World Service programme, Business Daily:","Ето как маркетинговият стратег Андреа Джоунс обяснява повече на Меган Лотън, водеща на предаването на BBC World Service „Business Daily“:",[11046,11080,11142,11208,11255,11313,11370,11390,11403,11440,11515,11561,11575,11626,11670,11714,11790,11828],11865],[2,"The more content they create, the more engagement they get, the more that they get paid.","Колкото повече съдържание създават, толкова повече ангажираност получават, толкова повече им плащат.",[11945,11952,11969,12005,12013,12061,12067,12092,12141,12152,12177,12184,12220,12234,12245,12263],12308],[2,"And so they will do anything... some creators will do anything to get more views because the more views they get, the more that they get paid, even if, even if, those views are negative or inciting rage and anger in people.","И затова ще направят всичко… някои създатели ще направят всичко, за да получат повече гледания, защото колкото повече гледания получат, толкова повече им плащат, дори ако, дори ако тези гледания са негативни или разпалват ярост и гняв у хората.",[12327,12350,12391,12411,12430,12486,12541,12558,12594,12602,12617,12694,12720,12755,12783,12816,12838,12845,12868,12894,12906,12932,12941,12975,12988,13001,13016,13097,13126,13156,13181,13194,13231,13304,13366,13432,13488,13566,13594,13606,13642,13658],13709],[3,"Andrea, how is rage bait different to clickbait or other online tactics? [...]","Андреа, с какво „rage bait“ се различава от „clickbait“ или други онлайн тактики?",[13710,13741,13825,13841,13881,13907,13957,13973,14056,14097,14116,14170,14170],14228],[2,"As a marketer, I'm always, you know, coaching my clients and talking to them about using hooks in their marketing, right?","Като маркетолог аз винаги, знаете, обучавам клиентите си и им говоря за използването на „куки“ в маркетинга им, нали?",[14228,14253,14257,14306,14322,14391,14406,14426,14466,14478,14525,14534,14569,14578,14594,14616,14648,14695,14708,14719,14760],14789],[2,"And I think the difference between a hook and rage bait or even its long-lost cousin, clickbait content...","И мисля, че разликата между една „кука“ и „rage bait“ или дори неговия отдавна изгубен братовчед – „clickbait“ съдържанието…",[14812,14825,14829,14848,14856,14902,14935,14944,15038,15062,15097,15126,15138,15194,15250,15304,15342,15392],15448],[2,"When we think about a hook, to me a hook accurately reflects what's in that piece of content and it comes from a place of trust, whereas rage-baiting content is designed to be manipulative.","Когато мислим за „кука“, за мен „куката“ точно отразява какво има в съдържанието и идва от доверие, докато „rage-baiting“ съдържанието е създадено да манипулира.",[15492,15503,15517,15538,15557,15563,15601,15619,15649,15659,15697,15778,15840,15866,15907,15947,15978,15988,16080,16099,16109,16144,16162,16168,16224,16285,16383,16431,16499,16561,16584,16631,16640,16654],16740],[1,"Andrea says the more reaction a post gets, the more money the creator makes, even if the reactions are hateful.","Андреа казва, че колкото повече реакции получава една публикация, толкова повече пари изкарва създателят, дори ако реакциите са изпълнени с омраза.",[16829,16871,16915,16950,17001,17066,17073,17108,17157,17186,17240,17290,17300,17358,17434,17469,17489,17500,17560,17581],17635],[1,"She uses the structure, the more one thing happens, the more something else happens, to show that as one thing happens repeatedly, so another thing increases as a result.","Тя използва конструкцията „the more… the more…“ (колкото повече… толкова повече…), за да покаже, че когато едно нещо се случва многократно, друго нещо в резултат се увеличава.",[17685,17704,17747,17754,17839,17856,17922,17941,17959,18039,18057,18119,18157,18185,18269,18279,18307,18338,18362,18389,18409,18459,18562,18569,18597,18629,18717,18744,18747],18804],[1,"For example, the more you practise English, the more you'll improve.","Например: колкото повече упражнявате английския, толкова повече ще се подобрите.",[18835,18847,18925,18937,18981,19000,19059,19126,19138,19175,19197],19263],[0,"It doesn't matter that the content is designed to incite outrage - to encourage unpleasant or violent reactions.","Няма значение, че съдържанието е създадено да „incite outrage“ – да насърчава неприятни или агресивни реакции.",[19276,19286,19318,19361,19379,19389,19437,19449,19495,19505,19554,19554,19640,19656,19700,19777,19794,19835],19901],[0,"That's why Andrea thinks rage bait is worse than clickbait.","Затова Андреа смята, че „rage bait“ е по-лош от „clickbait“.",[19983,20001,20016,20066,20099,20146,20183,20196,20276,20303],20371],[0,"While clickbait is more truthful about its content, rage bait is manipulative, meaning it tries to influence something to its own advantage.","Докато „clickbait“ е по-честен за съдържанието си, „rage bait“ е „manipulative“ – тоест се опитва да повлияе на нещо в своя полза.",[20415,20439,20512,20522,20542,20619,20649,20665,20761,20807,20840,20854,20979,21018,21040,21092,21102,21157,21214,21227,21244,21291],21366],[1,"So, it's not hard to see why many people think rage bait is toxic.","Така че не е трудно да се разбере защо много хора смятат „rage bait“ за токсичен.",[21388,21421,21447,21474,21510,21533,21556,21578,21612,21650,21688,21731,21769,21794],21867],[1,"So, if you're wondering why people react in the first place, listen as Dr William Brady explains the psychology behind rage bait to BBC World Service's, Business Daily:","А ако се чудите защо изобщо хората реагират, чуйте как д-р Уилям Брейди обяснява психологията зад „rage bait“ пред „Business Daily“ на BBC World Service:",[21897,21923,21941,21952,22001,22052,22102,22150,22163,22171,22212,22289,22338,22374,22404,22449,22503,22573,22586,22667,22714,22744,22788,22800,22850,22879,22953,23000],23046],[4,"If you are an influencer and you want to figure out, 'Well, how do I get more eyeballs on my content?' Well, you need to exploit those biases we have in our psychology because that's the content we'll pay more attention to.","Ако сте инфлуенсър и искате да разберете: „Как да привлека повече очи към съдържанието си?“ – трябва да използвате онези пристрастия, които имаме в психологията си, защото това е съдържанието, на което ще обърнем повече внимание.",[23102,23116,23154,23209,23224,23352,23388,23410,23426,23432,23465,23481,23498,23516,23531,23540,23565,23592,23650,23664,23679,23790,23838,23857,23871,23887,23949,23971,24027,24040,24089,24103,24117,24220,24242,24266,24274,24324,24334,24350,24371,24409],24440],[4,"In turn that's the content that algorithms will amplify, which ultimately means more advertising revenue.","А то пък е съдържанието, което алгоритмите ще усилят, което в крайна сметка означава повече приходи от реклами.",[24459,24477,24522,24541,24552,24596,24606,24662,24678,24759,24778,24822,24871,24903,24962],25003],[0,"Influencers want more eyeballs on their content - more people to view their website or social media posts - and use human psychology to do it.","Инфлуенсърите искат повече „eyeballs“ върху съдържанието си – повече хора да гледат сайта или публикациите им в социалните мрежи – и използват човешката психология, за да го постигнат.",[25062,25139,25169,25234,25314,25333,25344,25344,25455,25475,25525,25542,25581,25601,25667,25691,25728,25762,25762,25855,25867,25888,25929,26000,26012,26046],26075],[0,"Psychologically speaking, we all have biases - feelings - which are often unconscious, either for or against a certain idea or group of people.","От психологическа гледна точка всички имаме „biases“ (пристрастия) – чувства, често несъзнателни, за или против дадена идея или група хора.",[26129,26211,26283,26298,26330,26379,26379,26472,26472,26539,26564,26571,26604,26712,26736,26837,26856,26909,26914,26946,27010,27025,27049,27058],27100],[1,"Biases are emotional, and since listening to our emotions has been vital to the evolution of the human species, creators know that provoking our emotions will grab our attention.","Пристрастията са емоционални, а тъй като слушането на емоциите ни е било жизненоважно за еволюцията на човешкия вид, създателите знаят, че провокирането на емоциите ни ще грабне вниманието ни.",[27177,27233,27256,27343,27358,27393,27437,27459,27478,27542,27561,27580,27631,27647,27662,27719,27733,27741,27773,27871,27928,27941,27992,28062,28083,28134,28149,28181,28198],28265],[0,"So, what can be done to combat rage bait?","И така, какво може да се направи срещу „rage bait“?",[28324,28352,28397,28412,28422,28459,28472,28544,28575],28611],[0,"Well, we could all take a moment to think before reacting.","Ами, всички бихме могли да отделим момент да помислим, преди да реагираме.",[28668,28712,28725,28750,28764,28788,28793,28822,28831,28888,28919],28980],[0,"And remember that by sharing something outrageous you might be making things worse, while also making the creator richer.","И да помним, че като споделяме нещо възмутително, може да влошаваме нещата и в същото време да правим създателя по-богат.",[29027,29038,29078,29093,29104,29142,29171,29245,29259,29286,29296,29336,29362,29495,29512,29537,29575,29581,29635],29696],[1,"OK, Phil, let's reveal the answer to your question.","Добре, Фил, да разкрием отговора на твоя въпрос.",[29746,29775,29813,29848,29883,29898,29931,29949,29966],30016],[1,"You asked me what 'bait' is.","Попита ме какво е „bait“.",[30017,30033,30055,30065,30083,30135],30181],[0,"I did. And the correct answer is b) food put on a hook to catch a fish or an animal, and isn't that what you said, Beth?","Да. А верният отговор е б) храна, сложена на кука, за да се хване риба или животно – и не това ли каза ти, Бет?",[30212,30231,30279,30299,30306,30370,30412,30434,30527,30587,30618,30630,30650,30676,30688,30724,30727,30782,30802,30808,30845,30883,30904,30919,30938,30947,30965],30985],[1,"It is, yes.","Да, това казах.",[31019,31031,31056],31093],[0,"Right again! OK, let's recap the vocabulary we've learned in the programme, starting with rage bait, social media content designed to provoke anger, thereby encouraging people to engage with it.","Пак позна! Добре, нека преговорим думите, които научихме в предаването, като започнем с „rage bait“ – съдържание в социалните мрежи, създадено да предизвиква гняв и така да кара хората да взаимодействат с него.",[31124,31151,31209,31325,31362,31429,31443,31506,31533,31579,31600,31607,31694,31744,31783,31847,31919,31959,31991,32044,32100,32108,32151,32220,32271,32354,32393,32419,32458,32476],32499],[1,"The structure, the more... the more... describes the situation when one thing happening repeatedly results in another thing happening too.","Конструкцията „the more… the more…“ описва ситуация, при която нещо, което се случва многократно, води до това да се случва и друго нещо.",[32531,32541,32599,32626,32719,32731,32809,32873,32883,32956,32989,33025,33051,33105,33193,33244,33265,33307,33338,33386],33423],[0,"To incite someone means to encourage them to do or feel something unpleasant or violent.","„To incite someone“ значи да насърчиш някого да направи или почувства нещо неприятно или агресивно.",[33460,33475,33546,33617,33652,33684,33742,33760,33772,33840,33859,33898,33938,34024,34051],34115],[1,"The adjective, manipulative, describes trying to influence or control someone to your own advantage.","Прилагателното „manipulative“ описва опит да влияеш на някого или да го контролираш в своя полза.",[34156,34169,34222,34340,34395,34425,34438,34508,34525,34577,34625,34639,34663,34697],34776],[0,"Eyeballs is an informal word for the number of people viewing a particular website or television programme.","„Eyeballs“ е неформална дума за броя хора, които гледат определен сайт или телевизионно предаване.",[34823,34894,34912,34922,34978,35017,35030,35040,35074,35080,35118,35150,35155,35209,35280,35300,35362],35412],[1,"And finally, biases are feelings, often unconscious, either for or against an idea or a group of people.","И накрая, „biases“ са чувства, често несъзнателни, за или против дадена идея или група хора.",[35448,35462,35544,35606,35625,35709,35749,35862,35892,35938,35967,36019,36034,36096,36117,36119,36147,36159],36203],[1,"Once again, our six minutes are up.","Отново шестте ни минути изтекоха.",[36258,36281,36327,36348,36385,36418,36429],36440],[1,"Goodbye for now!","Засега довиждане!",[36468,36492,36503],36539],[0,"Bye!","Чао!",[36566],36623]],"v":[["rage bait","съдържание, което цели да ни ядоса",4],["the more… the more…","колкото повече… толкова повече…",46],["incite","подстрекавам, разпалвам",28],["manipulative","манипулативен",24],["eyeballs","зрители, гледания",33],["biases","пристрастия",33],["clickbait","примамка за кликове",3],["outraged","възмутен",5]],"g":[["headlines",2,12,1],["clickbait",3,2,1],["attention",3,11,1],["outraged",5,11,1],["provocative",14,9,1],["engagement",19,7,1],["manipulative",24,33,1],["incite",28,9,1],["toxic",31,13,1],["eyeballs",33,17,1],["biases",33,27,1],["outrageous",40,6,1]],"q":[["What is clickbait used for?","За какво се използва „clickbait“?","to grab your attention and make you read more","to sell food","to protect your data",3],["What is rage bait?","Какво е „rage bait“?","online content designed to make you angry","a type of fishing","a computer game",5],["What happens when people share rage bait?","Какво става, когато хората споделят „rage bait“?","it makes money for the creator","the creator loses money","the post is deleted",17],["Why does Andrea Jones think rage bait is worse than clickbait?","Защо Андреа Джоунс смята, че „rage bait“ е по-лош от „clickbait“?","it is manipulative","it is shorter","it is more truthful",29],["What can we do to combat rage bait?","Какво можем да направим срещу „rage bait“?","take a moment to think before reacting","share it more","comment angrily",39],["What does 'bait' mean?","Какво значи „bait“?","food put on a hook to catch fish or animals","a strong feeling of anger","a piece of computer software",43]]},"fraud":{"ser":"6 Minute English","icon":"🕵️","bg":"Измамите в интернет","t":"Online fraud","a":"ree/audio/fraud.mp3","sp":["Neil","Georgina","Rachel Tobac","Charmaine Cozier"],"L":[[0,"Hello. This is 6 Minute English from BBC Learning English.","Здравейте. Това е 6 Minute English от BBC Learning English.",[0,18,44,61,80,98,136,158,208,245],297],[0,"I'm Neil.","Аз съм Нийл.",[328,336],349],[1,"And I'm Georgina.","А аз съм Джорджина.",[350,366,385],438],[0,"Are you good at remembering your computer passwords, Georgina?","Добра ли си в запомнянето на компютърните си пароли, Джорджина?",[439,442,455,471,480,592,808,1112,1407],1461],[1,"Um, not really Neil - I mostly use something easy to remember, like my mother's maiden name or the street where I was born.","Ъъ, не особено, Нийл – най-често използвам нещо лесно за запомняне, като моминското име на майка ми или улицата, на която съм родена.",[1462,1469,1480,1551,1551,1566,1604,1657,1777,1939,1958,1981,2055,2695,2709,2750,2784,2838,2852,2861,2897,2912,2923,2943],2990],[0,"Or the name of your first pet!","Или името на първия ти домашен любимец!",[3059,3075,3082,3109,3117,3134,3170],3209],[0,"Yes, me too - but we should be more careful about online security, Georgina, because of a worrying trend, and the topic of this programme - online fraud.","Да, и аз – но трябва да сме по-внимателни с онлайн сигурността, Джорджина, заради една тревожна тенденция, която е и темата на това предаване – онлайн измамите.",[3209,3238,3256,3256,3314,3330,3345,3367,3381,3403,3455,3481,3521,3577,3644,3682,3692,3695,3759,3806,3841,3853,3892,3904,3920,3920,3997,4042],4087],[1,"Online fraud involves using the internet to trick someone into giving away their money or data.","Онлайн измамата е използване на интернет, за да подмамиш някого да даде парите или данните си.",[4122,4157,4194,4241,4270,4279,4331,4341,4369,4400,4423,4457,4490,4504,4548,4565],4606],[1,"It takes many forms, from deceptive emails which trick us into paying money to the wrong bank account, to the theft of credit card details.","Има много форми – от подвеждащи имейли, които ни подмамват да платим пари по грешна банкова сметка, до кражба на данни от кредитни карти.",[4672,4687,4716,4743,4789,4817,4871,4924,4944,4968,4982,5007,5036,5071,5089,5098,5127,5156,5223,5235,5245,5284,5291,5330,5356],5431],[0,"It's regarded by some as a highly profitable and relatively low-risk crime, so in this programme we'll be finding out why it's so easy for criminals, or fraudsters, to steal our money.","Някои я смятат за много доходоносно и сравнително нискорисково престъпление, затова в това предаване ще разберем защо е толкова лесно за престъпниците, или измамниците, да крадат парите ни.",[5538,5556,5602,5620,5662,5674,5677,5717,5781,5798,5856,5920,5995,6013,6023,6038,6102,6122,6131,6180,6197,6220,6234,6263,6298,6309,6366,6377,6452,6464,6522,6539],6575],[1,"And of course, we'll be learning some related vocabulary along the way.","И, разбира се, по пътя ще научим и думи, свързани с темата.",[6661,6684,6692,6730,6750,6762,6797,6827,6873,6936,6973,6981],7022],[0,"But first, it's time for our quiz question.","Но първо е време за въпроса от викторината.",[7073,7097,7131,7147,7171,7185,7197,7234],7280],[0,"In July 2020, nine British men were arrested for defrauding the Coronavirus Job Retention Scheme - a government fund for workers who've lost their job to Covid-19.","През юли 2020 г. девет британци бяха арестувани за измама със Схемата за запазване на работни места по време на коронавируса – държавен фонд за работници, загубили работата си заради Covid-19.",[7341,7355,7416,7494,7543,7578,7619,7641,7691,7710,7792,7814,7898,7938,7996,7996,8082,8085,8138,8172,8183,8239,8257,8289,8303,8335,8346],8446],[0,"They set up fake companies and applied, fraudulently, for money.","Те създали фалшиви фирми и кандидатствали измамно за пари.",[8501,8512,8541,8553,8592,8664,8700,8744,8825,8841],8880],[0,"But how much money has been claimed in total through the coronavirus job scheme in the UK?","Но колко пари общо са поискани чрез схемата за работни места заради коронавируса във Великобритания?",[8916,8931,8959,8989,9020,9041,9055,9096,9114,9162,9185,9194,9270,9292,9325,9344,9352],9408],[0,"Is it: a) 17 billion pounds?, b) 27 billion pounds?, or, c) 37 billion pounds?","Дали е: а) 17 милиарда паунда, б) 27 милиарда паунда, или в) 37 милиарда паунда?",[9455,9469,9480,9539,9603,9650,9766,9807,9867,9902,9991,10059,10112,10192,10227],10275],[1,"Hmm, it must be a lot, so I'll say a) 17 billion pounds.","Хм, сигурно е много, така че ще кажа а) 17 милиарда паунда.",[10364,10378,10434,10460,10475,10480,10503,10520,10539,10585,10652,10731,10791],10866],[0,"OK, Georgina, we'll find out later.","Добре, Джорджина, ще разберем по-късно.",[10992,11016,11059,11072,11103,11119],11172],[0,"Now, Rachel Tobac, CEO of Social Proof Security, is an expert in cyber crime.","Рейчъл Тобак, главен изпълнителен директор на Social Proof Security, е експерт по киберпрестъпност.",[11219,11241,11285,11357,11423,11438,11484,11512,11582,11589,11600,11652,11660,11697],11734],[0,"She describes herself as an 'ethical fraudster'.","Тя описва себе си като „етичен измамник“.",[11759,11780,11832,11877,11910,11935,11973],12044],[0,"Businesses wanting to combat fraud employ her to hack into their computer systems to find their weak spots.","Фирми, които искат да се борят с измамите, я наемат да проникне в компютърните им системи, за да открие слабите им места.",[12094,12147,12184,12194,12242,12295,12337,12352,12364,12403,12426,12440,12481,12527,12536,12577,12592,12617],12670],[1,"Here, Rachel explains to BBC World Service programme, The Inquiry, how getting people's information is the key to online fraud:","Ето как Рейчъл обяснява пред предаването на BBC World Service „The Inquiry“, че събирането на информация за хората е ключът към онлайн измамите:",[12756,12792,12831,12888,12897,12938,12968,13006,13056,13063,13159,13178,13212,13252,13316,13334,13344,13391,13402,13447],13488],[2,"The reason why we're able to do that, from an attacker mindset, is because we use what's called OSINT - open source intelligence.","Причината да можем да го направим, от гледна точка на нападателя, е, че използваме т.нар. OSINT – разузнаване от открити източници.",[13490,13628,13666,13687,13697,13722,13729,13751,13778,13793,13800,13850,13934,13946,13984,13994,14029,14047,14116,14116,14188,14222,14256],14334],[2,"We look up everything about you.","Търсим всичко за вас.",[14360,14375,14394,14419,14481,14519],14537],[2,"We can figure out who your assistant is, who your accountant is on LinkedIn.","Можем да разберем кой е асистентът ви, кой е счетоводителят ви в LinkedIn.",[14553,14565,14578,14606,14628,14641,14654,14700,14731,14741,14760,14800,14821,14835],14901],[2,"We know what emails you use from screen shots that you've put on your Instagram...","Знаем какви имейли използвате от екранни снимки, които сте сложили в Instagram…",[14925,14935,14953,14966,15012,15025,15071,15116,15156,15200,15216,15228,15268,15291,15306],15364],[0,"Rachel looks at fraud from a criminal's mindset - someone's way of thinking and the general attitudes and opinions they have about something.","Рейчъл гледа на измамите през „mindset“-а на престъпника – начина на мислене и общите нагласи и мнения на някого за нещо.",[15450,15490,15519,15525,15568,15584,15588,15641,15641,15734,15774,15799,15806,15869,15881,15889,15930,15994,16003,16062,16072,16097,16124],16171],[1,"From a fraudster's perspective, the most valuable thing is intelligence - secret information about a government or country, or in this case a person, such as the information people unwittingly post on social media.","От гледна точка на измамника най-ценното нещо е „intelligence“ – тайна информация за правителство или държава, или в случая за човек, като например информацията, която хората несъзнателно публикуват в социалните мрежи.",[16250,16272,16275,16337,16408,16416,16438,16478,16513,16527,16527,16640,16681,16744,16786,16794,16840,16853,16927,16944,16956,16978,17006,17019,17109,17143,17153,17166,17222,17258,17321,17361,17378,17418],17464],[0,"Fraudsters use this intelligence to build up a picture of someone's online activity.","Измамниците използват тази информация, за да си изградят картина на онлайн активността на някого.",[17533,17600,17631,17650,17716,17725,17753,17766,17769,17811,17828,17884,17940],18009],[1,"And as BBC World Service The Inquiry presenter, Charmaine Cozier, explains, there are many ways of doing this:","И както обяснява водещата на „The Inquiry“ по BBC World Service Шармейн Козиър, има много начини да се направи това:",[18055,18086,18109,18147,18169,18206,18219,18272,18312,18367,18415,18509,18528,18544,18572,18608,18622,18652],18694],[3,"Fraudsters have thousands of cover stories but the end goal is always the same - to trick people out of cash or possessions.","Измамниците имат хиляди прикрития, но крайната цел винаги е една и съща – да измамят хората за пари или вещи.",[18775,18844,18856,18927,18937,18969,19031,19047,19059,19085,19122,19144,19188,19197,19197,19288,19297,19334,19366,19385,19394,19441,19462],19553],[3,"Rachel says they have options for how to do that.","Рейчъл казва, че имат различни възможности как да го направят.",[19610,19644,19674,19685,19709,19766,19772,19794,19809,19831],19881],[3,"Login details stolen during a data breach from one company, often using software or viruses called malware, are used to infiltrate customer accounts at another.","Данни за вход, откраднати при изтичане на данни от една фирма, често чрез софтуер или вируси, наречени зловреден софтуер, се използват, за да се проникне в клиентски профили в друга.",[19916,19953,19997,20038,20066,20072,20109,20147,20170,20188,20282,20313,20350,20400,20412,20475,20494,20591,20598,20632,20641,20719,20766,20812,20841],20891],[0,"To access people's data, fraudsters use cover stories - false stories told in order to hide the truth.","За да получат достъп до данните на хората, измамниците използват „cover stories“ – лъжливи истории, разказани, за да скрият истината.",[20929,20953,21000,21044,21088,21164,21182,21216,21216,21282,21314,21362,21397,21413,21429,21441,21475,21481],21531],[0,"For example, they may pretend to be calling from your bank or credit card company.","Например може да се преструват, че се обаждат от банката ви или от компанията за кредитни карти.",[21558,21572,21628,21641,21662,21704,21712,21723,21764,21781,21803,21844,21856,21889,21917],21962],[1,"If people believe these cover stories and share personal data, this can result in a data breach - an occasion when private information can be seen by people who should not be able to see it.","Ако хората повярват на тези прикрития и споделят лични данни, това може да доведе до „data breach“ – случай, когато лична информация може да бъде видяна от хора, които не би трябвало да я виждат.",[22025,22035,22069,22109,22131,22153,22197,22214,22237,22287,22362,22382,22394,22441,22456,22467,22506,22506,22556,22595,22658,22677,22718,22782,22803,22816,22844,22861,22899,22914,22939,22967,22977,23004,23017,23047],23075],[0,"Malware - computer software and viruses that are designed to damage the way a computer works - can also be used to gain login details and passwords...","Зловредният софтуер – компютърни програми и вируси, създадени да повредят начина, по който работи компютърът – също може да се използва за получаване на данни за вход и пароли…",[23144,23144,23226,23265,23314,23327,23389,23402,23408,23460,23468,23518,23527,23546,23549,23596,23596,23677,23694,23723,23739,23772,23781,23817,23855,23913,23925],24001],[1,"...data which is then used to infiltrate other online accounts - secretly enter a place, group or organisation in order to spy on it or influence it.","…данни, които после се използват, за да се „infiltrate“ други онлайн профили – тайно да се проникне в място, група или организация, за да се шпионира или да се влияе на нея.",[24053,24091,24113,24126,24147,24171,24178,24238,24260,24304,24304,24390,24450,24479,24493,24540,24577,24593,24682,24701,24728,24742,24771,24786,24811,24845,24901],24938],[0,"Modern fraudsters are so devious at collecting online information that many victims only realise what's happened after their bank accounts have been emptied.","Съвременните измамници са толкова коварни в събирането на онлайн информация, че много жертви разбират какво е станало чак след като банковите им сметки са били опразнени.",[24999,25031,25092,25095,25120,25178,25185,25232,25269,25329,25341,25371,25433,25458,25516,25533,25570,25613,25631,25659,25700,25712,25726],25769],[1,"Which I guess was the mindset behind those British fraudsters you mentioned earlier, Neil.","Което предполагам е бил и начинът на мислене на онези британски измамници, които спомена по-рано, Нийл.",[25802,25825,25837,25863,25875,25890,25940,25978,26006,26048,26103,26120,26175,26212],26244],[0,"Ah yes, the nine men who tried to defraud the Coronavirus Jobs Retention Scheme.","А, да, деветимата мъже, които се опитаха да измамят Схемата за запазване на работни места по време на коронавируса.",[26303,26324,26364,26374,26406,26430,26444,26477,26487,26534,26542,26632,26663,26715],26750],[0,"Remember for my quiz question I asked you how much the scheme has paid out in total so far in the UK.","Помниш ли, във въпроса от викторината те попитах колко е изплатила схемата общо досега във Великобритания.",[26795,26838,26851,26864,26896,26950,26963,26993,27006,27030,27056,27064,27103,27123,27153,27181,27190,27232,27256,27289,27296,27306],27357],[1,"I said, a) 17 billion pounds.","Аз казах а) 17 милиарда паунда.",[27415,27433,27465,27507,27594,27647],27720],[0,"Well, in fact it's even more - the correct answer is b) 27 billion pounds.","Ами, всъщност е още повече – верният отговор е б) 27 милиарда паунда.",[27741,27792,27808,27845,27858,27879,27879,27917,27925,27966,28005,28025,28064,28148,28190],28230],[0,"Luckily, the 495 thousand pounds which these fraudsters tried to steal was recovered.","За щастие 495-те хиляди паунда, които тези измамници се опитаха да откраднат, бяха върнати.",[28273,28336,28345,28483,28527,28566,28586,28610,28668,28693,28700,28763,28774],28824],[1,"Even so, Neil, I think I'm going to change my passwords soon!","Въпреки това, Нийл, мисля, че скоро ще сменя паролите си!",[28907,28938,28969,29006,29019,29062,29081,29119,29130,29162,29175,29226],29269],[1,"Better safe than sorry!","По-добре да се пазиш, отколкото после да съжаляваш!",[29304,29332,29362,29375],29423],[0,"Good idea, Georgina.","Добра идея, Джорджина.",[29480,29495,29531],29588],[0,"In this programme, we've been hearing about the rise in online fraud, often committed when fraudsters gain intelligence - secret information about a person posted on the internet.","В това предаване чухме за ръста на онлайн измамите, често извършвани, когато измамниците се сдобият с „intelligence“ – тайна информация за човек, публикувана в интернет.",[29606,29622,29638,29688,29719,29733,29768,29795,29805,29848,29858,29912,30000,30029,30078,30092,30156,30186,30186,30295,30342,30400,30424,30428,30485,30526,30536,30547],30591],[1,"These criminals' mindset - or mentality, is to surreptitiously find information by creating a cover story - a false story someone tells in order to hide the truth.","Начинът на мислене – или манталитетът – на тези престъпници е тайно да намират информация, като създават „cover story“ – лъжлива история, която някой разказва, за да скрие истината.",[30657,30686,30735,30735,30793,30803,30908,30921,30931,31009,31046,31110,31128,31179,31192,31221,31221,31312,31319,31351,31387,31424,31462,31477,31500,31514,31548,31558],31612],[0,"By posing as clerks from your bank, for example, they might be able to access sensitive private information which they should not be able to see - an event sometimes called a data breach.","Като се представят например за служители на банката ви, те може да успеят да получат достъп до чувствителна лична информация, която не би трябвало да виждат – събитие, понякога наричано „data breach“.",[31696,31710,31752,31762,31822,31839,31860,31895,31906,31951,31961,31986,31994,32019,32030,32087,32150,32193,32252,32278,32292,32320,32342,32354,32378,32388,32388,32462,32473,32525,32576,32597,32603,32642],32685],[1,"Another way fraudsters infiltrate - or gain access secretly, without permission - is with the use of malware - computer software and viruses designed to damage the way a computer works.","Друг начин измамниците да „infiltrate“ – тоест да получат достъп тайно, без разрешение – е чрез „malware“ – компютърни програми и вируси, създадени да повредят начина, по който работи компютърът.",[32774,32803,32823,32883,32883,32950,32964,32990,33039,33094,33138,33138,33222,33238,33255,33269,33295,33312,33312,33409,33458,33507,33528,33589,33638,33647,33690,33700,33734,33742,33793],33851],[0,"If you want to find out more about keeping yourself safe from online fraud, search the BBC website using the term, 'cyber security'.","Ако искате да научите повече как да се пазите от онлайн измами, потърсете в сайта на Би Би Си с термина „cyber security“.",[33911,33931,33944,33961,33967,34000,34017,34052,34083,34114,34156,34194,34211,34255,34313,34350,34356,34410,34463,34494,34500,34555,34591],34662],[0,"And if you like topical discussion and want to learn how to use the vocabulary found in headlines, why not check out our News Review podcast?","А ако харесвате актуални дискусии и искате да научите как да използвате думите от заглавията на новините, защо не пробвате нашия подкаст News Review?",[34689,34738,34754,34767,34798,34844,34923,34935,34952,34960,34986,35006,35019,35047,35054,35137,35170,35182,35281,35306,35327,35357,35380,35399,35441,35473],35555],[0,"We also have a free app you can download for Android and iOS.","Имаме и безплатно приложение, което можете да свалите за Android и iOS.",[35599,35610,35636,35654,35658,35701,35744,35752,35769,35824,35839,35887,35933],36007],[1,"And for more trending topics and real-life vocabulary, look no further than 6 Minute English, from BBC Learning English.","А за още актуални теми и думи от реалния живот не търсете повече – 6 Minute English от BBC Learning English.",[36120,36139,36150,36166,36206,36249,36269,36312,36400,36426,36455,36499,36531,36567,36588,36650,36670,36724,36764],36811],[1,"See you next time. Bye!","До следващия път. Чао!",[36843,36862,36870,36892,36933],36981],[0,"Goodbye!","Довиждане!",[37044],37091]],"v":[["mindset","начин на мислене",22],["intelligence","тайна информация",22],["cover story","лъжлива история, прикритие",49],["data breach","изтичане на данни",32],["malware","зловреден софтуер",32],["infiltrate","прониквам тайно",32],["fraudster","измамник",19],["passwords","пароли",3]],"g":[["passwords",3,7,1],["online security",6,11,2],["fraud",6,27,1],["deceptive",8,5,1],["fraudsters",9,27,1],["arrested",12,7,1],["weak spots",20,16,2],["mindset",22,11,1],["intelligence",22,22,1],["cover stories",30,4,2],["data breach",32,5,2],["malware",32,16,1]],"q":[["What does Georgina use for her passwords?","Какво използва Джорджина за паролите си?","something easy to remember, like her mother's maiden name","long random numbers","her phone number",4],["What is online fraud?","Какво е онлайн измамата?","using the internet to trick someone into giving away money or data","selling things online","playing games online",7],["What does Rachel Tobac do?","Какво прави Рейчъл Тобак?","businesses employ her to hack their systems and find weak spots","she steals money","she writes news",20],["How do fraudsters access people's data?","Как измамниците получават достъп до данните на хората?","they use cover stories, like pretending to call from your bank","they ask the police","they buy it in shops",34],["How much money did the coronavirus job scheme pay out?","Колко пари е изплатила схемата за работни места?","27 billion pounds","17 billion pounds","37 billion pounds",43],["What will Georgina do soon?","Какво ще направи скоро Джорджина?","change her passwords","close her bank account","buy a new computer",45]]},"freelance":{"ser":"6 Minute English","icon":"💻","bg":"Работа на свободна практика","t":"Freelancing","a":"ree/audio/freelance.mp3","sp":["Georgina","Rob","Carla Barker","Fiona Thomas"],"L":[[0,"Hello. This is 6 Minute English from BBC Learning English.","Здравейте. Това е 6 Minute English от BBC Learning English.",[0,18,44,61,80,98,136,156,208,245],297],[0,"I'm Georgina.","Аз съм Джорджина.",[328,336],373],[1,"And I'm Rob.","А аз съм Роб.",[374,391,403],428],[0,"Rob, what's the best job you've ever had?","Роб, коя е най-добрата работа, която си имал?",[458,469,524,762,825,878,931,958],1037],[1,"Err well, this one, of course!","Ами, тази, разбира се!",[1038,1050,1380,1478,1489,1614],1637],[1,"It's very creative, with lots of variety.","Много е творческа и има голямо разнообразие.",[1638,1665,1698,1967,2014,2041,2047],2091],[0,"OK, any other reasons?","Добре, други причини?",[2250,2444,2624,2855],2931],[1,"Well yes - it's a permanent job - a staff job - with regular income and a pension.","Ами да – това е постоянна работа – щатна работа – с редовен доход и пенсия.",[2972,2990,2990,3023,3046,3060,3116,3116,3152,3167,3207,3207,3259,3284,3323,3380,3406,3412],3469],[0,"Yes, these things can be important, but have you ever been freelance - by that I mean, working for yourself and selling your skills and services to different businesses?","Да, тези неща може да са важни, но работил ли си някога на свободна практика – тоест да работиш за себе си и да продаваш уменията и услугите си на различни фирми?",[3515,3543,3570,3601,3625,3645,3769,3784,3805,3816,3851,3889,3889,3998,4015,4037,4045,4080,4129,4136,4193,4212,4255,4268,4316,4329,4387,4400,4448],4523],[1,"Well, I worked as a paperboy once - delivering newspapers.","Ами, веднъж работих като момче за вестници – разнасях вестници.",[4569,4612,4622,4670,4683,4691,4762,4762,4819,4870],4953],[1,"But not really - it's a risky way to earn an income.","Но не съвсем – това е рискован начин да изкарваш доход.",[4998,5009,5028,5028,5095,5109,5116,5163,5200,5235,5250,5260],5307],[0,"It can be Rob.","Може да е, Роб.",[5339,5359,5388,5402],5423],[0,"But many people choose to, or have to work as a freelancer to survive.","Но много хора избират или са принудени да работят на свободна практика, за да оцелеят.",[5424,5441,5469,5505,5545,5564,5588,5617,5628,5663,5685,5688,5784,5796],5859],[0,"And that's what we're talking about in this programme.","И точно за това говорим в това предаване.",[5895,5909,5935,5948,5961,6000,6034,6049,6073],6127],[0,"But let's start with a question for you, Rob.","Но да започнем с въпрос към теб, Роб.",[6156,6180,6209,6235,6248,6253,6303,6315,6342],6371],[1,"OK.","Добре.",[6418],6455],[0,"This is about job titles - back in the 19th Century, what kind of job was a drummer?","Въпросът е за наименованията на професии – през 19 век каква работа е била „drummer“?",[6509,6528,6539,6573,6601,6601,6691,6720,6731,6738,6790,6848,6896,6926,6936,6973,7001,7006],7053],[0,"Were they... a) someone who played the drums?","Дали е бил… а) някой, който свири на барабани?",[7084,7101,7137,7195,7241,7254,7309,7320],7383],[0,"b) a travelling salesman?, or, c) a music publicist - who drums up - meaning encourages, support for a band?","б) пътуващ търговец? или в) музикален публицист – който „drums up“, тоест насърчава подкрепата за някоя група?",[7427,7475,7481,7539,7661,7684,7747,7763,7804,7804,7895,7910,7959,7959,8024,8063,8146,8202,8220,8225],8277],[1,"Well, it's got to be someone who plays the drums - that's my kind of job.","Ами, сигурно е някой, който свири на барабани – това е моят вид работа.",[8316,8327,8344,8378,8389,8407,8440,8447,8479,8486,8486,8544,8596,8610,8630,8636],8668],[0,"OK, Rob, we'll find out if that's right at the end of the programme.","Добре, Роб, ще разберем дали е вярно в края на предаването.",[8713,8737,8762,8795,8823,8842,8851,8883,8908,8923,8935,8952,8959,8966],9015],[0,"But let's talk more about work now.","Но нека сега поговорим повече за работата.",[9035,9053,9080,9104,9146,9192,9237],9272],[0,"Long gone are the days of a job for life, where you spent your adult life working your way up the career ladder at the same company.","Отдавна отминаха дните на работата за цял живот, когато прекарваш целия си зрял живот, изкачвайки се по кариерната стълбица в една и съща фирма.",[9313,9338,9370,9384,9393,9434,9444,9456,9479,9497,9574,9590,9604,9640,9657,9692,9720,9771,9781,9821,9849,9860,9900,9929,9952,9962,10011],10076],[1,"Yes, that's right.","Да, точно така.",[10106,10126,10148],10188],[1,"We work in many different ways now because the needs of businesses change frequently and it needs to be agile - changing the size and type of work force in order to meet demand.","Сега работим по много различни начини, защото нуждите на фирмите се променят често и те трябва да са гъвкави – да променят размера и вида на работната си сила, за да отговорят на търсенето.",[10201,10218,10245,10252,10268,10299,10327,10352,10387,10394,10428,10434,10484,10521,10628,10652,10659,10683,10694,10731,10731,10826,10866,10874,10920,10930,10960,10970,10997,11061,11078,11107,11121,11142],11193],[0,"So, people need to adapt and some choose to work for themselves, offering their skills to different businesses as and when they are needed.","Така че хората трябва да се адаптират и някои избират да работят за себе си, предлагайки уменията си на различни фирми, когато и както са нужни.",[11216,11241,11286,11317,11328,11376,11392,11428,11462,11470,11496,11507,11597,11643,11655,11705,11717,11760,11848,11879,11898,11924,11941,11952],12008],[0,"But it can also be a lifestyle choice, as we're about to find out.","Но може да е и избор на начин на живот, както ще разберем след малко.",[12047,12061,12070,12091,12122,12152,12169,12227,12311,12336,12348,12386,12394,12428],12475],[1,"Yes, some people have chosen to become self-employed - working for themselves - but also, because of the recent coronavirus pandemic, some people have been forced into this situation.","Да, някои хора са избрали да станат самонаети – да работят за себе си – но и заради скорошната пандемия от коронавирус някои хора бяха принудени да изпаднат в тази ситуация.",[12502,12523,12550,12578,12591,12639,12648,12683,12683,12788,12822,12834,12834,12941,12954,12994,13053,13068,13078,13116,13181,13266,13285,13315,13326,13345,13390,13406,13419],13501],[1,"Let's hear from Carla Barker, who set up her own business after giving up her regular job.","Да чуем Карла Баркър, която основа собствен бизнес, след като напусна редовната си работа.",[13559,13585,13603,13642,13679,13752,13765,13797,13815,13835,13851,13909,13946,13981,13998,14012,14049],14092],[1,"She told BBC Radio 4's programme You and Yours how she felt...","Тя разказа пред предаването на BBC Radio 4 „You and Yours“ как се е чувствала…",[14140,14161,14201,14257,14288,14324,14377,14396,14405,14474,14494,14513],14560],[2,"You know the idea of giving up a solid, permanent, full-time, paid, comfortable, role is a bit petrifying...","Знаете ли, идеята да се откажеш от стабилна, постоянна, пълна, платена, удобна позиция е малко вцепеняваща…",[14663,14677,14688,14700,14730,14740,14765,14783,14818,14855,14946,15007,15064,15130,15176,15282,15288,15309],15372],[2,"It is super-scary because ... you then have that fear of 'oh my goodness can we do this'?","Супер страшно е, защото… после имаш онзи страх: „Боже мой, ще можем ли да се справим?“",[15417,15435,15454,15539,15539,15627,15639,15655,15671,15692,15738,15809,15813,15824,15910,15928,15938,15956],16000],[2,"You also have things creeping in that say you know like self-sabotage - are you good enough to do this?","Също така се прокрадват неща като самосаботаж – достатъчно добра ли си, за да го направиш?",[16011,16032,16059,16077,16112,16174,16196,16231,16296,16304,16330,16356,16356,16426,16439,16454,16471,16497,16507,16523],16566],[2,"Are people going to want to take me on as a business?","Ще искат ли хората да работят с мен като с бизнес?",[16591,16607,16636,16656,16662,16686,16761,16799,16819,16829,16843,16847],16898],[0,"So, Carla decided to go it alone - an informal way of saying work for herself.","Значи Карла решила да „go it alone“ – неформален начин да се каже, че работи за себе си.",[17024,17062,17100,17148,17157,17182,17201,17201,17282,17295,17347,17380,17388,17429,17467,17477],17540],[0,"She described giving up a full-time job as petrifying - so frightening you can't speak or move.","Тя описа напускането на работа на пълен работен ден като „petrifying“ – толкова страшно, че не можеш да говориш или да мръднеш.",[17585,17601,17660,17691,17716,17723,17783,17812,17839,17839,17978,18013,18072,18083,18119,18161,18178],18228],[0,"She may have been exaggerating slightly but she also said it was 'super-scary'!","Може да е преувеличавала малко, но каза също, че е било „супер страшно“!",[18282,18303,18316,18331,18355,18447,18547,18566,18581,18616,18656,18663,18678],18779],[1,"I guess working for yourself must be scary as you're solely responsible for your own success.","Предполагам, че да работиш за себе си сигурно е страшно, понеже ти единствен отговаряш за собствения си успех.",[18812,18822,18853,18891,18900,18958,18994,19004,19085,19100,19113,19163,19241,19250,19266,19288],19353],[1,"It's no surprise Carla had feelings of self-sabotage - having doubts and fears that stopped her achieving something.","Не е изненада, че Карла е имала чувства на самосаботаж – съмнения и страхове, които са ѝ пречели да постигне нещо.",[19416,19431,19447,19491,19525,19539,19589,19603,19603,19774,19806,19847,19857,19902,19925,19968,19977,20022],20074],[0,"Luckily, she persisted and things went well.","За щастие тя е упорствала и нещата са тръгнали добре.",[20106,20154,20172,20241,20264,20299,20327],20364],[0,"And many other people who have become self-employed or freelance have overcome the fear and discovered the benefits.","И много други хора, които са станали самонаети или на свободна практика, са преодолели страха и са открили ползите.",[20395,20409,20447,20466,20508,20524,20542,20592,20672,20684,20766,20783,20848,20858,20886,20923,20977,20997],21078],[1,"Like Fiona Thomas, who's the author of a book called 'Ditch the 9 to 5 and be your Own Boss'.","Като Фиона Томас, авторка на книга, наречена „Зарежи работата от 9 до 5 и бъди сам шеф“.",[21106,21134,21166,21247,21268,21281,21321,21333,21338,21372,21437,21469,21478,21505,21513,21559,21575,21593,21612,21630],21674],[1,"She also spoke to the BBC's You and Yours programme and explained why she gave up the 9 to 5 - the regular, full-time staff job - and how it helped her...","Тя също говори пред предаването на Би Би Си „You and Yours“ и обясни защо е напуснала работата от 9 до 5 – редовната щатна работа на пълен работен ден – и как това ѝ е помогнало…",[21753,21772,21797,21840,21850,21857,21912,21925,21934,21957,22057,22068,22121,22140,22157,22191,22207,22216,22246,22256,22256,22342,22352,22395,22448,22482,22482,22561,22573,22590,22598,22631],22636],[3,"A kind of combination of wanting some creative fulfilment from a job, compared to the job that I was in before, which was very much customer based and working face-to-face in hospitality.","Някаква комбинация от желание за творческа удовлетвореност от работата в сравнение с предишната ми работа, която беше изцяло свързана с клиенти и работа лице в лице в хотелиерството.",[22637,22762,22787,22794,22860,22881,22995,23017,23142,23212,23259,23266,23325,23356,23366,23375,23397,23408,23411,23424,23435,23473,23493,23505,23525,23549,23611,23668,23689,23722,23788,23853],23937],[3,"But I also wanted the flexibility to accommodate my mental health because I suffer from depression and anxiety and I found working in a rigid schedule and being in front of a lot of people all the time really exacerbated a lot of my symptoms.","Но исках и гъвкавост, за да се съобразя с психичното си здраве, защото страдам от депресия и тревожност и установих, че работата по строг график и постоянното стоене пред много хора наистина засилваше много от симптомите ми.",[23996,24010,24028,24066,24135,24159,24241,24253,24316,24328,24358,24403,24450,24472,24502,24531,24578,24587,24691,24716,24719,24747,24782,24799,24807,24881,24962,24978,25003,25013,25040,25056,25062,25078,25086,25131,25147,25153,25207,25241,25330,25332,25350,25361,25372],25444],[3,"And I also wanted the financial freedom to be able to, over time, increase my income without just having to wait on being promoted or getting a pay rise in traditional employment.","И исках също финансова свобода – с времето да мога да увелича доходите си, без просто да чакам да ме повишат или да ми увеличат заплатата на традиционна работа.",[25497,25550,25563,25590,25627,25657,25710,25754,25768,25781,25804,25875,25899,25924,25994,26004,26049,26191,26210,26235,26248,26269,26294,26318,26386,26393,26413,26422,26445,26482,26506,26547],26594],[0,"So, working for herself gave Fiona a good feeling that she achieved something she wanted to do - it gave her creative fulfilment.","Значи работата за себе си е дала на Фиона хубаво чувство, че е постигнала нещо, което е искала – дала ѝ е творческа удовлетвореност.",[26691,26726,26758,26772,26822,26847,26893,26907,26927,26980,27000,27018,27058,27101,27120,27163,27175,27175,27256,27273,27295,27312,27377],27455],[0,"It also meant she could work more flexibly and that helped her with her mental health because she didn't have to follow a fixed rota of tasks.","Означавало е също, че може да работи по-гъвкаво, а това ѝ е помогнало с психичното здраве, защото не е трябвало да следва фиксиран график от задачи.",[27500,27517,27550,27576,27592,27611,27650,27664,27749,27762,27788,27823,27836,27857,27870,27919,27989,28019,28030,28062,28089,28101,28129,28147,28199,28232,28255],28322],[1,"And it gave her financial freedom - meaning the money she earned was not controlled by someone else, and she didn't have to wait for someone else to give her a pay rise.","И ѝ е дало финансова свобода – тоест парите, които е изкарвала, не са били контролирани от някой друг и не е трябвало да чака някой друг да ѝ увеличи заплатата.",[28363,28389,28397,28425,28438,28514,28514,28623,28665,28675,28701,28723,28760,28781,28815,28865,28880,28916,29000,29014,29023,29042,29057,29070,29096,29107,29141,29160,29170,29199,29207,29233,29261],29302],[1,"Of course, that can be risky too.","Разбира се, и това може да е рисковано.",[29365,29375,29424,29443,29453,29464,29497],29537],[0,"Let's get back to my quiz question now, Rob.","Да се върнем към въпроса от викторината, Роб.",[29569,29601,29621,29645,29653,29667,29704,29744,29766],29797],[0,"Earlier I asked you if you knew what job a drummer used to do back in the 19th Century?","По-рано те попитах дали знаеш каква работа е вършел „drummer“ през 19 век?",[29852,29872,29897,29931,29939,29957,29969,29990,30019,30049,30062,30108,30144,30154,30189,30235,30246,30253,30306],30365],[1,"And obviously, a drummer plays the drums!","А очевидно „drummer“ свири на барабани!",[30401,30431,30500,30509,30554,30606,30613],30669],[0,"Well, you are sort of right but a drummer also used to be an informal way of describing a travelling salesperson - because their job was to drum up business for a company - meaning they tried to increase sales.","Ами, донякъде си прав, но „drummer“ е бил и неформален начин да се опише пътуващ търговец – защото работата му е била да „drum up business“ за някоя фирма, тоест да се опитва да увеличи продажбите.",[30694,30731,30747,30759,30800,30814,30875,30888,30892,30923,30964,30998,31006,31029,31045,31096,31133,31144,31212,31225,31284,31284,31429,31462,31476,31508,31528,31544,31581,31604,31656,31675,31678,31678,31771,31800,31814,31862,31870,31919],31975],[1,"Ahh very interesting, although I know which drummer I would rather be - a freelance drummer in a rock band!","Ааа, много интересно, макар че знам какъв „drummer“ бих предпочел да съм – барабанист на свободна практика в рок група!",[32008,32043,32064,32168,32195,32200,32219,32238,32268,32288,32300,32329,32329,32389,32397,32447,32494,32507,32513,32541],32588],[0,"And freelance is one of the words we've mentioned today.","А „freelance“ е една от думите, които споменахме днес.",[32616,32639,32700,32724,32738,32748,32756,32796,32813,32857],32904],[0,"To freelance means to work for yourself, selling your skills or services to different businesses.","„To freelance“ значи да работиш за себе си, продавайки уменията или услугите си на различни фирми.",[32950,32962,33013,33048,33059,33088,33098,33160,33199,33213,33260,33271,33335,33348,33394],33467],[1,"Becoming self-employed can be petrifying - frightening, so you can't speak or move.","Да станеш самонает може да е „petrifying“ – страшно, така че не можеш да говориш или да мръднеш.",[33500,33538,33628,33656,33680,33680,33784,33868,33880,33887,33916,33951,33962],34003],[1,"And starting out on your own can lead to self-sabotage - having doubts and fears that stop you achieving something.","А когато започнеш сам, това може да доведе до самосаботаж – съмнения и страхове, които ти пречат да постигнеш нещо.",[34075,34087,34133,34153,34163,34181,34207,34222,34246,34264,34264,34412,34442,34477,34488,34544,34563,34597,34612,34656],34712],[0,"But it can also give you fulfilment - a good feeling of achieving something for yourself.","Но може да ти даде и „fulfilment“ – хубаво чувство, че си постигнал нещо за себе си.",[34738,34756,34764,34781,34816,34838,34850,34850,34976,34983,35015,35058,35072,35115,35159,35170],35240],[1,"And having financial freedom means being able to control how you earn and use your money.","А финансовата свобода означава да можеш да контролираш как изкарваш и използваш парите си.",[35275,35294,35321,35380,35468,35499,35530,35559,35568,35625,35642,35669,35705,35723,35750,35767],35807],[0,"That's it for this programme.","Това е за това предаване.",[35836,35863,35881,35890,35913],35967],[0,"We have plenty more 6 Minute English programmes to enjoy on our website at bbclearningenglish.com.","Имаме още много предавания на 6 Minute English на нашия сайт bbclearningenglish.com.",[35994,36006,36036,36086,36106,36138,36162,36200,36261,36273,36312,36337,36356,36419,36456],36640],[0,"And check us out on Facebook, Twitter and Instagram.","И ни намерете във Facebook, Twitter и Instagram.",[36684,36710,36737,36750,36775,36790,36850,36885,36931],36994],[0,"Bye for now.","Засега чао.",[37031,37050,37064],37104],[1,"Goodbye.","Довиждане.",[37121],37169]],"v":[["freelance","на свободна практика",8],["drum up","раздвижвам, увеличавам (продажби)",53],["petrifying","вцепеняващ, ужасяващ",30],["self-sabotage","самосаботаж",32],["fulfilment","удовлетворение",43],["financial freedom","финансова свобода",45],["self-employed","самонает",27],["permanent job","постоянна работа",7]],"g":[["variety",5,6,1],["permanent",7,5,1],["income",7,14,1],["freelance",8,11,1],["risky",10,6,1],["career ladder",22,21,2],["self-employed",27,7,1],["petrifying",30,17,1],["self-sabotage",32,11,1],["fulfilment",43,8,1],["flexibility",44,5,1],["financial freedom",45,5,2]],"q":[["Why does Rob like his job?","Защо Роб харесва работата си?","it's creative, permanent and has a regular income","it's freelance","he works from home",7],["What job did Rob do once as a boy?","Каква работа е вършил Роб веднъж като момче?","a paperboy, delivering newspapers","a drummer","a waiter",9],["What happened to the idea of 'a job for life'?","Какво стана с идеята за „работа за цял живот“?","those days are long gone","it is more popular now","it was never real",22],["How did Carla Barker feel about giving up her job?","Как се е чувствала Карла Баркър, когато е напуснала работата си?","it was petrifying and super-scary","it was easy","she felt bored",30],["Why did Fiona Thomas want flexibility?","Защо Фиона Томас е искала гъвкавост?","to help her mental health","to travel more","to earn less",44],["What was a 'drummer' in the 19th Century?","Какво е бил „drummer“ през 19 век?","a travelling salesperson","a music publicist","a soldier",53]]},"gold":{"ser":"6 Minute English","icon":"🪙","bg":"Защо хората купуват злато?","t":"Why do people buy gold?","a":"ree/audio/gold.mp3","sp":["Georgie","Phil","Suki Cooper","Catherine Schenk","John Reade"],"L":[[0,"Hi Phil.","Здравей, Фил.",[0,30],64],[1,"Hi Georgie. I've got a question for you.","Здравей, Джорджи. Имам въпрос към теб.",[93,124,236,242,255,258,301,325],345],[1,"Do you own anything made of gold?","Притежаваш ли нещо от злато?",[423,442,467,526,629,646,666],714],[0,"Well, at the moment I'm wearing a lot of gold-coloured jewellery, but I'm not sure exactly how much of it is made of gold.","Ами, в момента нося много бижута със златен цвят, но не съм сигурна колко точно от тях са от злато.",[764,860,873,879,913,930,969,978,992,1004,1088,1155,1167,1179,1202,1299,1343,1366,1391,1400,1409,1421,1453,1463],1502],[1,"OK. I don't think I own anything made of gold.","Добре. Мисля, че аз не притежавам нищо от злато.",[1589,1657,1668,1679,1692,1710,1748,1816,1834,1842],1885],[1,"Beyond jewellery and other personal items, gold is bought and sold by investors and banks.","Освен бижутата и другите лични вещи, златото се купува и продава от инвеститори и банки.",[1964,1999,2058,2080,2107,2161,2243,2285,2306,2365,2384,2430,2448,2503,2516],2575],[1,"The price of gold has always gone up and down, but in 2026 it reached its highest ever price.","Цената на златото винаги се е качвала и спадала, но през 2026 г. достигна най-високата си цена в историята.",[2576,2635,2665,2675,2710,2727,2753,2779,2805,2821,2855,2880,2899,3013,3025,3066,3097,3181,3220],3292],[1,"In this episode of 6 Minute English, we'll be talking about how gold became a valuable investment and asking the question, why do people buy gold?","В този епизод на 6 Minute English ще говорим как златото се е превърнало в ценна инвестиция и ще си зададем въпроса: защо хората купуват злато?",[3362,3372,3390,3437,3449,3484,3502,3536,3552,3566,3605,3630,3670,3709,3745,3751,3802,3902,3913,3948,3953,4075,4109,4127,4176,4216],4270],[1,"Let's start with our quiz question, Georgie.","Да започнем с въпроса от нашата викторина, Джорджи.",[4603,4620,4641,4652,4669,4727,4787],4845],[1,"Gold is a metal that's extracted or dug up from under the ground in mines.","Златото е метал, който се добива – изкопава се изпод земята в мини.",[4925,4975,4989,4998,5044,5064,5156,5172,5209,5241,5284,5310,5321,5378,5406],5464],[1,"But how much gold has been extracted from the earth?","Но колко злато е добито от земята досега?",[5521,5631,5660,5702,5764,5784,5802,5924,5953,5970],6005],[1,"Is it: a) over 50,000 tonnes, b) over 100,000 tonnes, or c) over 200,000 tonnes?","Дали е: а) над 50 000 тона, б) над 100 000 тона, или в) над 200 000 тона?",[6070,6088,6138,6222,6289,6388,6531,6622,6650,6761,6866,6880,6972,7044,7248],7294],[0,"Phil, I have absolutely no idea, but I'm going to go with c) 200,000 tonnes.","Фил, нямам абсолютно никаква представа, но ще избера в) 200 000 тона.",[7338,7384,7400,7423,7486,7512,7572,7583,7594,7612,7719,7728,7741,7750,7825],7872],[1,"OK. Well, we'll give you the answer at the end of the programme.","Добре. Ще ти кажем отговора в края на предаването.",[7884,7906,7925,7942,7986,7994,8006,8041,8116,8142,8158,8166,8172],8217],[0,"OK Phil. So, we've been using gold for thousands of years, but why and how did it start?","Добре, Фил. Използваме златото от хиляди години, но защо и как започна това?",[8270,8300,8338,8366,8383,8400,8436,8480,8503,8569,8581,8636,8709,8761,8777,8791,8806,8815],8878],[1,"Well, before money was paper or plastic or just numbers in your bank account, a lot of it was actually gold.","Ами, преди парите да са хартия, пластмаса или просто числа в банковата ти сметка, голяма част от тях всъщност бяха злато.",[8898,8955,8985,9020,9042,9116,9130,9190,9222,9243,9295,9308,9323,9359,9455,9462,9479,9489,9509,9547,9625],9685],[1,"And experts have discovered gold in coins that are thought to have been made in the 6th Century BC.","А експерти са открили злато в монети, които се смята, че са направени през 6 век пр.н.е.",[9706,9734,9792,9810,9893,9982,9998,10052,10069,10073,10112,10122,10142,10187,10230,10260,10266,10307,10327],10404],[1,"So, gold coins were made and they were used because the metal was much easier to carry and trade than things like cattle or timber.","Така че са правели златни монети и са ги използвали, защото металът се пренася и търгува много по-лесно от неща като добитък или дървен материал.",[10462,10473,10512,10557,10580,10645,10658,10666,10679,10751,10799,10815,10856,10903,10925,10954,10964,11012,11028,11069,11087,11105,11118,11173,11191],11235],[0,"OK. But now our money isn't literally made of gold, so why is gold valuable?","Добре. Но сега парите ни не са буквално от злато, така че защо златото е ценно?",[11295,11324,11343,11392,11411,11443,11474,11530,11561,11573,11617,11658,11694,11714,11753],11816],[1,"It's a good question, but even though it isn't money, gold is still a financial asset, and an asset is something valuable that could be sold for money.","Добър въпрос, но макар да не са пари, златото все пак е финансов актив, а активът е нещо ценно, което може да се продаде за пари.",[11836,11847,11850,11864,11920,11991,12011,12022,12034,12062,12161,12208,12222,12275,12280,12361,12433,12444,12456,12500,12512,12562,12625,12652,12661,12667,12692,12703],12742],[1,"And people buy gold in times of crisis because it's thought of as a safe investment.","А хората купуват злато по време на криза, защото се смята за сигурна инвестиция.",[12797,12834,12875,12925,12972,12994,13050,13064,13192,13216,13231,13263,13278,13294,13297,13331],13403],[1,"Let's listen to expert Suki Cooper explaining more to the BBC World Service.","Да чуем как експертът Суки Купър обяснява повече пред BBC World Service.",[13428,13459,13485,13501,13548,13594,13647,13707,13756,13770,13779,13841,13872],13928],[2,"Gold is a safe haven because it's not connected to one particular government or one particular economy or one particular market, so the fact that it's neutral means it's an asset that's perceived to be a store of value over a longer term.","Златото е сигурно убежище, защото не е свързано с едно конкретно правителство, една конкретна икономика или един конкретен пазар, така че това, че е неутрално, означава, че е актив, който се възприема като средство за съхраняване на стойност в по-дългосрочен план.",[14006,14038,14050,14054,14088,14122,14141,14160,14192,14245,14275,14301,14347,14419,14450,14475,14523,14597,14622,14644,14694,14800,14807,14813,14835,14848,14875,14968,14988,15007,15016,15056,15072,15110,15122,15147,15150,15193,15201,15247,15275,15282,15312],15350],[1,"Suki describes gold as a safe haven, and a safe haven means something or somewhere that's protected from harm or danger, or in financial terms, from a fall in value.","Суки описва златото като „safe haven“ – сигурно убежище, а това значи нещо или място, което е защитено от вреда или опасност, или във финансов смисъл – от спад в стойността.",[15366,15412,15500,15548,15560,15566,15613,15673,15688,15693,15725,15763,15794,15850,15862,15953,15969,16062,16089,16131,16147,16248,16275,16285,16334,16375,16403,16409,16460,16479],16528],[0,"Yes, Suki explains that, unlike dollars or pounds for example, gold is not connected to a particular country.","Да, Суки обяснява, че за разлика от доларите или паундите например, златото не е свързано с определена държава.",[16566,16614,16654,16709,16729,16773,16825,16834,16881,16891,16979,17013,17029,17062,17116,17129,17134,17194],17245],[0,"It's neutral.","То е неутрално.",[17269,17287],17335],[1,"And Georgie, because we get gold from mines, there's more or less a fixed amount.","И, Джорджи, понеже взимаме златото от мини, количеството е горе-долу фиксирано.",[17407,17438,17484,17556,17569,17607,17643,17673,17785,17801,17813,17822,17844,17848,17915],17972],[1,"Unlike paper money, you can't just print more, as Catherine Schenk, professor of economic and social history, explains.","За разлика от хартиените пари, не можеш просто да напечаташ още, както обяснява Катрин Шенк, професор по икономическа и социална история.",[17973,18016,18062,18116,18123,18148,18166,18194,18271,18294,18343,18403,18457,18469,18534,18545,18581,18629],18703],[3,"It can't be created and fabricated out of thin air through alchemy, and so this, sort of, controls the supply and sustains an underlying value behind the demand for gold.","То не може да бъде създадено и произведено от нищото чрез алхимия, и така това донякъде контролира предлагането и поддържа една основна стойност зад търсенето на злато.",[18716,18731,18760,18772,18826,18841,18929,18947,18959,18979,18997,19018,19093,19109,19131,19156,19172,19181,19250,19256,19350,19369,19439,19448,19509,19570,19616,19622,19659,19672],19719],[0,"Catherine explains that gold can't be created out of thin air, an expression meaning making something from nothing.","Катрин обяснява, че златото не може да бъде създадено „out of thin air“ – израз, който значи да направиш нещо от нищо.",[19742,19782,19842,19860,19903,19941,19950,20019,20047,20054,20091,20144,20153,20203,20250,20297,20350,20372],20419],[1,"As Catherine says, we don't make gold through alchemy.","Както казва Катрин, ние не правим злато чрез алхимия.",[20441,20481,20531,20589,20622,20660,20697,20742,20775],20833],[1,"Alchemy is an ancient kind of chemistry that attempted to do impossible things, like turn ordinary metals into gold.","Алхимията е древен вид химия, която се е опитвала да прави невъзможни неща, като например да превръща обикновени метали в злато.",[20881,20935,20951,20966,21019,21053,21062,21120,21139,21182,21191,21216,21309,21392,21410,21442,21501,21548,21578],21635],[1,"And because we can't just magically make more gold, when lots of people want to buy gold, the price increases.","И понеже не можем просто магически да направим още злато, когато много хора искат да купят злато, цената се вдига.",[21681,21725,21789,21803,21831,21850,21906,21951,21979,22064,22078,22120,22128,22161,22195,22207,22231,22313,22323,22391],22494],[0,"OK. Understood. Now, Phil, at the start of this programme, you said that gold prices hit an all-time high in early 2026.","Добре. Разбрах. Фил, в началото на предаването каза, че цените на златото достигнаха рекордно високо ниво в началото на 2026 г.",[22556,22612,22753,22769,22800,22812,22819,22856,22862,22877,22945,22961,22991,23016,23046,23100,23127,23142,23205,23239,23278,23296],23411],[0,"So, what's going on?","Е, какво става?",[23451,23463,23486,23516],23544],[1,"Well, we mentioned that the price of gold increases in times of crisis because government banks want to buy more of it.","Ами, споменахме, че цената на златото се вдига по време на криза, защото държавните банки искат да купуват повече от него.",[23606,23626,23661,23721,23735,23745,23795,23816,23856,23933,23948,23979,23987,24086,24162,24198,24234,24276,24289,24316,24367,24378],24396],[1,"And there has been a series of world events that have made government banks want to buy more gold, for example the wars in Ukraine and the Middle East, and in politics too, for example the US imposing tariffs on international products.","А имаше редица световни събития, които накараха държавните банки да искат да купуват повече злато – например войните в Украйна и Близкия изток, а и в политиката – например САЩ, които налагат мита върху международни продукти.",[24444,24458,24467,24495,24521,24527,24628,24660,24691,24733,24755,24767,24785,24823,24855,24886,24894,24917,24941,25036,25047,25095,25105,25147,25164,25279,25294,25300,25328,25391,25406,25416,25478,25510,25525,25564,25578,25631,25688,25738,25755,25808],25869],[1,"But since that peak in January, the price has dropped a bit.","Но след онзи пик през януари цената малко спадна.",[25920,25974,26018,26031,26059,26069,26119,26131,26170,26214,26248,26251],26300],[0,"OK. And does the fall in the price of gold mean that people won't want to invest in it in the future?","Добре. А означава ли спадът в цената на златото, че хората няма да искат да инвестират в него в бъдеще?",[26350,26408,26445,26462,26470,26507,26518,26525,26555,26562,26606,26652,26667,26693,26723,26746,26757,26799,26810,26831,26844,26851],26890],[1,"No. It's likely that the price will go up again.","Не. Вероятно цената пак ще се вдигне.",[26921,27010,27035,27099,27121,27129,27156,27167,27196,27212],27258],[1,"Experts believe that gold will always be an attractive investment during uncertain times.","Експертите смятат, че златото винаги ще бъде привлекателна инвестиция в несигурни времена.",[27350,27396,27429,27443,27478,27518,27552,27566,27574,27637,27709,27737,27784],27835],[1,"Let's hear from market strategist John Reade.","Да чуем пазарния стратег Джон Рийд.",[27922,27953,28017,28047,28094,28182,28225],28274],[4,"So much of the world we live in now is ethereal.","Толкова голяма част от света, в който живеем сега, е ефимерна.",[28322,28347,28372,28386,28392,28419,28438,28460,28474,28507,28550],28621],[4,"It's... it's virtual, it's online, it disappears, whereas gold is something solid, something dependable and, you know, maybe something a little bit old fashioned.","Тя е… тя е виртуална, онлайн е, изчезва, докато златото е нещо твърдо, нещо надеждно и, знаете, може би нещо малко старомодно.",[28623,28681,28695,28756,28770,28831,28845,28927,28957,28988,28996,29081,29168,29216,29331,29398,29407,29424,29454,29519,29552,29576,29592,29608],29656],[4,"And maybe it's a hankering for traditional values rather than what is super modern and super changeable.","И може би това е копнеж по традиционните ценности, а не по това, което е супермодерно и суперпроменливо.",[29656,29666,29693,29707,29716,29781,29825,29894,29949,29983,30001,30024,30033,30067,30110,30125,30214],30270],[0,"John says that much of the modern world is ethereal, meaning it doesn't seem real.","Джон казва, че голяма част от модерния свят е „ethereal“ – тоест не изглежда истински.",[30298,30325,30366,30386,30418,30428,30437,30472,30513,30533,30624,30654,30670,30704,30736],30776],[1,"And in this ethereal world, people have a hankering for something that's solid and real, like gold.","И в този ефимерен свят хората копнеят за нещо твърдо и истинско, като златото.",[30788,30835,30851,30890,30952,31026,31060,31079,31084,31180,31189,31225,31242,31315,31328,31418,31430],31484],[1,"And the expression a hankering for means a strong desire for something.","А изразът „a hankering for“ значи силно желание за нещо.",[31485,31501,31507,31560,31566,31648,31717,31761,31770,31842,31908,31925],31978],[0,"OK. Phil, I think it's time for the answer to your quiz question.","Добре. Фил, мисля, че е време за отговора на въпроса от викторината.",[32014,32047,32086,32098,32123,32143,32174,32186,32202,32242,32262,32284,32310],32358],[1,"OK. Well, I asked how much gold has been mined from the ground to date.","Добре. Питах колко злато е добито от земята досега.",[32396,32440,32497,32513,32581,32602,32652,32736,32749,32777,32830,32853,32861,32920,32942],32994],[0,"I said 200,000 tonnes.","Аз казах 200 000 тона.",[33033,33066,33109,33243],33304],[1,"And that is the correct answer!","И това е верният отговор!",[33338,33361,33400,33416,33425,33452],33495],[1,"OK. Let's recap the vocabulary we learnt in this programme, starting with asset.","Добре. Нека преговорим думите, които научихме в предаването, като започнем с „asset“.",[33540,33604,33633,33680,33692,33750,33766,33801,33818,33835,33886,33954,33985],34051],[1,"And an asset is something of financial value that can be sold for money.","„Asset“ (актив) е нещо с финансова стойност, което може да се продаде за пари.",[34086,34099,34120,34175,34195,34236,34246,34314,34381,34391,34402,34411,34479,34489],34528],[0,"A safe haven is something or somewhere protected from harm or loss.","„Safe haven“ е нещо или място, защитено от вреда или загуба.",[34562,34568,34605,34653,34674,34719,34734,34781,34844,34867,34909,34926],34981],[1,"To make something out of thin air is an expression meaning to make something from nothing.","„To make something out of thin air“ е израз, който значи да направиш нещо от нищо.",[35031,35047,35076,35122,35150,35161,35198,35238,35257,35265,35319,35358,35377,35404,35504,35528],35573],[0,"Alchemy is a kind of ancient chemistry that attempted to do impossible things, like making gold from ordinary metals.","Алхимията е вид древна химия, която се е опитвала да прави невъзможни неща, като да прави злато от обикновени метали.",[35610,35657,35670,35674,35709,35730,35780,35851,35864,35924,35936,35959,36033,36094,36114,36152,36192,36214,36264],36323],[1,"If something is ethereal, it doesn't seem real.","Ако нещо е „ethereal“, то не изглежда истинско.",[36384,36394,36447,36466,36565,36582,36625,36671],36705],[0,"And if you have a hankering for something, you have a strong desire for it.","А ако имаш „a hankering for something“, имаш силно желание за него.",[36758,36789,36812,36826,36851,36855,36913,36924,36975,37000,37027,37038,37094,37141,37169],37190],[1,"Once again, our six minutes are up, and if you have a hankering for more practice, test what you've learned with the worksheet on our website.","Отново шестте ни минути изтекоха, а ако имате силно желание за още упражнения, проверете какво научихте с работния лист на нашия сайт.",[37218,37244,37288,37310,37368,37405,37431,37451,37462,37475,37496,37513,37519,37564,37578,37596,37682,37719,37732,37750,37783,37798,37806,37869,37883,37903],37950],[1,"That's bbclearningenglish.com.","Адресът е bbclearningenglish.com.",[37951,38002],38226],[0,"Thank you for joining us. Goodbye.","Благодарим, че бяхте с нас. Довиждане.",[38253,38275,38282,38292,38329,38362],38419],[1,"Goodbye!","Довиждане!",[38431],38479]],"v":[["asset","актив, нещо ценно",19],["safe haven","сигурно убежище",22],["out of thin air","от нищото",28],["alchemy","алхимия",28],["ethereal","ефимерен, нереален",42],["a hankering for","силно желание за",44],["investment","инвестиция",7],["valuable","ценен",7]],"g":[["jewellery",3,10,1],["investors",5,12,1],["valuable",7,15,1],["extracted",9,5,1],["coins",16,6,1],["asset",19,15,1],["safe haven",22,3,2],["neutral",22,26,1],["out of thin air",28,6,4],["alchemy",28,11,1],["ethereal",42,10,1],["hankering",44,4,1]],"q":[["What happened to the price of gold in 2026?","Какво стана с цената на златото през 2026 г.?","it reached its highest ever price","it fell to zero","it stayed the same",6],["Why were gold coins used in the past?","Защо в миналото са използвали златни монети?","gold was easier to carry and trade than cattle or timber","gold was cheap","people liked the colour",17],["When do people buy gold?","Кога хората купуват злато?","in times of crisis","only at Christmas","when they are bored",20],["Why is gold 'neutral'?","Защо златото е „неутрално“?","it is not connected to a particular country","it has no colour","nobody wants it",24],["Why can't we just make more gold?","Защо не можем просто да направим още злато?","it comes from mines, so the amount is more or less fixed","it is too heavy","banks don't allow it",26],["How much gold has been mined to date?","Колко злато е добито досега?","over 200,000 tonnes","over 50,000 tonnes","over 100,000 tonnes",51]]}}};
/* ===== „Истински разговори" – real BBC Learning English recordings inside „Пътят напред".
   Every recording is a chapter with three lessons: listen + words, fill the gaps, answer questions.
   Each lesson needs 90% from the first try, like the rest of the path. Audio is fetched whole (not streamed)
   so the service worker can keep it for offline use. ===== */
(function(){
  const D=window.__REE;if(!D)return;
  const ORDER=D.order,EP=D.eps,BASE=0x10;   // chapters use path units 16, 17, …
  const STEPS=[['🎧','Слушай и разбери'],['✍️','Попълни празните места'],['❓','Отговори на въпросите']];
  window.__reCodes=()=>{const o=[];ORDER.forEach(id=>{for(let n=1;n<=3;n++)o.push('E:'+id+'-'+n)});return o};
  window.__reHead=u=>{const e=EP[ORDER[u-BASE]];return e?[e.icon,e.bg]:['🎧','Истински разговори']};
  window.__reSmall=u=>{const i=u-BASE,e=EP[ORDER[i]];return 'Истински разговори · глава '+(i+1)+' от '+ORDER.length+(e?' · '+e.ser:'')};
  window.__reLesson=code=>{
    const m=/^E:(\w+)-(\d)$/.exec(code);if(!m||!EP[m[1]])return {code,kind:'listen',items:[]};
    const id=m[1],n=+m[2],e=EP[id],i=ORDER.indexOf(id);
    return {code,icon:STEPS[n-1][0],title:STEPS[n-1][1],sub:e.icon+' '+e.bg+' · нужни са 90%',kind:'listen',real:1,ep:id,step:n,unit:BASE+i,items:null};
  };

  /* ---------- small helpers ---------- */
  const mix=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.random()*(i+1)|0;[a[i],a[j]]=[a[j],a[i]]}return a};
  const fmt=t=>{t=Math.max(0,t||0);return Math.floor(t/60)+':'+String(Math.floor(t%60)).padStart(2,'0')};
  const OPT=()=>{try{if(!S.reOpt||typeof S.reOpt!=='object')S.reOpt={};return S.reOpt}catch(e){return {}}};
  const opt=(k,d)=>{const o=OPT();return k in o?o[k]:d};
  const setOpt=(k,v)=>{OPT()[k]=v;try{save()}catch(e){}};
  const blobs={};   // id -> object URL, kept for the session
  async function getAudio(id){
    if(blobs[id])return blobs[id];
    const r=await fetch(EP[id].a);if(!r.ok)throw new Error('HTTP '+r.status);
    const u=URL.createObjectURL(await r.blob());blobs[id]=u;return u;
  }

  let CSS=false;
  function css(){if(CSS)return;CSS=true;const st=document.createElement('style');st.textContent=`
.rew{display:flex;flex-direction:column;gap:12px;padding-bottom:12px}
.rew .lshead small{display:block}
.rew .lstr{max-height:none}
.rew .lsln{cursor:pointer}
.rew .lsln.guest{background:var(--gold-soft)}
.rew .lsln.guest .lswho{color:var(--gold)}
.rew.notext .lsen{filter:blur(6px);user-select:none}
.rew.notext .lsen.peek{filter:none}
.rew .lsbg{display:none}
.rew.bg .lsbg{display:block}
.rew.nofol .lw.cur{background:none;text-decoration:none}
.relead{margin:0;font-size:14px;color:var(--muted);line-height:1.4}
.redock{gap:6px}
.redock .rejump{font:inherit;font-size:13px;font-weight:700;min-width:44px;min-height:46px;border-radius:12px;border:1px solid var(--line);background:var(--surface);color:var(--ink);cursor:pointer}
.reseek{flex:1;min-width:60px;display:flex;flex-direction:column;gap:2px}
.reseek input{width:100%;accent-color:var(--rose);margin:0}
.reseek span{font-size:11.5px;color:var(--muted);font-variant-numeric:tabular-nums;text-align:center}
.redock .lspm{flex:none;min-width:52px;padding:10px 12px}
.redock .lsspd{flex:none;width:auto;max-width:76px}
.reseek span{white-space:nowrap}
.regap{font:inherit;font-size:inherit;display:inline-block;min-width:4.2em;padding:0 8px;margin:0 1px;border:0;border-bottom:2.5px solid var(--rose);border-radius:6px 6px 0 0;background:var(--rose-soft);color:var(--rose);font-weight:700;cursor:pointer;line-height:1.5}
.regap.ok{background:var(--ok-soft);border-color:var(--ok);color:var(--ok)}
.regap.bad{background:var(--bad-soft);border-color:var(--bad);color:var(--bad)}
.regap.open{outline:2.5px solid var(--rose);outline-offset:2px}
.regap .rewas{text-decoration:line-through;opacity:.7;font-weight:500;margin-right:4px}
.repick{display:flex;flex-direction:column;gap:8px;margin-top:8px;padding:10px;border-radius:12px;background:var(--ground);cursor:default}
.repick .lsopts{flex-direction:row;flex-wrap:wrap}
.repick .lsopt{flex:1 1 40%;text-align:center}
.reqbg{font-size:13.5px;color:var(--muted);font-weight:500}
.rehear{font:inherit;font-size:13.5px;font-weight:700;align-self:flex-start;min-height:38px;padding:6px 12px;border-radius:999px;border:1px solid var(--rose);background:var(--surface);color:var(--rose);cursor:pointer}
.rehear.on{background:var(--rose);color:#fff}
.revw{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.revw b{font-size:17px}
.refoot{display:flex;flex-direction:column;align-items:center;gap:8px;text-align:center;margin:8px 0}
.refoot p{margin:0;color:var(--muted)}
.rewarn{margin:0;font-size:13.5px;background:var(--gold-soft);border-radius:12px;padding:8px 12px}
.resave{font:inherit;font-size:12.5px;font-weight:600;border:0;background:none;color:var(--muted);text-decoration:underline;cursor:pointer;padding:4px;align-self:flex-start}
`;document.head.append(st)}

  /* ---------- one lesson ---------- */
  window.__reRun=function(area,st,L,finish){
    css();
    const id=L.ep,e=EP[id],step=L.step,lines=e.L;
    const root=h('div',{class:'storyw lsw rew'});
    const cls=()=>{root.classList.toggle('notext',step===3&&!opt('txt3',false)||step===1&&!opt('txt',true));
      root.classList.toggle('bg',!!opt('bg',false));root.classList.toggle('nofol',!opt('fol',true))};
    cls();
    /* --- score bookkeeping: first answer of every item counts --- */
    const need=[],got={};
    const info=h('span',{class:'lsupct'});
    const pct=()=>{const k=Object.keys(got);if(!k.length)return null;return Math.round(100*k.filter(x=>got[x]).length/k.length)};
    const foot=h('div',{class:'refoot'});
    function upd(){
      const p=pct(),left=need.filter(k=>!(k in got)).length;
      info.textContent=(p==null?'':'Резултат: '+p+'% · ')+(need.length-left)+' от '+need.length;
      if(need.length&&!left){const ok=need.filter(k=>got[k]).length;
        foot.replaceChildren(h('p',null,`Готово: ${ok} от ${need.length} верни от първия път (${Math.round(100*ok/need.length)}%). За да продължите, трябват поне 90%.`),
          h('button',{type:'button',class:'btn rose huge',onclick:()=>{stop(true);st.first=need.length;st.firstOk=ok;try{save()}catch(e){}finish()}},'Завърши урока →'))}
      else foot.replaceChildren(h('p',null,step===1?'Слушайте записа, после изберете значението на всяка дума. Брои се първият опит.':
        step===2?'Докоснете празно място, чуйте изречението и изберете думата. Брои се първият опит.':'Слушайте и отговорете на всички въпроси. Брои се първият опит.'))}
    const mark=(k,ok)=>{if(k in got)return;got[k]=!!ok;upd()};

    /* --- head --- */
    const ix=ORDER.indexOf(id);
    root.append(h('div',{class:'lesbar lsubar'},h('span',null,STEPS[step-1][0]+' '+STEPS[step-1][1]),info),
      h('div',{class:'lshead'},h('small',null,'Глава '+(ix+1)+' от '+ORDER.length+' · '+e.ser+' · урок '+step+' от 3'),
        h('h3',null,e.icon+' '+e.bg),h('p',null,'„'+e.t+'“')));
    /* --- toggles --- */
    const tg=(key,def,label,title,dis)=>{const b=h('button',{type:'button',class:'lstg','aria-pressed':String(!!opt(key,def)),title,disabled:dis||null},label);
      b.addEventListener('click',()=>{const on=!opt(key,def);setOpt(key,on);b.setAttribute('aria-pressed',String(on));cls();if(key==='fol'&&!on)clearW()});return b};
    root.append(h('div',{class:'lstgs'},
      step===2?null:tg(step===3?'txt3':'txt',step!==3,'Aa Текст','Покажи или скрий английския текст'),
      tg('bg',false,'🇧🇬 Превод','Покажи превода на български'),
      tg('fol',true,'〰 Следене','Подчертава думата, която се чува, и превърта екрана')));
    if(step===1)root.append(h('p',{class:'relead'},'Пуснете записа отдолу. Докоснете изречение, за да го чуете отново. Превода можете да включите с бутона „🇧🇬 Превод“.'));
    if(step===3)root.append(h('p',{class:'relead'},'Този път текстът е скрит – опитайте да разберете само на слух. Можете да го покажете с „Aa Текст“, а всеки въпрос има бутон „▶ Чуй откъса“.'));
    const warn=h('p',{class:'rewarn',hidden:true});root.append(warn);

    /* --- transcript --- */
    const LE=[],TOK=[];   // line elements; per line: array of token spans
    const gapAt={};       // "line:tok" -> gap index (step 2)
    if(step===2)e.g.forEach((g,k)=>{gapAt[g[1]+':'+g[2]]=k});
    const gapEls=[];
    const tr=h('div',{class:'lstr dlg'});
    lines.forEach((l,i)=>{
      const sp=e.sp[l[0]],side=l[0]===1?' me':l[0]>1?' guest':'';
      const pb=h('button',{type:'button',class:'lspb','aria-label':'Чуй изречението'},'▶');
      const en=h('div',{class:'lsen',lang:'en'});const toks=l[1].split(' ');const spans=[];
      for(let k=0;k<toks.length;k++){
        if(k)en.append(' ');
        const gk=gapAt[i+':'+k];
        if(gk!=null){const g=e.g[gk];const b=h('button',{type:'button',class:'regap lw','aria-label':'Празно място '+(gk+1)},'  '+(gk+1)+'  ');
          b.addEventListener('click',ev=>{ev.stopPropagation();openGap(gk)});gapEls[gk]={b,line:i,ans:toks.slice(k,k+g[3]).join(' ').replace(/^[^A-Za-z0-9]+|[^A-Za-z0-9]+$/g,''),lead:toks[k].match(/^[^A-Za-z0-9]*/)[0],tail:toks[k+g[3]-1].match(/[^A-Za-z0-9]*$/)[0]};
          if(gapEls[gk].lead)en.append(gapEls[gk].lead);en.append(b);if(gapEls[gk].tail)en.append(gapEls[gk].tail);
          for(let j=0;j<g[3];j++)spans.push(b);k+=g[3]-1;continue}
        const s=h('span',{class:'lw'},toks[k]);spans.push(s);en.append(s)}
      const bgEl=h('div',{class:'lsbg'},l[2]);
      const ln=h('div',{class:'lsln'+side},pb,h('div',{class:'lsbody'},h('span',{class:'lswho'},sp),en,bgEl));
      if(step===2&&Object.keys(gapAt).some(x=>+x.split(':')[0]===i))ln.classList.add('hasgap');
      pb.addEventListener('click',ev=>{ev.stopPropagation();playLine(i)});
      ln.addEventListener('click',()=>{if(root.classList.contains('notext')&&!en.classList.contains('peek')){en.classList.add('peek');return}playLine(i)});
      LE.push(ln);TOK.push(spans);tr.append(ln)});
    /* in the gap lesson the translation of a line with a gap stays hidden until the gap is solved */
    if(step===2)gapEls.forEach(g=>{const b=LE[g.line].querySelector('.lsbg');if(b)b.dataset.wait='1',b.style.visibility='hidden'});
    root.append(tr);

    /* --- exercises --- */
    if(step===1){
      const box=h('div',{class:'lsex'},h('h4',null,'📚 Думите от записа'),h('p',{class:'lsnote'},'Изберете какво означава всяка дума или израз. С „▶“ чувате изречението от записа, в което се среща.'));
      const pool=e.v.map(v=>v[1]);
      mix(e.v.map((v,k)=>[v,k])).forEach(([v,k])=>{
        const key='v'+k;need.push(key);
        const wrong=mix(pool.filter(x=>x!==v[1])).slice(0,2);
        const opts=mix([v[1],...wrong]);
        const row=h('div',{class:'lsopts'});
        opts.forEach(o=>{const b=h('button',{type:'button',class:'lsopt'+(o===v[1]?' right':'')},o);
          b.addEventListener('click',()=>{if(row.classList.contains('over'))return;const ok=o===v[1];b.classList.add(ok?'ok':'bad');
            if(!ok)row.querySelector('.right').classList.add('ok');row.classList.add('over');mark(key,ok);try{sfx&&sfx(ok?'ok':'bad')}catch(er){}});row.append(b)});
        const head=h('div',{class:'revw'},h('b',{lang:'en'},v[0]),v[2]!=null?h('button',{type:'button',class:'rehear',onclick:ev=>hear(ev.currentTarget,v[2],v[2])},'▶ Чуй'):null);
        box.append(h('div',{class:'lsqi'},head,row))});
      root.append(box);
    }
    let pick=null,curGap=null;
    function openGap(k){
      const g=gapEls[k];if(!g||g.done)return;
      if(pick){pick.remove();pick=null;if(curGap!=null)gapEls[curGap].b.classList.remove('open')}
      if(curGap===k){curGap=null;return}
      curGap=k;g.b.classList.add('open');
      const all=gapEls.map(x=>x.ans);const seen=new Set([g.ans.toLowerCase()]);
      const wrong=mix(all).filter(x=>{const y=x.toLowerCase();if(seen.has(y))return false;seen.add(y);return true}).slice(0,3);
      const row=h('div',{class:'lsopts'});
      mix([g.ans,...wrong]).forEach(o=>{const b=h('button',{type:'button',class:'lsopt'+(o===g.ans?' right':''),lang:'en'},o);
        b.addEventListener('click',ev=>{ev.stopPropagation();const ok=o.toLowerCase()===g.ans.toLowerCase();g.done=1;mark('g'+k,ok);
          g.b.classList.remove('open');g.b.classList.add(ok?'ok':'bad');g.b.replaceChildren(ok?'':h('span',{class:'rewas'},o),g.ans);
          const bg=LE[g.line].querySelector('.lsbg');if(bg&&gapEls.every(x=>x.line!==g.line||x.done))bg.style.visibility='';
          try{sfx&&sfx(ok?'ok':'bad')}catch(er){}
          pick.remove();pick=null;curGap=null;
          const nx=gapEls.findIndex(x=>!x.done);if(nx>=0)setTimeout(()=>{try{gapEls[nx].b.scrollIntoView({block:'center',behavior:'smooth'})}catch(er){}},250)});row.append(b)});
      pick=h('div',{class:'repick',onclick:ev=>ev.stopPropagation()},
        h('button',{type:'button',class:'rehear',onclick:ev=>hear(ev.currentTarget,g.line,g.line)},'▶ Чуй изречението'),row);
      LE[g.line].querySelector('.lsbody').append(pick);
      try{LE[g.line].scrollIntoView({block:'center',behavior:'smooth'})}catch(er){}
      playLine(g.line);
    }
    if(step===2){gapEls.forEach((g,k)=>need.push('g'+k))}
    if(step===3){
      const box=h('div',{class:'lsex'},h('h4',null,'❓ Въпроси към записа'),h('p',{class:'lsnote'},'Всеки въпрос има бутон „▶ Чуй откъса“ – можете да слушате колкото пъти искате.'));
      e.q.forEach((q,k)=>{
        const key='q'+k;need.push(key);
        const row=h('div',{class:'lsopts'});
        mix([q[2],q[3],q[4]]).forEach(o=>{const b=h('button',{type:'button',class:'lsopt'+(o===q[2]?' right':''),lang:'en'},o);
          b.addEventListener('click',()=>{if(row.classList.contains('over'))return;const ok=o===q[2];b.classList.add(ok?'ok':'bad');
            if(!ok)row.querySelector('.right').classList.add('ok');row.classList.add('over');mark(key,ok);try{sfx&&sfx(ok?'ok':'bad')}catch(er){}});row.append(b)});
        const a=Math.max(0,q[5]-1),z=Math.min(lines.length-1,q[5]+1);
        box.append(h('div',{class:'lsqi'},h('div',{class:'lsqq',lang:'en'},(k+1)+'. '+q[0]),h('div',{class:'lsbg reqbg'},q[1]),
          h('button',{type:'button',class:'rehear',onclick:ev=>hear(ev.currentTarget,a,z)},'▶ Чуй откъса'),row))});
      root.append(box);
    }
    root.append(foot);
    if(step===1){const sv=h('button',{type:'button',class:'resave'},'⬇ Запази всички 24 записа за слушане без интернет (≈50 MB)');
      sv.addEventListener('click',()=>{sv.disabled=true;window.__reSaveAll((n,t)=>{sv.textContent=n<t?'⬇ Запазване… '+n+' от '+t:'✓ Всички записи са запазени на устройството'})});root.append(sv)}

    /* --- player dock --- */
    const au=new Audio();au.preload='auto';
    const pm=h('button',{type:'button',class:'btn rose lspm','aria-label':'Пусни'},'▶');
    const rng=h('input',{type:'range',min:0,max:1000,value:0,'aria-label':'Позиция в записа'});
    const tm=h('span',null,'0:00 / –:––');
    const sp=h('select',{class:'lsspd','aria-label':'Скорост'},[['0.75','0.75×'],['0.9','0.9×'],['1','1×']].map(([v,t])=>{const o=h('option',{value:v},t);if(+v===+opt('spd',1))o.selected=true;return o}));
    sp.addEventListener('change',()=>{setOpt('spd',+sp.value);au.playbackRate=+sp.value});
    const back=h('button',{type:'button',class:'rejump','aria-label':'5 секунди назад'},'↺5');
    const fwd=h('button',{type:'button',class:'rejump','aria-label':'5 секунди напред'},'5↻');
    const dock=h('div',{class:'lsdock redock'},back,pm,fwd,h('div',{class:'reseek'},rng,tm),sp);
    root.append(dock);
    area.replaceChildren(root);document.body.classList.add('lsdocked');
    try{window.scrollTo({top:0})}catch(er){}

    /* playback: free play, one line, or a range of lines (stopAt) */
    let stopAt=null,hearBtn=null,ready=false,curW=null,curL=-1,raf=0,dead=false,quiet=false;
    const T0=i=>lines[i][3][0]/100,T1=i=>lines[i][4]/100;
    function clearW(){if(curW){curW.classList.remove('cur');curW=null}}
    function live(i){if(i===curL)return;if(curL>=0&&LE[curL])LE[curL].classList.remove('live');curL=i;if(i>=0&&LE[i]){LE[i].classList.add('live');
      if(opt('fol',true)&&!pick&&!quiet){const r=LE[i].getBoundingClientRect(),vh=innerHeight;if(r.top<vh*0.12||r.bottom>vh*0.75){try{LE[i].scrollIntoView({block:'center',behavior:'smooth'})}catch(er){}}}}}
    function lineAt(t){let lo=0,hi=lines.length-1,r=-1;while(lo<=hi){const m=(lo+hi)>>1;if(T0(m)<=t+0.05){r=m;lo=m+1}else hi=m-1}
      if(r>=0&&t>T1(r)+0.6)return -1;return r}
    function tick(){
      if(dead)return;
      if(!root.isConnected){stop(true);return}
      const t=au.currentTime;
      if(stopAt!=null&&t>=stopAt){au.pause();stopAt=null}
      const i=lineAt(t);live(i);
      if(i>=0&&opt('fol',true)){const st=lines[i][3];let k=-1;for(let j=0;j<st.length;j++){if(st[j]/100<=t+0.04)k=j;else break}
        const w=k>=0?TOK[i][k]:null;if(w!==curW){clearW();if(w&&w.classList){w.classList.add('cur');curW=w}}}else clearW();
      if(!rng.matches(':active'))rng.value=au.duration?Math.round(1000*t/au.duration):0;
      tm.textContent=fmt(t)+' / '+(au.duration?fmt(au.duration):'–:––');
      raf=requestAnimationFrame(tick)}
    function ui(){pm.textContent=au.paused?'▶':'⏸';pm.setAttribute('aria-label',au.paused?'Пусни':'Пауза');
      if(au.paused&&hearBtn){hearBtn.classList.remove('on');hearBtn=null}}
    au.addEventListener('play',ui);au.addEventListener('pause',ui);au.addEventListener('ended',()=>{stopAt=null;ui()});
    function go(t,end){if(!ready){warn.hidden=false;warn.textContent='⏳ Записът още се зарежда…';return}
      au.currentTime=Math.max(0,t);stopAt=end==null?null:end;au.playbackRate=+opt('spd',1);au.play().catch(()=>{})}
    function playLine(i){quiet=false;go(T0(i)-0.08,T1(i)+0.25)}
    function hear(btn,a,z){if(hearBtn===btn&&!au.paused){au.pause();return}if(hearBtn)hearBtn.classList.remove('on');quiet=step!==2;go(T0(a)-0.08,T1(z)+0.3);hearBtn=btn;btn.classList.add('on')}
    pm.addEventListener('click',()=>{if(!ready){warn.hidden=false;warn.textContent='⏳ Записът още се зарежда…';return}if(au.paused){stopAt=null;quiet=false;au.playbackRate=+opt('spd',1);au.play().catch(()=>{})}else au.pause()});
    back.addEventListener('click',()=>{if(ready)au.currentTime=Math.max(0,au.currentTime-5)});
    fwd.addEventListener('click',()=>{if(ready)au.currentTime=Math.min(au.duration||0,au.currentTime+5)});
    rng.addEventListener('input',()=>{if(ready&&au.duration){au.currentTime=au.duration*rng.value/1000;stopAt=null}});
    function stop(full){try{au.pause()}catch(er){}if(full){dead=true;cancelAnimationFrame(raf);document.body.classList.remove('lsdocked');try{au.removeAttribute('src');au.load()}catch(er){}}}
    root.__stop=()=>stop(true);
    pm.disabled=false;
    getAudio(id).then(u=>{if(dead)return;au.src=u;au.playbackRate=+opt('spd',1);ready=true;warn.hidden=true;raf=requestAnimationFrame(tick)})
      .catch(()=>{warn.hidden=false;warn.textContent='📶 Записът не можа да се зареди. Свържете се с интернет веднъж – после ще работи и без връзка.';});
    upd();
  };

  /* save every recording for offline use (called from the path, optional) */
  window.__reSaveAll=async function(onp){let n=0;for(const id of ORDER){try{const r=await fetch(EP[id].a);if(r.ok)await r.blob()}catch(e){}n++;onp&&onp(n,ORDER.length)}};
})();
